function canonicalCodexUpstreamModelName(model: string) {
  const trimmed = model.trim()
  const route = trimmed.split('/')
  const upstream = route[0]?.toLowerCase() === 'gaoge' && route.length >= 4
    ? route.slice(3).join('/')
    : trimmed
  return upstream.toLowerCase().replaceAll('_', '-')
}

function isCodexImageGenerationModel(model: string) {
  const canonical = canonicalCodexUpstreamModelName(model)
  return CODEX_IMAGE_GENERATION_MODEL_RELEASES.some((release) => {
    if (canonical === release) return true
    if (!canonical.startsWith(`${release}-`)) return false
    const suffix = canonical.slice(release.length + 1)
    return /^\d{8}$/.test(suffix) || /^\d{4}-\d{2}-\d{2}$/.test(suffix)
  })
}

function isCodexConversationModel(model: string) {
  return Boolean(model.trim()) && !isCodexImageGenerationModel(model)
}

function filterCodexConversationModels(models: string[]) {
  return Array.from(new Set(models.map((model) => model.trim()).filter(isCodexConversationModel)))
}

function selectCodexConversationModel(models: string[], requested = '') {
  const available = filterCodexConversationModels(models)
  const normalizedRequested = requested.trim()
  if (isCodexConversationModel(normalizedRequested) && available.includes(normalizedRequested)) {
    return normalizedRequested
  }
  return available.includes(CODEX_MODEL) ? CODEX_MODEL : available[0] || CODEX_MODEL
}

