function readStoredUser() {
  const raw = localStorage.getItem('gaoge_desktop_user')
  if (!raw) return null
  try {
    return JSON.parse(raw) as ApiUser
  } catch {
    localStorage.removeItem('gaoge_desktop_user')
    return null
  }
}

function readStoredCodexRelaySource(): CodexRelaySource {
  const value = localStorage.getItem(CODEX_RELAY_SOURCE_STORAGE_KEY)
  return value === 'one-click' || value === 'fuel-pack' || value === 'aggregate' ? value : ''
}

function readStoredCodexFuelRecovery() {
  try {
    return localStorage.getItem(CODEX_FUEL_RECOVERY_STORAGE_KEY) === 'true'
  } catch {
    return false
  }
}

function readStoredCodexModelSelectionMode(): CodexModelSelectionMode {
  migrateStoredCodexDefaultModel()
  localStorage.setItem(CODEX_MODEL_SELECTION_DEFAULTED_STORAGE_KEY, '1')
  localStorage.setItem(CODEX_MODEL_SELECTION_MODE_STORAGE_KEY, 'upstream')
  return 'upstream'
}

function migrateStoredCodexDefaultModel() {
  migrateCodexDefaultModelStorage(localStorage, codexModelMigrationOptions())
}

function codexModelMigrationOptions() {
  return {
    currentDefaultModel: CODEX_MODEL,
    legacyDefaultModel: CODEX_LEGACY_DEFAULT_MODEL,
    modelKey: 'gaoge_desktop_codex_model',
    lockedModelKey: CODEX_LOCKED_MODEL_STORAGE_KEY,
    selectionModeKey: CODEX_MODEL_SELECTION_MODE_STORAGE_KEY,
    legacyDefaultedKey: CODEX_MODEL_SELECTION_DEFAULTED_STORAGE_KEY,
    selectionOriginKey: CODEX_MODEL_SELECTION_ORIGIN_STORAGE_KEY,
    migrationKey: CODEX_DEFAULT_MODEL_MIGRATION_STORAGE_KEY,
    isConversationModel: isCodexConversationModel,
  }
}

function readStoredLockedCodexModel() {
  const stored = localStorage.getItem(CODEX_LOCKED_MODEL_STORAGE_KEY)
    || localStorage.getItem('gaoge_desktop_codex_model')
    || CODEX_MODEL
  return isCodexConversationModel(stored) ? stored : CODEX_MODEL
}

function readStoredLoginGroups(): Record<ToolKey, number> {
  try {
    const parsed = JSON.parse(localStorage.getItem(LOGIN_GROUP_STORAGE_KEY) || '{}') as Partial<Record<ToolKey, unknown>>
    return {
      codex: Number(parsed.codex) || 0,
      claude: Number(parsed.claude) || 0,
    }
  } catch {
    return { codex: 0, claude: 0 }
  }
}

function saveSelectedLoginGroup(tool: ToolKey, groupId: number) {
  const stored = readStoredLoginGroups()
  localStorage.setItem(LOGIN_GROUP_STORAGE_KEY, JSON.stringify({
    ...stored,
    [tool]: groupId,
  }))
}

function readStoredDefaultApiKeyIds(): Record<ToolKey, number> {
  try {
    const parsed = JSON.parse(localStorage.getItem(DEFAULT_API_KEY_ID_STORAGE_KEY) || '{}') as Partial<Record<ToolKey, unknown>>
    return {
      codex: Number(parsed.codex) || 0,
      claude: Number(parsed.claude) || 0,
    }
  } catch {
    return { codex: 0, claude: 0 }
  }
}

function saveDefaultApiKeyId(tool: ToolKey, keyId: number) {
  if (!keyId) return
  const stored = readStoredDefaultApiKeyIds()
  localStorage.setItem(DEFAULT_API_KEY_ID_STORAGE_KEY, JSON.stringify({
