function getScopedStorageKey(baseKey: string) {
  const scope = String(authUser.value?.id || authUser.value?.email || 'guest')
    .trim()
    .replace(/[^\w.-]/g, '_') || 'guest'
  return `${baseKey}_${scope}`
}

function getRechargeBonusQueueStorageKey() {
  return getScopedStorageKey(RECHARGE_BONUS_QUEUE_STORAGE_KEY)
}

function normalizePendingRechargeBonusJob(value: unknown): PendingRechargeBonusJob | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<PendingRechargeBonusJob>
  const orderId = Number(source.orderId || 0)
  const planId = String(source.planId || source.snapshot?.planId || '').trim()
  const snapshotSource = source.snapshot
  if (!Number.isFinite(orderId) || orderId <= 0 || !planId || !snapshotSource) return null

  const payAmount = Number(snapshotSource.payAmount || 0)
  const baseCreditAmount = Number(snapshotSource.baseCreditAmount || 0)
  const bonusAmount = Number(snapshotSource.bonusAmount || 0)
  const totalCreditAmount = Number(snapshotSource.totalCreditAmount || 0)
  if (
    !Number.isFinite(payAmount) || payAmount <= 0 ||
    !Number.isFinite(baseCreditAmount) || baseCreditAmount < 0 ||
    !Number.isFinite(bonusAmount) || bonusAmount <= 0 ||
    !Number.isFinite(totalCreditAmount) || totalCreditAmount <= 0
  ) return null

  const now = new Date().toISOString()
  const createdAt = String(source.createdAt || snapshotSource.createdAt || now)
  return {
    version: 1,
    orderId,
    planId,
    snapshot: {
      planId,
      payAmount,
      baseCreditAmount,
      bonusAmount,
      totalCreditAmount,
      ...(Number.isFinite(Number(snapshotSource.multiplier)) ? { multiplier: Number(snapshotSource.multiplier) } : {}),
      createdAt: String(snapshotSource.createdAt || createdAt),
    },
    createdAt,
    updatedAt: String(source.updatedAt || createdAt),
    attempts: Math.max(0, Math.floor(Number(source.attempts || 0))),
    nextRetryAt: Math.max(0, Number(source.nextRetryAt || Date.now())),
    autoRetry: source.autoRetry !== false,
    lastAttemptAt: source.lastAttemptAt ? String(source.lastAttemptAt) : undefined,
    lastError: source.lastError ? stripSensitiveErrorText(String(source.lastError)).slice(0, 300) : undefined,
  }
}

function readPendingRechargeBonusJobs() {
  const storageKey = getRechargeBonusQueueStorageKey()
  try {
    const raw = localStorage.getItem(storageKey)
    const parsed = raw ? JSON.parse(raw) : []
    if (!Array.isArray(parsed)) return []
    return parsed
      .map(normalizePendingRechargeBonusJob)
      .filter((item): item is PendingRechargeBonusJob => Boolean(item))
      .sort((left, right) => left.nextRetryAt - right.nextRetryAt)
      .slice(0, RECHARGE_BONUS_MAX_PENDING_JOBS)
  } catch {
    try {
      localStorage.removeItem(storageKey)
    } catch {
      // Storage can be unavailable in restricted webview contexts.
    }
    return []
  }
}

function writePendingRechargeBonusJobs(jobs: PendingRechargeBonusJob[]) {
  const storageKey = getRechargeBonusQueueStorageKey()
  const normalized = jobs
    .map(normalizePendingRechargeBonusJob)
    .filter((item): item is PendingRechargeBonusJob => Boolean(item))
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt))
    .slice(-RECHARGE_BONUS_MAX_PENDING_JOBS)
  if (!normalized.length) {
    try {
      localStorage.removeItem(storageKey)
    } catch {
      // Keep the payment flow usable even when local persistence is unavailable.
    }
    return
  }
  try {
    localStorage.setItem(storageKey, JSON.stringify(normalized))
  } catch {
    // The current payment can still apply its bonus through the in-memory snapshot.
  }
}

function findPendingRechargeBonusJob(orderId: number) {
  return readPendingRechargeBonusJobs().find((job) => job.orderId === orderId) || null
}

function savePendingRechargeBonusJob(job: PendingRechargeBonusJob) {
  const normalized = normalizePendingRechargeBonusJob(job)
  if (!normalized) return null
  const jobs = readPendingRechargeBonusJobs()
  const index = jobs.findIndex((item) => item.orderId === normalized.orderId)
  if (index >= 0) jobs[index] = normalized
  else jobs.push(normalized)
  writePendingRechargeBonusJobs(jobs)
  return normalized
}

function enqueuePendingRechargeBonusJob(orderId: number, snapshot: OnlinePaymentSnapshot) {
  if (!Number.isFinite(orderId) || orderId <= 0 || Number(snapshot.bonusAmount || 0) <= 0) return null
  const existing = findPendingRechargeBonusJob(orderId)
  const now = new Date().toISOString()
  const job = savePendingRechargeBonusJob({
    version: 1,
    orderId,
    planId: snapshot.planId,
    snapshot,
    createdAt: existing?.createdAt || now,
    updatedAt: now,
    attempts: existing?.attempts || 0,
    nextRetryAt: existing?.nextRetryAt || Date.now() + RECHARGE_BONUS_PENDING_PAYMENT_RETRY_MS,
    autoRetry: existing?.autoRetry ?? true,
    lastAttemptAt: existing?.lastAttemptAt,
    lastError: existing?.lastError,
  })
  schedulePendingRechargeBonusRetry()
  return job
}

function removePendingRechargeBonusJob(orderId: number) {
  const jobs = readPendingRechargeBonusJobs().filter((job) => job.orderId !== orderId)
  writePendingRechargeBonusJobs(jobs)
  schedulePendingRechargeBonusRetry()
}

function updatePendingRechargeBonusJob(
  job: PendingRechargeBonusJob,
  updates: Partial<Pick<PendingRechargeBonusJob, 'attempts' | 'nextRetryAt' | 'autoRetry' | 'lastAttemptAt' | 'lastError'>>,
) {
  return savePendingRechargeBonusJob({
    ...job,
    ...updates,
    updatedAt: new Date().toISOString(),
  })
}

function getInvoiceStorageKey(baseKey: string) {
  return getScopedStorageKey(baseKey)
}

function getAnnouncementReadStorageKey() {
  const scope = String(authUser.value?.id || authUser.value?.email || 'guest')
    .trim()
    .replace(/[^\w.-]/g, '_') || 'guest'
  return `${ANNOUNCEMENT_READ_STORAGE_KEY}_${scope}`
}

function readAnnouncementReadIds() {
  try {
    const raw = localStorage.getItem(getAnnouncementReadStorageKey())
    const parsed = raw ? JSON.parse(raw) : []
    return new Set(Array.isArray(parsed) ? parsed.map((item) => String(item)).filter(Boolean) : [])
  } catch {
    localStorage.removeItem(getAnnouncementReadStorageKey())
    return new Set<string>()
  }
}

function writeAnnouncementReadIds(ids: Set<string>) {
  localStorage.setItem(getAnnouncementReadStorageKey(), JSON.stringify(Array.from(ids).slice(-500)))
}

function readStoredInvoiceArray<T>(baseKey: string, normalizer: (value: unknown) => T | null) {
  const storageKey = getInvoiceStorageKey(baseKey)
  try {
    const raw = localStorage.getItem(storageKey)
    const parsed = raw ? JSON.parse(raw) : []
    if (!Array.isArray(parsed)) return []
    return parsed.map(normalizer).filter((item): item is T => Boolean(item))
  } catch {
    localStorage.removeItem(storageKey)
    return []
  }
}

function writeStoredInvoiceArray<T>(baseKey: string, items: T[]) {
  localStorage.setItem(getInvoiceStorageKey(baseKey), JSON.stringify(items))
}

function normalizePlatformSubscriptionCache(value: unknown): PlatformSubscriptionCache | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<PlatformSubscriptionCache>
  const cachedAt = String(source.cachedAt || '').trim()
  const subscription = normalizeActiveSubscriptionPayload(source.subscription || null)
  const summary = source.summary && typeof source.summary === 'object'
    ? source.summary as SubscriptionSummary
    : null
  const summaryItems = Array.isArray(summary?.subscriptions)
    ? summary.subscriptions.filter((item): item is SubscriptionSummaryItem => Boolean(item))
    : []
  if (!subscription && !summaryItems.length) return null
  return {
    subscription,
    summary: summary ? { ...summary, subscriptions: summaryItems } : null,
    cachedAt: cachedAt || new Date().toISOString(),
  }
}

function readPlatformSubscriptionCache() {
  const storageKey = getScopedStorageKey(PLATFORM_SUBSCRIPTION_CACHE_STORAGE_KEY)
  try {
    const raw = localStorage.getItem(storageKey)
    return normalizePlatformSubscriptionCache(raw ? JSON.parse(raw) : null)
  } catch {
    localStorage.removeItem(storageKey)
    return null
  }
}

function writePlatformSubscriptionCache(payload: PlatformSubscriptionMyResponse) {
  const subscription = normalizeActiveSubscriptionPayload(payload.subscription)
  const subscriptions = (payload.subscriptions || []) as SubscriptionSummaryItem[]
  if (!subscription && !subscriptions.length) {
    localStorage.removeItem(getScopedStorageKey(PLATFORM_SUBSCRIPTION_CACHE_STORAGE_KEY))
    return
  }
  const cache: PlatformSubscriptionCache = {
    subscription,
    summary: {
      active_count: subscription ? 1 : 0,
      subscriptions,
    },
    cachedAt: new Date().toISOString(),
  }
  localStorage.setItem(getScopedStorageKey(PLATFORM_SUBSCRIPTION_CACHE_STORAGE_KEY), JSON.stringify(cache))
}

function applyPlatformSubscriptionCache(cache: PlatformSubscriptionCache | null) {
  if (!cache) return false
  activePlatformSubscription.value = normalizeActiveSubscriptionPayload(cache.subscription)
  platformSubscriptionSummary.value = cache.summary
  return Boolean(activePlatformSubscription.value || platformSubscriptionSummary.value)
}

function restorePlatformSubscriptionFromCache() {
  return applyPlatformSubscriptionCache(readPlatformSubscriptionCache())
}

