function monotonicNow() {
  return typeof performance !== 'undefined' && Number.isFinite(performance.now())
    ? performance.now()
    : Date.now()
}

function formatCodexOperationElapsed(elapsedMs: number, message = '') {
  const seconds = Math.max(0, elapsedMs) / 1000
  const elapsed = `已用 ${seconds.toFixed(1)} 秒`
  if (seconds < 5) return elapsed
  const normalizedMessage = message.trim()
  return normalizedMessage ? `${elapsed} · ${normalizedMessage}` : elapsed
}
