function isCodexRouterRelayBaseUrlCurrent(settings?: GaogeDesktopCodexRouterSettings | null) {
  const savedRelayBaseUrl = String(settings?.relayBaseUrl || '').trim()
  if (savedRelayBaseUrl) return isGaogeCodexRelayBaseUrl(savedRelayBaseUrl)
  if (isAggregateLoginActive.value) {
