        const modelError = result?.modelError || ''
        return {
          ...group,
          models,
          modelReady: isAggregateModelResultReady(result),
          modelError,
          loading: aggregateGroupLoading.value[key] === true,
          fallback: result?.fallback === true,
          builtinCatalog: result?.builtinCatalog === true,
          message: result?.message || '',
          keyReady: aggregateGroupKeyReady.value[key] === true,
          keyError: aggregateGroupKeyErrors.value[key] || '',
        }
      })
    const models = extractModelNames({
      models: providerGroups.flatMap((group) => group.modelReady ? group.models : []),
