const platformSubscriptionExpiresDetail = computed(() => {
  if (!hasPlatformSubscriptionRecord.value) return ''
  const subscription = isPlatformSubscriptionRecordActive(activePlatformSubscription.value)
    ? activePlatformSubscription.value
    : null
  const expiresAt = activePlatformSubscriptionSummaryItem.value?.expires_at ||
    subscription?.expires_at ||
    subscription?.valid_until ||
    subscription?.end_at
  if (!expiresAt) return subscription || activePlatformSubscriptionSummaryItem.value ? '有效期 30 天' : ''
  const millis = new Date(expiresAt).getTime()
  const suffix = Number.isFinite(millis)
    ? millis <= Date.now()
      ? '已到期'
      : `剩余 ${Math.ceil((millis - Date.now()) / 86_400_000)} 天`
    : '剩余时间待同步'
  return `${suffix} · ${formatFullTime(expiresAt)}`
})
