  image2OutputFormat.value = next.outputFormat
  image2Mode.value = next.mode
  image2Size.value = next.size
  image2SizePreset.value = image2SizeOptions.find((option) => option.value === next.size)?.id || 'auto'
  image2ImageCount.value = next.imageCount
  image2Complexity.value = next.complexity
  image2FrameCount.value = next.frameCount
  image2FrameDurationMs.value = next.frameDurationMs
  if (!next.referenceImagePaths.length) image2References.value = []
  if (next.outputFormat === 'gif') isImage2SizeDialogOpen.value = false
})

watch(image2SelectedSize, (option) => {
  if (!option) return
  if (image2SizePreset.value !== option.id) image2SizePreset.value = option.id
  if (image2Size.value !== option.value) image2Size.value = option.value
}, { immediate: true })

watch(image2Quality, (quality) => {
  const normalized = legacyImage2QualityMap[quality] || quality
  const hasQuality = image2QualityOptions.some((option) => option.value === normalized)
  const nextQuality = hasQuality ? normalized : 'medium'
  if (image2Quality.value !== nextQuality) image2Quality.value = nextQuality
}, { immediate: true })
