  void loadCodexThemeCatalog()
}

function closeCodexThemeDialog() {
  isCodexThemeDialogOpen.value = false
}

function rotateCodexThemeCarousel(direction: 'previous' | 'next') {
  if (isCodexThemeCarouselMoving.value) return
  const offset = direction === 'previous' ? -1 : 1
  const total = codexThemeCatalog.value.length
  if (!total) return
  isCodexThemeCarouselMoving.value = true
  const nextStart = (codexThemeCarouselStart.value + offset + total) % total
  codexThemeCarouselStart.value = nextStart
  selectedCodexThemeId.value = codexThemeCatalog.value[nextStart]?.id || selectedCodexThemeId.value
  if (codexThemeCarouselMoveTimer !== null) window.clearTimeout(codexThemeCarouselMoveTimer)
  codexThemeCarouselMoveTimer = window.setTimeout(() => {
    isCodexThemeCarouselMoving.value = false
    codexThemeCarouselMoveTimer = null
  }, 420)
}

function selectCodexThemeSlot(slot: CodexThemeCarouselSlot) {
  if (isCodexThemeCarouselMoving.value) return
  if (slot.offset !== 0) {
    const total = codexThemeCatalog.value.length
    const nextStart = (codexThemeCarouselStart.value + slot.offset + total) % total
    isCodexThemeCarouselMoving.value = true
    codexThemeCarouselStart.value = nextStart
    selectedCodexThemeId.value = slot.item.id
    if (codexThemeCarouselMoveTimer !== null) window.clearTimeout(codexThemeCarouselMoveTimer)
    codexThemeCarouselMoveTimer = window.setTimeout(() => {
      isCodexThemeCarouselMoving.value = false
      codexThemeCarouselMoveTimer = null
    }, 420)
  } else {
    selectedCodexThemeId.value = slot.item.id
  }
}

function codexThemePreviewStyle(item: CodexThemeCatalogItem) {
  if (item.previewUrl) {
    return {
      backgroundImage: `url(${JSON.stringify(item.previewUrl)})`,
      backgroundPosition: 'center',
      backgroundSize: 'cover',
      '--theme-accent': item.accent,
    }
  }
  return {
    backgroundImage: `linear-gradient(135deg, ${item.accent}70, #111827 72%)`,
    backgroundPosition: 'center',
    backgroundSize: 'cover',
    '--theme-accent': item.accent,
  }
}

function formatCodexThemeBytes(bytes: number) {
  if (!Number.isFinite(bytes) || bytes <= 0) return '按需下载'
  if (bytes >= 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`
  return `${Math.max(1, Math.round(bytes / 1024))} KB`
}

function normalizeCodexThemeItem(item: GaogeDesktopCodexThemeItem): CodexThemeCatalogItem {
  const fallback = codexThemeFallbackCatalog.find((candidate) => candidate.id === item.id)
  return {
    id: item.id,
    name: item.name,
    style: item.style || fallback?.style || (item.custom ? '自定义' : '主题'),
    description: item.description || fallback?.description || '',
    previewPosition: fallback?.previewPosition,
    previewUrl: item.previewUrl || '',
    accent: fallback?.accent || '#22d3ee',
    size: formatCodexThemeBytes(item.sizeBytes),
    sizeBytes: Number(item.sizeBytes || 0),
    version: item.version || '1.0.0',
    remoteVersion: item.remoteVersion || '',
    author: item.author || '未知作者',
    platforms: (item.platforms || []).map((platform) => (
      platform === 'windows' ? 'Windows' : platform === 'macos' ? 'macOS' : platform
    )),
    sourceLabel: item.sourceLabel || (item.custom ? '自定义主题' : '社区素材'),
    installed: item.installed === true,
    custom: item.custom === true,
    active: item.active === true,
    applied: item.applied === true && item.pending !== true,
    pending: item.pending === true,
    updateAvailable: item.updateAvailable === true,
    enabled: item.enabled !== false,
  }
}

function mergeCodexThemeFallbackCatalog(items: CodexThemeCatalogItem[]) {
  const byId = new Map(items.map((item) => [item.id, item]))
  const merged = buildCodexThemeFallbackCatalog().map((fallback) => {
    const local = byId.get(fallback.id)
    if (!local) return fallback
    byId.delete(fallback.id)
    return {
      ...fallback,
      ...local,
      previewUrl: local.previewUrl || fallback.previewUrl,
    }
  })
  return [...merged, ...byId.values()]
}

function getCodexThemeCatalogError(error: unknown) {
  const rawMessage = typeof error === 'string'
    ? error.trim()
    : typeof (error as ApiError)?.message === 'string'
      ? (error as ApiError).message.trim()
      : ''
  const lowerMessage = rawMessage.toLowerCase()
  if (
    lowerMessage.includes('gaoge_list_codex_themes') ||
    lowerMessage.includes('unknown command') ||
    lowerMessage.includes('command not found')
  ) {
    return '桌面主题服务尚未加载，请重新打开 Gaoge Free 后重试。'
  }
  if (
    rawMessage.includes('主题目录') ||
    lowerMessage.includes('catalog.json') ||
    lowerMessage.includes('expected value at line')
  ) {
    return '主题资源服务器暂时不可用，当前先展示备用主题信息。'
  }
  return getErrorMessage(error, { notFoundMessage: '主题资源暂不可用，请稍后重试。' })
}

async function loadCodexThemeCatalog(options: { silent?: boolean } = {}) {
  if (!window.gaogeDesktop?.listCodexThemes) {
    codexThemeRuntime.value = null
    codexThemeCatalog.value = buildCodexThemeFallbackCatalog()
    codexThemeCatalogError.value = '当前不是桌面环境，暂时显示主题目录预览。'
    return
  }
  const generation = ++codexThemeCatalogGeneration
  isCodexThemeCatalogLoading.value = true
  if (!options.silent) codexThemeCatalogError.value = ''
  try {
    const response = await window.gaogeDesktop.listCodexThemes()
    if (generation !== codexThemeCatalogGeneration) return
    codexThemeRuntime.value = response.runtime || null
    const themes = (response.themes || []).filter((item) => item.enabled !== false)
    const normalizedThemes = themes.map(normalizeCodexThemeItem)
    codexThemeCatalog.value = response.catalogError
      ? mergeCodexThemeFallbackCatalog(normalizedThemes)
      : normalizedThemes.length
        ? normalizedThemes
        : buildCodexThemeFallbackCatalog()
    codexThemeActiveName.value =
      codexThemeCatalog.value.find((item) => item.active)?.name || ''
    const selectedExists = codexThemeCatalog.value.some((item) => item.id === selectedCodexThemeId.value)
    if (!selectedExists) selectedCodexThemeId.value = codexThemeCatalog.value[0]?.id || 'aurora-valley'
    codexThemeCarouselStart.value %= Math.max(1, codexThemeCatalog.value.length)
    codexThemeCatalogError.value = response.catalogError
      ? getCodexThemeCatalogError(response.catalogError)
      : ''
  } catch (error) {
    if (generation !== codexThemeCatalogGeneration) return
    codexThemeRuntime.value = null
    reportPageError('codex-theme', 'load-catalog', error)
    codexThemeCatalog.value = mergeCodexThemeFallbackCatalog(codexThemeCatalog.value)
    codexThemeCatalogError.value = getCodexThemeCatalogError(error)
    if (!options.silent) notify(codexThemeCatalogError.value, 'error', 'Codex 主题')
  } finally {
    if (generation === codexThemeCatalogGeneration) isCodexThemeCatalogLoading.value = false
  }
}

const activeCodexTheme = computed(
  () => codexThemeCatalog.value.find((item) => item.active) || null,
)

function codexThemeRuntimeIsApplied(runtime: GaogeDesktopCodexThemeRuntimeStatus | null | undefined, themeId: string) {
  return runtime?.runtimeReady === true && runtime.needsRestart !== true && !runtime.runtimeError
    && runtime.selectedThemeId === themeId && runtime.appliedThemeId === themeId
}

const codexThemeSelectionStatus = computed(() => {
  const runtime = codexThemeRuntime.value
  const themeId = activeCodexTheme.value?.id || ''
  if (codexThemeRuntimeIsApplied(runtime, themeId)) return '已应用'
  if (runtime?.runtimeError) return '应用未完成'
  if (runtime?.needsRestart || activeCodexTheme.value?.pending) return '待生效'
  return activeCodexTheme.value ? '已选择' : '默认主题'
})

function codexThemePrimaryActionDisabled(item: CodexThemeCatalogItem) {
  return Boolean(codexThemeActionId.value) || (item.active && !item.updateAvailable)
}

function applyCodexThemeActionFeedback(
  result: { runtime?: GaogeDesktopCodexThemeRuntimeStatus; needsRestart?: boolean; applied?: boolean },
  themeId: string,
  name: string,
  verb = '已选择',
) {
  codexThemeRuntime.value = result.runtime || null
  if (codexThemeRuntimeIsApplied(result.runtime, themeId)) {
    notify(`${name} ${verb === '已更新' ? '已更新并应用' : '已应用'}。`, 'success', 'Codex 主题')
  } else if (result.runtime?.runtimeError) {
    notify(`${name} ${verb}，应用未完成：${result.runtime.runtimeError}`, 'warning', 'Codex 主题')
  } else {
    notify(`${name} ${verb}，待 Codex 连接后生效。`, 'info', 'Codex 主题')
  }
}

function invalidateCodexThemeCatalogReads() {
  codexThemeCatalogGeneration += 1
  isCodexThemeCatalogLoading.value = false
}

function codexThemePrimaryActionText(item: CodexThemeCatalogItem) {
  if (codexThemeActionId.value === item.id) {
    if (codexThemeActionType.value === 'download') {
      const progress = codexThemeDownloadProgress.value[item.id] || 0
      return progress > 0 ? `下载中 ${progress}%` : '正在下载'
    }
    if (codexThemeActionType.value === 'apply') return '正在应用'
  }
  if (item.updateAvailable) return '更新'
  if (item.active) return codexThemeRuntimeIsApplied(codexThemeRuntime.value, item.id) ? '已应用' : item.pending || codexThemeRuntime.value?.needsRestart ? '待生效' : '已选择'
  if (item.installed) return '使用'
  return '下载'
}

async function previewCodexThemeDownload(item: CodexThemeCatalogItem) {
  selectedCodexThemeId.value = item.id
  if (codexThemeActionId.value) return
  if (!window.gaogeDesktop?.installCodexTheme || !window.gaogeDesktop?.activateCodexTheme) {
    notify('当前不是桌面环境，无法安装 Codex 主题。', 'error', 'Codex 主题')
    return
  }
  if (!item.installed || item.updateAvailable) {
    invalidateCodexThemeCatalogReads()
    codexThemeActionId.value = item.id
    codexThemeActionType.value = 'download'
    codexThemeDownloadProgress.value = { ...codexThemeDownloadProgress.value, [item.id]: 0 }
    try {
      const result = await window.gaogeDesktop.installCodexTheme(item.id)
      codexThemeCatalog.value = (result.status.themes || []).map(normalizeCodexThemeItem)
      codexThemeRuntime.value = result.runtime || result.status.runtime || null
      codexThemeActiveName.value = codexThemeCatalog.value.find((theme) => theme.active)?.name || ''
      if (item.active) {
        applyCodexThemeActionFeedback({ ...result, runtime: codexThemeRuntime.value || undefined }, item.id, item.name, '已更新')
      } else {
        notify(`${item.name} 已下载，可以使用了。`, 'success', 'Codex 主题')
      }
    } catch (error) {
      reportPageError('codex-theme', 'download-theme', error, { themeId: item.id })
      notify(getErrorMessage(error), 'error', 'Codex 主题')
    } finally {
      codexThemeActionId.value = ''
      codexThemeActionType.value = ''
    }
    return
  }
  if (item.active) return
  invalidateCodexThemeCatalogReads()
  codexThemeActionId.value = item.id
  codexThemeActionType.value = 'apply'
  try {
    const result = await window.gaogeDesktop.activateCodexTheme(item.id)
    applyCodexThemeActionFeedback(result, item.id, item.name)
  } catch (error) {
    reportPageError('codex-theme', 'apply-theme', error, { themeId: item.id })
    notify(getErrorMessage(error), 'error', 'Codex 主题')
  } finally {
    codexThemeActionId.value = ''
    codexThemeActionType.value = ''
    await loadCodexThemeCatalog({ silent: true })
  }
}

async function previewCodexThemeImport() {
  if (codexThemeActionId.value) return
  if (!window.gaogeDesktop?.importCodexTheme) {
    notify('当前不是桌面环境，无法导入主题包。', 'error', 'Codex 主题')
    return
  }
  invalidateCodexThemeCatalogReads()
  codexThemeActionId.value = 'import'
  codexThemeActionType.value = 'import'
  try {
    let result = await window.gaogeDesktop.importCodexTheme()
    if (result.cancelled) return
    if (result.replaceRequired) {
      const replace = await confirmAction(`本机已有“${result.themeName || result.themeId}”，是否用这个 ZIP 替换？`, {
        title: '替换自定义主题',
        confirmText: '确认替换',
        cancelText: '保留原主题',
      })
      if (!replace) return
      result = await window.gaogeDesktop.importCodexTheme({
        filePath: result.filePath,
        replace: true,
      })
    }
    if (result.imported) {
      selectedCodexThemeId.value = result.themeId
      await loadCodexThemeCatalog({ silent: true })
      const importedThemeIndex = codexThemeCatalog.value.findIndex(
        (item) => item.id === result.themeId,
      )
      if (importedThemeIndex >= 0) codexThemeCarouselStart.value = importedThemeIndex
      if (result.runtime?.selectedThemeId === result.themeId) {
        applyCodexThemeActionFeedback(result, result.themeId, result.themeName || '主题', '已更新')
      } else {
        notify('主题包已导入，可以使用了。', 'success', 'Codex 主题')
      }
    }
  } catch (error) {
    reportPageError('codex-theme', 'import-theme', error)
    notify(getErrorMessage(error), 'error', 'Codex 主题')
  } finally {
    codexThemeActionId.value = ''
    codexThemeActionType.value = ''
  }
}

async function restoreNativeCodexTheme() {
  if (!activeCodexTheme.value || codexThemeActionId.value) return
  if (!window.gaogeDesktop?.deactivateCodexTheme) return
  invalidateCodexThemeCatalogReads()
  codexThemeActionId.value = activeCodexTheme.value.id
  codexThemeActionType.value = 'restore'
  try {
    const result = await window.gaogeDesktop.deactivateCodexTheme()
    applyCodexThemeActionFeedback(result, '', 'Codex 默认主题')
  } catch (error) {
    reportPageError('codex-theme', 'restore-native-theme', error)
    notify(getErrorMessage(error), 'error', 'Codex 主题')
  } finally {
    codexThemeActionId.value = ''
    codexThemeActionType.value = ''
    await loadCodexThemeCatalog({ silent: true })
  }
}

function handleCodexThemeDownloadStatus(status: GaogeDesktopCodexThemeDownloadStatus) {
  codexThemeDownloadProgress.value = {
    ...codexThemeDownloadProgress.value,
    [status.themeId]: Math.max(0, Math.min(100, Number(status.progress || 0))),
  }
}

