function buildSoftwareInvitationUrl(token: string) {
  const softwareOrigin = String(getSoftwareOrigin() || '').trim()
  if (!softwareOrigin) throw new Error('未配置软件分享地址，请先选择服务线路。')
  const invitationUrl = new URL('/invite', softwareOrigin)
  invitationUrl.searchParams.set('t', token)
  return invitationUrl.toString()
}

async function loadSoftwareShareUrl() {
  softwareShareUrl.value = ''
  softwareShareError.value = ''
  if (invitationPreviewMode) {
    try { softwareShareUrl.value = buildSoftwareInvitationUrl('preview-signed-invitation-token') }
    catch (error) { softwareShareError.value = getErrorMessage(error) }
    return
  }
  if (!authToken.value) {
    softwareShareError.value = '请先登录后再生成专属邀请链接。'
    return
  }

  isSoftwareShareLoading.value = true
  try {
    const result = await createAffiliateShareToken(authToken.value)
    softwareShareUrl.value = buildSoftwareInvitationUrl(result.token)
  } catch (error) {
    softwareShareError.value = getErrorMessage(error)
    reportPageError('invitation-share', 'create-share-token', error)
  } finally {
    isSoftwareShareLoading.value = false
  }
}

async function copySoftwareShareUrl() {
  if (!softwareShareUrl.value) {
    notify('专属邀请链接暂不可用。', 'warning')
    return
  }
  try {
    await navigator.clipboard.writeText(softwareShareUrl.value)
    notify('专属邀请链接已复制', 'success')
  } catch (error) {
    notify('邀请链接复制失败，请手动复制。', 'error')
    reportPageError('invitation-share', 'copy-share-url', error)
  }
}

async function loadInvitationData(options: { silent?: boolean } = {}) {
  if (!authToken.value) {
    if (!invitationPreviewMode) affiliateDetail.value = null
    return
