  isInvitationLoading.value = true
  invitationError.value = ''
  try {
    const detail = await getAffiliateDetail(authToken.value)
    affiliateDetail.value = detail
    boundInvitationUpstreamId.value = detail.inviter_id ? String(detail.inviter_id) : ''
  } catch (error) {
    invitationError.value = getErrorMessage(error)
    if (!options.silent) notify(invitationError.value, 'error', '我的邀请')
    reportPageError('invitation', 'load-affiliate-detail', error)
  } finally {
    isInvitationLoading.value = false
  }
}

