async function confirmBindInvitationUpstream() {
  const upstreamIdentifier = invitationUpstreamIdInput.value.trim()
  if (boundInvitationUpstreamId.value) {
    notify('当前账号已经绑定邀请人，无法再次变更。', 'warning', '我的邀请')
    return
  }
  if (!upstreamIdentifier) {
    notify('请输入邀请人的账号 ID 或邀请码。', 'warning', '我的邀请')
    return
  }
  if (!/^[A-Za-z0-9_-]{1,32}$/.test(upstreamIdentifier)) {
    notify('请输入有效的账号 ID 或邀请码。', 'warning', '我的邀请')
    return
  }
  const normalizedIdentifier = upstreamIdentifier.toUpperCase()
  const ownAffiliateCode = String(affiliateDetail.value?.aff_code || '').toUpperCase()
  if (
    (invitationCodeCopyable.value && upstreamIdentifier === invitationCode.value)
    || (ownAffiliateCode && normalizedIdentifier === ownAffiliateCode)
  ) {
    notify('不能绑定自己的账号 ID 或邀请码。', 'warning', '我的邀请')
    return
  }
  const confirmed = await confirmAction(`你即将把当前账号绑定到邀请人：${upstreamIdentifier}。`, {
    title: '确认绑定邀请人',
    details: [
      '绑定后邀请关系将永久生效，无法修改、解绑或更换。',
      '后续当前账号产生符合规则的充值时，会按平台规则为该邀请人计算奖励。',
      '账号 ID 与字母邀请码都可以绑定，请确认内容无误后再继续。',
    ],
    dangerDetails: ['绑定关系不可修改；如果填写错误，后续奖励也会归属到错误账号。'],
    confirmText: '确认绑定',
    cancelText: '取消',
    tone: 'warning',
  })
  if (!confirmed) return
  if (!authToken.value) {
    notify('请先登录后再绑定邀请人。', 'warning', '我的邀请')
    return
  }
  isInvitationActionLoading.value = true
  try {
    const detail = await bindAffiliateInviter(upstreamIdentifier, authToken.value)
    affiliateDetail.value = detail
    boundInvitationUpstreamId.value = detail.inviter_id ? String(detail.inviter_id) : upstreamIdentifier
    invitationUpstreamIdInput.value = ''
    notify('邀请人绑定成功，后续仅计算绑定后新创建的在线充值订单。', 'success', '我的邀请')
  } catch (error) {
    notify(getErrorMessage(error), 'error', '我的邀请')
    reportPageError('invitation', 'bind-affiliate-inviter', error)
  } finally {
    isInvitationActionLoading.value = false
  }
}

function openInvitationRewardIntro() {
  const formatPercent = (value: number) => {
    const normalized = Math.round(Number(value || 0) * 100) / 100
    return Number.isInteger(normalized) ? String(normalized) : normalized.toFixed(2).replace(/0+$/, '').replace(/\.$/, '')
  }
  const tierDetails = (affiliateDetail.value?.rebate_tiers || []).map((tier) => {
    const range = tier.max_active_count == null
      ? `${tier.min_active_count} 人及以上`
      : `${tier.min_active_count}-${tier.max_active_count} 人`
    return `生效受邀人数 ${range}：返 ${formatPercent(tier.rate_percent)}%。`
  })
  const currentRate = Number(affiliateDetail.value?.effective_rebate_rate_percent || 0)
  const exampleReward = 60 * currentRate / 100
  void confirmAction('邀请人可根据名下生效受邀人数享受长期充值返利。受邀人每次完成符合规则的支付后，系统会按照当前阶梯比例计算奖励，并立即进入奖励池。', {
    title: '邀请奖励说明',
    details: [
      '生效人数说明：受邀用户累计充值满 ¥20，或通过兑换码累计兑换额度达到 60刀，即视为达标客户。',
      '达标客户最近 15 天内有实际使用记录时计入生效人数；最后使用时间距今超过 15 天即计入失效人数，已经生效的客户同样适用。',
      ...(tierDetails.length > 0 ? tierDetails : ['返利阶梯以后台当前配置为准，请登录后查看实时比例。']),
      `示例：受邀人支付 ¥20，基础到账 60刀并额外赠送 5刀时，赠送额度不参与返利；当前奖励比例为 ${formatPercent(currentRate)}%，邀请人可获得 ${formatPlainAmount(exampleReward)}刀奖励额度。`,
      `选择领取时，奖励将以额度形式发放至账户余额；选择提现时，按 1刀奖励额度 = ¥${formatPlainAmount(invitationWithdrawalCashRate.value)} 折算现金并联系客服人工结算。`,
      '每次符合规则的充值都会重新计算返利，具体结算以后端实际记录为准。',
    ],
    confirmText: '我知道了',
    cancelText: '',
    tone: 'info',
  })
}

