function formatUsageDate(date: Date) {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

function getDefaultUsageDateRange() {
  const end = new Date()
  const start = new Date(end)
  start.setDate(end.getDate() - 6)
  return {
    startDate: formatUsageDate(start),
    endDate: formatUsageDate(end),
  }
}

function setNewThemeLoginMode(mode: NewThemeLoginMode) {
  if (isNewThemeAuthLoading.value) return
  newThemeLoginMode.value = mode
  newThemeAuthNotice.value = ''
  newThemeAuthError.value = ''
}

function hasChineseText(value: string) {
  return /[\u4e00-\u9fa5]/.test(value)
}

type ErrorMessageOptions = {
  notFoundMessage?: string
}

function stripSensitiveErrorText(value: string) {
  return value
    .replace(/(["']?(?:authorization|proxy-authorization|x-api-key|api[_-]?key|access[_-]?token|refresh[_-]?token|id[_-]?token|client[_-]?secret|password|cookie|set-cookie)["']?\s*[:=]\s*)(?:"[^"\r\n]*"|'[^'\r\n]*'|(?:Bearer|Basic)\s+[^\s,;，；}\]\r\n]+|[^\s,;，；}\]\r\n]+)/gi, '$1[已隐藏]')
    .replace(/\b(Bearer|Basic)\s+[A-Za-z0-9._~+/-]+=*/gi, '$1 [已隐藏]')
    .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '[已隐藏]')
    .replace(/https?:\/\/[^\s"'，。；;]+/gi, '服务地址')
    .replace(/[A-Z]:\\[^\s"'，。；;]+/gi, '本地路径')
    .replace(/\/(?:[\w.-]+\/){2,}[\w.-]+/g, '本地路径')
    .replace(/\b(?:sk|ak|pk|sess|token|key)-[A-Za-z0-9_-]{8,}\b/gi, '密钥')
    .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, '账号')
    .replace(/中转站|中转|relay|proxy|base\s*url|endpoint/gi, '服务')
    .trim()
}

function getFriendlyErrorByStatus(status?: number, options: ErrorMessageOptions = {}) {
  if (status === 0) return '网络连接失败，请检查网络后重试。'
  if (status === 400) return '提交内容有误，请检查后重试。'
  if (status === 401) return '登录状态已失效，请重新登录。'
  if (status === 403) return '当前账号暂无此操作权限。'
  if (status === 404) return options.notFoundMessage || '请求的内容不存在或已失效。'
  if (status === 409) return '当前操作与已有数据冲突，请调整后重试。'
  if (status === 422) return '提交内容未通过校验，请检查后重试。'
  if (status === 429) return '操作太频繁，请稍后再试。'
  if (typeof status === 'number' && status >= 500) return '服务暂时开小差了，请稍后再试。'
  return ''
}

function getErrorMessage(error: unknown, options: ErrorMessageOptions = {}) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const statusMessage = getFriendlyErrorByStatus(apiError?.status, options)
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()

  if (statusMessage && (!normalized || /^请求失败[:：]?\s*\d+$/.test(normalized))) return statusMessage
  if (!normalized || /^not found$/i.test(normalized)) return statusMessage || '操作失败，请稍后再试。'
  if (lowerMessage.includes('failed to fetch') || lowerMessage.includes('networkerror') || lowerMessage.includes('network error')) {
    return '网络连接失败，请检查网络后重试。'
  }
  if (lowerMessage.includes('timeout') || lowerMessage.includes('timed out')) return '请求超时，请稍后重试。'
  if (lowerMessage.includes('unauthorized') || lowerMessage.includes('invalid token')) return '登录状态已失效，请重新登录。'
  if (lowerMessage.includes('forbidden')) return '当前账号暂无此操作权限。'
  if (lowerMessage.includes('not found')) return statusMessage || '当前内容不存在或已失效。'
  if (lowerMessage.includes('invalid') && lowerMessage.includes('password')) return '账号或密码不正确，请重新输入。'
  if (lowerMessage.includes('password')) return '密码校验失败，请检查后重试。'
  if (lowerMessage.includes('email')) return '账号格式不正确，请检查后重试。'
  if (
    lowerMessage.includes('redeem code') ||
    lowerMessage.includes('invalid redeem') ||
    normalized.includes('兑换码') ||
    normalized.includes('卡密')
  ) return '兑换码不可用，请检查后重试。'
  if (lowerMessage.includes('permission')) return '当前账号暂无此操作权限。'
  if (lowerMessage.includes('server') || lowerMessage.includes('internal')) return '服务暂时开小差了，请稍后再试。'
  if (!hasChineseText(normalized)) return statusMessage || '操作失败，请稍后再试。'
  return normalized
}

function isNetworkOrTimeoutError(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const lowerMessage = rawMessage.toLowerCase()
  return apiError?.status === 0 ||
    lowerMessage.includes('failed to fetch') ||
    lowerMessage.includes('networkerror') ||
    lowerMessage.includes('network error') ||
    lowerMessage.includes('timeout') ||
    lowerMessage.includes('timed out') ||
    lowerMessage.includes('无法连接') ||
    lowerMessage.includes('请求超时')
}

function isAuthStateError(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const lowerMessage = rawMessage.toLowerCase()
  return apiError?.status === 401 ||
    lowerMessage.includes('unauthorized') ||
    lowerMessage.includes('invalid token') ||
    lowerMessage.includes('token revoked') ||
    lowerMessage.includes('token has been revoked') ||
    lowerMessage.includes('登录状态已失效') ||
    lowerMessage.includes('会话已过期')
}

function isPasswordVerificationError(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()
  return apiError?.code === 'PASSWORD_INCORRECT' ||
    ((lowerMessage.includes('invalid') || lowerMessage.includes('incorrect')) && lowerMessage.includes('password')) ||
    lowerMessage.includes('old_password') ||
    lowerMessage.includes('current_password') ||
    lowerMessage.includes('old password') ||
    lowerMessage.includes('current password') ||
    normalized.includes('原密码')
}

function handleThemeLogoError(event: Event) {
  const image = event.target as HTMLImageElement | null
  if (image && image.src !== gaogeUserAvatarLogo) {
    image.src = gaogeUserAvatarLogo
  }
}

function getImage2GenerationErrorMessage(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const statusMessage = getFriendlyErrorByStatus(apiError?.status, {
    notFoundMessage: '生图服务暂不可用，请稍后重试。',
  })
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()

  if (normalized.includes(IMAGE2_BUSY_MESSAGE)) return IMAGE2_BUSY_MESSAGE
  if (normalized.includes('读取参考图失败')) return '参考图读取失败，请重新选择参考图后再试。'
  if (normalized.includes('参考图格式无效')) return '参考图格式无效，请使用 PNG、JPG 或 WEBP 图片。'
  if (normalized.includes('图片数据解析失败')) return '生图结果解析失败，请稍后重试。'
  if (normalized.includes('生图服务没有返回图片')) return '生图服务没有返回图片，请稍后重试。'
  if (normalized.includes('保存生成图片失败')) return '生成图片保存失败，请检查保存位置后重试。'
  if (normalized.includes('下载生成图片失败')) return '生成图片下载失败，请稍后重试。'

  if (lowerMessage.includes('concurrency limit') || lowerMessage.includes('concurrent')) {
    return '生图通道当前并发已满，请稍后再试。'
  }
  if (lowerMessage.includes('rate limit') || lowerMessage.includes('too many requests')) {
    return '生图请求触发限速，请稍后再试。'
  }
  if (
    lowerMessage.includes('temporarily unavailable') ||
    lowerMessage.includes('service unavailable') ||
    lowerMessage.includes('upstream request failed') ||
    lowerMessage.includes('upstream service') ||
    lowerMessage.includes('http 503') ||
    lowerMessage.includes('status 503')
  ) {
    return '生图上游暂时不可用，请稍后重试。'
  }
  if (lowerMessage.includes('insufficient_quota') || lowerMessage.includes('quota')) {
    return '生图额度暂时不可用，请稍后重试或联系客服处理。'
  }
  if (lowerMessage.includes('content policy') || lowerMessage.includes('safety')) {
    return '提示词或参考图未通过安全检查，请调整后重试。'
  }
  if (lowerMessage.includes('invalid') && lowerMessage.includes('size')) {
    return '当前图片尺寸不被生图服务支持，请换一个尺寸后重试。'
  }
  if (lowerMessage.includes('invalid') && lowerMessage.includes('quality')) {
    return '当前清晰度参数不被生图服务支持，请换一个清晰度后重试。'
  }
  if (
    (lowerMessage.includes('invalid') || lowerMessage.includes('unsupported')) &&
    lowerMessage.includes('image')
  ) {
    return '参考图不被生图服务支持，请换一张 PNG、JPG 或 WEBP 图片。'
  }
  if (lowerMessage.includes('image too large') || lowerMessage.includes('file too large')) {
    return '参考图文件过大，请压缩后重试。'
  }
  if (normalized.includes('生图服务返回格式无效')) {
    const detail = normalized.replace(/^.*?生图服务返回格式无效[:：]?\s*/u, '').trim()
    return detail
      ? `生图服务返回格式异常：${detail}`
      : '生图服务返回格式异常，请稍后重试。'
  }
  return getErrorMessage(error, {
    notFoundMessage: statusMessage || '生图服务暂不可用，请稍后重试。',
  })
}

function getSmsReceiverErrorMessage(error: unknown, options: ErrorMessageOptions = {}) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()

  if (
    normalized.includes('鲁班') ||
    normalized.includes('服务列表') ||
    normalized.includes('确认价格')
  ) return '未获取号码'
  if (
    lowerMessage.includes('service_id') ||
    lowerMessage.includes('serviceid') ||
    (lowerMessage.includes('service') && (lowerMessage.includes('required') || lowerMessage.includes('invalid')))
  ) return '接码服务编号缺失或无效，请刷新国家列表后再取号。'
  if (lowerMessage.includes('apikey') || lowerMessage.includes('api key')) {
    return '接码服务密钥配置不正确，请联系售后处理。'
  }
  if (lowerMessage.includes('balance') || lowerMessage.includes('insufficient') || normalized.includes('余额不足')) {
    return '接码服务余额不足，请联系售后处理。'
  }
  if (
    lowerMessage.includes('wrong_status') ||
    lowerMessage.includes('timeout') ||
    lowerMessage.includes('time out') ||
    normalized.includes('超时')
  ) return '该号码已超时或不可继续接收短信，请重新取号。'
  if (
    lowerMessage.includes('no number') ||
    lowerMessage.includes('not available') ||
    lowerMessage.includes('out of stock') ||
    normalized.includes('暂无号码') ||
    normalized.includes('无可用号码')
  ) return '当前国家暂时没有可用号码，请换个国家或稍后再试。'

  return getErrorMessage(error, options)
}

function getAccountProfileErrorMessage(error: unknown) {
  return getErrorMessage(error, {
    notFoundMessage: '账号资料保存接口暂不可用，请稍后重试或联系售后。',
  })
}

function getChangePasswordErrorMessage(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? apiError.message.trim()
    : typeof error === 'string'
      ? error.trim()
      : ''
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()

  if (
    lowerMessage.includes('authorization') ||
    lowerMessage.includes('unauthorized') ||
    lowerMessage.includes('invalid token')
  ) {
    return '登录状态已失效，请重新登录后再修改密码。'
  }
  if ((lowerMessage.includes('invalid') || lowerMessage.includes('incorrect')) && lowerMessage.includes('password')) {
    return '原密码错误，请重新输入。'
  }
  if (
    lowerMessage.includes('old_password') ||
    lowerMessage.includes('current_password') ||
    lowerMessage.includes('old password') ||
    lowerMessage.includes('current password') ||
    normalized.includes('原密码')
  ) {
    return '原密码错误，请重新输入。'
  }
  if (lowerMessage.includes('new_password') || normalized.includes('新密码')) {
    return '新密码不符合要求，请检查后重试。'
  }
  if (lowerMessage.includes('password') || normalized.includes('密码')) {
    return '原密码错误或新密码不符合要求，请检查后重试。'
  }
  if (apiError?.status === 404 || apiError?.status === 405) {
    return '修改密码接口暂不可用，请稍后重试或联系售后。'
  }

  return getErrorMessage(error, {
    notFoundMessage: '修改密码接口暂不可用，请稍后重试或联系售后。',
  })
}

function getRedeemCodeErrorMessage(error: unknown, label = '兑换码') {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string' ? apiError.message.trim() : ''
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()
  if (lowerMessage.includes('expired')) return `${label}已过期。`
  if (lowerMessage.includes('used') || lowerMessage.includes('already redeemed')) return `${label}已被使用。`
  if (
    apiError?.status === 404 ||
    lowerMessage.includes('redeem code not found') ||
    lowerMessage.includes('invalid redeem') ||
    lowerMessage.includes('invalid code') ||
    lowerMessage.includes('code not found') ||
    normalized.includes('兑换码') ||
    normalized.includes('卡密')
  ) {
    return `${label}错误。`
  }
  return getErrorMessage(error, { notFoundMessage: `${label}错误。` })
}

function getRegisterErrorMessage(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string' ? apiError.message.trim() : ''
  const normalized = stripSensitiveErrorText(rawMessage)
  const lowerMessage = normalized.toLowerCase()
  if (
    apiError?.status === 409 ||
    lowerMessage.includes('already exists') ||
    lowerMessage.includes('email exists') ||
    normalized.includes('已存在')
  ) {
    return '该邮箱已注册，请直接登录。'
  }
  if (lowerMessage.includes('registration') && (lowerMessage.includes('disabled') || lowerMessage.includes('closed'))) {
    return '当前暂未开放注册，请联系售后处理。'
  }
  if (lowerMessage.includes('password')) return '密码至少需要 6 位，请检查后重试。'
  if (lowerMessage.includes('email')) return '邮箱格式不正确，请检查后重试。'
  return getErrorMessage(error)
}

