function getPlatformSubscriptionActivationErrorMessage(error: unknown) {
  const apiError = error as ApiError
  const rawMessage = typeof apiError?.message === 'string'
    ? stripSensitiveErrorText(apiError.message).trim()
    : ''
  const lowerMessage = rawMessage.toLowerCase()
  if (apiError?.status === 409) {
    if (lowerMessage.includes('amount mismatch')) {
      return '支付已完成，但支付订单金额与平台套餐金额不一致，后台会继续自动重试；如果仍未到账，请联系售后处理。'
    }
    if (lowerMessage.includes('user mismatch')) {
      return '支付已完成，但支付订单账号与当前账号不一致，请联系售后核对订单。'
    }
    if (lowerMessage.includes('not paid')) {
      return '正在等待支付平台同步成功，稍后会自动重试。'
    }
    if (lowerMessage.includes('another active') || lowerMessage.includes('active platform subscription')) {
      return '当前账号已有其他平台订阅，后台未确认本次覆盖请求，请刷新订阅状态后重试。'
    }
  }
  return getPaymentErrorMessage(error)
}

type PlatformSubscriptionSubmitStage = 'create-payment' | 'register-subscription' | 'render-payment'

function getPlatformSubscriptionSubmitErrorMessage(
  error: unknown,
  actionContext: PlatformSubscriptionActionContext,
  stage: PlatformSubscriptionSubmitStage,
) {
  const apiError = error as ApiError
  if (apiError?.status === 409 && actionContext.subscription_action === 'replace') {
    return `当前账号已有「${actionContext.current_plan_name || '平台订阅'}」，桌面端已提交覆盖请求，但后台仍返回已有订阅冲突。请先升级软件后台平台订阅接口支持套餐覆盖后再重试。`
  }
  if (apiError?.status === 409 && actionContext.subscription_action === 'renew') {
    return '当前套餐续期请求与后台已有订单冲突，请刷新订阅状态后重试。'
  }
  const message = getPaymentErrorMessage(error)
  if (stage === 'register-subscription') return `订阅订单登记失败：${message}`
  if (stage === 'render-payment') return `支付信息加载失败：${message}`
  return `支付订单创建失败：${message}`
}

