function isMacReadOnlyUpdateError(error?: string) {
  const text = String(error || '')
  return (
    text.includes('macOS 安装镜像') ||
    text.includes('只读位置') ||
    text.includes('只读文件系统') ||
    text.includes('Read-only file system') ||
    text.includes('os error 30')
  )
}

function notificationTitle(tone: NotificationTone) {
  if (tone === 'success') return '操作成功'
  if (tone === 'error') return '操作失败'
  if (tone === 'warning') return '请确认'
  return '提示'
}

function shouldSuppressNotification(message: string, tone: NotificationTone) {
  if (tone !== 'error') return false
  const compactMessage = stripSensitiveErrorText(message).replace(/\s+/g, '')
  return compactMessage.includes('登录状态已失效') ||
    compactMessage.includes('会话已过期，请重新登录')
}

function getNotificationCooldownKey(message: string, tone: NotificationTone) {
  if (tone !== 'error') return ''
  const compactMessage = stripSensitiveErrorText(message).replace(/\s+/g, '')
  if (
    compactMessage.includes('网络连接失败') ||
    compactMessage.includes('无法连接到GaogeAI服务器') ||
    compactMessage.includes('无法链接到GaogeAI服务器') ||
    compactMessage.includes('请求超时')
  ) {
    return 'api-connection-error'
  }
  return ''
}

function shouldThrottleNotification(message: string, tone: NotificationTone) {
  const key = getNotificationCooldownKey(message, tone)
  if (!key) return false
  const now = Date.now()
  const lastShownAt = notificationCooldowns.get(key) || 0
  if (now - lastShownAt < CONNECTION_ERROR_NOTIFICATION_COOLDOWN_MS) return true
  notificationCooldowns.set(key, now)
  return false
}

function notify(message: string, tone: NotificationTone = 'info', title = notificationTitle(tone)) {
  const text = stripSensitiveErrorText(message).trim()
  if (!text) return
  if (shouldSuppressNotification(text, tone)) return
  if (shouldThrottleNotification(text, tone)) return
  const id = ++notificationSeed
  appNotifications.value = [
    ...appNotifications.value.filter((item) => item.message !== text),
    { id, tone, title, message: text },
  ].slice(-4)
  window.setTimeout(() => {
    appNotifications.value = appNotifications.value.map((item) => (
      item.id === id ? { ...item, leaving: true } : item
    ))
  }, 1800)
  window.setTimeout(() => {
    appNotifications.value = appNotifications.value.filter((item) => item.id !== id)
  }, 2200)
}

function confirmAction(message: string, options: Partial<Omit<ConfirmDialogState, 'open' | 'message'>> = {}) {
  if (confirmResolve) {
    confirmResolve(false)
    confirmResolve = null
  }
  const details = Array.isArray(options.details)
    ? options.details.map((item) => stripSensitiveErrorText(item).trim()).filter(Boolean)
    : []
  const dangerDetails = Array.isArray(options.dangerDetails)
    ? options.dangerDetails.map((item) => stripSensitiveErrorText(item).trim()).filter(Boolean)
    : []
  confirmDialog.value = {
    open: true,
    tone: options.tone || 'warning',
    title: options.title || '操作确认',
    message: stripSensitiveErrorText(message),
    details,
    dangerDetails,
    confirmText: options.confirmText || '确认',
    cancelText: options.cancelText ?? '取消',
  }
  return new Promise<boolean>((resolve) => {
    confirmResolve = resolve
  })
}

function closeConfirmDialog(confirmed: boolean) {
  if (!confirmDialog.value.open) return
  confirmDialog.value = { ...confirmDialog.value, open: false }
  confirmResolve?.(confirmed)
  confirmResolve = null
}

function openCodexOperationDialog(
  title: string,
  message = '正在处理中',
  detail = '',
): CodexOperationHandle {
  const operationId = ++codexOperationDialogSeed
  removeCodexLoginProgressListener?.()
  removeCodexLoginProgressListener = null
  if (codexOperationElapsedTimer !== null) {
    window.clearInterval(codexOperationElapsedTimer)
    codexOperationElapsedTimer = null
  }
  codexOperationStartedAt = monotonicNow()
  codexOperationDialog.value = {
    open: true,
    title,
    message,
    detail: detail || formatCodexOperationElapsed(0, message),
  }
  const refreshElapsed = () => {
    if (operationId !== codexOperationDialogSeed || !codexOperationDialog.value.open) return
    const currentMessage = codexOperationDialog.value.message
    codexOperationDialog.value = {
      ...codexOperationDialog.value,
      detail: formatCodexOperationElapsed(monotonicNow() - codexOperationStartedAt, currentMessage),
    }
  }
  refreshElapsed()
  codexOperationElapsedTimer = window.setInterval(refreshElapsed, 250)
  removeCodexLoginProgressListener = window.gaogeDesktop?.onCodexLoginProgress?.((status) => {
    if (operationId !== codexOperationDialogSeed || !codexOperationDialog.value.open) return
    codexOperationDialog.value = {
      ...codexOperationDialog.value,
      message: status.message,
    }
    // Backend progress events describe stages, but they are sparse and may
    // arrive with a clock that starts before/after the UI operation. The UI's
    // monotonic timer remains the single source of truth for elapsed time.
    refreshElapsed()
  }) || null
  return {
    update(patch) {
      if (operationId !== codexOperationDialogSeed) return
      codexOperationDialog.value = {
        ...codexOperationDialog.value,
        ...patch,
        open: true,
      }
      refreshElapsed()
    },
    close() {
      if (operationId !== codexOperationDialogSeed) return
      removeCodexLoginProgressListener?.()
      removeCodexLoginProgressListener = null
      if (codexOperationElapsedTimer !== null) {
        window.clearInterval(codexOperationElapsedTimer)
        codexOperationElapsedTimer = null
      }
      codexOperationStartedAt = 0
      codexOperationDialog.value = {
        ...codexOperationDialog.value,
        open: false,
      }
      codexOperationDialogSeed += 1
    },
  }
}

function showForgotPasswordDialog() {
  void confirmAction('忘记密码请联系售后 QQ 1944773240 人工处理。', {
    tone: 'info',
    title: '忘记密码',
    confirmText: '知道了',
    cancelText: '',
  })
}

let codexLoginNotificationDepth = 0
const codexLoginDiagnostics = ref<{ action: string; messages: string[] }>({ action: '', messages: [] })

function beginCodexLoginFeedback() {
  codexLoginNotificationDepth += 1
  stopCodexUltraStatusCheck()
  let finished = false
  return () => {
    if (finished) return
    finished = true
    codexLoginNotificationDepth = Math.max(0, codexLoginNotificationDepth - 1)
  }
}

function recordCodexLoginDiagnostics(
  action: string,
  result?: GaogeDesktopCodexLaunchFeedback | null,
  messages: Array<string | undefined> = [],
) {
  const feedback = codexRuntimeFeedback(result)
  const details = [...new Set([
    ...codexLaunchWarningMessages(result), feedback.notice, feedback.warning, ...messages,
  ].filter((message): message is string => typeof message === 'string' && Boolean(message.trim()))
    .map((message) => stripSensitiveErrorText(message).trim()))]
  codexLoginDiagnostics.value = { action, messages: details }
  // Login notifications describe the operation only. Runtime verification remains
  // owned by the background watcher and is available in developer diagnostics.
  if (details.length) console.debug('[Codex login diagnostics]', action, details)
}

function codexLoginFailureDetails(error: unknown) {
  let value: unknown = error
  if (typeof value === 'string' && value.trim().startsWith('{')) {
    try { value = JSON.parse(value) } catch { /* Preserve a plain native error. */ }
  }
  const object = value && typeof value === 'object' ? value as Record<string, unknown> : null
  const nested = object?.error && typeof object.error === 'object'
    ? object.error as Record<string, unknown> : null
  const scalar = (candidate: unknown) => typeof candidate === 'string' || typeof candidate === 'number'
    ? String(candidate).trim() : ''
  const reason = scalar(nested?.reason) || scalar(nested?.message) || scalar(object?.reason)
    || scalar(object?.message) || scalar(object?.error_description) || scalar(object?.error)
    || (typeof value === 'string' ? value.trim() : '')
  const code = scalar(nested?.code) || scalar(object?.code) || scalar(object?.errorCode)
    || scalar(object?.status) || reason.match(/^(CODEX_[A-Z0-9_]+)(?::|：|\s|$)/)?.[1] || ''
  return {
    code: stripSensitiveErrorText(code),
    reason: stripSensitiveErrorText(reason || '操作未完成，未收到具体错误原因。'),
  }
}

async function showCodexLoginFailure(error: unknown, fuel = false) {
  const failure = codexLoginFailureDetails(error)
  await confirmAction(failure.reason, {
    tone: 'error', title: fuel ? '加油失败' : '登录失败',
    details: failure.code ? [`错误码：${failure.code}`] : [],
    confirmText: '知道了', cancelText: '',
  })
}

function watchFeedback(source: Ref<string>, tone: NotificationTone, quietDuringLogin = false) {
  watch(source, (message) => {
    if (!message || (quietDuringLogin && codexLoginNotificationDepth > 0)) return
    notify(message, tone)
  }, quietDuringLogin ? { flush: 'sync' } : {})
}

function watchFeedbackGetter(source: () => string, tone: NotificationTone, quietDuringLogin = false) {
  watch(source, (message) => {
    if (!message || (quietDuringLogin && codexLoginNotificationDepth > 0)) return
    notify(message, tone)
  }, quietDuringLogin ? { flush: 'sync' } : {})
}

function reportPageError(feature: string, action: string, error: unknown, metadata: Record<string, unknown> = {}) {
  reportFeatureError(feature, action, error, {
    page: activePage.value,
    metadata,
  })
}

function getCardRedeemErrorMessage(error: unknown) {
  return getRedeemCodeErrorMessage(error, '卡密')
}

function getRandomText(length = 10) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789'
  const bytes = new Uint8Array(length)
  window.crypto?.getRandomValues?.(bytes)
  return Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join('')
}

function createDesktopAccountCredentials() {
  const stamp = Date.now().toString(36)
  const suffix = getRandomText(10)
  return {
    email: `desk-${stamp}-${suffix}@${desktopRegistrationEmailDomain(readFrontendDeploymentValue('VITE_GAOGE_DESKTOP_EMAIL_DOMAIN'))}`,
    password: DESKTOP_INITIAL_PASSWORD,
  }
}

function shouldFallbackToLegacyRedeem(error: unknown) {
  const apiError = error as ApiError
  if (apiError?.status === 404) return true
  if (apiError?.status !== 401 && apiError?.status !== 403) return false

  const message = typeof apiError.message === 'string' ? apiError.message : ''
  return message.includes('请先登录后台') || message.includes('后台')
}

function normalizeDesktopAuth(response: DesktopRedeemRegisterResponse): {
  auth: AuthResponse
  password: string
} {
  const auth = response.auth || (
    response.access_token && response.user
      ? {
          access_token: response.access_token,
          refresh_token: response.refresh_token,
          expires_in: response.expires_in,
          token_type: response.token_type,
          user: response.user,
        }
      : null
  )
  if (!auth) throw new Error('兑换注册接口返回缺少登录 token。')
  const password = response.password || response.account?.password || DESKTOP_INITIAL_PASSWORD
  const email = response.email || response.account?.email
  if (email) auth.user.email = email
  if (typeof response.new_balance === 'number') auth.user.balance = response.new_balance
  return { auth, password }
}

function decodeJwtExpiresAt(token: string) {
  try {
    const [, payload] = token.split('.')
    if (!payload) return 0
    const normalized = payload.replace(/-/g, '+').replace(/_/g, '/')
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, '=')
    const parsed = JSON.parse(window.atob(padded)) as { exp?: unknown }
    const exp = Number(parsed.exp)
    return Number.isFinite(exp) && exp > 0 ? exp * 1000 : 0
  } catch {
    return 0
  }
}

function persistAuthExpiry(accessToken: string, expiresIn?: number, explicitExpiresAt?: number) {
  const expiresAt = explicitExpiresAt ||
    (Number.isFinite(Number(expiresIn)) && Number(expiresIn) > 0 ? Date.now() + Number(expiresIn) * 1000 : 0) ||
    decodeJwtExpiresAt(accessToken)
  if (expiresAt > 0) {
    localStorage.setItem(AUTH_TOKEN_EXPIRES_AT_STORAGE_KEY, String(expiresAt))
  } else {
    localStorage.removeItem(AUTH_TOKEN_EXPIRES_AT_STORAGE_KEY)
  }
  return expiresAt
}

function readAuthExpiresAt() {
  const stored = Number(localStorage.getItem(AUTH_TOKEN_EXPIRES_AT_STORAGE_KEY) || 0)
  if (Number.isFinite(stored) && stored > 0) return stored
  const decoded = decodeJwtExpiresAt(authToken.value)
  if (decoded > 0) localStorage.setItem(AUTH_TOKEN_EXPIRES_AT_STORAGE_KEY, String(decoded))
  return decoded
}

function normalizeAuthSessionUser(value: unknown): ApiUser | null {
  if (!value || typeof value !== 'object') return null
  const user = value as Partial<ApiUser>
  const id = Number(user.id)
  const email = String(user.email || '').trim()
  if (!Number.isFinite(id) || !email) return null
  return {
    ...user,
    id,
    email,
    balance: Number(user.balance) || 0,
  } as ApiUser
}

async function savePersistentAuthSession(request: GaogeDesktopAuthSessionRequest) {
  if (!window.gaogeDesktop?.saveAuthSession || !request.accessToken) return
  try {
    await window.gaogeDesktop.saveAuthSession({
      ...request,
      persist: rememberPassword.value,
      apiBaseUrl: getCurrentApiBaseUrl(),
    })
  } catch (error) {
    reportPageError('auth', 'save-auth-session', error)
  }
}

async function readPersistentAuthSession() {
  if (!window.gaogeDesktop?.getAuthSession) return null
  try {
    return await window.gaogeDesktop.getAuthSession()
  } catch (error) {
    reportPageError('auth', 'read-auth-session', error)
    return null
  }
}

function persistAuthSessionLocally(session: GaogeDesktopAuthSessionResponse) {
  if (!session.saved || !session.accessToken) return false
  authToken.value = session.accessToken
  localStorage.setItem('gaoge_desktop_auth_token', session.accessToken)
  if (session.refreshToken) {
    refreshToken.value = session.refreshToken
    localStorage.setItem('gaoge_desktop_refresh_token', session.refreshToken)
  }
  persistAuthExpiry(session.accessToken, session.expiresIn, Number(session.expiresAt) || undefined)
  const user = normalizeAuthSessionUser(session.user)
  if (user) applyAuthenticatedUserState(user)
  return true
}

function applyRefreshedAuthTokens(detail: DesktopAuthRefreshEventDetail) {
  if (!detail.accessToken) return
  authToken.value = detail.accessToken
  localStorage.setItem('gaoge_desktop_auth_token', detail.accessToken)
  if (detail.refreshToken) {
    refreshToken.value = detail.refreshToken
    localStorage.setItem('gaoge_desktop_refresh_token', detail.refreshToken)
  }
  const expiresAt = persistAuthExpiry(detail.accessToken, detail.expiresIn, detail.expiresAt)
  void savePersistentAuthSession({
    accessToken: detail.accessToken,
    refreshToken: detail.refreshToken || refreshToken.value,
    expiresAt,
    expiresIn: detail.expiresIn,
    tokenType: detail.tokenType,
    user: authUser.value,
  })
}

function clearAuthRefreshTimer() {
  if (authRefreshTimer !== null) {
    window.clearTimeout(authRefreshTimer)
    authRefreshTimer = null
  }
}

function stopAuthRefreshScheduler() {
  clearAuthRefreshTimer()
  authRefreshInFlight = false
  authRefreshRetryCount = 0
}

function scheduleAuthRefresh(delayMs?: number) {
  clearAuthRefreshTimer()
  if (!isNewThemeAuthenticated.value || !authToken.value || !refreshToken.value) return

  const expiresAt = readAuthExpiresAt()
  const naturalDelay = expiresAt > 0
    ? expiresAt - Date.now() - AUTH_REFRESH_EARLY_MS
    : AUTH_REFRESH_FALLBACK_INTERVAL_MS
  const delay = Math.max(AUTH_REFRESH_MIN_DELAY_MS, delayMs ?? naturalDelay)
  authRefreshTimer = window.setTimeout(() => {
    void refreshAuthSession({ reason: 'timer' })
  }, delay)
}

function scheduleAuthRefreshRetry() {
  const delay = Math.min(
    AUTH_REFRESH_RETRY_MAX_MS,
    AUTH_REFRESH_RETRY_BASE_MS * 2 ** Math.min(authRefreshRetryCount, 5),
  )
  scheduleAuthRefresh(delay)
}

function shouldRefreshAuthNow(force = false) {
  if (force) return true
  const expiresAt = readAuthExpiresAt()
  return expiresAt <= 0 || expiresAt - Date.now() <= AUTH_REFRESH_EARLY_MS
}

async function refreshAuthSession(options: { force?: boolean; reason?: string } = {}) {
  if (!isNewThemeAuthenticated.value || !authToken.value || !refreshToken.value) return false
  if (authRefreshInFlight) return false
  if (!shouldRefreshAuthNow(options.force === true)) {
    scheduleAuthRefresh()
    return false
  }

  const now = Date.now()
  if (!options.force && now - lastAuthRefreshAttemptAt < AUTH_REFRESH_MIN_ATTEMPT_INTERVAL_MS) {
    scheduleAuthRefresh(AUTH_REFRESH_MIN_ATTEMPT_INTERVAL_MS - (now - lastAuthRefreshAttemptAt))
    return false
  }

  authRefreshInFlight = true
  lastAuthRefreshAttemptAt = now
  try {
    const refreshed = await refreshDesktopAuthToken()
    applyRefreshedAuthTokens({
      accessToken: refreshed.access_token,
      refreshToken: refreshed.refresh_token,
      expiresIn: refreshed.expires_in,
      tokenType: refreshed.token_type,
    })
    authRefreshRetryCount = 0
    scheduleAuthRefresh()
    return true
  } catch (error) {
    const status = (error as ApiError)?.status
    if (status === 0 || status === 429 || typeof status !== 'number' || status >= 500) {
      authRefreshRetryCount += 1
      scheduleAuthRefreshRetry()
    } else {
      stopAuthRefreshScheduler()
    }
    reportPageError('auth', `refresh-session-${options.reason || 'background'}`, error)
    return false
  } finally {
    authRefreshInFlight = false
  }
}

function refreshAuthSessionIfNeeded(reason: string) {
  if (!isNewThemeAuthenticated.value || !authToken.value || !refreshToken.value) return
  if (shouldRefreshAuthNow(false)) {
    void refreshAuthSession({ reason })
  } else {
    scheduleAuthRefresh()
  }
}

function handleDesktopAuthRefreshed(event: Event) {
  const detail = (event as CustomEvent<DesktopAuthRefreshEventDetail>).detail
  if (!detail) return
  applyRefreshedAuthTokens(detail)
  authRefreshRetryCount = 0
  scheduleAuthRefresh()
}

function handleAuthRefreshVisibilityChange() {
  if (document.visibilityState === 'visible') refreshAuthSessionIfNeeded('visible')
}

function handleAuthRefreshOnline() {
  void refreshAuthSession({ force: true, reason: 'online' })
  void resumePendingRechargeBonusQueue({ force: true, includeBlocked: true })
  void resumePendingOfficialSubscriptionOrders()
}

function persistAuth(response: AuthResponse, password?: string) {
  authToken.value = response.access_token
  refreshToken.value = response.refresh_token || ''
  applyAuthenticatedUserState(response.user)
  savedPassword.value = password || savedPassword.value
  localStorage.setItem('gaoge_desktop_auth_token', response.access_token)
  const expiresAt = persistAuthExpiry(response.access_token, response.expires_in)
  if (response.refresh_token) {
    localStorage.setItem('gaoge_desktop_refresh_token', response.refresh_token)
  } else {
    localStorage.removeItem('gaoge_desktop_refresh_token')
  }
  void savePersistentAuthSession({
    accessToken: response.access_token,
    refreshToken: response.refresh_token,
    expiresAt,
    expiresIn: response.expires_in,
    tokenType: response.token_type,
    user: response.user,
  })
}

function clearLocalAuthState() {
  stopDesktopAnnouncementPolling()
  stopPendingRechargeBonusRetryTimer()
  aggregateApiKeyCache.clear()
  aggregateApiKeyRequests.clear()
  aggregateGroupModelResults.value = {}
  aggregateGroupLoading.value = {}
  aggregateGroupKeyReady.value = {}
  aggregateGroupKeyErrors.value = {}
  aggregateConnectionTests.value = {}
  selectedAggregateProviderId.value = ''
  authToken.value = ''
  refreshToken.value = ''
  authUser.value = null
  clearPaymentPanelDismissTimer()
  hidePaymentPanel()
  resetInvoiceUiState()
  invoiceTitles.value = []
  invoiceOrders.value = []
  invoiceApplications.value = []
  officialSubscriptionRecords.value = []
  activeOfficialSubscriptionRequest.value = null
  officialSubscriptionRecoveryOrders.value = []
  officialIdentifiedAccount.value = null
  officialSessionTextInput.value = ''
  activePlatformSubscription.value = null
  platformSubscriptionSummary.value = null
  activePlatformSubscriptionOrderId.value = ''
  stopAuthRefreshScheduler()
  localStorage.removeItem('gaoge_desktop_auth_token')
  localStorage.removeItem('gaoge_desktop_refresh_token')
  localStorage.removeItem(AUTH_TOKEN_EXPIRES_AT_STORAGE_KEY)
  localStorage.removeItem('gaoge_desktop_user')
}

function persistAuthPreferences() {
  if (autoLogin.value && !rememberPassword.value) rememberPassword.value = true
  localStorage.setItem(REMEMBER_PASSWORD_STORAGE_KEY, String(rememberPassword.value))
  localStorage.setItem(AUTO_LOGIN_STORAGE_KEY, String(autoLogin.value && rememberPassword.value))
}

async function rememberLocalLogin(email: string, password?: string) {
  persistAuthPreferences()
  if (!rememberPassword.value) {
    autoLogin.value = false
    persistAuthPreferences()
    await window.gaogeDesktop?.clearSavedLogin?.().catch(() => undefined)
    return
  }
  autoLogin.value = true
  persistAuthPreferences()
  if (!window.gaogeDesktop?.saveLocalLogin || !password) return
  try {
    await window.gaogeDesktop.saveLocalLogin({
      email,
      password,
      rememberPassword: true,
      autoLogin: true,
    })
  } catch (error) {
    reportPageError('auth', 'save-local-login', error)
    dashboardNotice.value = '本地账号密码保存失败，下次可能需要重新登录。'
  }
}

async function handleRememberPasswordChange() {
  if (rememberPassword.value) {
    autoLogin.value = true
  } else {
    autoLogin.value = false
    savedPassword.value = ''
    if (!isNewThemeAuthenticated.value) newThemeLoginPassword.value = ''
    await window.gaogeDesktop?.clearSavedLogin?.().catch(() => undefined)
    await window.gaogeDesktop?.clearAuthSession?.().catch(() => undefined)
  }
  persistAuthPreferences()
}

async function readSavedLogin() {
  if (!window.gaogeDesktop?.getSavedLogin) return null
  try {
    const saved = await window.gaogeDesktop.getSavedLogin()
    if (saved.email) newThemeLoginAccount.value = saved.email
    if (saved.password) {
      newThemeLoginPassword.value = saved.password
      savedPassword.value = saved.password
    }
    if (saved.saved) {
      rememberPassword.value = saved.rememberPassword ?? true
      autoLogin.value = Boolean(saved.autoLogin && rememberPassword.value)
      persistAuthPreferences()
    }
    return saved
  } catch (error) {
    reportPageError('auth', 'read-saved-login', error)
    return null
  }
}

async function finishAuthenticated(response: AuthResponse, password?: string) {
  persistAuth(response, password)
  loadInvoiceLocalData()
  loadOfficialSubscriptionRecords()
  restorePlatformSubscriptionFromCache()
  void syncInvoiceApplications({ silent: true })
  await rememberLocalLogin(response.user.email, password)
  isNewThemeAuthenticated.value = true
  activePage.value = '仪表盘'
  setDesktopWindowLayout('app')
  scheduleAuthRefresh()
  refreshNewThemeDataInBackground()
  startDesktopAnnouncementPolling()
  void resumePendingRechargeBonusQueue({ force: true, includeBlocked: true })
  void resumePendingOfficialSubscriptionOrders()
}

async function restoreSessionFromToken(savedPasswordValue?: string) {
  if (!authToken.value) return false
  const current = await getCurrentUser(authToken.value)
  applyAuthenticatedUserState(current)
  savedPassword.value = savedPasswordValue || savedPassword.value
  void savePersistentAuthSession({
    accessToken: authToken.value,
    refreshToken: refreshToken.value,
    expiresAt: readAuthExpiresAt(),
    user: current,
  })
  loadInvoiceLocalData()
  loadOfficialSubscriptionRecords()
  restorePlatformSubscriptionFromCache()
  void syncInvoiceApplications({ silent: true })
  isNewThemeAuthenticated.value = true
  setDesktopWindowLayout('app')
  scheduleAuthRefresh()
  refreshNewThemeDataInBackground()
  startDesktopAnnouncementPolling()
  void resumePendingRechargeBonusQueue({ force: true, includeBlocked: true })
  void resumePendingOfficialSubscriptionOrders()
  return true
}

async function restoreSessionFromPersistentAuthSession(
  session: GaogeDesktopAuthSessionResponse | null,
  savedPasswordValue?: string,
) {
  if (!session?.saved || !session.accessToken) return false
  if (!persistAuthSessionLocally(session)) return false

  try {
    await restoreSessionFromToken(savedPasswordValue)
    newThemeAuthNotice.value = '已恢复更新前的登录状态。'
    return true
  } catch (error) {
    if (!session.refreshToken) {
      clearLocalAuthState()
      return false
    }

    try {
      const refreshed = await refreshDesktopAuthToken()
      applyRefreshedAuthTokens({
        accessToken: refreshed.access_token,
        refreshToken: refreshed.refresh_token,
        expiresIn: refreshed.expires_in,
        tokenType: refreshed.token_type,
      })
      await restoreSessionFromToken(savedPasswordValue)
      newThemeAuthNotice.value = '已刷新并恢复更新前的登录状态。'
      return true
    } catch (refreshError) {
      clearLocalAuthState()
      reportPageError('auth', 'restore-persistent-auth-session', refreshError || error)
      return false
    }
  }
}

async function restoreSessionFromSavedLogin(saved: GaogeDesktopSavedLoginResponse | null) {
  if (!saved?.saved || !saved.email || !saved.password || !saved.autoLogin) return false
  const response = await loginWithPassword(saved.email, saved.password)
  if (isTotpRequired(response)) {
    newThemeLoginMode.value = 'account'
    newThemeAuthError.value = '当前账号开启了 2FA，桌面端暂未接入二次验证。'
    return true
  }
  await finishAuthenticated(response, saved.password)
  newThemeAuthNotice.value = '已使用本地保存账号自动登录。'
  return true
}

async function restoreSavedSession() {
  const saved = await readSavedLogin()
  const savedAuthSession = await readPersistentAuthSession()
  if (!authToken.value && !savedAuthSession?.saved && !saved?.autoLogin) {
    setDesktopWindowLayout('login')
    return
  }

  isNewThemeAuthLoading.value = true
  newThemeAuthNotice.value = '正在恢复登录状态...'
  try {
    if (authToken.value) {
      try {
        await restoreSessionFromToken(saved?.password)
        newThemeAuthNotice.value = ''
        return
      } catch {
        clearLocalAuthState()
      }
    }

    if (await restoreSessionFromPersistentAuthSession(savedAuthSession, saved?.password)) {
      newThemeAuthNotice.value = ''
      return
    }

    if (await restoreSessionFromSavedLogin(saved)) {
      newThemeAuthNotice.value = ''
      return
    }
  } catch (error) {
    newThemeLoginMode.value = 'account'
    newThemeAuthError.value = getErrorMessage(error)
  } finally {
    isNewThemeAuthLoading.value = false
    if (!isNewThemeAuthenticated.value) setDesktopWindowLayout('login')
  }
}

async function submitNewThemeAuth() {
  if (isNewThemeAuthLoading.value) return
  newThemeAuthError.value = ''
  newThemeAuthNotice.value = ''
  if (runtimeConfigUnavailable.value) {
    newThemeAuthError.value = '服务器配置不可用，请先刷新服务器或检查网络。'
    return
  }
  const mode = newThemeLoginMode.value
  isNewThemeAuthLoading.value = true
  try {
    if (mode === 'account') {
      const email = newThemeLoginAccount.value.trim()
      const password = newThemeLoginPassword.value
      if (!email || !password) {
        newThemeAuthError.value = '请输入账号和密码。'
        return
      }
      const response = await loginWithPassword(email, password)
      if (isTotpRequired(response)) {
        newThemeAuthError.value = '当前账号开启了 2FA，桌面端暂未接入二次验证。'
        return
      }
      await finishAuthenticated(response, password)
      newThemeAuthNotice.value = '登录成功，已同步账户信息。'
      return
    }

    if (mode === 'register') {
      const email = newThemeRegisterEmail.value.trim()
      const password = newThemeRegisterPassword.value
      const confirmPassword = newThemeRegisterConfirmPassword.value
      if (!email || !password || !confirmPassword) {
        newThemeAuthError.value = '请完整填写邮箱、密码和确认密码。'
        return
      }
      if (password.length < 6) {
        newThemeAuthError.value = '密码至少需要 6 位。'
        return
      }
      if (password !== confirmPassword) {
        newThemeAuthError.value = '两次输入的密码不一致。'
        return
      }
      const response = await registerWithPassword({ email, password })
      if (isTotpRequired(response)) {
        newThemeAuthError.value = '当前账号开启了 2FA，桌面端暂未接入二次验证。'
        return
      }
      newThemeLoginAccount.value = email
      newThemeLoginPassword.value = password
      await finishAuthenticated(response, password)
      newThemeAuthNotice.value = '注册成功，已进入账户。'
      return
    }

    const code = newThemeRedeemCode.value.trim()
    if (!code) {
      newThemeAuthError.value = '请输入兑换码。'
      return
    }

    try {
      const response = await redeemAndRegister(code, DESKTOP_INITIAL_PASSWORD)
      const { auth, password } = normalizeDesktopAuth(response)
      await finishAuthenticated(auth, password)
      newThemeAuthNotice.value = '兑换成功，账户已自动创建并同步余额。'
      showRedeemSecurityDialog.value = true
      return
    } catch (error) {
      if (!shouldFallbackToLegacyRedeem(error)) throw error
    }

    const credentials = createDesktopAccountCredentials()
    const auth = await registerWithPassword(credentials)
    if (isTotpRequired(auth)) {
      newThemeAuthError.value = '当前账号开启了 2FA，桌面端暂未接入二次验证。'
      return
    }
    const redeemResult = await redeemCode(code, auth.access_token)
    if (typeof redeemResult.new_balance === 'number') auth.user.balance = redeemResult.new_balance
    await finishAuthenticated(auth, credentials.password)
    newThemeAuthNotice.value = redeemResult.message || '兑换成功，账户已自动创建并同步余额。'
    showRedeemSecurityDialog.value = true
  } catch (error) {
    newThemeAuthError.value = mode === 'register'
      ? getRegisterErrorMessage(error)
      : mode === 'redeem'
        ? getRedeemCodeErrorMessage(error)
        : getErrorMessage(error)
  } finally {
    isNewThemeAuthLoading.value = false
  }
}

async function handleNewThemeLogout() {
  const saved = rememberPassword.value ? await readSavedLogin() : null
  const rememberedEmail = saved?.email || authUser.value?.email || newThemeLoginAccount.value
  const rememberedPassword = saved?.password || savedPassword.value || newThemeLoginPassword.value
  autoLogin.value = false
  persistAuthPreferences()
  if (rememberPassword.value && rememberedEmail && rememberedPassword) {
    await window.gaogeDesktop?.saveLocalLogin?.({
      email: rememberedEmail,
      password: rememberedPassword,
      rememberPassword: true,
      autoLogin: false,
    }).catch(() => undefined)
  } else {
    await window.gaogeDesktop?.clearSavedLogin?.().catch(() => undefined)
  }
  stopPaymentPolling()
  stopDesktopAnnouncementPolling()
  clearLocalAuthState()
  await window.gaogeDesktop?.clearAuthSession?.().catch(() => undefined)
  isNewThemeAuthenticated.value = false
  isNewThemeAuthLoading.value = false
  newThemeAuthNotice.value = ''
  newThemeAuthError.value = ''
  openUserMenu.value = false
  isCollapsed.value = false
  activePage.value = '仪表盘'
  usageRows.value = []
  dashboardStats.value = null
  connectedTools.value = {
    codex: false,
    claude: localStorage.getItem(CLAUDE_CONFIGURED_STORAGE_KEY) === 'true',
  }
  compatibleKeys.value = { codex: '', claude: '', image2: '' }
  setDesktopWindowLayout('login')
}

async function openUpgradeUnavailableDialog() {
  openUserMenu.value = false
  await confirmAction('当前暂未开通升级服务，感谢您的支持，请关注后续开放。', {
    tone: 'info',
    title: '服务暂未开放',
    confirmText: '知道了',
    cancelText: '',
  })
}

function resetAccountSettingsForm() {
  accountProfileForm.value = {
    email: authUser.value?.email || user.value.email,
    username: authUser.value?.username || user.value.name,
  }
  passwordForm.value = {
    oldPassword: '',
    newPassword: '',
    confirmPassword: '',
  }
  accountSettingsError.value = ''
  accountSettingsNotice.value = ''
}

function openAccountSettingsDialog() {
  resetAccountSettingsForm()
  showAccountSettingsDialog.value = true
  openUserMenu.value = false
}

function closeAccountSettingsDialog() {
  showAccountSettingsDialog.value = false
  accountSettingsError.value = ''
  accountSettingsNotice.value = ''
}

function normalizeAccountEmail(email?: string | null) {
  return String(email || '').trim().toLowerCase()
}

function applyAuthenticatedUserState(current: ApiUser) {
  authUser.value = current
  localStorage.setItem('gaoge_desktop_user', JSON.stringify(current))
  if (current.email?.trim()) {
    newThemeLoginAccount.value = current.email.trim()
  }
}

function createAccountEmailMismatchError(requestedEmail: string, actualEmail?: string | null) {
  const actual = actualEmail?.trim() || '空'
  return new Error(`服务端已返回成功，但账号邮箱仍是 ${actual}，没有变成 ${requestedEmail}。请确认软件后台账号修改中转接口和 sub2 管理员接口配置。`)
}

type AccountChangeResult = {
  user: ApiUser
  passwordChanged: boolean
  authRecovered: boolean
  warning?: string
}

async function rememberChangedLoginPassword(email: string, password: string) {
  savedPassword.value = password
  newThemeLoginPassword.value = password
  await rememberLocalLogin(email, password)
}

async function loginWithChangedPassword(email: string, password: string): Promise<AccountChangeResult> {
  const response = await loginWithPassword(email, password)
  if (isTotpRequired(response)) {
    await rememberChangedLoginPassword(email, password)
    const current = {
      ...(authUser.value || user.value),
      email,
    } as ApiUser
    applyAuthenticatedUserState(current)
    return {
      user: current,
      passwordChanged: true,
      authRecovered: false,
      warning: '密码已修改，新密码已同步本地保存；当前账号开启了 2FA，请下次使用新密码手动登录。',
    }
  }
  persistAuth(response, password)
  await rememberChangedLoginPassword(response.user.email || email, password)
  return {
    user: response.user,
    passwordChanged: true,
    authRecovered: true,
  }
}

async function loginWithChangedPasswordCandidates(
  primaryEmail: string,
  password: string,
  extraEmails: Array<string | undefined | null> = [],
): Promise<AccountChangeResult> {
  const emails = [
    primaryEmail,
    ...extraEmails,
    authUser.value?.email,
    user.value.email,
    newThemeLoginAccount.value,
  ]
    .map((email) => String(email || '').trim())
    .filter(Boolean)
  const candidates = Array.from(new Set(emails))
  let lastError: unknown = null

  for (const email of candidates) {
    try {
      const result = await loginWithChangedPassword(email, password)
      if (normalizeAccountEmail(email) !== normalizeAccountEmail(primaryEmail)) {
        return {
          ...result,
          warning: '密码已修改并已用新密码重新登录；邮箱 / 账号修改可能未完成，请确认后再保存一次账号信息。',
        }
      }
      return result
    } catch (error) {
      lastError = error
      if (isNetworkOrTimeoutError(error)) throw error
    }
  }

  throw lastError || new Error('无法使用新密码恢复登录。')
}

async function submitAndVerifyAccountChange(payload: {
  email: string
  username: string
  oldPassword?: string
  newPassword?: string
  loginPassword?: string
}, shouldVerifyEmail: boolean): Promise<AccountChangeResult> {
  const fallbackPassword = payload.newPassword || payload.loginPassword || ''
  let result: Awaited<ReturnType<typeof submitAccountChange>>
  try {
    result = await submitAccountChange({
      email: payload.email,
      username: payload.username || undefined,
      old_password: payload.oldPassword || undefined,
      current_password: payload.oldPassword || undefined,
      new_password: payload.newPassword || undefined,
      login_password: fallbackPassword || undefined,
    }, authToken.value)
  } catch (error) {
    const newLoginPassword = payload.newPassword || ''
    const canRecoverPasswordChange = Boolean(newLoginPassword) && (
      isNetworkOrTimeoutError(error) ||
      isAuthStateError(error) ||
      isPasswordVerificationError(error)
    )
    if (canRecoverPasswordChange) {
      try {
        return await loginWithChangedPasswordCandidates(payload.email, newLoginPassword)
      } catch (loginError) {
        if (isNetworkOrTimeoutError(error) && isNetworkOrTimeoutError(loginError)) {
          await rememberChangedLoginPassword(payload.email, newLoginPassword)
          const current = {
            ...(authUser.value || user.value),
            email: payload.email,
            username: payload.username || authUser.value?.username || user.value.name,
          } as ApiUser
          applyAuthenticatedUserState(current)
          return {
            user: current,
            passwordChanged: true,
            authRecovered: false,
            warning: '密码修改请求已提交，但网络中断导致无法确认登录状态；新密码已保存，网络恢复后会优先使用新密码登录。',
          }
        }
      }
    }
    throw error
  }

  const passwordChanged = Boolean(payload.newPassword && result.passwordChanged !== false)
  const resultEmail = result.user?.email || payload.email

  if (result.auth?.access_token) {
    persistAuth(result.auth, fallbackPassword || undefined)
    if (passwordChanged && payload.newPassword) {
      await rememberChangedLoginPassword(result.auth.user.email || resultEmail, payload.newPassword)
    }
    return {
      user: result.auth.user,
      passwordChanged,
      authRecovered: true,
    }
  }

  const localUser = {
    ...(authUser.value || user.value),
    ...result.user,
    email: result.user?.email || payload.email,
    username: result.user?.username || payload.username,
  } as ApiUser

  if (passwordChanged && payload.newPassword) {
    await rememberChangedLoginPassword(resultEmail, payload.newPassword)
  }

  if (fallbackPassword) {
    try {
      const response = await loginWithPassword(resultEmail, fallbackPassword)
      if (!isTotpRequired(response)) {
        persistAuth(response, fallbackPassword)
        if (passwordChanged && payload.newPassword) {
          await rememberChangedLoginPassword(response.user.email || resultEmail, payload.newPassword)
        }
        return {
          user: response.user,
          passwordChanged,
          authRecovered: true,
        }
      }
      if (passwordChanged) {
        return {
          user: localUser,
          passwordChanged,
          authRecovered: false,
          warning: '密码已修改，新密码已同步本地保存；当前账号开启了 2FA，请下次使用新密码手动登录。',
        }
      }
      return {
        user: localUser,
        passwordChanged,
        authRecovered: false,
      }
    } catch (error) {
      if (!passwordChanged || !payload.newPassword) throw error
      applyAuthenticatedUserState(localUser)
      return {
        user: localUser,
        passwordChanged: true,
        authRecovered: false,
        warning: isNetworkOrTimeoutError(error)
          ? '密码已修改，新密码已同步本地保存；网络恢复后会优先使用新密码重新登录。'
          : '密码已修改，新密码已同步本地保存；自动刷新登录状态失败，请重新打开软件后继续使用。',
      }
    }
  }

  applyAuthenticatedUserState(localUser)

  let current = localUser
  try {
    current = await getCurrentUser(authToken.value)
  } catch {
    return {
      user: localUser,
      passwordChanged,
      authRecovered: false,
    }
  }
  if (shouldVerifyEmail && normalizeAccountEmail(current.email) !== normalizeAccountEmail(payload.email)) {
    throw createAccountEmailMismatchError(payload.email, current.email)
  }

  applyAuthenticatedUserState(current)
  return {
    user: current,
    passwordChanged,
    authRecovered: true,
  }
}

async function saveAccountProfile() {
  if (isAccountProfileSaving.value) return
  const email = accountProfileForm.value.email.trim()
  const username = accountProfileForm.value.username.trim()
  const currentEmail = (authUser.value?.email || user.value.email || '').trim()
  const shouldUpdateEmail = normalizeAccountEmail(email) !== normalizeAccountEmail(currentEmail)
  if (!email) {
    accountSettingsError.value = '请输入账号邮箱。'
    return
  }
  accountSettingsError.value = ''
  accountSettingsNotice.value = ''
  isAccountProfileSaving.value = true
  try {
    const current = await submitAndVerifyAccountChange({
      email,
      username,
      loginPassword: savedPassword.value || newThemeLoginPassword.value || undefined,
    }, shouldUpdateEmail)
    if (savedPassword.value) {
      await rememberLocalLogin(current.user.email || email, savedPassword.value)
    }
    accountSettingsNotice.value = '账号信息已更新。'
  } catch (error) {
    accountSettingsError.value = getAccountProfileErrorMessage(error)
  } finally {
    isAccountProfileSaving.value = false
  }
}

async function changeAccountPasswordAndRefreshSession(payload: {
  currentEmail: string
  requestedEmail: string
  oldPassword: string
  newPassword: string
}) {
  const loginPrimaryEmail = payload.currentEmail || payload.requestedEmail
  const loginExtraEmails = [payload.requestedEmail]
  try {
    await changePassword({
      old_password: payload.oldPassword,
      current_password: payload.oldPassword,
      new_password: payload.newPassword,
    }, authToken.value)
  } catch (error) {
    if (!isAuthStateError(error) && !isPasswordVerificationError(error) && !isNetworkOrTimeoutError(error)) {
      throw error
    }

    try {
      const recovered = await loginWithChangedPasswordCandidates(
        loginPrimaryEmail,
        payload.newPassword,
        loginExtraEmails,
      )
      return {
        ...recovered,
        warning: recovered.warning || '密码已修改并已用新密码重新登录。',
      }
    } catch (loginError) {
      if (isNetworkOrTimeoutError(error) && isNetworkOrTimeoutError(loginError)) {
        await rememberChangedLoginPassword(loginPrimaryEmail, payload.newPassword)
        const current = {
          ...(authUser.value || user.value),
          email: loginPrimaryEmail,
        } as ApiUser
        applyAuthenticatedUserState(current)
        return {
          user: current,
          passwordChanged: true,
          authRecovered: false,
          warning: '密码修改请求已提交，但网络中断导致无法确认登录状态；新密码已保存，网络恢复后会优先使用新密码登录。',
        }
      }
      throw error
    }
  }

  return loginWithChangedPasswordCandidates(loginPrimaryEmail, payload.newPassword, loginExtraEmails)
}

async function submitAccountSettingsChange() {
  if (isAccountProfileSaving.value || isAccountPasswordSaving.value) return
  const originalEmail = authUser.value?.email || user.value.email
  const oldPassword = passwordForm.value.oldPassword
  const newPassword = passwordForm.value.newPassword
  const confirmPassword = passwordForm.value.confirmPassword
  const email = accountProfileForm.value.email.trim()
  const username = accountProfileForm.value.username.trim()
  const currentEmail = (authUser.value?.email || user.value.email || '').trim()
  const currentUsername = (authUser.value?.username || user.value.name || '').trim()
  const shouldChangePassword = Boolean(newPassword || confirmPassword)
  const shouldUpdateEmail = normalizeAccountEmail(email) !== normalizeAccountEmail(currentEmail)
  const shouldUpdateUsername = username !== currentUsername
  const shouldUpdateProfile = shouldUpdateEmail || shouldUpdateUsername
  if (!email) {
    accountSettingsError.value = '请输入账号邮箱。'
    return
  }
  if (shouldChangePassword && (!oldPassword || !newPassword || !confirmPassword)) {
    accountSettingsError.value = '请完整填写原密码、新密码和确认密码。'
    return
  }
  if (shouldChangePassword && newPassword !== confirmPassword) {
    accountSettingsError.value = '两次输入的新密码不一致。'
    return
  }
  if (shouldChangePassword && newPassword.length < 6) {
    accountSettingsError.value = '新密码至少需要 6 位。'
    return
  }
  if (!shouldUpdateProfile && !shouldChangePassword) {
    accountSettingsError.value = ''
    accountSettingsNotice.value = '没有需要保存的修改。'
    return
  }

  accountSettingsError.value = ''
  accountSettingsNotice.value = ''
  isAccountProfileSaving.value = shouldUpdateProfile
  isAccountPasswordSaving.value = shouldChangePassword
  try {
    let loginEmail = currentEmail || email || originalEmail
    let activePassword = savedPassword.value
    let pendingPasswordNotice = ''

    if (shouldChangePassword) {
      try {
        const passwordChange = await changeAccountPasswordAndRefreshSession({
          currentEmail: currentEmail || originalEmail,
          requestedEmail: email,
          oldPassword,
          newPassword,
        })
        loginEmail = passwordChange.user.email || currentEmail || email || loginEmail
        activePassword = newPassword
        pendingPasswordNotice = passwordChange.warning || ''
      } catch (error) {
        accountSettingsError.value = getChangePasswordErrorMessage(error)
        return
      }
    }

    if (shouldChangePassword) {
      savedPassword.value = newPassword
      newThemeLoginPassword.value = newPassword
      await rememberLocalLogin(loginEmail, newPassword)
    }

    if (shouldUpdateProfile) {
      try {
        const accountChange = await submitAndVerifyAccountChange({
          email,
          username,
          loginPassword: activePassword || newThemeLoginPassword.value || undefined,
        }, shouldUpdateEmail)
        loginEmail = accountChange.user.email || email || loginEmail
        if (activePassword) {
          await rememberLocalLogin(loginEmail, activePassword)
        }
        if (accountChange.warning) {
          accountSettingsNotice.value = accountChange.warning
        } else {
          pendingPasswordNotice = ''
        }
      } catch (error) {
        if (shouldChangePassword) {
          accountSettingsNotice.value = pendingPasswordNotice || '密码已修改并已同步本地保存；账号信息保存失败，请稍后在账户设置里重新保存。'
        } else {
          accountSettingsError.value = getAccountProfileErrorMessage(error)
          return
        }
      }
    } else if (activePassword) {
      await rememberLocalLogin(loginEmail || authUser.value?.email || email, activePassword)
    }

    if (!accountSettingsNotice.value && pendingPasswordNotice) {
      accountSettingsNotice.value = pendingPasswordNotice
    }

    passwordForm.value = {
      oldPassword: '',
      newPassword: '',
      confirmPassword: '',
    }
    const successMessage = accountSettingsNotice.value || (shouldChangePassword
      ? shouldUpdateProfile
        ? '账号信息和密码已更新，已同步本地登录保存。'
        : '密码已更新，已同步本地登录保存。'
      : '账号信息已更新。')
    if (accountSettingsNotice.value) {
      notify(successMessage, accountSettingsNotice.value.includes('失败') || accountSettingsNotice.value.includes('中断') ? 'warning' : 'success')
    } else {
      closeAccountSettingsDialog()
      notify(successMessage, 'success')
    }
  } catch (error) {
    accountSettingsError.value = getErrorMessage(error)
  } finally {
    isAccountProfileSaving.value = false
    isAccountPasswordSaving.value = false
  }
}

function confirmRedeemSecurityPrompt() {
  showRedeemSecurityDialog.value = false
  openAccountSettingsDialog()
}

async function refreshNewThemeData(options: { silent?: boolean } = {}) {
  const silent = options.silent === true
  await syncGroups({ silent })
  await Promise.allSettled([
    syncCurrentUser({ silent }),
    activePage.value === '仪表盘'
      ? syncUsageDashboardStats({ silent: true })
      : Promise.resolve(),
    loadOnlinePaymentConfig({ silent: true }),
    loadPlatformSubscriptionPlans(),
    syncActivePlatformSubscription({ silent: true }),
    loadApiKeys({ silent: true }),
    loadCodexRouterStatus({ silent: true }),
    loadCodexAccounts({ silent }),
    loadCodexSessionStats(),
    loadCodexInstallStatus(),
    loadUpdateStatus(),
  ])
  await loadCompatibleAccessKeys({ silent })
}

function refreshNewThemeDataInBackground() {
  void refreshNewThemeData({ silent: true }).catch((error) => {
    reportPageError('dashboard', 'refresh-new-theme-data', error)
  })
}

function isImage2Group(group: Group) {
  const platform = String(group.platform || '').toLowerCase()
  const name = String(group.name || '').toLowerCase()
  return platform === 'openai' && (
    Number(group.id) === IMAGE2_GROUP_FALLBACK_ID ||
    name.includes('image2') ||
    name.includes('image-2') ||
    name.includes('gpt-image')
  )
}

function isGrokGroup(group: Group) {
  const platform = String(group.platform || '').trim().toLowerCase()
  const name = String(group.name || '').trim().toLowerCase()
  return platform === 'grok' || platform === 'xai' || /(?:^|[^a-z0-9])(gork|grok)(?:[^a-z0-9]|$)/i.test(name)
}

function isKimiGroup(group: Group) {
  const platform = String(group.platform || '').trim().toLowerCase()
  const name = String(group.name || '').trim().toLowerCase()
  return platform === 'kimi'
    || platform === 'moonshot'
    || /(?:^|[^a-z0-9])(kimi|moonshot)(?:[^a-z0-9]|$)/i.test(name)
}

function isDeepSeekGroup(group: Group) {
  const platform = String(group.platform || '').trim().toLowerCase()
  const name = String(group.name || '').trim().toLowerCase()
  return platform === 'deepseek'
    || /(?:^|[^a-z0-9])deep[\s_-]*seek(?:[^a-z0-9]|$)/i.test(name)
}

function isGlmGroup(group: Group) {
  const platform = String(group.platform || '').trim().toLowerCase()
  const name = String(group.name || '').trim().toLowerCase()
  return ['glm', 'zhipu', 'bigmodel', 'zai', 'z.ai'].includes(platform)
    || /(?:glm|zhipu|bigmodel|z[\s._-]*ai|智谱)/i.test(name)
}

function formatGroupRateMultiplier(value?: number | null) {
  const multiplier = Number(value)
  if (!Number.isFinite(multiplier) || multiplier <= 0) return '倍率未配置'
  const normalized = multiplier.toFixed(3).replace(/\.?0+$/, '')
  return `${normalized}x 倍率`
}

function formatGroupRateValue(value?: number | null) {
  const multiplier = Number(value)
  if (!Number.isFinite(multiplier) || multiplier <= 0) return ''
  return `${multiplier.toFixed(3).replace(/\.?0+$/, '')}x`
}

function isAvailableGroupEnabled(group: Group) {
  const record = group as unknown as Record<string, unknown>
  const explicitFlags: unknown[] = [record.enabled, record.is_active, record.is_enabled]
  if (explicitFlags.some((value) => (
    value === false || value === 0 || ['0', 'false', 'inactive', 'disabled', 'off'].includes(String(value).trim().toLowerCase())
  ))) return false
  const status = String(record.status || '').trim().toLowerCase()
  return !['0', 'inactive', 'disabled', 'closed', 'off'].includes(status)
}

function aggregateStateKeysForGroups(groupOptions: GroupOption[]) {
  const keys = new Set<string>()
  for (const provider of aggregateProviderDefinitions) {
    if (!provider.available || !provider.tool || !provider.groupType) continue
    for (const group of groupOptions) {
      if (group.type === provider.groupType) {
        keys.add(aggregateGroupStateKey(provider.id, group.id))
      }
    }
  }
  return keys
}

function pruneAggregateRecord<T>(record: Record<string, T>, activeKeys: Set<string>) {
  return Object.fromEntries(
    Object.entries(record).filter(([key]) => activeKeys.has(key)),
  ) as Record<string, T>
}

function aggregateStateKeyFromScopedCacheKey(cacheKey: string) {
  const parts = cacheKey.split(':')
  return parts.length >= 2 ? parts.slice(-2).join(':') : ''
}

function pruneInactiveAggregateGroupState(activeKeys: Set<string>) {
  aggregateGroupModelResults.value = pruneAggregateRecord(aggregateGroupModelResults.value, activeKeys)
  aggregateGroupLoading.value = pruneAggregateRecord(aggregateGroupLoading.value, activeKeys)
  aggregateGroupKeyReady.value = pruneAggregateRecord(aggregateGroupKeyReady.value, activeKeys)
  aggregateGroupKeyErrors.value = pruneAggregateRecord(aggregateGroupKeyErrors.value, activeKeys)
  aggregateConnectionTests.value = pruneAggregateRecord(aggregateConnectionTests.value, activeKeys)
  for (const cacheKey of Array.from(aggregateApiKeyCache.keys())) {
    if (!activeKeys.has(aggregateStateKeyFromScopedCacheKey(cacheKey))) {
      aggregateApiKeyCache.delete(cacheKey)
    }
  }
  for (const cacheKey of Array.from(aggregateApiKeyRequests.keys())) {
    if (!activeKeys.has(aggregateStateKeyFromScopedCacheKey(cacheKey))) {
      aggregateApiKeyRequests.delete(cacheKey)
    }
  }
  if (
    selectedAggregateProviderId.value &&
    !Array.from(activeKeys).some((key) => key.startsWith(`${selectedAggregateProviderId.value}:`))
  ) {
    selectedAggregateProviderId.value = ''
  }
}

function toGroupOption(group: Group): GroupOption | null {
  const platform = String(group.platform || '').toLowerCase()
  const type: GroupType | null = isGrokGroup(group)
    ? 'grok'
    : isKimiGroup(group)
      ? 'kimi'
      : isDeepSeekGroup(group)
        ? 'deepseek'
        : isGlmGroup(group)
          ? 'glm'
          : platform === 'openai'
            ? isImage2Group(group) ? 'image2' : 'codex'
            : platform === 'anthropic' ? 'claude' : null
  if (!type) return null
  const rateMultiplier = Number(group.rate_multiplier)
  const normalizedRate = Number.isFinite(rateMultiplier) && rateMultiplier > 0 ? rateMultiplier : null
  return {
    id: group.id,
    name: group.name,
    type,
    platform,
    badge: type === 'codex'
      ? 'Codex'
      : type === 'image2'
        ? 'Image2'
        : type === 'grok'
          ? 'Grok'
          : type === 'kimi'
            ? 'Kimi'
            : type === 'deepseek'
              ? 'DeepSeek'
              : type === 'glm'
                ? 'GLM'
                : 'Claude',
    rateMultiplier: normalizedRate,
    rateText: formatGroupRateMultiplier(normalizedRate),
  }
}

function updateSelectedGroups() {
  ;(['codex', 'claude'] as ToolKey[]).forEach((tool) => {
    const toolGroups = getToolGroups(tool)
    if (toolGroups.length === 0) {
      selectedGroup.value[tool] = 0
      return
    }
    const selected = toolGroups.find((group) => group.id === selectedGroup.value[tool])
    if (!selected) selectedGroup.value[tool] = toolGroups[0].id
  })
  const tool = activeTool.value
  if (tool) {
    const selected = getToolGroups(tool).find((group) => group.id === selectedGroup.value[tool])
    selectedLoginGroup.value = selected?.name || getToolGroups(tool)[0]?.name || ''
    if (tool === 'claude' && claudeModelsGroupId.value !== selectedGroup.value.claude) {
      claudeModelOptions.value = []
      claudeModelsGroupId.value = null
      selectedLoginModel.value = '自动匹配'
    }
  }
}

async function syncGroups(options: { silent?: boolean; throwOnError?: boolean } = {}) {
  if (!authToken.value) return
  const silent = options.silent === true
  if (!silent) dashboardError.value = ''
  try {
    const available = await getAvailableGroups(authToken.value)
    const mapped = available
      .filter(isAvailableGroupEnabled)
      .map(toGroupOption)
      .filter((group): group is GroupOption => Boolean(group))
    groups.value = mapped
    pruneInactiveAggregateGroupState(aggregateStateKeysForGroups(mapped))
    updateSelectedGroups()
    ensureSelectedApiKeyGroup()
  } catch (error) {
    if (!silent) {
      reportPageError('dashboard', 'sync-groups', error)
      dashboardError.value = getGroupErrorMessage(error)
    }
    if (options.throwOnError) throw error
  }
}

function ensureSelectedApiKeyGroup() {
  if (apiKeyGroupOptions.value.some((group) => group.id === selectedApiKeyGroupId.value)) return
  selectedApiKeyGroupId.value = apiKeyGroupOptions.value[0]?.id || 0
}

async function loadApiKeys(options: { silent?: boolean } = {}) {
  const silent = options.silent === true
  if (!silent) apiKeysError.value = ''
  if (!silent) apiKeysNotice.value = ''
  if (!authToken.value) {
    if (!silent) apiKeysError.value = '请先登录账户。'
    return
  }
  isApiKeysLoading.value = true
  try {
    await syncGroups({ silent })
    ensureSelectedApiKeyGroup()
    const result = await getApiKeys(authToken.value, { page: 1, pageSize: 100 })
    apiKeys.value = result.items
    if (!silent) apiKeysNotice.value = `已读取 ${result.items.length} 个 Key。`
  } catch (error) {
    reportPageError('api-keys', 'load-api-keys', error)
    if (!silent) apiKeysError.value = getApiKeyErrorMessage(error)
  } finally {
    isApiKeysLoading.value = false
  }
}

async function createNewApiKey() {
  apiKeysError.value = ''
  apiKeysNotice.value = ''
  if (!authToken.value) {
    apiKeysError.value = '请先登录账户。'
    return
  }
  if (apiKeyGroupOptions.value.length === 0) await syncGroups()
  const group = selectedApiKeyGroup.value
  if (!group) {
    apiKeysError.value = '请先选择可用分组。'
    return
  }
  const name = newApiKeyName.value.trim() || `${group.badge} Key`
  isApiKeysLoading.value = true
  try {
    const created = await createApiKey(name, group.id, authToken.value)
    newApiKeyName.value = ''
    selectedApiKeyGroupId.value = group.id
    apiKeys.value = [created, ...apiKeys.value.filter((item) => item.id !== created.id)]
    visibleApiKeyIds.value = { ...visibleApiKeyIds.value, [created.id]: true }
    await loadApiKeys({ silent: true })
    apiKeysNotice.value = `已创建 Key：${created.name || name}。`
  } catch (error) {
    reportPageError('api-keys', 'create-api-key', error, { groupId: group.id })
    apiKeysError.value = getGroupErrorMessage(error)
  } finally {
    isApiKeysLoading.value = false
  }
}

async function syncCurrentUser(options: { silent?: boolean } = {}) {
  if (!authToken.value) return
  try {
    const current = await getCurrentUser(authToken.value)
    applyAuthenticatedUserState(current)
  } catch (error) {
    if (!options.silent) {
      reportPageError('dashboard', 'sync-current-user', error)
      dashboardError.value = getDashboardErrorMessage(error)
    }
  }
}

function getPlatformSubscriptionOwnerParams() {
  const user = authUser.value
  return {
    userId: user?.id,
    email: typeof user?.email === 'string' ? user.email : '',
  }
}

async function ensurePlatformSubscriptionOwnerParams(options: { silent?: boolean } = {}) {
  let owner = getPlatformSubscriptionOwnerParams()
  if (!owner.userId && !owner.email && authToken.value) {
    await syncCurrentUser(options)
    owner = getPlatformSubscriptionOwnerParams()
  }
  return owner
}

function applyPlatformSubscriptionState(payload: PlatformSubscriptionMyResponse) {
  activePlatformSubscription.value = normalizeActiveSubscriptionPayload(payload.subscription)
  platformSubscriptionSummary.value = {
    active_count: activePlatformSubscription.value ? 1 : 0,
    subscriptions: (payload.subscriptions || []) as SubscriptionSummaryItem[],
  }
  writePlatformSubscriptionCache(payload)
}

async function syncPlatformSubscriptionState(options: { silent?: boolean } = {}) {
  if (!authToken.value) {
    activePlatformSubscription.value = null
    platformSubscriptionSummary.value = null
    return
  }
  if (!options.silent) {
    platformSubscriptionError.value = ''
  }
  if (!platformSubscriptionStateSyncPromise) {
    platformSubscriptionStateSyncPromise = (async () => {
      const owner = await ensurePlatformSubscriptionOwnerParams(options)
      if (!owner.userId && !owner.email) {
        if (!restorePlatformSubscriptionFromCache()) {
          activePlatformSubscription.value = null
          platformSubscriptionSummary.value = null
        }
        return
      }
      const payload = await getMyPlatformSubscriptionFromSoftwareAdmin(owner, authToken.value)
      applyPlatformSubscriptionState(payload)
    })().finally(() => {
      platformSubscriptionStateSyncPromise = null
    })
  }
  try {
    await platformSubscriptionStateSyncPromise
  } catch (error) {
    const status = (error as ApiError)?.status
    const restoredFromCache = restorePlatformSubscriptionFromCache()
    if (!restoredFromCache) {
      activePlatformSubscription.value = null
      platformSubscriptionSummary.value = null
    }
    if (status === 404) return
    reportPageError('platform-subscription', 'sync-platform-subscription-state', error)
    if (!options.silent) {
      const message = getErrorMessage(error, {
        notFoundMessage: '当前暂无平台订阅。',
      })
      platformSubscriptionError.value = restoredFromCache
        ? `${message} 已显示本机缓存的订阅信息。`
        : message
    }
  }
}

async function syncActivePlatformSubscription(options: { silent?: boolean } = {}) {
  await syncPlatformSubscriptionState(options)
}

async function syncPlatformSubscriptionSummary(options: { silent?: boolean } = {}) {
  await syncPlatformSubscriptionState(options)
}

async function refreshPlatformSubscriptionInfo(options: { silent?: boolean } = {}) {
  const isManualRefresh = !options.silent
  if (isManualRefresh) {
    if (isPlatformSubscriptionInfoRefreshing.value) return
    platformSubscriptionNotice.value = ''
    platformSubscriptionError.value = ''
    if (!authToken.value) {
      platformSubscriptionError.value = '请先登录账户。'
      return
    }
    isPlatformSubscriptionInfoRefreshing.value = true
  }
  try {
    await syncPlatformSubscriptionState(options)
  } finally {
    if (isManualRefresh) {
      isPlatformSubscriptionInfoRefreshing.value = false
    }
  }
}

async function syncUsageDashboardStats(options: { silent?: boolean } = {}) {
  if (!authToken.value) return
  try {
    dashboardStats.value = await getUsageDashboardStats(authToken.value)
  } catch (error) {
    if (!options.silent) {
      reportPageError('dashboard', 'sync-usage-dashboard-stats', error)
    }
  }
}

async function syncUsage(options: { silent?: boolean; force?: boolean; includeSummary?: boolean } = {}) {
  if (!authToken.value) return
  const force = options.force === true
  const includeSummary = options.includeSummary !== false
  if (force) {
    usageSyncGeneration += 1
    isUsageLoading.value = false
  } else if (isUsageLoading.value) {
    return
  }
  const generation = usageSyncGeneration
  const silent = options.silent === true
  if (!silent) usageError.value = ''
  isUsageLoading.value = true
  try {
    const timeRange = getUsageTimeRangeQuery()
    const [logsResult, summaryResult] = await Promise.allSettled([
      getUsageLogs(authToken.value, {
        page: usagePage.value,
        pageSize: usagePageSize.value,
        apiKeyId: usageApiKeyFilter.value,
        ...timeRange,
      }),
      includeSummary
        ? getUsageStats(authToken.value, {
            apiKeyId: usageApiKeyFilter.value,
            ...timeRange,
          })
        : Promise.resolve(null),
    ])
    if (generation !== usageSyncGeneration) return
    if (logsResult.status === 'rejected') {
      throw logsResult.reason
    }
    const logs = logsResult.value
    usageRows.value = logs.items
    usageTotal.value = Number(logs.total || 0)
    usagePages.value = Math.max(1, Number(logs.pages || 1))
    if (includeSummary) {
      if (summaryResult.status === 'fulfilled' && summaryResult.value) {
        usageSummary.value = summaryResult.value
      } else {
        usageSummary.value = null
        if (!silent) {
          const summaryError = summaryResult.status === 'rejected'
            ? summaryResult.reason
            : new Error('统计汇总返回为空')
          reportPageError('dashboard', 'sync-usage-summary', summaryError)
          usageError.value = '请求记录已加载，但统计汇总加载失败，请稍后重试。'
        }
      }
    }
  } catch (error) {
    if (generation !== usageSyncGeneration) return
    if (!silent) {
      reportPageError('dashboard', 'sync-usage', error)
      usageError.value = getUsageErrorMessage(error)
    }
  } finally {
    if (generation === usageSyncGeneration) {
      isUsageLoading.value = false
    }
  }
}

async function refreshDashboardSnapshot(options: { force?: boolean } = {}) {
  const force = options.force === true
  if (!isNewThemeAuthenticated.value || !authToken.value || activePage.value !== '仪表盘') return
  if (force) dashboardRefreshInFlight = false
  if (dashboardRefreshInFlight) return
  dashboardRefreshInFlight = true
  try {
    await Promise.allSettled([
      syncCurrentUser({ silent: true }),
      syncUsageDashboardStats({ silent: true }),
      syncActivePlatformSubscription({ silent: true }),
      syncPlatformSubscriptionSummary({ silent: true }),
    ])
  } finally {
    dashboardRefreshInFlight = false
  }
}

function startDashboardAutoRefresh() {
  if (dashboardRefreshTimer !== null) return
  dashboardRefreshTimer = window.setInterval(() => {
    void refreshDashboardSnapshot()
  }, 60000)
}

function stopDashboardAutoRefresh() {
  if (dashboardRefreshTimer === null) return
  window.clearInterval(dashboardRefreshTimer)
  dashboardRefreshTimer = null
}

function getUsageTimeRangeQuery() {
  return {
    startDate: usageCustomStartDate.value,
    endDate: usageCustomEndDate.value,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'Asia/Shanghai',
  }
}

async function applyUsageFilters() {
  usageError.value = ''
  if (!usageCustomStartDate.value || !usageCustomEndDate.value) {
    usageError.value = '请选择完整的开始日期和结束日期。'
    return
  }
  if (usageCustomStartDate.value > usageCustomEndDate.value) {
    usageError.value = '开始日期不能晚于结束日期。'
    return
  }
  if (usageCustomEndDate.value > formatUsageDate(new Date())) {
    usageError.value = '结束日期不能晚于今天。'
    return
  }
  usagePage.value = 1
  await syncUsage({ includeSummary: true })
}

async function changeUsagePageSize() {
  usagePage.value = 1
  await syncUsage({ includeSummary: false })
}

async function goUsagePage(page: number) {
  usagePage.value = Math.min(Math.max(page, 1), usagePages.value)
  await syncUsage({ includeSummary: false })
}

function getToolGroups(tool: ToolKey) {
  return tool === 'codex' ? codexGroups.value : claudeGroups.value
}

function getLoginGroupOptions(tool: ToolKey): LoginGroupOption[] {
  const available = getToolGroups(tool)
  if (available.length === 0) {
    return [{ id: 0, name: '暂无可用分组', detail: '登录后同步 OpenAI 分组' }]
  }
  return available.map((group) => ({
    id: group.id,
    name: group.name,
    detail: `${user.value.email} · ${group.badge}`,
    rateText: group.rateText,
    rateValue: formatGroupRateValue(group.rateMultiplier),
  }))
}

function getAggregateGroupOptions(provider: AggregateProviderDefinition): LoginGroupOption[] {
  if (!provider.groupType) return []
  const available = provider.groupType === 'codex'
    ? codexGroups.value
    : provider.groupType === 'claude'
      ? claudeGroups.value
      : provider.groupType === 'grok'
        ? grokGroups.value
        : provider.groupType === 'kimi'
          ? kimiGroups.value
          : provider.groupType === 'deepseek'
            ? deepSeekGroups.value
            : provider.groupType === 'glm'
              ? glmGroups.value
              : image2Groups.value
  return available.map((group) => ({
    id: group.id,
    name: group.name,
    detail: `${user.value.email} · ${group.badge}`,
    rateText: group.rateText,
    rateValue: formatGroupRateValue(group.rateMultiplier),
    platform: group.platform,
  }))
}

function aggregateGroupTool(provider: AggregateProviderDefinition, group: LoginGroupOption): ToolKey | null {
  const platform = String(group.platform || '').trim().toLowerCase()
  if (platform === 'anthropic' || platform === 'claude') return 'claude'
  if (platform === 'openai') return 'codex'
  return provider.tool
}

function normalizeClaudeModelName(model: string) {
  const normalized = model.trim()
  const withoutContextMarker = normalized.replace(/\s*\[1m\]\s*$/i, '')
  if (withoutContextMarker.toLowerCase() === CLAUDE_LEGACY_FABLE_MODEL) {
    return CLAUDE_FABLE_MODEL
  }
  return normalized
}

let lastApiFailoverNoticeRequestId = ''

function handleApiConnectionState(event: Event) {
  const detail = (event as CustomEvent<Record<string, unknown>>).detail
  if (!detail?.retrying) return
  const requestId = String(detail.requestId || '')
  if (requestId && requestId === lastApiFailoverNoticeRequestId) return
  lastApiFailoverNoticeRequestId = requestId
  notify(
    String(detail.message || '当前线路连接失败，正在尝试备用线路。'),
    'warning',
    '在线支付线路切换',
  )
}

function isClaudeFableModel(model: string) {
  return normalizeClaudeModelName(model).toLowerCase() === CLAUDE_FABLE_MODEL
}

function uniqueClaudeModels(models: string[]) {
  return Array.from(new Set(models.map(normalizeClaudeModelName).filter(Boolean)))
}

function findClaudeModelByKeyword(models: string[], keyword: string) {
  return models.find((model) => model.toLowerCase().includes(keyword)) || ''
}

function getClaudeModelTag(model: string, index: number) {
  const lower = model.toLowerCase()
  if (isClaudeFableModel(model)) return 'Fable'
  if (lower.includes('opus')) return '高能'
  if (lower.includes('sonnet')) return index === 0 ? '主力' : '均衡'
  if (lower.includes('haiku')) return '快速'
  return index === 0 ? '主力' : '可用'
}

function getClaudeModelDetail(model: string, index: number) {
  if (isClaudeFableModel(model)) return 'Fable 档位高阶模型'
  return index === 0 ? 'Claude Code 与桌面版将使用此模型' : '可写入 Claude Code 与桌面版'
}

function getClaudeRoleModels(selectedModel: string, availableModels: string[]) {
  const models = uniqueClaudeModels([selectedModel, ...availableModels])
  return {
    sonnetModel: findClaudeModelByKeyword(models, 'sonnet') || selectedModel,
    haikuModel: findClaudeModelByKeyword(models, 'haiku') || selectedModel,
    opusModel: findClaudeModelByKeyword(models, 'opus') || selectedModel,
    fableModel: models.find(isClaudeFableModel) || '',
  }
}

function getLoginModelOptions(tool: ToolKey): LoginModelOption[] {
  if (tool === 'claude') {
    return [
      { name: '自动匹配', detail: '使用 Claude 返回的首选可用模型', tag: '推荐', value: claudeModelOptions.value[0] || CLAUDE_DEFAULT_MODEL },
      ...claudeModelOptions.value.map((model, index) => ({
        name: model,
        detail: getClaudeModelDetail(model, index),
        tag: getClaudeModelTag(model, index),
        value: model,
      })),
    ]
  }
  return [
    {
      name: CODEX_UPSTREAM_MODEL_LABEL,
      detail: '模型目录以服务端配置为准，登录或重启时同步',
      tag: '推荐',
      value: codexRouterForm.value.model,
      selectionMode: 'upstream' as CodexModelSelectionMode,
    },
  ]
}

function toolLabel(tool: ToolKey) {
  return tool === 'codex' ? 'Codex' : 'Claude'
}

function toolGroupLabel(tool: ToolKey) {
  return tool === 'codex' ? 'Codex' : 'Claude'
}

async function ensureToolDefaultApiKeyForGroup(tool: ToolKey, groupId: number, options: { syncGroup?: boolean } = {}) {
  const apiKey = await ensureDefaultApiKey(groupId, authToken.value, tool, {
    preferredId: toolApiKeyIds.value[tool],
    ...options,
  })
  toolApiKeys.value[tool] = apiKey.key
  toolApiKeyIds.value[tool] = apiKey.id
  saveDefaultApiKeyId(tool, apiKey.id)
  return apiKey
}

async function syncToolDefaultKeyGroup(tool: ToolKey, groupId: number) {
  const apiKey = await ensureToolDefaultApiKeyForGroup(tool, groupId, { syncGroup: false })
  if (Number(apiKey.group_id) === Number(groupId)) return apiKey
  const updated = await updateApiKey(apiKey.id, { group_id: groupId }, authToken.value)
  const next = { ...apiKey, ...updated, key: updated.key || apiKey.key }
  toolApiKeys.value[tool] = next.key
  toolApiKeyIds.value[tool] = next.id
  saveDefaultApiKeyId(tool, next.id)
  return next
}

async function selectLoginGroup(group: LoginGroupOption) {
  if (!group.id) return
  const tool = activeTool.value
  if (!tool || isToolGroupSyncing.value[tool]) return
  const previousGroupId = selectedGroup.value[tool]
  const previousGroupName = selectedLoginGroup.value
  if (previousGroupId === group.id && previousGroupName === group.name) return

  const wasToolConfigured = isActiveToolConfigured.value
  isToolGroupSyncing.value[tool] = true
  let groupChanged = false
  try {
    if (wasToolConfigured) {
      const confirmed = await confirmAction(`确认修改分组为「${group.name}」？`, {
        tone: 'warning',
        title: '修改分组',
        confirmText: '确认修改',
        cancelText: '取消',
      })
      if (!confirmed) return
    }

    selectedLoginGroup.value = group.name
    selectedGroup.value[tool] = group.id
    saveSelectedLoginGroup(tool, group.id)
    groupChanged = true
    toolErrors.value[tool] = ''

    if (tool === 'claude') {
      claudeModelOptions.value = []
      claudeModelsGroupId.value = null
      selectedLoginModel.value = '自动匹配'
      if (authToken.value) await refreshClaudeModels()
    } else if (authToken.value) {
      await refreshCodexModels()
    }

    if (!authToken.value || !wasToolConfigured) return
    await syncToolDefaultKeyGroup(tool, group.id)
    if (wasToolConfigured) {
      notify(`修改成功：${toolLabel(tool)} 已修改为「${group.name}」分组。`, 'success')
    }
  } catch (error) {
    if (groupChanged) {
      selectedGroup.value[tool] = previousGroupId
      selectedLoginGroup.value = previousGroupName
      saveSelectedLoginGroup(tool, previousGroupId)
      if (tool === 'claude') {
        claudeModelOptions.value = []
        claudeModelsGroupId.value = null
        selectedLoginModel.value = '自动匹配'
        if (authToken.value) await refreshClaudeModels()
      } else if (authToken.value) {
        await refreshCodexModels()
      }
    }
    reportPageError('one-click-login', `switch-${tool}-group`, error, { tool, groupId: group.id })
    toolErrors.value[tool] = `${toolGroupLabel(tool)} 分组切换失败：${getApiKeyErrorMessage(error)}`
  } finally {
    isToolGroupSyncing.value[tool] = false
  }
}

function persistCodexModelSelection(origin?: CodexModelSelectionOrigin) {
  localStorage.setItem(CODEX_MODEL_SELECTION_DEFAULTED_STORAGE_KEY, '1')
  localStorage.setItem(CODEX_MODEL_SELECTION_MODE_STORAGE_KEY, codexModelSelectionMode.value)
  localStorage.setItem(CODEX_LOCKED_MODEL_STORAGE_KEY, lockedCodexModel.value)
  if (origin) localStorage.setItem(CODEX_MODEL_SELECTION_ORIGIN_STORAGE_KEY, origin)
}

function syncSelectedLoginModelForTool(tool: ToolKey) {
  if (tool === 'codex') {
    selectedLoginModel.value = CODEX_UPSTREAM_MODEL_LABEL
    return
  }
  selectedLoginModel.value = '自动匹配'
}

function selectLoginModel(model: LoginModelOption) {
  selectedLoginModel.value = model.name
  if (activeTool.value !== 'codex') return
  codexModelSelectionMode.value = 'upstream'
  selectedLoginModel.value = CODEX_UPSTREAM_MODEL_LABEL
  persistCodexModelSelection('user')
}

function selectedToolGroupId(tool: ToolKey) {
  const byId = getToolGroups(tool).find((group) => group.id === selectedGroup.value[tool])
  if (byId) return byId.id
  const byName = getToolGroups(tool).find((group) => group.name === selectedLoginGroup.value)
  return byName?.id || getToolGroups(tool)[0]?.id || 0
}

function extractModelNames(payload: unknown) {
  const body = payload as Record<string, unknown>
  const candidates = Array.isArray(body?.data)
    ? body.data
    : Array.isArray(body?.models)
      ? body.models
      : Array.isArray(payload)
        ? payload
        : []
  return Array.from(new Set(candidates
    .map((item) => {
      if (typeof item === 'string') return item
      const row = item as Record<string, unknown>
      return String(row?.id || row?.name || row?.model || row?.model_id || row?.model_name || row?.slug || '')
    })
    .map((item) => item.trim())
    .filter(Boolean)))
}

function extractCodexConversationModelNames(payload: unknown) {
  return filterCodexConversationModels(extractModelNames(payload))
}

async function fetchCodexModelsWithBrowser(apiKey: string, requestedBaseUrl = currentCodexBaseUrl()): Promise<ModelListResult> {
  const baseUrl = requestedBaseUrl.replace(/\/+$/, '')
  const response = await fetch(`${baseUrl}/models`, {
    headers: {
      Accept: 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
  })
  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    const body = payload as Record<string, unknown> | null
    const errorBody = body?.error as Record<string, unknown> | undefined
    throw new Error(String(errorBody?.message || body?.message || `模型列表读取失败：HTTP ${response.status}`))
  }
  return { models: extractCodexConversationModelNames(payload), baseUrl }
}

function codexFallbackModelResult(error?: unknown): ModelListResult {
  return {
    models: [...CODEX_FALLBACK_MODELS],
    baseUrl: currentCodexBaseUrl(),
    fallback: true,
    message: error ? getModelListErrorMessage(error, 'codex') : '上游模型列表为空。',
  }
}

function cloneModelListResult(result: ModelListResult, cached = false): ModelListResult {
  return {
    ...result,
    models: [...result.models],
    cached,
  }
}

function codexModelListCacheKey(options: CodexModelFetchOptions) {
  const baseUrl = currentCodexBaseUrl().replace(/\/+$/, '').toLowerCase()
  return `${options.groupId}:${options.apiKeyId || 0}:${baseUrl}`
}

async function requestCodexModelList(apiKey: string): Promise<ModelListResult> {
  try {
    const baseUrl = currentCodexBaseUrl()
    const result = window.gaogeDesktop?.fetchCodexModels
      ? await window.gaogeDesktop.fetchCodexModels({ apiKey, baseUrl, applyDesktopModelSupport: true, modelPolicyApiBaseUrl: getCurrentApiBaseUrl() })
      : await fetchCodexModelsWithBrowser(apiKey)
    const upstreamModels = extractCodexConversationModelNames({ models: result.models })
    if (result.fallback) {
      return {
        ...result,
        models: [...CODEX_FALLBACK_MODELS],
        fallback: true,
      }
    }
    if (upstreamModels.length === 0) return codexFallbackModelResult()
    return { ...result, models: upstreamModels, fallback: false }
  } catch (error) {
    reportPageError('one-click-login', 'fetch-codex-models', error)
    if (String(error).includes('CODEX_MODEL_SUPPORT_UNAVAILABLE:')) throw error
    return codexFallbackModelResult(error)
  }
}

async function requestAggregateCodexModelList(
  apiKey: ApiKey,
  provider: AggregateProviderDefinition,
): Promise<AggregateModelListResult> {
  const fallbackModels = provider.defaultModels ? [...provider.defaultModels] : []
  try {
    const baseUrl = currentCodexBaseUrl()
    const result = window.gaogeDesktop?.fetchCodexModels
      ? await window.gaogeDesktop.fetchCodexModels({ apiKey: apiKey.key, baseUrl })
      : await fetchCodexModelsWithBrowser(apiKey.key, baseUrl)
    if (result.fallback) {
      throw new Error(result.message || `${provider.name} 模型目录读取失败。`)
    }
    const models = extractCodexConversationModelNames({ models: result.models })
    if (models.length === 0) throw new Error(`${provider.name} 没有返回可用模型。`)
    return { ...result, models, fallback: false, builtinCatalog: false }
  } catch (error) {
    if (fallbackModels.length === 0) throw error
    return {
      models: fallbackModels,
      baseUrl: currentCodexBaseUrl(),
      fallback: true,
      builtinCatalog: true,
      message: getModelListErrorMessage(error, 'codex'),
    }
  }
}

async function fetchCodexModelList(apiKey: string, options: CodexModelFetchOptions): Promise<ModelListResult> {
  const cacheKey = codexModelListCacheKey(options)
  const pending = codexModelListRequests.get(cacheKey)
  if (pending) return cloneModelListResult(await pending)

  const cached = codexModelListCache.get(cacheKey)
  if (!options.force && cached && cached.expiresAt > Date.now()) {
    return cloneModelListResult(cached.result, true)
  }
  if (cached) codexModelListCache.delete(cacheKey)

  const request = requestCodexModelList(apiKey)
    .then((result) => {
      const ttl = result.fallback ? CODEX_MODEL_FALLBACK_CACHE_TTL_MS : CODEX_MODEL_CACHE_TTL_MS
      const normalized = cloneModelListResult(result)
      codexModelListCache.set(cacheKey, {
        expiresAt: Date.now() + ttl,
        result: normalized,
      })
      return normalized
    })
    .finally(() => {
      codexModelListRequests.delete(cacheKey)
    })
  codexModelListRequests.set(cacheKey, request)
  return cloneModelListResult(await request)
}

function applyCodexModelList(result: ModelListResult) {
  const models = result.fallback
    ? [...CODEX_FALLBACK_MODELS]
    : extractCodexConversationModelNames({ models: result.models })
  codexModelOptions.value = models
  codexModelCatalogSource.value = result.fallback ? 'fallback' : 'upstream'
  if (result.fallback) {
    loginModelsNotice.value = `上游模型获取失败，已启用 ${CODEX_FALLBACK_MODELS.length} 个内置兼容模型。${result.message ? ` ${result.message}` : ''}`
    loginModelsError.value = ''
    return
  }
  loginModelsNotice.value = result.cached
    ? `已使用刚刚同步的 Codex 上游模型目录，共 ${models.length} 个模型。`
    : `模型目录同步成功，共 ${models.length} 个模型。`
  if (result.message) loginModelsNotice.value += ` ${result.message}`
  loginModelsError.value = ''
}

async function resolveCodexModelSelection(
  apiKey: string,
  options: Omit<CodexModelFetchOptions, 'force'>,
): Promise<ResolvedCodexModelSelection> {
  const mode: CodexModelSelectionMode = 'upstream'
  const result = await fetchCodexModelList(apiKey, { ...options, force: true })
  const upstreamModels = !result.fallback
    ? extractCodexConversationModelNames({ models: result.models })
    : []
  const availableModels = upstreamModels.length > 0
    ? upstreamModels
    : [...CODEX_FALLBACK_MODELS]
  const source: CodexModelCatalogSource = upstreamModels.length > 0 ? 'upstream' : 'fallback'
  const previousModel = codexRouterForm.value.model
  const previousOrigin = normalizeCodexModelSelectionOrigin(
    localStorage.getItem(CODEX_MODEL_SELECTION_ORIGIN_STORAGE_KEY),
  )
  const model = selectCodexConversationModel(availableModels, previousModel)
  const origin: CodexModelSelectionOrigin = previousOrigin === 'user' && model === previousModel
    ? 'user'
    : 'automatic'
  const supportedModels = availableModels

  codexModelSelectionMode.value = mode
  codexRouterForm.value.model = model
  codexRouterForm.value.relayBaseUrl = currentCodexBaseUrl()
  persistCodexRouterForm(origin)
  return {
    mode,
    source,
    model,
    origin,
    supportedModels,
    fallback: source === 'fallback',
    warning: source === 'fallback' ? '暂未读取到上游模型目录，已使用四个默认模型。' : '',
  }
}

async function fetchClaudeModelsWithBrowser(apiKey: string): Promise<ModelListResult> {
  const baseUrl = currentClaudeBaseUrl().replace(/\/$/, '')
  const endpoints = [`${baseUrl}/v1/models`, `${baseUrl}/models`]
  let lastError = ''

  for (const endpoint of endpoints) {
    try {
      const response = await fetch(endpoint, {
        headers: {
          Accept: 'application/json',
          Authorization: `Bearer ${apiKey}`,
          'anthropic-version': '2023-06-01',
          'x-api-key': apiKey,
        },
      })
      const payload = await response.json().catch(() => null)
      if (!response.ok) {
        const body = payload as Record<string, unknown> | null
        const errorBody = body?.error as Record<string, unknown> | undefined
        lastError = String(errorBody?.message || body?.message || `Claude 模型列表读取失败：HTTP ${response.status}`)
        continue
      }

      const models = extractModelNames(payload)
      if (models.length > 0) return { models, baseUrl }
      lastError = 'Claude 没有返回可用模型。'
    } catch (error) {
      lastError = getModelListErrorMessage(error, 'claude')
    }
  }

  throw new Error(lastError || 'Claude 模型列表读取失败。')
}

async function requestMappedProviderModelList(
  provider: AggregateProviderDefinition,
  group: LoginGroupOption,
  groupTool: ToolKey,
  apiKey: ApiKey,
  options: { force?: boolean } = {},
): Promise<ModelListResult> {
  const result: ModelListResult = groupTool === 'claude'
    ? window.gaogeDesktop?.fetchClaudeModels
      ? await window.gaogeDesktop.fetchClaudeModels({
        apiKey: apiKey.key,
        baseUrl: currentClaudeBaseUrl(),
        allowFallback: false,
      })
      : await fetchClaudeModelsWithBrowser(apiKey.key)
    : await fetchCodexModelList(apiKey.key, {
      groupId: group.id,
      apiKeyId: apiKey.id,
      force: options.force,
    })
  const models = groupTool === 'claude'
    ? uniqueClaudeModels(result.models)
    : extractCodexConversationModelNames({ models: result.models })
  if (result.fallback || models.length === 0) {
    throw new Error(result.message || `${provider.name} / ${group.name} 没有返回可用模型。`)
  }
  return { ...result, models, fallback: false, builtinCatalog: false }
}

function claudeFallbackModelResult(error?: unknown): ModelListResult {
  return {
    models: [...CLAUDE_FALLBACK_MODELS],
    baseUrl: currentClaudeBaseUrl(),
    fallback: true,
    message: error ? getModelListErrorMessage(error, 'claude') : '上游模型列表为空。',
  }
}

async function requestClaudeModelList(apiKey: string): Promise<ModelListResult> {
  try {
    const result: ModelListResult = window.gaogeDesktop?.fetchClaudeModels
      ? await window.gaogeDesktop.fetchClaudeModels({ apiKey, baseUrl: currentClaudeBaseUrl() })
      : await fetchClaudeModelsWithBrowser(apiKey)
    const models = uniqueClaudeModels(result.models.filter(Boolean))
    if (result.fallback || models.length === 0) {
      return {
        ...claudeFallbackModelResult(result.message || '上游模型列表为空。'),
        ...result,
        models: [...CLAUDE_FALLBACK_MODELS],
        fallback: true,
      }
    }
    return { ...result, models, fallback: false }
  } catch (error) {
    reportPageError('one-click-login', 'fetch-claude-models', error)
    return claudeFallbackModelResult(error)
  }
}

async function refreshCodexModels(options: { force?: boolean } = {}): Promise<ModelListResult | null> {
  loginModelsNotice.value = ''
  loginModelsError.value = ''
  if (!authToken.value) {
    loginModelsError.value = '请先登录账户。'
    return null
  }
  if (codexGroups.value.length === 0) await syncGroups()
  const groupId = selectedToolGroupId('codex')
  if (!groupId) {
    loginModelsError.value = '未找到可用的 Codex 分组。'
    return null
  }
  isCodexModelsLoading.value = true
  try {
    const apiKey = await ensureToolDefaultApiKeyForGroup('codex', groupId)
    const result = await fetchCodexModelList(apiKey.key, {
      groupId,
      apiKeyId: apiKey.id,
      force: options.force,
    })
    applyCodexModelList(result)
    return result
  } catch (error) {
    reportPageError('one-click-login', 'refresh-codex-models', error)
    loginModelsError.value = getModelListErrorMessage(error, 'codex')
    return null
  } finally {
    isCodexModelsLoading.value = false
  }
}

async function refreshClaudeModels() {
  loginModelsNotice.value = ''
  loginModelsError.value = ''
  if (!authToken.value) {
    loginModelsError.value = '请先登录账户。'
    return
  }
  if (claudeGroups.value.length === 0) await syncGroups()
  const groupId = selectedToolGroupId('claude')
  if (!groupId) {
    loginModelsError.value = '未找到可用的 Claude 分组。'
    return
  }
  if (claudeModelsGroupId.value !== groupId) {
    claudeModelOptions.value = []
    claudeModelsGroupId.value = null
  }
  isClaudeModelsLoading.value = true
  try {
    const apiKey = await ensureToolDefaultApiKeyForGroup('claude', groupId)
    const result = await requestClaudeModelList(apiKey.key)
    const models = uniqueClaudeModels(result.models)
    claudeModelOptions.value = models
    claudeModelsGroupId.value = groupId
    loginModelsNotice.value = result.fallback
      ? `上游模型获取失败，已启用 ${CLAUDE_FALLBACK_MODELS.length} 个内置 Claude 兼容模型。${result.message ? ` ${result.message}` : ''}`
      : `已刷新 ${models.length} 个 Claude 模型。`
  } catch (error) {
    reportPageError('one-click-login', 'refresh-claude-models', error)
    loginModelsError.value = getModelListErrorMessage(error, 'claude')
  } finally {
    isClaudeModelsLoading.value = false
  }
}

async function refreshLoginModels() {
  if (activeTool.value === 'codex') {
    await refreshCodexModels({ force: true })
    return
  }
  if (activeTool.value === 'claude') {
    await refreshClaudeModels()
  }
}

function aggregateApiKeyName(providerId: string, groupId: number) {
  return `聚合-${providerId}-分组-${groupId}`
}

function aggregateGroupStateKey(providerId: string, groupId: number) {
  return `${providerId}:${groupId}`
}

function aggregateApiKeyCacheKey(providerId: string, groupId: number) {
  const userScope = String(authUser.value?.id || authUser.value?.email || 'anonymous')
  return `${userScope}:${aggregateGroupStateKey(providerId, groupId)}`
}

function normalizeAggregateApiKey(value: ApiKey): ApiKey {
  const record = value as unknown as Record<string, unknown>
  const key = [record.key, record.apiKey, record.api_key, record.token]
    .find((candidate) => typeof candidate === 'string' && candidate.trim().length > 0)
  const normalizedKey = typeof key === 'string' ? key.trim() : ''
  if (!normalizedKey || /(?:\*|•){3,}/.test(normalizedKey)) {
    throw new Error('中转站返回的聚合 Key 为空或已被隐藏，请刷新后重试。')
  }
  return { ...value, key: normalizedKey }
}

function currentAggregateKeyPreparationState(): AggregateKeyPreparationState {
  return {
    ready: aggregateGroupKeyReady.value,
    errors: aggregateGroupKeyErrors.value,
  }
}

function applyAggregateKeyPreparationState(state: AggregateKeyPreparationState) {
  aggregateGroupKeyReady.value = state.ready
  aggregateGroupKeyErrors.value = state.errors
}

function setAggregateGroupKeyReady(stateKey: string) {
  applyAggregateKeyPreparationState(markAggregateKeyReady(currentAggregateKeyPreparationState(), stateKey))
}

function setAggregateGroupKeyFailed(stateKey: string, error: unknown) {
  applyAggregateKeyPreparationState(markAggregateKeyFailed(
    currentAggregateKeyPreparationState(),
    stateKey,
    getApiKeyErrorMessage(error),
  ))
}

async function ensureAggregateApiKey(providerId: string, groupId: number) {
  const stateKey = aggregateGroupStateKey(providerId, groupId)
  const cacheKey = aggregateApiKeyCacheKey(providerId, groupId)
  return ensureAggregateApiKeyWithCache({
    stateKey,
    cacheKey,
    cache: aggregateApiKeyCache,
    requests: aggregateApiKeyRequests,
    load: () => ensureNamedApiKey(aggregateApiKeyName(providerId, groupId), groupId, authToken.value),
    normalize: normalizeAggregateApiKey,
    onReady: setAggregateGroupKeyReady,
    onError: setAggregateGroupKeyFailed,
  })
}

async function refreshAggregateGroupModels(
  provider: AggregateProviderDefinition,
  group: LoginGroupOption,
  options: { force?: boolean } = {},
) {
  if (!provider.tool || !group.id) return
  const groupTool = aggregateGroupTool(provider, group)
  if (!groupTool) return
  const key = aggregateGroupStateKey(provider.id, group.id)
  const emptyBaseUrl = groupTool === 'claude' ? currentClaudeBaseUrl() : currentCodexBaseUrl()
  await refreshAggregateGroupRuntime<ApiKey, AggregateModelListResult>({
    ensureKey: () => ensureAggregateApiKey(provider.id, group.id),
    fetchModels: async (apiKey) => provider.defaultModels?.length
      ? requestAggregateCodexModelList(apiKey, provider)
      : provider.id === 'kimi' || provider.id === 'deepseek'
        ? requestMappedProviderModelList(provider, group, groupTool, apiKey, options)
        : groupTool === 'codex'
          ? fetchCodexModelList(apiKey.key, {
            groupId: group.id,
            apiKeyId: apiKey.id,
            force: options.force,
          })
          : requestClaudeModelList(apiKey.key),
    normalizeModels: (models) => groupTool === 'claude'
      ? uniqueClaudeModels(models)
      : extractCodexConversationModelNames({ models }),
    emptyBaseUrl,
    formatKeyError: getApiKeyErrorMessage,
    formatModelError: (error) => getModelListErrorMessage(error, groupTool),
    onLoading: (loading) => {
      aggregateGroupLoading.value = { ...aggregateGroupLoading.value, [key]: loading }
    },
    onResult: (result) => {
      aggregateGroupModelResults.value = {
        ...aggregateGroupModelResults.value,
        [key]: result,
      }
    },
    onFailure: (_phase, error) => {
      reportPageError('aggregate-login', `refresh-${provider.id}-${group.id}`, error)
    },
  })
}

async function refreshAggregateModels(options: { force?: boolean; groupsAlreadySynced?: boolean } = {}) {
  aggregateLoginError.value = ''
  aggregateLoginNotice.value = ''
  if (!authToken.value) {
    aggregateLoginError.value = '请先登录账户。'
    return
  }
  isAggregateModelsLoading.value = true
  try {
    if (!options.groupsAlreadySynced) await syncGroups({ silent: true })
    const jobs = aggregateProviderDefinitions.flatMap((provider) => (
      provider.available && provider.tool && provider.groupType
        ? getAggregateGroupOptions(provider)
          .filter((group) => group.id > 0)
          .map((group) => refreshAggregateGroupModels(provider, group, options))
        : []
    ))
    await Promise.all(jobs)
    const keyFailureGroups = aggregateAvailableProviders.value.flatMap((provider) => (
      provider.groups
        .filter((group) => !group.keyReady || Boolean(group.keyError))
        .map((group) => `${provider.name} / ${group.name}：${aggregateGroupFailureReason(group)}`)
    ))
    const modelFailureGroups = aggregateAvailableProviders.value.flatMap((provider) => (
      provider.groups
        .filter((group) => group.keyReady && !group.keyError && (!group.modelReady || Boolean(group.modelError)))
        .map((group) => `${provider.name} / ${group.name}：${aggregateGroupFailureReason(group)}`)
    ))
    if (keyFailureGroups.length > 0 || modelFailureGroups.length > 0) {
      const failures = [
        keyFailureGroups.length > 0
          ? `${keyFailureGroups.length} 个分组的独立 Key 准备失败：${keyFailureGroups.join('；')}`
          : '',
        modelFailureGroups.length > 0
          ? `${modelFailureGroups.length} 个分组的模型目录读取失败：${modelFailureGroups.join('；')}`
          : '',
      ].filter(Boolean)
      aggregateLoginError.value = failures.join('；')
      return
    }
    const fallbackGroups = aggregateAvailableProviders.value.flatMap((provider) => (
      provider.groups.filter((group) => group.fallback).map((group) => `${provider.name} / ${group.name}`)
    ))
    const builtinCatalogGroups = aggregateAvailableProviders.value.flatMap((provider) => (
      provider.groups.filter((group) => group.builtinCatalog).map((group) => `${provider.name} / ${group.name}`)
    ))
    aggregateLoginNotice.value = `已聚合 ${aggregateAvailableProviders.value.length} 个供应商、${aggregateGroupCount.value} 个分组，共 ${aggregateModelChoices.value.length} 条模型路由。${fallbackGroups.length ? ` ${fallbackGroups.length} 个分组已使用内置兜底模型。` : ''}${builtinCatalogGroups.length ? ` ${builtinCatalogGroups.length} 个分组已使用默认支持模型。` : ''}`
  } catch (error) {
    reportPageError('aggregate-login', 'refresh-models', error)
    aggregateLoginError.value = getErrorMessage(error)
  } finally {
    isAggregateModelsLoading.value = false
  }
}

function openAggregateProvider(providerId: string) {
  selectedAggregateProviderId.value = providerId
}

function closeAggregateProvider() {
  selectedAggregateProviderId.value = ''
}

function aggregateConnectionTestState(providerId: string, groupId: number): AggregateConnectionTestState {
  return aggregateConnectionTests.value[aggregateGroupStateKey(providerId, groupId)] || {
    status: 'idle',
    latencyMs: 0,
    model: '',
    message: '',
    testedAt: 0,
  }
}

function updateAggregateConnectionTest(
  providerId: string,
  groupId: number,
  state: AggregateConnectionTestState,
) {
  const key = aggregateGroupStateKey(providerId, groupId)
  aggregateConnectionTests.value = { ...aggregateConnectionTests.value, [key]: state }
}

function aggregateProviderIsTesting(provider: AggregateProviderView) {
  return provider.groups.some((group) => (
    aggregateConnectionTestState(provider.id, group.id).status === 'testing'
  ))
}

function aggregateConnectionTestLabel(providerId: string, groupId: number) {
  const state = aggregateConnectionTestState(providerId, groupId)
  if (state.status === 'testing') return '正在调用'
  if (state.status === 'success') return `${formatDuration(state.latencyMs)} 可用`
  if (state.status === 'error') return '连接失败'
  return '尚未测试'
}

function aggregateConnectionTestTime(timestamp: number) {
  if (!timestamp) return ''
  return new Date(timestamp).toLocaleTimeString('zh-CN', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
}

async function testAggregateGroupConnection(
  provider: AggregateProviderView,
  group: AggregateGroupView,
  options: { announce?: boolean } = {},
) {
  const announce = options.announce !== false
  const stateKey = aggregateGroupStateKey(provider.id, group.id)
  const testedAt = Date.now()
  const groupTool = aggregateGroupTool(provider, group)
  if (!groupTool) return false
  if (!authToken.value) {
    updateAggregateConnectionTest(provider.id, group.id, {
      status: 'error', latencyMs: 0, model: '', message: '请先登录账户。', testedAt,
    })
    return false
  }
  if (!window.gaogeDesktop?.testProviderLatency) {
    updateAggregateConnectionTest(provider.id, group.id, {
      status: 'error', latencyMs: 0, model: '', message: '当前桌面版本不支持连接测试。', testedAt,
    })
    return false
  }
  if (aggregateConnectionTests.value[stateKey]?.status === 'testing') return false

  updateAggregateConnectionTest(provider.id, group.id, {
    status: 'testing', latencyMs: 0, model: '', message: '正在发起最小模型调用…', testedAt,
  })
  try {
    const apiKey = await ensureAggregateApiKey(provider.id, group.id)
    let result = aggregateGroupModelResults.value[stateKey]
    let models = groupTool === 'claude'
      ? uniqueClaudeModels(result?.models || group.models)
      : extractCodexConversationModelNames({ models: result?.models || group.models })
    if (models.length === 0 || Boolean(result?.modelError)) {
      await refreshAggregateGroupModels(provider, group, { force: true })
      result = aggregateGroupModelResults.value[stateKey]
      models = groupTool === 'claude'
        ? uniqueClaudeModels(result?.models || [])
        : extractCodexConversationModelNames({ models: result?.models || [] })
    }
    const keyError = aggregateGroupKeyErrors.value[stateKey]
    if (keyError) throw new Error(keyError)
    if (result?.modelError) throw new Error(result.modelError)
    const model = models.find((name) => !/(?:^|[-_/])image(?:[-_/]|$)/i.test(name)) || models[0]
    if (!model) throw new Error('该分组没有可测试的模型。')

    const response = await window.gaogeDesktop.testProviderLatency({
      tool: groupTool,
      apiKey: apiKey.key,
      baseUrl: result?.baseUrl || (groupTool === 'claude' ? currentClaudeBaseUrl() : currentCodexBaseUrl()),
      model,
      wireApi: 'responses',
    })
    if (!response.ok) throw new Error(response.message || '模型调用失败。')
    const latencyMs = Number(response.latencyMs || 0)
    const modelUsed = response.modelUsed || model
    updateAggregateConnectionTest(provider.id, group.id, {
      status: 'success',
      latencyMs,
      model: modelUsed,
      message: `真实模型调用成功 · ${modelUsed}`,
      testedAt: Date.now(),
    })
    if (announce) {
      aggregateLoginError.value = ''
      aggregateLoginNotice.value = `${provider.name} / ${group.name} 连接成功：${formatDuration(latencyMs)} · ${modelUsed}`
    }
    return true
  } catch (error) {
    const message = getModelListErrorMessage(error, groupTool)
    updateAggregateConnectionTest(provider.id, group.id, {
      status: 'error', latencyMs: 0, model: '', message, testedAt: Date.now(),
    })
    reportPageError('aggregate-login', `connection-${provider.id}-${group.id}`, error)
    if (announce) {
      aggregateLoginNotice.value = ''
      aggregateLoginError.value = `${provider.name} / ${group.name}：${message}`
    }
    return false
  }
}

async function testAggregateProviderConnections(provider: AggregateProviderView) {
  if (isAnyAggregateConnectionTesting.value || isAggregateConnectionsTesting.value) return
  aggregateLoginError.value = ''
  aggregateLoginNotice.value = ''
  const results: boolean[] = []
  for (const group of provider.groups) {
    results.push(await testAggregateGroupConnection(provider, group, { announce: false }))
  }
  const successCount = results.filter(Boolean).length
  const failureCount = results.length - successCount
  if (failureCount > 0) {
    aggregateLoginError.value = `${provider.name} 测试完成：${successCount} 个分组可用，${failureCount} 个分组失败。请查看右侧分组详情。`
  } else {
    aggregateLoginNotice.value = `${provider.name} 的 ${successCount} 个分组均已通过真实模型调用测试。`
  }
}

async function testAllAggregateConnections() {
  if (isAggregateConnectionsTesting.value || isAnyAggregateConnectionTesting.value || isAggregateModelsLoading.value) return
  const providers = aggregateCanvasProviders.value
  const targets = providers.flatMap((provider) => provider.groups.map((group) => ({ provider, group })))
  if (targets.length === 0) {
    aggregateLoginError.value = '当前没有已经添加的上游分组，请先登录账户并刷新模型。'
    return
  }
  aggregateLoginError.value = ''
  aggregateLoginNotice.value = '正在逐个验证上游连接与真实模型调用…'
  isAggregateConnectionsTesting.value = true
  try {
    const results: boolean[] = []
    for (const { provider, group } of targets) {
      results.push(await testAggregateGroupConnection(provider, group, { announce: false }))
    }
    const successCount = results.filter(Boolean).length
    const failureCount = results.length - successCount
    if (failureCount > 0) {
      aggregateLoginNotice.value = ''
      aggregateLoginError.value = `连接测试完成：${successCount} 个分组可用，${failureCount} 个分组失败。点击供应商查看具体原因。`
    } else {
      aggregateLoginNotice.value = `连接测试完成：${providers.length} 个供应商、${successCount} 个分组均可正常调用。`
    }
  } finally {
    isAggregateConnectionsTesting.value = false
  }
}

async function testToolLatency(tool: ToolKey) {
  toolLatencyErrors.value[tool] = ''
  toolLatencyNotices.value[tool] = ''
  if (!authToken.value) {
    toolLatencyErrors.value[tool] = '请先登录账户。'
    return
  }
  if (!window.gaogeDesktop?.testProviderLatency) {
    toolLatencyErrors.value[tool] = '当前版本暂不支持测速，请更新桌面端。'
    return
  }
  if (getToolGroups(tool).length === 0) await syncGroups()
  const groupId = selectedToolGroupId(tool)
  if (!groupId) {
    toolLatencyErrors.value[tool] = `未找到可用的 ${tool === 'codex' ? 'Codex' : 'Claude'} 分组。`
    return
  }
  isToolLatencyTesting.value[tool] = true
  toolLatencyNotices.value[tool] = '正在测速...'
  try {
    const apiKey = await ensureToolDefaultApiKeyForGroup(tool, groupId)
    const selectedModel = tool === 'codex'
      ? codexModelSelectionMode.value === 'upstream'
        ? codexRouterForm.value.model
        : lockedCodexModel.value
      : selectedLoginModel.value === '自动匹配'
        ? claudeModelOptions.value[0] || CLAUDE_DEFAULT_MODEL
        : selectedLoginModel.value
    const result = await window.gaogeDesktop.testProviderLatency({
      tool,
      apiKey: apiKey.key,
      baseUrl: tool === 'claude' ? currentClaudeBaseUrl() : currentCodexBaseUrl(),
      model: selectedModel,
    })
    if (!result.ok) throw new Error(result.message || '测速失败。')
    toolLatencyNotices.value[tool] = `测速成功：${formatDuration(result.latencyMs)} · ${result.modelUsed || selectedModel}`
  } catch (error) {
    reportPageError('one-click-login', `test-${tool}-latency`, error, { tool })
    toolLatencyNotices.value[tool] = ''
    toolLatencyErrors.value[tool] = getModelListErrorMessage(error, tool)
  } finally {
    isToolLatencyTesting.value[tool] = false
  }
}

async function testLatencyForActivePage() {
  if (!activeTool.value) return
  await testToolLatency(activeTool.value)
}

function confirmCodexClose(actionName: string) {
  return confirmAction(`${actionName} 需要先关闭正在运行的 Codex。完成后请手动重新打开 Codex。是否继续？`, {
    tone: 'warning',
    title: '关闭 Codex 后继续',
    confirmText: '继续操作',
    cancelText: '暂不操作',
  })
}

function confirmCodexRestart(actionName: string) {
  return confirmAction(`${actionName} 将关闭正在运行的 Codex，完成配置后会自动重新打开。是否继续？`, {
    tone: 'warning',
    title: '重启 Codex 后继续',
    confirmText: '继续操作',
    cancelText: '暂不操作',
  })
}

function rawErrorText(error: unknown) {
  if (typeof error === 'string') return error
  if (error && typeof error === 'object' && 'message' in error) {
    return String((error as { message?: unknown }).message || '')
  }
  return ''
}

function isCodexConfigurationBusyError(error: unknown) {
  return [
    'Codex 正在切换账号，请稍后刷新账号列表。',
    'Codex configure 正在进行中，请稍后再试。',
    'Codex 正在处理其他配置，请稍后重试。',
  ].includes(rawErrorText(error).trim())
}

function isCodexAccountInvalidError(error: unknown) {
  const message = rawErrorText(error)
  const compact = `${message}\n${stripSensitiveErrorText(message)}`.toLowerCase()
  return (
    compact.includes('account_invalid') ||
    compact.includes('requiresreauth') ||
    compact.includes('has no refresh token') ||
    compact.includes('refresh codex token failed: http 400') ||
    compact.includes('refresh codex token failed: http 401') ||
    compact.includes('refresh codex token failed: http 403') ||
    compact.includes('登录快照已过期且无法续期') ||
    compact.includes('登录已失效') ||
    compact.includes('登录无效') ||
    compact.includes('重新登录该 codex 账号')
  )
}

function invalidActiveCodexAccount() {
  const account = currentCodexAccount.value ||
    codexAccounts.value.find((item) => item.accountKey === activeCodexAccountKey.value) ||
    null
  if (!account) return null
  if (account.requiresReauth || account.loginState === 'invalid' || account.canSwitch === false) return account
  return null
}

function codexAccountDisplayName(account?: GaogeDesktopCodexAccount | null) {
  if (!account) return '当前账号'
  return account.email || account.accountName || account.profileName || codexAccountTitle(account)
}

function confirmClaudeClose(actionName: string, afterCloseMessage = '完成后请手动重新打开 Claude。') {
  return confirmAction(`${actionName} 需要先关闭正在运行的 Claude Desktop 与 Claude Code。${afterCloseMessage}是否继续？`, {
    tone: 'warning',
    title: '关闭 Claude 后继续',
    confirmText: '继续操作',
    cancelText: '暂不操作',
  })
}

function showManualOpenNotice(action: ManualOpenNoticeAction, message?: string) {
  const messages: Record<ManualOpenNoticeAction, { title: string; message: string; dangerDetails?: string[] }> = {
    'codex-login': {
      title: 'Codex 登录已完成',
      message: '一键登录配置已写入。请手动打开 Codex 后使用。',
    },
    'codex-login-close': {
      title: 'Codex 登录已关闭',
      message: '已恢复官方原生路由。请手动打开 Codex 后使用。',
    },
    'codex-force-official': {
      title: '已恢复官方原生路由',
      message: '已清理中转并恢复官方原生路由。请手动打开 Codex 后使用。',
    },
    'claude-login': {
      title: 'Claude 登录已完成',
      message: '一键登录配置已写入。请手动打开 Claude 后使用。',
    },
    'claude-login-close': {
      title: 'Claude 登录已关闭',
      message: '已恢复官方默认路由。请手动打开 Claude 后使用。',
    },
  }
  const notice = messages[action]
  void confirmAction(message || notice.message, {
    tone: 'success',
    title: notice.title,
    dangerDetails: notice.dangerDetails || [],
