function persistCodexRouterForm(origin?: CodexModelSelectionOrigin) {
  codexRouterForm.value.relayBaseUrl = currentCodexBaseUrl()
  localStorage.setItem('gaoge_desktop_codex_model', codexRouterForm.value.model)
