  localStorage.setItem('gaoge_desktop_codex_official_base_url', codexRouterForm.value.officialBaseUrl)
  persistCodexModelSelection(origin)
}

function setCodexRelaySource(source: CodexRelaySource) {
  codexRelaySource.value = source
  if (source) {
    localStorage.setItem(CODEX_RELAY_SOURCE_STORAGE_KEY, source)
    return
  }
  localStorage.removeItem(CODEX_RELAY_SOURCE_STORAGE_KEY)
}

function setCodexFuelRecoveryAvailable(available: boolean) {
  isCodexFuelRecoveryAvailable.value = available
  try {
    if (available) localStorage.setItem(CODEX_FUEL_RECOVERY_STORAGE_KEY, 'true')
    else localStorage.removeItem(CODEX_FUEL_RECOVERY_STORAGE_KEY)
