  localStorage.removeItem(CLAUDE_CONFIGURED_STORAGE_KEY)
}

function syncRuntimeServerState() {
  runtimeConfigSnapshot.value = getRuntimeDomainConfig()
  runtimeServers.value = getRuntimeServers()
  selectedRuntimeServer.value = getSelectedRuntimeServer()
  storedRuntimeServerId.value = getStoredRuntimeServerId()
  codexRouterForm.value.relayBaseUrl = currentCodexBaseUrl()
}

function runtimeServerStatusText(server: RuntimeServerView) {
  const status = server.status
  if (status.status === 'testing') return '测速中'
  if (status.status === 'ok') return `${status.latencyMs || 0}ms`
  if (status.status === 'failed') return '未连通'
  return '未测速'
}

function runtimeServerReachabilityText(server: RuntimeServerView) {
  const status = server.status.status
  if (status === 'testing') return '测试中'
  if (status === 'ok') return server.status.load?.label ? `服务器可用 · ${server.status.load.label}` : '服务器可用'
  if (status === 'failed') return '服务器不可用'
  return '未测试'
}

function runtimeServerReachabilityClass(server: RuntimeServerView) {
  const loadLevel = server.status.load?.level || 'unknown'
  return `reachability-${server.status.status} load-${loadLevel}`
}

function runtimeServerStatusDetail(server: RuntimeServerView) {
  const status = server.status
  if (status.status === 'ok') return `HTTP ${status.httpStatus || 200} · ${status.testedAt ? formatFullTime(status.testedAt) : '刚刚'}`
  if (status.status === 'failed') return status.reason || '连接失败'
  if (status.status === 'testing') return '正在测试 API 连通性'
  return '点击刷新测速后显示延迟'
}

function runtimeServerStatusClass(server: RuntimeServerView) {
  return `status-${server.status.status}`
}

function runtimeServerSelectionLabel(server: RuntimeServerView) {
  if (server.selected && hasConfirmedRuntimeServerSelection.value) return '当前使用'
  if (server.selected) return '推荐'
  return '可选择'
}

function runtimeServerActionText(server: RuntimeServerView) {
  if (server.selected && hasConfirmedRuntimeServerSelection.value) return '正在使用'
  return '使用此服务器'
}

function isRuntimeServerSelectDisabled(server: RuntimeServerView) {
  return isRuntimeServerRefreshing.value || (server.selected && hasConfirmedRuntimeServerSelection.value)
}

async function testRuntimeServerList(options: { silent?: boolean } = {}) {
  runtimeServerError.value = ''
  if (!runtimeServers.value.length) {
    runtimeServerError.value = '还没有读取到服务器列表，请先刷新服务器。'
    return
  }
  isRuntimeServerTesting.value = true
  if (!options.silent) runtimeServerNotice.value = '正在测速所有服务器...'
  try {
    runtimeServers.value = await testRuntimeServers()
    selectedRuntimeServer.value = getSelectedRuntimeServer()
    if (!options.silent) runtimeServerNotice.value = '测速完成。'
  } catch (error) {
    reportPageError('system-config', 'test-runtime-servers', error)
    runtimeServerError.value = getErrorMessage(error)
  } finally {
    isRuntimeServerTesting.value = false
  }
}

async function refreshRuntimeServersFromOss() {
  runtimeServerError.value = ''
  runtimeServerNotice.value = ''
  isRuntimeServerRefreshing.value = true
  try {
    await refreshRuntimeServerDirectory()
    syncRuntimeServerState()
    runtimeServerNotice.value = '服务器列表已刷新。'
    await testRuntimeServerList({ silent: true })
  } catch (error) {
    reportPageError('system-config', 'refresh-runtime-server-directory', error)
    runtimeServerError.value = getErrorMessage(error)
  } finally {
    isRuntimeServerRefreshing.value = false
  }
}

async function selectRuntimeServerFromUi(server: RuntimeServerView) {
  runtimeServerError.value = ''
  runtimeServerNotice.value = ''
  try {
    selectRuntimeServer(server.id)
    syncRuntimeServerState()
    hasConfirmedRuntimeServerSelectionThisSession.value = true
    clearCodexRelayState()
    setClaudeConfigured(false)
    toolNotices.value.codex = '服务器已切换，请重新点击一键登录写入当前节点。'
    toolNotices.value.claude = '服务器已切换，请重新点击一键登录写入当前节点。'
    runtimeServerNotice.value = `已切换到 ${server.name}，当前页面数据正在刷新。`
    notify(`已切换服务器：${server.name}`, 'success')
    startRuntimeServicesAfterServerSelection()
    setPage(activePage.value)
  } catch (error) {
    reportPageError('system-config', 'select-runtime-server', error)
    runtimeServerError.value = getErrorMessage(error)
  }
}

async function returnToRuntimeServerGate() {
  openUserMenu.value = false
  hasConfirmedRuntimeServerSelectionThisSession.value = false
  runtimeServerError.value = ''
  runtimeServerNotice.value = '请重新选择一个服务器。'
  syncRuntimeServerState()
  if (runtimeServers.value.length > 0) {
    await testRuntimeServerList({ silent: true })
  }
}

function handleRuntimeServerChanged() {
  syncRuntimeServerState()
  invalidateOnlinePaymentConfig()
  if (authToken.value) void loadOnlinePaymentConfig({ silent: true })
  void resumePendingRechargeBonusQueue({ force: true, includeBlocked: true })
  if (isCodexThemeDialogOpen.value) {
    void loadCodexThemeCatalog({ silent: true })
  }
}

function invalidateCodexStatusRequests() {
  codexStatusGeneration += 1
  return codexStatusGeneration
}

function invalidateCodexAccountsRequests() {
  codexAccountsLoadGeneration += 1
  isCodexAccountsLoading.value = false
  if (codexAccountsRetryTimer !== null) {
    window.clearTimeout(codexAccountsRetryTimer)
    codexAccountsRetryTimer = null
  }
  return codexAccountsLoadGeneration
}

function beginCodexAccountMutation() {
  stopCodexUltraStatusCheck()
  codexAccountMutationDepth += 1
  invalidateCodexAccountsRequests()
  invalidateCodexStatusRequests()
  let finished = false
  return () => {
    if (finished) return
    finished = true
    codexAccountMutationDepth -= 1
    invalidateCodexAccountsRequests()
    invalidateCodexStatusRequests()
  }
}

function handleCodexConfigUpgradeBusy(busy: boolean) {
  if (busy && !finishCodexConfigUpgradeMutation) {
    finishCodexConfigUpgradeMutation = beginCodexAccountMutation()
    isToolConnecting.value.codex = true
  } else if (!busy && finishCodexConfigUpgradeMutation) {
    finishCodexConfigUpgradeMutation()
    finishCodexConfigUpgradeMutation = null
    isToolConnecting.value.codex = false
  }
}

async function readCodexAccountSwitchRoute() {
  const desktopApi = window.gaogeDesktop
  if (!desktopApi?.getCodexRouterStatus) {
    throw new Error('无法读取当前 Codex 路由状态，请更新桌面软件后重试。')
  }
  const [router, aggregate] = await Promise.all([
    desktopApi.getCodexRouterStatus(),
    desktopApi.getAggregateLoginStatus?.(),
  ])
  const preserveRelay = codexRouterHasActiveRelay(router)
  const source: CodexRelaySource = !preserveRelay
    ? ''
    : aggregate?.enabled && aggregate.running
      ? 'aggregate'
      : codexRelaySource.value === 'one-click'
        ? 'one-click'
        : fuelPackAccountKey.value ? 'fuel-pack' : 'one-click'
  return { preserveRelay, source, aggregate }
}

function applyCodexAccountSwitchRoute(
  result: Pick<GaogeDesktopCodexAccountActivateResponse, 'router' | 'relayPreserved' | 'aggregate'>,
  accountKey: string,
  previousRoute: Awaited<ReturnType<typeof readCodexAccountSwitchRoute>>,
) {
  if (result.router) applyCodexRouterSettings(result.router)
  const relayPreserved = result.relayPreserved ?? codexRouterHasActiveRelay(result.router)
  if (!relayPreserved) {
    markAggregateLoginInactive()
    clearCodexRelayState({ clearFuelRecovery: true })
    return
  }
  connectedTools.value.codex = true
  const aggregate = result.aggregate ?? previousRoute.aggregate
  if (aggregate?.enabled && aggregate.running) {
    applyAggregateLoginStatus(aggregate)
    return
  }
  markAggregateLoginInactive()
  if (previousRoute.source === 'fuel-pack') {
    fuelPackAccountKey.value = accountKey
    localStorage.setItem('gaoge_desktop_fuel_pack_account_key', accountKey)
    setCodexRelaySource('fuel-pack')
  } else {
    fuelPackAccountKey.value = ''
    localStorage.removeItem('gaoge_desktop_fuel_pack_account_key')
    setCodexRelaySource('one-click')
  }
}

function clearCodexRelayState(options: { invalidate?: boolean; clearFuelRecovery?: boolean } = {}) {
  if (options.invalidate !== false) invalidateCodexStatusRequests()
  connectedTools.value.codex = false
  if (options.clearFuelRecovery) setCodexFuelRecoveryAvailable(false)
  fuelPackAccountKey.value = ''
  setCodexRelaySource('')
  localStorage.removeItem('gaoge_desktop_fuel_pack_account_key')
}

function applyAggregateLoginStatus(status: GaogeDesktopAggregateLoginStatus) {
  aggregateLoginStatus.value = status
  if (status.enabled && status.running) {
    connectedTools.value.codex = true
    setCodexFuelRecoveryAvailable(false)
    fuelPackAccountKey.value = ''
    localStorage.removeItem('gaoge_desktop_fuel_pack_account_key')
    setCodexRelaySource('aggregate')
    return
  }
  if (codexRelaySource.value === 'aggregate') {
    clearCodexRelayState({ invalidate: false })
  }
}

function markAggregateLoginInactive() {
  invalidateCodexStatusRequests()
  if (!aggregateLoginStatus.value?.enabled && codexRelaySource.value !== 'aggregate') return
  aggregateLoginStatus.value = {
    enabled: false,
    running: false,
    routerBaseUrl: '',
    defaultModel: '',
    providerCount: 0,
    groupCount: 0,
    modelCount: 0,
    providers: [],
    updatedAt: Date.now(),
  }
  if (codexRelaySource.value === 'aggregate') setCodexRelaySource('')
}

async function loadAggregateLoginStatus(
  options: { silent?: boolean; afterMutation?: boolean } = {},
  requestGeneration?: number,
) {
  if (codexAccountMutationDepth > 0 && !options.afterMutation) return
  if (!window.gaogeDesktop?.getAggregateLoginStatus) return
  const generation = requestGeneration ?? invalidateCodexStatusRequests()
  try {
    const status = await window.gaogeDesktop.getAggregateLoginStatus()
    if (generation !== codexStatusGeneration) return
    applyAggregateLoginStatus(status)
  } catch (error) {
    if (generation !== codexStatusGeneration) return
    reportPageError('aggregate-login', 'load-status', error)
    if (!options.silent) aggregateLoginError.value = getErrorMessage(error)
  }
}

function applyCodexRouterSettings(settings: GaogeDesktopCodexRouterSettings) {
  codexRouterStatus.value = settings
  const relayConfigured = codexRouterHasActiveRelay(settings)
  const relayBaseUrlIsCurrent = isCodexRouterRelayBaseUrlCurrent(settings)
  if (settings.mode === 'official' && !codexRouterHasConfiguredRelay(settings)) {
    setCodexFuelRecoveryAvailable(false)
  }
  connectedTools.value.codex = Boolean(
    relayBaseUrlIsCurrent &&
      relayConfigured,
  )
  if (!relayBaseUrlIsCurrent) {
    clearCodexRelayState({ invalidate: false })
    if (relayConfigured) {
      toolNotices.value.codex = '检测到本机 Codex 中转地址已不是后台当前启用域名，请重新点击一键登录写入新地址。'
    }
  }
  codexRouterForm.value.mode = settings.mode
  const backendModel = resolveCodexBackendModelAfterDefaultMigration(
    localStorage,
    codexModelMigrationOptions(),
    settings.model || '',
    settings.modelOrigin,
  )
  codexRouterForm.value.model = backendModel
  codexRouterForm.value.relayBaseUrl = currentCodexBaseUrl()
  codexRouterForm.value.officialBaseUrl = settings.officialBaseUrl || CODEX_OFFICIAL_BASE_URL
  codexModelOptions.value = filterCodexConversationModels([
    backendModel,
    ...codexModelOptions.value,
  ])
  if (isCodexImageGenerationModel(settings.model || '')) {
    toolWarnings.value.codex = `旧配置中的生图模型 ${settings.model} 不能用于对话，已自动切换到 ${codexRouterForm.value.model}。`
  }
  persistCodexRouterForm()
  if (activeTool.value === 'codex') syncSelectedLoginModelForTool('codex')
}

async function loadCodexRouterStatus(options: { silent?: boolean } = {}) {
  if (codexAccountMutationDepth > 0) return
  if (!window.gaogeDesktop?.getCodexRouterStatus) return
  const generation = invalidateCodexStatusRequests()
  try {
    const [, settings] = await Promise.all([
      loadAggregateLoginStatus({ silent: true }, generation),
      window.gaogeDesktop.getCodexRouterStatus(),
    ])
    if (generation !== codexStatusGeneration) return
    applyCodexRouterSettings(settings)
  } catch (error) {
    if (generation !== codexStatusGeneration) return
    reportPageError('one-click-login', 'load-codex-router-status', error)
    if (!options.silent) toolErrors.value.codex = getToolActionErrorMessage(error, 'codex')
  }
}

async function applySessionSyncSetting(options: ApplyCodexSettingOptions = {}) {
  settingErrors.value.sessionSync = ''
  settingNotices.value.sessionSync = ''
  if (!window.gaogeDesktop?.syncCodexSessions) throw new Error('当前不是桌面环境，无法同步 Codex 会话。')
  if (!options.skipCloseConfirm && !(await confirmCodexClose('同步 Codex 会话'))) {
    settingNotices.value.sessionSync = '已取消同步会话。'
    return ''
  }
  settingLoading.value.sessionSync = true
  try {
    const result = await window.gaogeDesktop.syncCodexSessions()
    const detected = Math.max(result.rolloutSessions || 0, result.rolloutFiles || 0, result.indexedSessionEntries || 0, result.sqliteThreads || 0)
    const indexedPreserved = result.indexedSessionsPreserved || 0
    const indexedFixed = (result.indexedSessionsAdded || 0) + (result.indexedSessionsRemoved || 0)
    const sqliteFixed = (result.providerThreadsChanged || 0) + (result.sqliteBackfilledThreads || 0) + (result.sqliteRolloutPathsChanged || 0) + (result.sqliteMetadataThreadsChanged || 0) + (result.userEventThreadsChanged || 0)
    const rolloutFixed = result.rolloutsChanged || 0
    const synced = result.totalChanged ?? (indexedFixed + sqliteFixed + rolloutFixed)
    const leftovers = (result.providerMismatches || 0) + (result.indexMissingRollouts || 0) + (result.indexStaleEntries || 0)
    const warningCount = result.warnings?.length || 0
    const details = [
      `索引修复 ${indexedFixed}`,
      `线程修复 ${sqliteFixed}`,
      `文件修复 ${rolloutFixed}`,
    ]
    if (indexedPreserved > 0) details.push(`索引保留 ${indexedPreserved}`)
    const projectSync = result.nativeProjectSync
    if (projectSync?.restored) details.push(`项目归属恢复 ${projectSync.restored}`)
    if (projectSync?.deferred) details.push('项目归属恢复未完成')
    if (leftovers > 0) details.push(`待复查 ${leftovers}`)
    if (warningCount > 0) details.push(`提示 ${warningCount}`)
    const summary = `识别 ${detected} 个会话，同步 ${synced} 项。${details.join(' · ')}。`
    settingNotices.value.sessionSync = summary
    if (projectSync?.deferred) settingErrors.value.sessionSync = projectSync.warning || '项目归属恢复未完成，请关闭 Codex 后重试同步。'
    return summary
  } catch (error) {
    reportPageError('system-config', 'sync-codex-sessions', error)
    settingErrors.value.sessionSync = getErrorMessage(error)
    throw error
  } finally {
    settingLoading.value.sessionSync = false
  }
}

function stopCodexPluginStatusCheck() {
  pluginStatusGeneration += 1
  pluginStatusCancelWait?.()
  pluginStatusCancelRequest?.()
  pluginStatusCancelWait = null
  pluginStatusCancelRequest = null
  if (pluginStatusTimer !== null) window.clearTimeout(pluginStatusTimer)
  pluginStatusTimer = null
  pluginStatusChecking.value = false
}

function waitForCodexPluginStatusCheck(generation: number) {
  return new Promise<boolean>((resolve) => {
    if (generation !== pluginStatusGeneration || pluginStatusDisposed) return resolve(false)
    const finish = (proceed: boolean) => {
      if (pluginStatusTimer !== null) window.clearTimeout(pluginStatusTimer)
      pluginStatusTimer = null
      if (pluginStatusCancelWait === cancel) pluginStatusCancelWait = null
      resolve(proceed)
    }
    const cancel = () => finish(false)
    pluginStatusCancelWait = cancel
    pluginStatusTimer = window.setTimeout(() => finish(generation === pluginStatusGeneration), CODEX_PLUGIN_STATUS_INTERVAL_MS)
  })
}

function readCodexPluginStatusWithTimeout(generation: number) {
  return new Promise<GaogeDesktopPluginStatus | null>((resolve, reject) => {
    const read = window.gaogeDesktop?.getCodexPluginsStatus
    if (!read || generation !== pluginStatusGeneration || pluginStatusDisposed) return resolve(null)
    let settled = false
    let timeout: number | null = null
    const finish = (value: GaogeDesktopPluginStatus | null, error?: unknown) => {
      if (settled) return
      settled = true
      if (timeout !== null) window.clearTimeout(timeout)
      if (pluginStatusCancelRequest === cancel) pluginStatusCancelRequest = null
      if (error) reject(error)
      else resolve(value)
    }
    const cancel = () => finish(null)
    pluginStatusCancelRequest = cancel
    timeout = window.setTimeout(() => finish(null, new Error('读取插件运行状态超时，请稍后重新检测。')), CODEX_PLUGIN_STATUS_REQUEST_TIMEOUT_MS)
    Promise.resolve().then(() => read()).then(
      (value) => finish(generation === pluginStatusGeneration && !pluginStatusDisposed ? value : null),
      (error) => finish(null, error),
    )
  })
}

function applyCodexPluginStatus(result: GaogeDesktopPluginResponse | GaogeDesktopPluginStatus) {
  const status = result.status || result
  const mutation = result as Partial<GaogeDesktopPluginResponse>
  const enabled = typeof status.configEnabled === 'boolean' ? status.configEnabled
    : typeof result.configEnabled === 'boolean' ? result.configEnabled
      : typeof status.enabled === 'boolean' ? status.enabled : result.enabled === true
  const error = status.error || status.runtimeError || result.error || result.runtimeError || ''
  const reason = status.reason || ''
  const legacyPatch = ['legacy-runtime-restart-required', 'legacy-or-replaced-hooks-require-restart'].includes(reason)
  const missingEntry = ['native-plugin-entry-unavailable', 'native-plugin-entry-unverified'].includes(reason)
  const unsupported = enabled && (status.state === 'unsupported'
    || ['unsupported-codex-version', 'native-plugin-entry-unavailable', 'native-plugin-entry-unverified',
      'native-plugin-entry-disabled', 'native-account-epoch-unverified', 'native-plugin-binding-unavailable'].includes(reason))
  const notRunning = status.reason === 'codex-not-running'
  // A native entry may only exist while its menu/page is open. Accept the
  // configured monitor without inventing a sidebar button or claiming ready.
  const configuredAwaitingEntry = enabled && !error && !unsupported && !notRunning
    && status.needsRestart !== true && status.configured === true && status.monitoring === true
    && status.runtimeInjected === true && status.listVerified === true
    && status.nativeEntryReady === false && status.state === 'pending' && reason === 'awaiting-native-entry'
  persistSettingToggle('plugins', enabled)
  pluginRuntimeInjected.value = enabled && status.runtimeInjected === true
  pluginNativeEntryReady.value = enabled && status.nativeEntryReady === true
  pluginListVerified.value = enabled && status.listVerified === true
  pluginSearchReady.value = enabled && status.searchReady === true
  // A legacy applied flag or script marker cannot prove a usable native entry.
  pluginRuntimeReady.value = enabled && !error && !unsupported && !notRunning && status.needsRestart !== true && status.runtimeReady === true
    && pluginRuntimeInjected.value && pluginNativeEntryReady.value && pluginListVerified.value
  pluginNeedsRestart.value = status.needsRestart === true
  pluginStatusReason.value = status.reason || ''
  pluginStatusUnsupported.value = unsupported
  pluginDisablePending.value = !enabled && (Boolean(error) || status.pending === true || status.runtimePending === true
    || (status as Partial<GaogeDesktopPluginStatus>).pluginEnhancementsEnabled === true)
  const count = status.availablePluginCount ?? result.availablePluginCount
    ?? mutation.pluginMarketplace?.pluginCount ?? mutation.pluginBootstrap?.pluginCount
    ?? status.indexedPlugins
  if (typeof count === 'number' && Number.isFinite(count)) availablePluginCount.value = Math.max(0, Math.trunc(count))
  settingErrors.value.plugins = error ? getErrorMessage(error) : ''
  if (legacyPatch) {
    pluginStatusMessage.value = `${enabled ? '开启偏好' : '关闭配置'}已保存；检测到旧插件补丁或被替换的增强钩子，尚未确认清理完成。若补丁写入应用文件，普通重启仍会加载，请先备份并恢复干净的 Codex 安装后重新检测；本操作不会自动清理文件或重启，已安装插件及各自启停设置保留。`
  } else if (!enabled) {
    pluginStatusMessage.value = pluginNeedsRestart.value
      ? '关闭配置已保存；当前 Codex 窗口需重启后完全移除增强。已安装插件及各自启停设置均保留。'
      : pluginDisablePending.value
        ? '关闭配置已保存，正在确认当前 Codex 窗口的增强已移除；已安装插件及各自启停设置均保留。'
        : '入口增强已关闭；已安装插件及各自启停设置均保留。'
  } else if (pluginRuntimeReady.value) {
    pluginStatusMessage.value = pluginSearchReady.value
      ? '插件入口、列表与搜索已验证；请单独安装需要的插件，并完成各插件要求的服务授权。'
      : '插件入口与列表已验证；搜索尚未验证，各插件仍需单独安装或授权。'
  } else if (configuredAwaitingEntry) {
    pluginStatusMessage.value = '插件增强配置已保存，原生列表已验证；保留原生侧栏，等待原生插件入口显示。'
  } else if (pluginNeedsRestart.value) {
    pluginStatusMessage.value = '入口增强配置已保存，当前尚未生效。请先保存任务，再通过软件内“重启 Codex”确认重启，然后重新检测。'
  } else if (reason === 'native-plugin-entry-disabled') {
    pluginStatusMessage.value = 'Codex 原生插件入口当前已禁用或被原生界面限制，尚未确认可用；请在 Codex 中检查登录状态和插件访问权限后重新检测，不会绕过原生限制。'
  } else if (missingEntry) {
    pluginStatusMessage.value = '当前 Codex 界面尚未找到已验证的可用插件入口；请先打开 Codex 的插件页面再重新检测。若仍无入口，请更新兼容适配；不会改动账号或插件权限。'
  } else if (reason === 'native-account-epoch-unverified') {
    pluginStatusMessage.value = '尚未安全验证当前账号作用域，无法确认插件可用；请等待 Codex 完成账号初始化后重新检测。不会读取凭据、修改认证或沿用其他账号的验证结果。'
  } else if (reason === 'native-plugin-binding-unavailable') {
    pluginStatusMessage.value = '暂未找到已验证的原生插件请求接口或当前账号作用域，尚未确认功能可用；请等待 Codex 初始化后重新检测，仍无结果时更新兼容适配。'
  } else if (pluginStatusUnsupported.value) {
    pluginStatusMessage.value = reason === 'unsupported-codex-version'
      ? '当前 Codex 版本暂不支持此插件入口适配，尚未开启；请更新兼容适配后重新检测。'
      : '当前插件适配尚未通过原生可用性验证；请更新兼容适配后重新检测，不会绕过账号或插件权限。'
  } else if (pluginStatusReason.value === 'codex-not-running') {
    pluginStatusMessage.value = '开启偏好已保存，Codex 尚未运行；请从本软件打开 Codex 后重新检测，不会为此自动启动或重启。'
  } else if (pluginStatusReason.value === 'awaiting-native-plugin-entry') {
    pluginStatusMessage.value = '原生插件列表已验证，正在等待可用的插件入口；请打开 Codex 的插件页面后重新检测。'

  } else {
    pluginStatusMessage.value = '配置已保存，正在等待原生插件入口与列表验证；尚未确认功能可用。'
  }
  if ('imageToolsMigration' in status && status.imageToolsMigration && status.imageToolsMigration.status !== 'not_checked') {
    imageToolsMigrationFeedback.value = getImageToolsMigrationFeedback(status.imageToolsMigration)
  }
  return (!enabled && !pluginDisablePending.value) || pluginRuntimeReady.value || configuredAwaitingEntry || pluginNeedsRestart.value
    || pluginStatusUnsupported.value || pluginStatusReason.value === 'codex-not-running' || Boolean(error)
}

async function pollCodexPluginStatus(generation: number) {
  if (!window.gaogeDesktop?.getCodexPluginsStatus) {
    pluginRuntimeReady.value = false
    settingErrors.value.plugins = '当前桌面版本不支持插件运行验证，请更新软件；尚未确认入口可用。'
    return
  }
  pluginStatusChecking.value = true
  try {
    for (let attempt = 0; attempt < CODEX_PLUGIN_STATUS_MAX_ATTEMPTS; attempt += 1) {
      if (generation !== pluginStatusGeneration || pluginStatusDisposed) return
      const result = await readCodexPluginStatusWithTimeout(generation)
      if (generation !== pluginStatusGeneration || pluginStatusDisposed) return
      if (!result) {
        pluginRuntimeReady.value = false
        settingErrors.value.plugins = '未收到有效的插件运行状态，请稍后重新检测；尚未确认当前窗口状态。'
        return
      }
      if (applyCodexPluginStatus(result)) return
      if (attempt + 1 < CODEX_PLUGIN_STATUS_MAX_ATTEMPTS && !(await waitForCodexPluginStatusCheck(generation))) return
    }
    if (generation === pluginStatusGeneration && !pluginStatusDisposed) {
      settingErrors.value.plugins = pluginDisablePending.value
        ? '关闭配置已保存，但尚未确认当前 Codex 窗口的增强已移除，已停止自动检测。可重新检测，或保存任务后从软件内确认重启 Codex。'
        : '插件入口仍未通过验证，已停止自动检测；开启偏好已保留。可重新检测，或保存任务后从软件内确认重启 Codex。'
    }
  } catch (error) {
    if (generation !== pluginStatusGeneration || pluginStatusDisposed) return
    pluginRuntimeReady.value = false
    settingErrors.value.plugins = getErrorMessage(error)
    reportPageError('system-config', 'verify-codex-plugin-status', error)
  } finally {
    if (generation === pluginStatusGeneration) pluginStatusChecking.value = false
  }
}

async function applyPluginSetting(enabled: boolean, _options: ApplyCodexSettingOptions = {}) {
  // Claim the operation before any await; toggling never implicitly restarts Codex.
  if (pluginMutationInFlight.value || pluginStatusDisposed) return ''
  pluginMutationInFlight.value = true
  stopCodexPluginStatusCheck()
  const generation = pluginStatusGeneration
  settingLoading.value.plugins = true
  settingErrors.value.plugins = ''
  settingNotices.value.plugins = ''
  pluginStatusMessage.value = ''
  try {
    if (!window.gaogeDesktop?.setCodexPlugins) throw new Error('当前不是桌面环境，无法写入 Codex 插件配置。')
    const result = await window.gaogeDesktop.setCodexPlugins({ enabled })
    if (generation !== pluginStatusGeneration || pluginStatusDisposed) return ''
    const finished = applyCodexPluginStatus(result)
    if (enabled && !settingToggles.value.plugins && !settingErrors.value.plugins) {
      settingErrors.value.plugins = '插件入口增强配置未开启，请检查提示后重试。'
    }
    settingLoading.value.plugins = false
    if (!finished) await pollCodexPluginStatus(generation)
    if (generation === pluginStatusGeneration && !pluginStatusDisposed && !settingErrors.value.plugins) {
      settingNotices.value.plugins = pluginStatusMessage.value
    }
    return pluginStatusMessage.value
  } catch (error) {
    if (generation !== pluginStatusGeneration || pluginStatusDisposed) return ''
    reportPageError('system-config', enabled ? 'enable-codex-plugins' : 'disable-codex-plugins', error)
    // Reconcile the saved preference, but do not let a status read erase the failure.
    try {
      const status = await readCodexPluginStatusWithTimeout(generation)
      if (status && generation === pluginStatusGeneration && !pluginStatusDisposed) applyCodexPluginStatus(status)
    } catch { /* The mutation error remains the actionable error. */ }
    if (generation === pluginStatusGeneration && !pluginStatusDisposed) settingErrors.value.plugins = getErrorMessage(error)
    return ''
  } finally {
    pluginMutationInFlight.value = false
    if (generation === pluginStatusGeneration) settingLoading.value.plugins = false
  }
}

async function loadCodexPluginsStatus(_options: { silent?: boolean } = {}) {
  if (pluginMutationInFlight.value || pluginStatusDisposed) return
  stopCodexPluginStatusCheck()
  settingErrors.value.plugins = ''
  await pollCodexPluginStatus(pluginStatusGeneration)
}

async function loadCodexSessionDeleteStatus(options: { silent?: boolean } = {}) {
  if (!window.gaogeDesktop?.getCodexSessionDeleteStatus) {
    persistSettingToggle('sessionDelete', false)
    sessionDeleteRuntimeReady.value = false
    return
  }
  settingLoading.value.sessionDelete = true
  if (!options.silent) settingErrors.value.sessionDelete = ''
  try {
    const result = await window.gaogeDesktop.getCodexSessionDeleteStatus()
    persistSettingToggle('sessionDelete', result.enabled === true)
    sessionDeleteRuntimeReady.value = result.runtimeReady === true
  } catch (error) {
    reportPageError('system-config', 'load-codex-session-delete-status', error)
    if (!options.silent) settingErrors.value.sessionDelete = getErrorMessage(error)
  } finally {
    settingLoading.value.sessionDelete = false
  }
}

function applyCodexEnhancementResults(
  enhancements?: {
    plugin?: GaogeDesktopCodexEnhancementResult
    sessionDelete?: GaogeDesktopCodexEnhancementResult
    theme?: GaogeDesktopCodexEnhancementResult
  } | null,
) {
  if (enhancements?.plugin) {
    persistSettingToggle('plugins', enhancements.plugin.enabled === true)
    // Launch completion is not plugin-entry verification; refresh live evidence.
    pluginRuntimeReady.value = false
    if (!pluginMutationInFlight.value) void loadCodexPluginsStatus({ silent: true })
    if (enhancements.plugin.disabledAfterFailure) {
      settingErrors.value.plugins = enhancements.plugin.error || '插件加载失败，已自动关闭。'
      settingNotices.value.plugins = ''
    }
  }
  if (enhancements?.sessionDelete) {
    persistSettingToggle('sessionDelete', enhancements.sessionDelete.enabled === true)
    sessionDeleteRuntimeReady.value = enhancements.sessionDelete.applied === true
    if (enhancements.sessionDelete.disabledAfterFailure) {
      settingErrors.value.sessionDelete = enhancements.sessionDelete.error || '删除会话加载失败，已自动关闭。'
      settingNotices.value.sessionDelete = ''
    }
  }
  if (enhancements?.theme) {
    if (enhancements.theme.disabledAfterFailure) {
      const failure = enhancements.theme.error || '主题加载失败，已恢复 Codex 官方默认主题。'
      codexThemeActiveName.value = ''
      codexThemeCatalogError.value = failure
      void loadCodexThemeCatalog({ silent: true }).finally(() => {
        if (!codexThemeActiveName.value) codexThemeCatalogError.value = failure
      })
    } else if (enhancements.theme.requested) {
      void loadCodexThemeCatalog({ silent: true })
    }
  }
}

function codexLaunchWarningMessages(result?: GaogeDesktopCodexLaunchFeedback | null) {
  return [...new Set([
    ...(result?.warnings || []),
    ...(result?.appPatch?.warnings || []),
    ...(result?.appPatch?.ultra?.warnings || []),
    ...(result?.launch?.warnings || []),
    ...(result?.ultra?.warnings || []),
    ...(result?.launch?.ultra?.warnings || []),
    ...(result?.apiMode?.warnings || []),
    ...(result?.launch?.apiMode?.warnings || []),
    ...(result?.nativeFast?.warnings || []),
    ...(result?.launch?.nativeFast?.warnings || []),
    ...(result?.appPatch?.nativeFast?.warnings || []),
  ].filter((warning): warning is string => typeof warning === 'string')
    .map((warning) => warning.trim()).filter(Boolean))]
}

function codexUltraFeedback(result?: GaogeDesktopCodexLaunchFeedback | null) {
  const status = result?.launch?.ultra ?? result?.ultra ?? result?.appPatch?.ultra
  if (status?.requested === false || status?.reason === 'disabled') {
    return { notice: '', warning: '', pending: false }
  }
  const warnings: Record<string, string> = {
    'unsupported-query': '当前 Codex 版本的 Ultra 界面尚未适配，不能视为已启用。请更新本软件的兼容适配后再重启 Codex；反复 API 登录不能修复版本不兼容。',
    'verification-failed': 'Ultra 界面检查未通过，尚未确认生效。请打开当前聊天的模型或思考档位选择器后重试；若仍失败，请更新本软件并重新启动 Codex。',
    'connection-unavailable': '暂时无法连接 Codex 界面，Ultra 检查尚未完成。请完全退出 Codex，再从本软件点击「重启 Codex」；若仍失败，请检查启动路径是否仍指向更新前的旧版本，避免从旧快捷方式启动。',
    'asset-timeout': 'Ultra 界面资源加载超时，正在自动重试。',
    'catalog-unavailable': 'Ultra 模型目录不可用，请检查当前配置档（profile）是否覆盖模型目录，再重新执行 API 登录以修复配置；无需删除个人配置或密钥。',
    'route-inactive': '当前 API 路由未就绪，Ultra 适配尚未启用，请检查登录配置及当前配置档（profile）的提供商、路由和模型目录是否一致，再从本软件重启 Codex。',
    'observation-expired': 'Ultra 上次检查结果已过期，尚未确认当前窗口生效。请打开本地聊天的模型或思考档位选择器，重新检查当前窗口。',
  }
  const reason = status?.reason || ''
  if (warnings[reason]) {
    return { notice: '', warning: warnings[reason], pending: reason === 'asset-timeout' || reason === 'observation-expired' }
  }
  // A previous process/window verification is not evidence for the current one.
  if (status?.connectionState === 'disconnected') {
    return { notice: '', warning: warnings['connection-unavailable'], pending: false }
  }
  if (status?.observationFresh === false
      && (status.verified === true || status.ready === true || typeof status.observationAgeMs === 'number')) {
    return { notice: '', warning: warnings['observation-expired'], pending: true }
  }
  if (status?.error) {
    return { notice: '', warning: 'Ultra 尚未就绪，当前可继续使用其他思考档位。请先从本软件重启 Codex，并检查当前模型、配置档（profile）及模型目录；仍失败时可反馈不含密钥的状态提示。', pending: false }
  }
  if (reason === 'setting-disabled') {
    return { notice: '当前选择器未允许显示 Ultra，请检查思考档位设置；这是显示设置限制，不代表当前模型不支持。调整后请重新打开选择器验证。', warning: '', pending: status?.enabled !== false }
  }
  if (reason === 'model-unsupported') {
    return { notice: '当前模型未声明支持 Ultra，请切换到模型目录中明确支持 Ultra 的模型；若预期已支持，请检查当前配置档（profile）使用的模型目录。不会把不支持的模型强制标为支持。', warning: '', pending: status?.enabled !== false }
  }
  if (reason === 'visible-model-unsupported') {
    return { notice: '当前模型或可见选项未提供 Ultra，请确认当前聊天选中的模型与模型目录一致，再重新打开思考档位选择器；可继续使用其他思考档位。', warning: '', pending: status?.enabled !== false }
  }
  if (reason === 'awaiting-visible-picker') {
    return { notice: '当前输入框仍在等待 Ultra 验证，请打开本地聊天的模型或思考档位选择器；若 Ultra 可选，请手动选择一次以完成原生选择检查。不会自动切换档位；目录准备完成或适配已加载不等于 Ultra 已可用。', warning: '', pending: true }
  }
  if (status?.verified === true && status.ready === true && status.enabled !== false) {
    return { notice: 'Ultra 已通过本次检查。', warning: '', pending: false }
  }
  if (status || result?.appPatch?.modelPickerEnhanced || result?.appPatch?.ultraReasoningPatched !== undefined) {
    return { notice: 'Ultra 检查尚未完成。', warning: '', pending: true }
  }
  return { notice: '', warning: '', pending: false }
}

function codexNativeFastFeedback(result?: GaogeDesktopCodexLaunchFeedback | null) {
  const status = result?.launch?.nativeFast ?? result?.nativeFast ?? result?.appPatch?.nativeFast
  if (!status || status.enabled === false || status.reason === 'disabled') {
    return { notice: '', warning: '', pending: false }
  }
  const reason = status.reason || ''
  if (status.phase === 'unsupported' || [
    'unsupported-modules', 'native-fast-unavailable', 'native-runtime-unavailable',
    'module-preparation-failed', 'invalid-prepared-modules', 'module-install-failed',
  ].includes(reason)) {
    return { notice: '', warning: '当前 Codex 版本的原生加速适配未完成，尚未确认 Fast 可用。请更新本软件的兼容适配，再从本软件点击「重启 Codex」。', pending: false }
  }
  if (reason === 'connection-unavailable') {
    return { notice: '', warning: '暂时无法连接 Codex 界面，原生加速尚未确认生效。请完全退出 Codex，再从本软件点击「重启 Codex」。', pending: false }
  }
  if (status.error) {
    return { notice: '', warning: '原生加速检查未通过，尚未确认 Fast 可用。请从本软件点击「重启 Codex」后重试。', pending: false }
  }
  if (status.needsRestart === true || reason === 'awaiting-restart') {
    return { notice: '', warning: '原生加速等待重启，尚未确认 Fast 可用。请从本软件点击「重启 Codex」后再检查。', pending: false }
  }
  if (status.enabled === true && status.ready === true && status.verified === true
      && status.compiled === true && reason === 'compiled'
      && (status.phase === undefined || status.phase === 'compiled')) {
    return { notice: '原生 Fast 入口已通过本次检查。', warning: '', pending: false }
  }
  return { notice: '', warning: '原生加速适配检查尚未完成，尚未确认 Fast 可用。',
    pending: ['awaiting-page', 'preparing-modules', 'preparing', 'prepared', 'armed'].includes(reason)
      || ['pending', 'preparing', 'prepared', 'armed'].includes(status.phase || '') }
}

function codexLaunchWarnings(result?: GaogeDesktopCodexLaunchFeedback | null) {
  return [...new Set([...codexLaunchWarningMessages(result), codexUltraFeedback(result).warning,
    codexNativeFastFeedback(result).warning].filter(Boolean))].join(' ')
}

function codexApiModeFeedback(result?: GaogeDesktopCodexLaunchFeedback | null) {
  const status = result?.launch?.apiMode ?? result?.apiMode
  if (!status || status.requested === false || status.reason === 'disabled') {
    return { notice: '', warning: '', pending: false }
  }
  if (status.reason === 'unsupported-runtime') {
    return { notice: '', warning: status.warnings?.join(' ') || '当前 Codex 版本的纯 API 编码模式尚未适配，尚未确认成功。', pending: false }
  }
  if (status.verified === true && status.ready === true && status.enabled !== false
      && status.reason === 'coding' && !status.error) {
    return { notice: '纯 API 登录已使用 Codex 编码模式。', warning: '', pending: false }
  }
  return { notice: '', warning: status.warnings?.join(' ') || '纯 API 编码模式正在验证，尚未确认生效。',
    pending: true }
}

function codexRuntimeFeedback(result?: GaogeDesktopCodexLaunchFeedback | null) {
  const ultra = codexUltraFeedback(result)
  const apiMode = codexApiModeFeedback(result)
  const nativeFast = codexNativeFastFeedback(result)
  return { notice: [ultra.notice, apiMode.notice, nativeFast.notice].filter(Boolean).join(' '),
    warning: [ultra.warning, apiMode.warning, nativeFast.warning].filter(Boolean).join(' '),
    pending: ultra.pending || apiMode.pending || nativeFast.pending }
}

let codexUltraStatusGeneration = 0
let codexUltraStatusTimer: number | null = null
let codexUltraStatusCancelWait: (() => void) | null = null

function cancelCodexUltraStatusWait() {
  if (codexUltraStatusTimer !== null) window.clearTimeout(codexUltraStatusTimer)
  codexUltraStatusTimer = null
  const cancel = codexUltraStatusCancelWait
  codexUltraStatusCancelWait = null
  cancel?.()
}

function stopCodexUltraStatusCheck() {
  codexUltraStatusGeneration += 1
  cancelCodexUltraStatusWait()
}

function waitForCodexUltraStatusCheck() {
  return new Promise<boolean>((resolve) => {
    codexUltraStatusCancelWait = () => resolve(false)
    codexUltraStatusTimer = window.setTimeout(() => {
      codexUltraStatusTimer = null
      codexUltraStatusCancelWait = null
      resolve(true)
    }, 2000)
  })
}

function showCodexLaunchFeedback(
  result: GaogeDesktopCodexLaunchFeedback,
  message: string,
  extraWarnings: Array<string | undefined> = [],
  forceWarning = false,
  target: 'codex' | 'aggregate' = 'codex',
) {
  stopCodexUltraStatusCheck()
  const generation = codexUltraStatusGeneration
  const initialRuntimeWarnings = new Set([
    ...(result.ultra?.warnings || []), ...(result.launch?.ultra?.warnings || []), ...(result.appPatch?.ultra?.warnings || []),
    ...(result.apiMode?.warnings || []), ...(result.launch?.apiMode?.warnings || []),
    ...(result.nativeFast?.warnings || []), ...(result.launch?.nativeFast?.warnings || []),
    ...(result.appPatch?.nativeFast?.warnings || []),
  ].map((warning) => warning.trim()))
  const baseWarnings = [...new Set([...codexLaunchWarningMessages(result), ...extraWarnings]
    .filter((warning): warning is string => typeof warning === 'string')
    .map((warning) => warning.trim()).filter((warning) => warning && !initialRuntimeWarnings.has(warning)))]
  const readNotice = () => target === 'aggregate' ? aggregateLoginNotice.value : toolNotices.value.codex
  const readWarning = () => target === 'aggregate' ? aggregateLoginError.value : toolWarnings.value.codex
  let lastNotice = readNotice()
  let lastWarning = readWarning()
  const stillCurrent = () => generation === codexUltraStatusGeneration
    && readNotice() === lastNotice && readWarning() === lastWarning
    && (target === 'aggregate' || !toolErrors.value.codex)
  const display = (feedback: ReturnType<typeof codexUltraFeedback>, warnings: string[] = []) => {
    const warning = [...new Set([...baseWarnings, ...warnings, feedback.warning].filter(Boolean))].join(' ')
    const text = [message, feedback.notice, warning].filter(Boolean).join(' ')
    if (target === 'aggregate') {
      lastNotice = [message, feedback.notice].filter(Boolean).join(' ')
      lastWarning = warning
      aggregateLoginNotice.value = lastNotice
      aggregateLoginError.value = lastWarning
    } else {
      lastNotice = warning || forceWarning ? '' : text
      lastWarning = warning || forceWarning ? text : ''
      toolNotices.value.codex = lastNotice
      toolWarnings.value.codex = lastWarning
    }
  }
  const initial = codexRuntimeFeedback(result)
  let latestResult = result
  let latestFeedback = initial
  display(initial)
  const readStatus = window.gaogeDesktop?.getCodexUltraStatus
  const readApiMode = window.gaogeDesktop?.getCodexApiModeStatus
  const readNativeFast = window.gaogeDesktop?.getCodexNativeFastStatus
  const canCheck = () => Boolean(
    (codexUltraFeedback(latestResult).pending && readStatus)
    || (codexApiModeFeedback(latestResult).pending && readApiMode)
    || (codexNativeFastFeedback(latestResult).pending && readNativeFast))
  if (!initial.pending || !canCheck()) return
  void (async () => {
    for (let attempt = 0; attempt < 15; attempt += 1) {
      if (!await waitForCodexUltraStatusCheck() || !stillCurrent()) return
      let statuses: [GaogeDesktopCodexUltraResult | null, GaogeDesktopCodexUltraResult | null,
        GaogeDesktopCodexNativeFastResult | null] | null
      try {
        statuses = await Promise.race([
          Promise.all([readStatus ? readStatus() : Promise.resolve(latestResult.launch?.ultra ?? latestResult.ultra ?? null),
            readApiMode ? readApiMode() : Promise.resolve(latestResult.launch?.apiMode ?? latestResult.apiMode ?? null),
            readNativeFast ? readNativeFast() : Promise.resolve(latestResult.launch?.nativeFast
              ?? latestResult.nativeFast ?? latestResult.appPatch?.nativeFast ?? null)]),
          waitForCodexUltraStatusCheck().then(() => null),
        ])
      } catch {
        statuses = null
      }
      if (!stillCurrent()) return
      cancelCodexUltraStatusWait()
      if (!statuses || (codexApiModeFeedback(latestResult).pending && readApiMode && !statuses[1])
        || (codexUltraFeedback(latestResult).pending && readStatus && !statuses[0])
        || (codexNativeFastFeedback(latestResult).pending && readNativeFast && !statuses[2])) {
        const warning = codexApiModeFeedback(latestResult).pending
          ? '暂时无法完成纯 API 编码模式检查，尚未确认生效。'
          : codexNativeFastFeedback(latestResult).pending
            ? '暂时无法完成原生加速检查，尚未确认 Fast 可用。'
            : '暂时无法完成 Ultra 检查，当前可继续使用其他思考档位。'
        display({ ...latestFeedback, warning: [latestFeedback.warning, warning].filter(Boolean).join(' '), pending: false })
        return
      }
      const [status, apiMode, nativeFastStatus] = statuses
      const nativeFast = nativeFastStatus ?? latestResult.launch?.nativeFast
        ?? latestResult.nativeFast ?? latestResult.appPatch?.nativeFast ?? null
      latestResult = { ultra: status, apiMode, nativeFast }
      const feedback = codexRuntimeFeedback(latestResult)
      latestFeedback = feedback
      display(feedback, [...(status?.warnings || []), ...(apiMode?.warnings || []), ...(nativeFast?.warnings || [])])
      if (!feedback.pending || !canCheck()) return
    }
    if (stillCurrent()) display(latestFeedback.notice === 'Ultra 检查尚未完成。'
      ? { ...latestFeedback, notice: 'Ultra 检查尚未完成，可继续使用当前可见的思考档位。', pending: false }
      : { ...latestFeedback, pending: false })
  })()
}

function codexOfficialAccountRestoreNotice(result: GaogeDesktopCodexDisableResponse, identityVerified = false) {
  const cleanup = result.authCleanup
  if (cleanup?.reason === 'native_signed_out_after_missing_official_auth') {
    return '原账号登录凭据缺失，已恢复官方未登录状态，请在 Codex 中重新登录自己的账号。'
  }
  if (cleanup?.reason === 'native_signed_out_after_invalid_official_auth') {
    return '原账号登录已失效，已恢复官方未登录状态，请在 Codex 中重新登录自己的账号。'
  }
  if (cleanup?.reason === 'preserved_current_auth_after_missing_official_auth') {
    return '原账号登录凭据缺失，无法恢复原账号，已保留当前登录状态。'
  }
  if (cleanup?.reason === 'preserved_current_auth_after_invalid_official_auth') {
    return '原账号登录已失效，无法恢复原账号，已保留当前登录状态。'
  }
  if (cleanup?.reason === 'native_signed_out_after_corrupt_restore') {
    return '恢复记录损坏，未找到可确认的官方登录。请在 Codex 中重新登录自己的订阅账号。'
  }
  if (cleanup?.reason === 'preserved_live_official_auth_after_corrupt_restore') {
    return '恢复记录损坏，已保留当前可确认的官方账号。'
  }
  if (cleanup?.reason === 'restored_pre_login_signed_out'
    || cleanup?.reason === 'missing_auth'
    || (cleanup?.removed && !cleanup.restored)) {
    return '当前处于官方未登录状态，请在 Codex 中登录自己的账号。'
  }
  if (cleanup?.restored === false && cleanup.restoredAccountKey) {
    return '官方路由已恢复，但没有确认恢复原账号；当前登录凭据已保留，请核对账号。'
  }
  if (cleanup?.restoredAccountKey) return identityVerified
    ? '原账号本机登录凭据已恢复并核验；尚未核验 Codex 原生会话，请以其界面状态为准。'
    : '官方账号登录状态待核验。'
  if (cleanup?.restored) return '已恢复登录配置，账号登录状态待核验。'
  return ''
}

async function verifyCodexOfficialAccountRestore(result: GaogeDesktopCodexDisableResponse) {
  const verification = result.authVerification
  const cleanup = result.authCleanup
  const expectedKey = String(verification?.expectedAccountKey || cleanup?.restoredAccountKey || '').trim()
  const generation = invalidateCodexAccountsRequests()
  let timer: number | undefined
  let current: GaogeDesktopCodexAccount | null = null
  try {
    if (!window.gaogeDesktop?.getCodexAccounts) throw new Error('当前桌面版本不支持登录状态核验')
    const rawState = await Promise.race([
      window.gaogeDesktop.getCodexAccounts(),
      new Promise<never>((_, reject) => {
        timer = window.setTimeout(() => reject(new Error('登录状态核验超时')), 8000)
      }),
    ])
    if (generation !== codexAccountsLoadGeneration) {
      return { notice: '', warning: '官方路由已恢复，但账号状态已变化，未能确认原账号登录；请刷新账号后核验。' }
    }
    // The explicit backend currentAccount reflects local auth; saved/isActive/selected
    // fallbacks are presentation data, not proof of credentials or a native session.
    current = normalizeCodexAccount(rawState?.currentAccount)
    const normalized = normalizeCodexAccountsState(rawState)
    codexAccountsState.value = {
      ...normalized,
      currentAccount: current,
      activeAccountKey: current?.accountKey || '',
      accounts: normalized.accounts.map((account) => ({
        ...account,
        isActive: Boolean(current && current.accountKey === account.accountKey),
        isLiveCurrent: Boolean(current && current.accountKey === account.accountKey),
      })),
    }
    ensureSelectedCodexAccount()
    syncOfficialSubscriptionRecordsFromAccounts()
  } catch (error) {
    reportPageError('official-restore', 'verify-current-account', error)
    return { notice: '', warning: '官方路由已恢复，但未能确认原账号登录：' + getCodexAccountErrorMessage(error) + '。请刷新账号核验，不要重复开关中转。' }
  } finally {
    if (timer !== undefined) window.clearTimeout(timer)
  }
  const signedOut = cleanup?.reason === 'restored_pre_login_signed_out'
    || cleanup?.reason === 'missing_auth'
    || cleanup?.reason?.startsWith('native_signed_out_')
    || Boolean(cleanup?.removed && !cleanup.restored)
  if (verification?.status === 'failed') {
    return { notice: '', warning: '官方路由已恢复，但原账号登录核验失败，未能确认恢复成功；请刷新账号并检查 Codex 当前登录。' }
  }
  if (expectedKey && (!current || current.accountKey !== expectedKey
      || current.requiresReauth === true || current.canSwitch === false)) {
    return { notice: '', warning: '官方路由已恢复，但当前登录账号与原账号不一致或已失效，未能确认原账号恢复；请检查账号管理，不会自动选择其他账号。' }
  }
  if (signedOut) {
    return current
      ? { notice: '', warning: '官方路由已恢复，但当前账号与原始未登录状态不一致，未能确认登录恢复结果；请刷新账号核验。' }
      : { notice: codexOfficialAccountRestoreNotice(result), warning: '' }
  }
  const pending = result.codexLaunchQueued === true || result.codexLaunched !== true
    || verification?.status === 'pending' || verification?.checkedAfterLaunch === false
  if (pending && (expectedKey || cleanup?.restored || verification?.status === 'pending')) {
    return { notice: '', warning: '官方路由及登录配置已恢复，但尚未确认原生登录；待 Codex 启动后核验账号。' }
  }
  if (expectedKey) return { notice: codexOfficialAccountRestoreNotice(result, true), warning: '' }
  if (cleanup?.restored) return { notice: '', warning: '官方路由已恢复，但恢复记录没有可核对的原账号标识，未能确认账号登录；请在 Codex 中核验。' }
  return { notice: codexOfficialAccountRestoreNotice(result), warning: '' }
}

async function loadCodexLaunchTarget(options: { silent?: boolean } = {}) {
  if (!window.gaogeDesktop?.getCodexLaunchTarget) return
  isCodexLaunchTargetLoading.value = true
  if (!options.silent) codexLaunchTargetError.value = ''
  try {
    codexLaunchTarget.value = await window.gaogeDesktop.getCodexLaunchTarget()
    if (codexLaunchTarget.value.warning) {
      codexLaunchTargetError.value = codexLaunchTarget.value.warning
    }
  } catch (error) {
    reportPageError('system-config', 'load-codex-launch-target', error)
    if (!options.silent) codexLaunchTargetError.value = getErrorMessage(error)
  } finally {
    isCodexLaunchTargetLoading.value = false
  }
}

async function selectCodexLaunchTarget() {
  if (!window.gaogeDesktop?.selectCodexLaunchTarget) {
    codexLaunchTargetError.value = '当前不是桌面环境，无法设置 Codex 启动路径。'
    return
  }
  if (!(await confirmCodexRestart('设置 Codex / ChatGPT 启动路径'))) return
  isCodexLaunchTargetLoading.value = true
  codexLaunchTargetError.value = ''
  codexLaunchTargetNotice.value = ''
  try {
    const result = await window.gaogeDesktop.selectCodexLaunchTarget()
    if (result.cancelled) {
      codexLaunchTargetNotice.value = '已取消选择启动路径。'
      return
    }
    codexLaunchTarget.value = result
    applyCodexEnhancementResults(result.restart)
    const warning = codexLaunchWarnings(result.restart)
    codexLaunchTargetNotice.value = result.restart?.launched
      ? `已使用手动路径重新打开 Codex。${warning}`.trim()
      : '启动路径已保存，但 Codex 未能自动打开，请检查所选程序。'
    if (!result.restart?.launched) {
      codexLaunchTargetError.value = warning || 'Codex 自动启动失败。'
    }
  } catch (error) {
    reportPageError('system-config', 'select-codex-launch-target', error)
    codexLaunchTargetError.value = getErrorMessage(error)
  } finally {
    isCodexLaunchTargetLoading.value = false
  }
}

async function resetCodexLaunchTarget() {
  if (!window.gaogeDesktop?.resetCodexLaunchTarget) {
    codexLaunchTargetError.value = '当前不是桌面环境，无法恢复自动识别路径。'
    return
  }
  if (!(await confirmCodexRestart('恢复自动识别启动路径'))) return
  isCodexLaunchTargetLoading.value = true
  codexLaunchTargetError.value = ''
  codexLaunchTargetNotice.value = ''
  try {
    const result = await window.gaogeDesktop.resetCodexLaunchTarget()
    codexLaunchTarget.value = result
    applyCodexEnhancementResults(result.restart)
    const warning = codexLaunchWarnings(result.restart)
    codexLaunchTargetNotice.value = result.restart?.launched
      ? `已恢复自动识别路径并重新打开 Codex。${warning}`.trim()
      : '已恢复自动识别路径，但 Codex 未能自动打开。'
    if (!result.restart?.launched) {
      codexLaunchTargetError.value = warning || '没有识别到可启动的 Codex。'
    }
  } catch (error) {
    reportPageError('system-config', 'reset-codex-launch-target', error)
    codexLaunchTargetError.value = getErrorMessage(error)
  } finally {
    isCodexLaunchTargetLoading.value = false
  }
}

async function applySessionDeleteSetting(enabled: boolean) {
  settingErrors.value.sessionDelete = ''
  settingNotices.value.sessionDelete = ''
  if (!window.gaogeDesktop?.setCodexSessionDelete) {
    throw new Error('当前不是桌面环境，无法设置 Codex 删除会话功能。')
  }
  if (enabled) {
    const confirmed = await confirmAction(
      '开启后将关闭并重新启动 Codex，以加载会话删除按钮。此操作不会修改模型、账号、登录配置或现有会话。是否继续？',
      {
        tone: 'warning',
        title: '开启删除会话',
        confirmText: '开启并重启',
        cancelText: '取消',
      },
    )
    if (!confirmed) {
      settingNotices.value.sessionDelete = '已取消开启删除会话。'
      return
    }
  }

  settingLoading.value.sessionDelete = true
  try {
    const result = await window.gaogeDesktop.setCodexSessionDelete({ enabled })
    applyCodexEnhancementResults(result.enhancements || result.launch)
    persistSettingToggle('sessionDelete', result.enabled === true)
    sessionDeleteRuntimeReady.value = result.runtimeReady === true
    settingNotices.value.sessionDelete = result.message || (
      enabled ? '删除会话功能已开启。' : '删除会话功能已关闭。'
    )
    if (enabled && result.enabled !== true) {
      settingErrors.value.sessionDelete = result.error || result.enhancements?.sessionDelete.error || '删除会话加载失败，已自动关闭。'
    }
  } catch (error) {
    reportPageError('system-config', enabled ? 'enable-codex-session-delete' : 'disable-codex-session-delete', error)
    settingErrors.value.sessionDelete = getErrorMessage(error)
    if (enabled) {
      persistSettingToggle('sessionDelete', false)
      sessionDeleteRuntimeReady.value = false
    }
    throw error
  } finally {
    settingLoading.value.sessionDelete = false
  }
}

async function toggleSessionDeleteSetting() {
  const shouldDisable = settingToggles.value.sessionDelete && sessionDeleteRuntimeReady.value
  await applySessionDeleteSetting(!shouldDisable).catch(() => undefined)
}

function setCodexSessionManagerSelection(sessionIds: string[]) {
  codexSessionManagerSelectedIds.value = Array.from(new Set(sessionIds.filter(Boolean)))
}

function isCodexSessionManagerSelected(sessionId: string) {
  return codexSessionManagerSelectedSet.value.has(sessionId)
}

function toggleCodexSessionManagerSelection(sessionId: string) {
  const selected = new Set(codexSessionManagerSelectedIds.value)
  if (selected.has(sessionId)) selected.delete(sessionId)
  else selected.add(sessionId)
  setCodexSessionManagerSelection(Array.from(selected))
}

function toggleAllVisibleCodexSessions() {
  const selected = new Set(codexSessionManagerSelectedIds.value)
  if (codexSessionManagerAllVisibleSelected.value) {
    filteredCodexManagerSessions.value.forEach((session) => selected.delete(session.id))
  } else {
    filteredCodexManagerSessions.value.forEach((session) => selected.add(session.id))
  }
  setCodexSessionManagerSelection(Array.from(selected))
}

function selectCodexSessionManagerProject(projectId: string) {
  codexSessionManagerProjectId.value = projectId
}

async function loadCodexSessionManager(options: { preserveNotice?: boolean } = {}) {
  if (!window.gaogeDesktop?.listCodexSessions) {
    codexSessionManagerError.value = '当前桌面版本不支持会话管理，请更新后重试。'
    return
  }
  codexSessionManagerLoading.value = true
  codexSessionManagerError.value = ''
  if (!options.preserveNotice) codexSessionManagerNotice.value = ''
  try {
    const result = await window.gaogeDesktop.listCodexSessions()
    codexSessionManagerData.value = result
    const existingIds = new Set(result.sessions.map((session) => session.id))
    setCodexSessionManagerSelection(
      codexSessionManagerSelectedIds.value.filter((sessionId) => existingIds.has(sessionId)),
    )
    if (
      codexSessionManagerProjectId.value !== '__all__'
      && !result.projects.some((project) => project.id === codexSessionManagerProjectId.value)
    ) {
      codexSessionManagerProjectId.value = '__all__'
    }
  } catch (error) {
    reportPageError('system-config', 'list-codex-sessions', error)
    codexSessionManagerError.value = getErrorMessage(error)
  } finally {
    codexSessionManagerLoading.value = false
  }
}

async function openCodexSessionManager() {
  showCodexSessionManagerDialog.value = true
  codexSessionManagerProjectId.value = '__all__'
  codexSessionManagerQuery.value = ''
  setCodexSessionManagerSelection([])
  codexSessionManagerError.value = ''
  codexSessionManagerNotice.value = ''
  await loadCodexSessionManager()
}

function closeCodexSessionManager() {
  if (codexSessionManagerDeleting.value || codexSessionManagerExporting.value || showCodexSessionImportDialog.value) return
  showCodexSessionManagerDialog.value = false
}

async function deleteManagedCodexSessions(sessionIds: string[], scopeLabel: string) {
  if (!sessionIds.length || !window.gaogeDesktop?.deleteCodexSessions) return
  const runningWarning = codexSessionManagerData.value?.codexRunning
    ? '\n\nCodex 当前正在运行；如果包含正在使用的会话，请先切换到其他会话，防止当前会话被重新写入。'
    : ''
  const confirmed = await confirmAction(
    `确定永久删除“${scopeLabel}”中的 ${sessionIds.length} 个会话吗？删除后无法恢复。${runningWarning}`,
    {
      tone: 'error',
      title: sessionIds.length > 1 ? '批量删除会话' : '删除会话',
      confirmText: sessionIds.length > 1 ? `删除 ${sessionIds.length} 个会话` : '确认删除',
      cancelText: '取消',
    },
  )
  if (!confirmed) return
  codexSessionManagerDeleting.value = true
  codexSessionManagerError.value = ''
  codexSessionManagerNotice.value = ''
  try {
    const result = await window.gaogeDesktop.deleteCodexSessions({ sessionIds })
    await loadCodexSessionManager({ preserveNotice: true })
    if (result.deletedCount > 0) {
      codexSessionManagerNotice.value = `已删除 ${result.deletedCount} 个会话${result.descendantSessions ? `，并清理 ${result.descendantSessions} 个子会话` : ''}。`
    }
    if (result.failedCount > 0) {
      const firstFailure = result.failures[0]?.message || '部分会话删除失败'
      codexSessionManagerError.value = `${result.failedCount} 个会话未能删除：${firstFailure}`
    }
  } catch (error) {
    reportPageError('system-config', 'delete-codex-sessions', error, { sessionCount: sessionIds.length })
    codexSessionManagerError.value = getErrorMessage(error)
  } finally {
    codexSessionManagerDeleting.value = false
  }
}

async function deleteSelectedCodexSessions() {
  await deleteManagedCodexSessions(
    codexSessionManagerSelectedSessions.value.map((session) => session.id),
    '已选择会话',
  )
}

async function deleteCurrentCodexSessionScope() {
  await deleteManagedCodexSessions(
    codexSessionManagerCurrentScope.value.map((session) => session.id),
    codexSessionManagerScopeLabel.value,
  )
}

async function handleCodexSessionsImported(result: GaogeDesktopCodexSessionsImportResponse) {
  await loadCodexSessionManager({ preserveNotice: true })
  codexSessionManagerNotice.value = `已导入 ${result.importedCount} 个会话，跳过 ${result.skippedCount} 个，失败 ${result.failedCount} 个。${result.importedCount ? '重新打开 Codex 后查看。' : ''}`
  if (result.failedCount) codexSessionManagerError.value = result.failures[0]?.message || '部分会话未能导入。'
}

async function exportManagedCodexSessions(sessionIds: string[], scopeLabel: string) {
  if (!sessionIds.length || !window.gaogeDesktop?.exportCodexSessions) return
  codexSessionManagerExporting.value = true
  codexSessionManagerError.value = ''
  codexSessionManagerNotice.value = ''
  try {
    const result = await window.gaogeDesktop.exportCodexSessions(sessionIds)
    if (!result.cancelled) {
      const metadataOnly = result.metadataOnlyCount || 0
      codexSessionManagerNotice.value = `已导出“${scopeLabel}”中的 ${result.exportedCount} 个会话${metadataOnly ? `，其中 ${metadataOnly} 个仅包含原生索引元数据` : ''}。`
    }
  } catch (error) {
    reportPageError('system-config', 'export-codex-sessions', error, { sessionCount: sessionIds.length })
    codexSessionManagerError.value = getErrorMessage(error)
  } finally {
    codexSessionManagerExporting.value = false
  }
}

async function exportSelectedCodexSessions() {
  await exportManagedCodexSessions(
    codexSessionManagerSelectedSessions.value.map((session) => session.id),
    '已选择会话',
  )
}

async function exportCurrentCodexSessionScope() {
  await exportManagedCodexSessions(
    codexSessionManagerCurrentScope.value.map((session) => session.id),
    codexSessionManagerScopeLabel.value,
  )
}

async function loadCodexLanguageSettings(options: { silent?: boolean } = {}) {
  if (settingLoading.value.language || !window.gaogeDesktop?.getCodexLanguageSettings) return
  settingLoading.value.language = true
  try {
    const legacyDisabled = localStorage.getItem(settingStorageKeys.language) === 'false'
    const result = await window.gaogeDesktop.getCodexLanguageSettings(
      legacyDisabled ? { legacyEnabled: false } : {},
    )
    persistSettingToggle('language', result.enabled)
    codexLanguageNeedsRestart.value = Boolean(result.needsRestart)
    settingErrors.value.language = ''
  } catch (error) {
    reportPageError('system-config', 'load-codex-language', error)
    if (!options.silent) settingErrors.value.language = getErrorMessage(error)
  } finally {
    settingLoading.value.language = false
  }
}

async function applyLanguageSetting(enabled: boolean) {
  if (settingLoading.value.language) return ''
  settingErrors.value.language = ''
  settingNotices.value.language = ''
  settingLoading.value.language = true
  try {
    if (!window.gaogeDesktop?.setCodexLanguage) throw new Error('当前不是桌面环境，无法保存中文设置。')
    const result = await window.gaogeDesktop.setCodexLanguage({ enabled })
    persistSettingToggle('language', result.enabled)
    codexLanguageNeedsRestart.value = Boolean(result.needsRestart)
    settingNotices.value.language = result.needsRestart
      ? '已保存，重启 Codex 后生效。'
      : result.enabled ? '已开启强制中文。' : '已关闭强制中文。'
    return settingNotices.value.language
  } catch (error) {
    reportPageError('system-config', enabled ? 'enable-codex-language' : 'disable-codex-language', error)
    settingErrors.value.language = getErrorMessage(error)
    throw error
  } finally {
    settingLoading.value.language = false
  }
}

function persistSettingToggle(key: SettingToggleKey, enabled: boolean) {
  settingToggles.value[key] = enabled
  localStorage.setItem(settingStorageKeys[key], String(enabled))
}

async function toggleSetting(key: SettingToggleKey) {
  if (key === 'sessionDelete') {
    await toggleSessionDeleteSetting()
    return
  }
  const enabled = !settingToggles.value[key]
  if (key === 'plugins') {
    await applyPluginSetting(enabled).catch(() => undefined)
    return
  }
  if (key === 'language') {
    await applyLanguageSetting(enabled).catch(() => undefined)
    return
  }
  persistSettingToggle(key, enabled)
  try {
    if (key === 'sessionSync') {
      if (enabled) await applySessionSyncSetting()
      else settingNotices.value.sessionSync = '已关闭自动会话同步。'
      return
    }
  } catch {
    // Session sync keeps its saved preference even when this one-time run fails.
  }
}

async function applyEnabledCodexSettings(options: ApplyCodexSettingOptions = {}) {
  if (settingToggles.value.plugins) {
    await applyPluginSetting(true, options).catch(() => undefined)
  }
  if (settingToggles.value.sessionSync) {
    await applySessionSyncSetting(options).catch(() => undefined)
  }
  if (settingToggles.value.language) {
    await applyLanguageSetting(true).catch(() => undefined)
  }
}

async function startAggregateLogin() {
  if (codexAccountMutationDepth > 0 || isAggregateLoginLoading.value) return
  const finishLoginFeedback = beginCodexLoginFeedback()
  isAggregateLoginLoading.value = true
  try {
    aggregateLoginError.value = ''
    aggregateLoginNotice.value = ''
    if (!authToken.value) {
      aggregateLoginError.value = '请先登录账户。'
      await showCodexLoginFailure(aggregateLoginError.value)
      return
    }
    const desktopApi = window.gaogeDesktop
    if (!desktopApi?.configureAggregateLogin) {
      aggregateLoginError.value = '当前桌面版本还不支持聚合登录，请重新启动本地开发版本。'
      await showCodexLoginFailure(aggregateLoginError.value)
      return
    }
    // Saved custom interfaces are loaded locally by the desktop backend. Only
    // participating relay groups require the relay's live group lookup.
    const needsRelayGroupSync = () => (
      aggregateAvailableProviders.value.length > 0 || aggregateExternalModelCount.value === 0
    )
    try {
      if (needsRelayGroupSync()) await syncGroups({ silent: true, throwOnError: true })
    } catch (error) {
      aggregateLoginError.value = `读取中转站启用分组失败：${getGroupErrorMessage(error)}`
      await showCodexLoginFailure(error)
      return
    }
    if ((aggregateAvailableProviders.value.length === 0 || aggregateGroupCount.value === 0) && aggregateExternalModelCount.value === 0) {
      aggregateLoginError.value = '当前没有启用中的可聚合分组，请先在中转站启用至少一个分组。'
      await showCodexLoginFailure(aggregateLoginError.value)
      return
    }
    if (aggregateAvailableProviders.value.some((provider) => provider.groups.some((group) => (
      !isAggregateGroupReady(group)
    )))) {
      await refreshAggregateModels({ force: true })
    }
    const unavailableGroups = aggregateAvailableProviders.value.flatMap((provider) => (
      provider.groups
        .filter((group) => !isAggregateGroupReady(group))
        .map((group) => `${provider.name} / ${group.name}：${aggregateGroupFailureReason(group)}`)
    ))
    if (unavailableGroups.length > 0) {
      aggregateLoginError.value ||= `以下分组尚未准备完成：${unavailableGroups.join('；')}`
      await showCodexLoginFailure(aggregateLoginError.value)
      return
    }
    const confirmed = await confirmCodexRestart(isAggregateLoginActive.value ? '重新写入聚合登录' : '启用聚合登录')
    if (!confirmed) {
      aggregateLoginNotice.value = '已取消聚合登录。'
      return
    }
    if (codexAccountMutationDepth > 0) return

    isAggregateLoginLoading.value = true
    const finishAccountMutation = beginCodexAccountMutation()
    try {
      if (needsRelayGroupSync()) {
        await syncGroups({ silent: true, throwOnError: true })
      }
      if ((aggregateAvailableProviders.value.length === 0 || aggregateGroupCount.value === 0) && aggregateExternalModelCount.value === 0) {
        throw new Error('当前没有启用中的可聚合分组，请先在中转站启用至少一个分组。')
      }
      if (aggregateAvailableProviders.value.some((provider) => provider.groups.some((group) => (
        !isAggregateGroupReady(group)
      )))) {
        await refreshAggregateModels({ force: true, groupsAlreadySynced: true })
        // Refreshing models can take time; revalidate enabled groups afterwards.
        // Already-ready groups use the single fresh lookup above.
        await syncGroups({ silent: true, throwOnError: true })
      }
      if ((aggregateAvailableProviders.value.length === 0 || aggregateGroupCount.value === 0) && aggregateExternalModelCount.value === 0) {
        throw new Error('中转站当前没有启用中的可聚合分组。')
      }
      const finalUnavailableGroups = aggregateAvailableProviders.value.flatMap((provider) => (
        provider.groups
          .filter((group) => !isAggregateGroupReady(group))
          .map((group) => `${provider.name} / ${group.name}：${aggregateGroupFailureReason(group)}`)
      ))
      if (finalUnavailableGroups.length > 0) {
        throw new Error(`启用分组尚未准备完成：${finalUnavailableGroups.join('；')}`)
      }
      const imageTools = await tryEnsureCodexImageTools()
      const providerRequests: GaogeDesktopAggregateProviderRequest[] = []
      for (const provider of aggregateAvailableProviders.value) {
        if (!provider.tool) continue
        const providerGroups: GaogeDesktopAggregateGroupRequest[] = []
        let providerBaseUrl = ''
        for (const group of provider.groups) {
          if (!isAggregateGroupReady(group)) {
            throw new Error(`${provider.name} / ${group.name}：${aggregateGroupFailureReason(group)}`)
          }
          const groupTool = aggregateGroupTool(provider, group)
          if (!groupTool) continue
          const groupBaseUrl = groupTool === 'codex' ? currentCodexBaseUrl() : currentClaudeBaseUrl()
          if (!providerBaseUrl) providerBaseUrl = groupBaseUrl
          const apiKey = await ensureAggregateApiKey(provider.id, group.id)
          const key = apiKey.key.trim()
          if (!key) throw new Error(`${provider.name} / ${group.name} 的独立 Key 无效，请刷新后重试。`)
          providerGroups.push({
            id: group.id,
            name: group.name,
            rateText: group.rateText || '',
            platform: group.platform || (groupTool === 'claude' ? 'anthropic' : 'openai'),
            apiKey: key,
            baseUrl: groupBaseUrl,
            models: [...group.models],
          })
        }
        providerRequests.push({
          id: provider.id,
          name: provider.name,
          baseUrl: providerBaseUrl || (provider.tool === 'codex' ? currentCodexBaseUrl() : currentClaudeBaseUrl()),
          groups: providerGroups,
        })
      }
      invalidateCodexStatusRequests()
      const result = await desktopApi.configureAggregateLogin({
        providers: providerRequests,
        ...(imageTools.key
          ? {
              imageApiKey: imageTools.key,
              imageBaseUrl: currentCodexBaseUrl(),
            }
          : {}),
      })
      applyCodexEnhancementResults(result.enhancements || result.launch)
      if (result.aggregate) {
        applyAggregateLoginStatus(result.aggregate)
      } else {
        await loadAggregateLoginStatus({ silent: true, afterMutation: true })
      }
      if (result.router) applyCodexRouterSettings(result.router)
      connectedTools.value.codex = true
      fuelPackAccountKey.value = ''
      localStorage.removeItem('gaoge_desktop_fuel_pack_account_key')
      setCodexRelaySource('aggregate')
      const imageSkillFeedback = result.codexDirs?.some((target) => target.imageSkill)
        ? getImageToolsTargetFeedback(result.codexDirs)
        : { notice: '', warning: '' }
      if (imageSkillFeedback.notice || imageSkillFeedback.warning) imageToolsMigrationFeedback.value = imageSkillFeedback
      const warnings = [
        result.modelCatalogWarning,
        result.routeWarning,
        result.imageToolsWarning,
        imageSkillFeedback.warning,
        imageTools.warning,
      ]
      recordCodexLoginDiagnostics('aggregate', result, [...warnings, imageSkillFeedback.notice])
      aggregateLoginError.value = ''
      aggregateLoginNotice.value = '登录成功'
      notify('登录成功', 'success')
    } catch (error) {
      reportPageError('aggregate-login', 'configure', { message: codexLoginFailureDetails(error).reason, code: codexLoginFailureDetails(error).code })
      aggregateLoginError.value = codexLoginFailureDetails(error).reason
      await showCodexLoginFailure(error)
    } finally {
      finishAccountMutation()
      isAggregateLoginLoading.value = false
    }
  } finally {
    isAggregateLoginLoading.value = false
    finishLoginFeedback()
  }
}

async function disableAggregateLogin() {
  if (codexAccountMutationDepth > 0) return
  aggregateLoginError.value = ''
  aggregateLoginNotice.value = ''
  if (!window.gaogeDesktop?.disableAggregateLogin) {
    aggregateLoginError.value = '当前桌面版本还不支持退出聚合登录。'
    return
  }
  if (!(await confirmCodexRestart('退出聚合登录'))) {
    aggregateLoginNotice.value = '已取消退出聚合登录。'
    return
  }
  if (codexAccountMutationDepth > 0) return
  const codexOperation = openCodexOperationDialog('正在退出聚合登录', '正在恢复 Codex 官方路由')
  isAggregateLoginLoading.value = true
  const finishAccountMutation = beginCodexAccountMutation()
  try {
    invalidateCodexStatusRequests()
    const result = await window.gaogeDesktop.disableAggregateLogin()
    applyCodexEnhancementResults(result.enhancements || result.launch)
    if (result.aggregate) applyAggregateLoginStatus(result.aggregate)
    else markAggregateLoginInactive()
    if (result.router) applyCodexRouterSettings(result.router)
    clearCodexRelayState({ clearFuelRecovery: true })
    const identity = await verifyCodexOfficialAccountRestore(result)
    aggregateLoginNotice.value = `已退出聚合登录并恢复 Codex 官方路由。${identity.notice}${result.codexLaunched ? ' Codex 已自动重新打开。' : ''} ${codexLaunchWarnings(result)}`.trim()
    aggregateLoginError.value = identity.warning
    notify(identity.warning || '已退出聚合登录。', identity.warning ? 'warning' : 'success')
  } catch (error) {
    reportPageError('aggregate-login', 'disable', error)
    aggregateLoginError.value = getToolActionErrorMessage(error, 'codex')
  } finally {
    finishAccountMutation()
    codexOperation.close()
    isAggregateLoginLoading.value = false
  }
}

async function connectTool(tool: ToolKey, options: ConnectToolOptions = {}) {
  if (tool === 'codex' && codexAccountMutationDepth > 0) return
  const finishLoginFeedback = beginCodexLoginFeedback()
  try {
    toolErrors.value[tool] = ''
    toolNotices.value[tool] = ''
    toolWarnings.value[tool] = ''
    const forceApiMode = tool === 'codex' && options.forceApiMode === true
    const requireCurrentChatgptAccount = tool === 'codex' && options.requireCurrentChatgptAccount === true
    const fuelCheckGeneration = codexFuelAccountCheckGeneration
    let codexConfigurationApplied = false
    let codexFuelIdentityRejected = false
    if (!authToken.value) {
      toolErrors.value[tool] = '请先登录账户。'
      await showCodexLoginFailure(toolErrors.value[tool], Boolean(options.accountKey))
      return
    }
    const groupId = selectedToolGroupId(tool)
    if (!groupId) {
      toolErrors.value[tool] = `请先选择 ${tool === 'codex' ? 'Codex' : 'Claude'} 分组。`
      await showCodexLoginFailure(toolErrors.value[tool], Boolean(options.accountKey))
      return
    }
    const desktopApi = window.gaogeDesktop
    if (tool === 'codex' && !desktopApi?.configureCodex) {
      toolErrors.value.codex = '当前不是桌面环境，无法写入本机 Codex 配置。'
      await showCodexLoginFailure(toolErrors.value[tool], Boolean(options.accountKey))
      return
    }
    if (tool === 'claude' && !desktopApi?.configureClaude) {
      toolErrors.value.claude = '当前不是桌面环境，无法写入本机 Claude 配置。'
      await showCodexLoginFailure(toolErrors.value[tool], Boolean(options.accountKey))
      return
    }
    // The guarded fuel flow already checked the live account. Cached snapshots can
    // still describe an older, expired login and must not override that result.
    if (tool === 'codex' && !forceApiMode && !requireCurrentChatgptAccount) {
      const invalidAccount = invalidActiveCodexAccount()
      if (invalidAccount) {
        toolErrors.value.codex = options.accountKey
          ? '当前 ChatGPT 账号登录已失效，请先重新登录自己的账号，或改用“无账号登录”。'
          : '当前 ChatGPT 账号登录已失效，请先重新登录。'
        await showCodexLoginFailure(toolErrors.value.codex, Boolean(options.accountKey))
        return
      }
    }
    const codexLoginActionName = forceApiMode
      ? 'ChatGPT 无账号登录'
      : options.accountKey
        ? 'ChatGPT 已有账号加油'
        : 'ChatGPT 登录'
    if (tool === 'codex' && !(await confirmCodexRestart(codexLoginActionName))) {
      toolNotices.value.codex = `已取消${codexLoginActionName}。`
      return
    }
    if (tool === 'claude' && !(await confirmClaudeClose('一键登录 Claude'))) {
      toolNotices.value.claude = '已取消一键登录 Claude。'
      return
    }
    if (tool === 'codex' && codexAccountMutationDepth > 0) return
    if (requireCurrentChatgptAccount && (
      fuelCheckGeneration !== codexFuelAccountCheckGeneration || activeCodexLoginMode.value !== 'existing-account'
    )) return

    isToolConnecting.value[tool] = true
    const finishAccountMutation = tool === 'codex' ? beginCodexAccountMutation() : () => {}
    try {
      const apiKey = await ensureToolDefaultApiKeyForGroup(tool, groupId)
      if (tool === 'claude') {
        if (claudeModelsGroupId.value !== groupId || claudeModelOptions.value.length === 0) {
          await refreshClaudeModels()
        }
        if (claudeModelsGroupId.value !== groupId || claudeModelOptions.value.length === 0) {
          throw new Error(loginModelsError.value || '请先刷新 Claude 模型列表。')
        }
        const availableClaudeModels = uniqueClaudeModels(claudeModelOptions.value)
        const requestedClaudeModel = selectedLoginModel.value === '自动匹配' ? '' : selectedLoginModel.value
        const selectedClaudeModel = requestedClaudeModel && availableClaudeModels.includes(requestedClaudeModel)
          ? requestedClaudeModel
          : availableClaudeModels[0] || CLAUDE_DEFAULT_MODEL
        const desktopModels = uniqueClaudeModels([
          selectedClaudeModel,
          ...availableClaudeModels,
        ])
        const roleModels = getClaudeRoleModels(selectedClaudeModel, availableClaudeModels)
        const result = await desktopApi!.configureClaude({
          apiKey: apiKey.key,
          baseUrl: currentClaudeBaseUrl(),
          model: selectedClaudeModel,
          sonnetModel: roleModels.sonnetModel,
          haikuModel: roleModels.haikuModel,
          opusModel: roleModels.opusModel,
          ...(roleModels.fableModel ? { fableModel: roleModels.fableModel } : {}),
          desktopModels,
        })
        setClaudeConfigured(true)
        recordCodexLoginDiagnostics('claude', { appPatch: result.appPatch }, [result.desktop?.message])
        toolNotices.value.claude = '登录成功'
        notify('登录成功', 'success')
        return
      }

      const [imageTools, modelSelection] = await Promise.all([
        tryEnsureCodexImageTools(),
        resolveCodexModelSelection(apiKey.key, {
          groupId,
          apiKeyId: apiKey.id,
        }),
      ])
      if (requireCurrentChatgptAccount && (
        fuelCheckGeneration !== codexFuelAccountCheckGeneration || activeCodexLoginMode.value !== 'existing-account'
      )) return
      const baseUrl = currentCodexBaseUrl()
      codexRouterForm.value.relayBaseUrl = baseUrl
      invalidateCodexStatusRequests()
      const result = await desktopApi!.configureCodex({
        apiKey: apiKey.key,
        ...(options.accountKey ? { accountKey: options.accountKey } : {}),
        ...(imageTools.key
          ? {
              imageApiKey: imageTools.key,
              imageBaseUrl: baseUrl,
            }
          : {}),
        baseUrl,
        modelPolicyApiBaseUrl: getCurrentApiBaseUrl(),
        providerName: '',
        model: modelSelection.model,
        modelSelectionOrigin: modelSelection.origin,
        modelSelectionMode: modelSelection.mode,
        modelCatalogSource: modelSelection.source,
        supportedModels: modelSelection.supportedModels,
        mode: 'relay',
        forceApiMode,
        ...(requireCurrentChatgptAccount ? { requireCurrentChatgptAccount: true } : {}),
        enhanceModelPicker: true,
      })
      codexConfigurationApplied = true
      // A written route must remain recoverable even if the subsequent account
      // read fails. Persist the fuel identity only after that read confirms it.
      setCodexFuelRecoveryAvailable(Boolean(options.accountKey))
      markAggregateLoginInactive()
      applyCodexEnhancementResults(result.enhancements || result.launch)
      if (result.router) applyCodexRouterSettings(result.router)
      // The native writer has the authoritative remote policy and verifies its
      // managed catalog. Reflect that result instead of the preflight upstream list.
      if (result.modelCatalogModels?.length) {
        codexModelOptions.value = [...result.modelCatalogModels]
        codexModelCatalogSource.value = result.modelCatalogSource || 'upstream'
        loginModelsNotice.value = result.desktopModelSupportEnabled
          ? `已按服务端模型支持配置写入 ${result.modelCatalogModels.length} 个模型。`
          : `模型目录已写入，共 ${result.modelCatalogModels.length} 个模型。`
        loginModelsError.value = ''
      }
      const nativeModelFallback = result.nativeModelFallback === true
      codexRouterForm.value.model = nativeModelFallback
        ? result.model || CODEX_MODEL
        : modelSelection.mode === 'locked'
        ? modelSelection.model
        : result.model || modelSelection.model
      if (modelSelection.mode === 'locked' && !nativeModelFallback) {
        lockedCodexModel.value = modelSelection.model
      }
      persistCodexRouterForm()
      syncSelectedLoginModelForTool('codex')
      if (options.accountKey) {
        // Re-read the native account state after the backend has restored auth.json
        // and relaunched Codex. Do not show successful existing-account fuel
        // until the selected account is still the live current account.
        const returnedState = await desktopApi!.getCodexAccounts()
        const verifiedState = normalizeCodexAccountsState(returnedState)
        codexAccountsState.value = verifiedState
        ensureSelectedCodexAccount()
        const verifiedAccount = normalizeCodexAccount(verifiedState.currentAccount)
        if (!verifiedAccount || verifiedAccount.accountKey !== options.accountKey) {
          codexFuelIdentityRejected = true
          throw new Error('当前账号与本次检测的账号不一致，账号登录状态校验失败。')
        }
        if (verifiedAccount.requiresReauth === true || verifiedAccount.loginState === 'invalid'
          || verifiedAccount.canSwitch === false) {
          codexFuelIdentityRejected = true
          const returnedAccount = returnedState.currentAccount as unknown as Record<string, unknown>
          throw {
            message: verifiedAccount.reauthReason || '当前 ChatGPT 账号登录已失效，请重新登录。',
            code: returnedAccount?.code ?? returnedAccount?.errorCode ?? returnedAccount?.reauthCode,
          }
        }
        fuelPackAccountKey.value = options.accountKey
        localStorage.setItem('gaoge_desktop_fuel_pack_account_key', options.accountKey)
        setCodexRelaySource('fuel-pack')
        setCodexFuelRecoveryAvailable(false)
      } else {
        fuelPackAccountKey.value = ''
        localStorage.removeItem('gaoge_desktop_fuel_pack_account_key')
        setCodexRelaySource('one-click')
      }
      connectedTools.value.codex = true
      const sessionWarning = result.sessionSync?.warnings?.filter(Boolean).join(' ') || ''
      const launchQueued = result.codexLaunchQueued === true
        || result.appPatch?.launchQueued === true
        || result.appPatch?.background === true
      const launchFailureWarning = !result.codexLaunched && !launchQueued
        ? 'Codex 未能自动重新打开，请点击“重启 ChatGPT”或手动打开原来的客户端。'
        : ''
      const imageSkillFeedback = result.codexDirs?.some((target) => target.imageSkill)
        ? getImageToolsTargetFeedback(result.codexDirs)
        : { notice: '', warning: '' }
      if (imageSkillFeedback.notice || imageSkillFeedback.warning) imageToolsMigrationFeedback.value = imageSkillFeedback
      const warnings = [
        result.modelCatalogWarning,
        result.routeWarning,
        result.imageToolsWarning,
        imageSkillFeedback.warning,
        imageTools.warning,
        result.desktopModelSupportEnabled ? undefined : modelSelection.warning,
        sessionWarning,
        launchFailureWarning,
      ]
      recordCodexLoginDiagnostics(options.accountKey ? 'fuel' : 'api', result, [...warnings, imageSkillFeedback.notice])
      toolNotices.value.codex = options.accountKey ? '加油成功' : '登录成功'
      notify(toolNotices.value.codex, 'success')
    } catch (error) {
      reportPageError('one-click-login', `connect-${tool}`, { message: codexLoginFailureDetails(error).reason, code: codexLoginFailureDetails(error).code }, { tool })
      const errorText = rawErrorText(error)
      if (requireCurrentChatgptAccount && !codexConfigurationApplied && errorText.includes('CODEX_FUEL_ACCOUNT_REQUIRED')) {
        finishAccountMutation()
        await showMissingCodexFuelAccountDialog(error)
        return
      }
      if (requireCurrentChatgptAccount && !codexConfigurationApplied && errorText.includes('CODEX_FUEL_ACCOUNT_CHANGED')) {
        toolErrors.value.codex = '当前 ChatGPT 账号已发生变化，请重新点击“开始加油”检测账号。'
        await showCodexLoginFailure(error, true)
        return
      }
      if (tool === 'codex' && options.accountKey && codexConfigurationApplied) {
        setCodexFuelRecoveryAvailable(true)
        toolErrors.value.codex = `加油配置已写入，但未能确认加油成功。可点击“关闭加油”恢复官方路由。${getToolActionErrorMessage(error, tool)}`
        recordCodexLoginDiagnostics('fuel', null, [toolErrors.value.codex])
        if (codexFuelIdentityRejected) await showCodexLoginFailure(error, true)
        return
      }
      if (tool === 'codex' && !forceApiMode && isCodexAccountInvalidError(error)) {
        finishAccountMutation()
        await loadCodexAccounts({ silent: true, force: true }).catch(() => undefined)
        toolErrors.value.codex = options.accountKey
          ? '当前 ChatGPT 账号登录已失效，加油未执行。请重新登录自己的账号，或改用“无账号登录”。'
          : '当前 ChatGPT 账号登录已失效，请重新登录。'
        await showCodexLoginFailure(error, Boolean(options.accountKey))
        return
      }
      toolErrors.value[tool] = codexLoginFailureDetails(error).reason
      await showCodexLoginFailure(error, Boolean(options.accountKey))
    } finally {
      finishAccountMutation()
      isToolConnecting.value[tool] = false
    }
  } finally {
    finishLoginFeedback()
  }
}

async function closeCodexRelayFromLoginPage() {
  if (activeTool.value !== 'codex' || codexAccountMutationDepth > 0) return
  toolErrors.value.codex = ''
  toolNotices.value.codex = ''
  toolWarnings.value.codex = ''

  const closingFuel = activeCodexLoginMode.value === 'existing-account'
  const actionName = closingFuel ? '关闭加油' : '关闭登录'
  const source = isCodexFuelRecoveryAvailable.value ? 'fuel-pack' : normalizedCodexRelaySource.value
  const canDisableAggregate = source === 'aggregate' && Boolean(window.gaogeDesktop?.disableAggregateLogin)
  const canDisableCodexRelay = Boolean(window.gaogeDesktop?.disableCodexFuelPack)
  if (!canDisableAggregate && !canDisableCodexRelay) {
    toolErrors.value.codex = '当前不是桌面环境，无法关闭 Codex 中转。'
    return
  }
  const confirmed = await confirmAction(
    `${actionName}会移除 Gaoge 中转配置，恢复官方原生路由，并保留最后主动切换的账号；如果没有主动切换过账号，则恢复开启中转前的登录状态。原账号凭据缺失或登录失效时，会保留当前可用登录，或回到官方未登录状态。是否继续？`,
    {
      tone: 'warning',
      title: '关闭中转并恢复官方原生路由',
      confirmText: actionName,
      cancelText: '暂不操作',
    },
  )
  if (!confirmed) {
    toolNotices.value.codex = `已取消${actionName}。`
    return
  }
  if (codexAccountMutationDepth > 0) return

  const codexOperation = openCodexOperationDialog(
    closingFuel ? '正在关闭加油' : '正在关闭 Codex 中转',
    '正在恢复官方原生路由',
  )
  isCodexFuelPackClosing.value = true
  isToolConnecting.value.codex = true
  const finishAccountMutation = beginCodexAccountMutation()
  try {
    codexOperation.update({ message: closingFuel ? '正在关闭加油' : '正在关闭中转', detail: '' })
    invalidateCodexStatusRequests()
    const disabled = canDisableAggregate
      ? await window.gaogeDesktop!.disableAggregateLogin!()
      : await window.gaogeDesktop!.disableCodexFuelPack()
    markAggregateLoginInactive()
    applyCodexEnhancementResults(disabled.enhancements || disabled.launch)
    codexOperation.update({
      message: '正在同步状态',
      detail: '',
    })
    if (disabled.router) applyCodexRouterSettings(disabled.router)
    clearCodexRelayState({ clearFuelRecovery: true })
    const identity = await verifyCodexOfficialAccountRestore(disabled)
    const warning = [codexLaunchWarnings(disabled), identity.warning].filter(Boolean).join(' ')
    const successMessage = `${closingFuel ? '已关闭加油' : '已关闭中转'}并恢复官方原生路由。${identity.notice}${disabled.codexLaunched ? ' Codex 已自动重新打开。' : ''}`
    if (warning) toolWarnings.value.codex = `${successMessage} ${warning}`.trim()
    else toolNotices.value.codex = successMessage
    if (!disabled.codexLaunched) {
      showManualOpenNotice('codex-login-close', `${successMessage} ${warning} 请手动打开 Codex 后使用。`.trim())
    }
  } catch (error) {
    reportPageError('one-click-login', 'close-codex-relay', error)
    toolErrors.value.codex = getToolActionErrorMessage(error, 'codex')
  } finally {
    finishAccountMutation()
    codexOperation.close()
    isCodexFuelPackClosing.value = false
    isToolConnecting.value.codex = false
    void loadCodexRouterStatus({ silent: true })
  }
}

async function forceOfficialCodexForActivePage() {
  if (activeTool.value !== 'codex' || codexAccountMutationDepth > 0) return
  toolErrors.value.codex = ''
  toolNotices.value.codex = ''
  toolWarnings.value.codex = ''
  if (!window.gaogeDesktop?.disableCodexFuelPack) {
    toolErrors.value.codex = '当前不是桌面环境，无法强制恢复官方路由。'
    return
  }
  if (!(await confirmCodexRestart('强制官方'))) {
    toolNotices.value.codex = '已取消强制官方。'
    return
  }
  if (codexAccountMutationDepth > 0) return
  const codexOperation = openCodexOperationDialog(
    '正在强制恢复官方路由',
    '正在恢复中',
  )
  isCodexFuelPackClosing.value = true
  isToolConnecting.value.codex = true
  const finishAccountMutation = beginCodexAccountMutation()
  try {
    codexOperation.update({ message: '正在恢复中', detail: '' })
    invalidateCodexStatusRequests()
    const disabled = await window.gaogeDesktop.disableCodexFuelPack({ forceOfficial: true })
    markAggregateLoginInactive()
    applyCodexEnhancementResults(disabled.enhancements || disabled.launch)
    codexOperation.update({
      message: '正在同步状态',
      detail: '',
    })
    if (disabled.router) applyCodexRouterSettings(disabled.router)
    clearCodexRelayState({ clearFuelRecovery: true })
    const identity = await verifyCodexOfficialAccountRestore(disabled)
    const warning = [codexLaunchWarnings(disabled), identity.warning].filter(Boolean).join(' ')
    const successMessage = `已清理中转并恢复官方原生路由。${identity.notice}${disabled.codexLaunched ? ' Codex 已自动重新打开。' : ''}`
    if (warning) toolWarnings.value.codex = `${successMessage} ${warning}`.trim()
    else toolNotices.value.codex = successMessage
    if (!disabled.codexLaunched) {
      showManualOpenNotice('codex-force-official', `${successMessage} ${warning} 请手动打开 Codex 后使用。`.trim())
    }
  } catch (error) {
    reportPageError('one-click-login', 'force-official-codex', error)
    toolErrors.value.codex = getToolActionErrorMessage(error, 'codex')
  } finally {
    finishAccountMutation()
    codexOperation.close()
    isCodexFuelPackClosing.value = false
    isToolConnecting.value.codex = false
    void loadCodexRouterStatus({ silent: true })
  }
}

async function restartCodexForActivePage() {
  const fromPluginMarket = activePage.value === '安装插件'
  if (activeTool.value !== 'codex' && !fromPluginMarket) return
  if (fromPluginMarket) pluginMarketRestartRequested.value = true
  toolErrors.value.codex = ''
  toolNotices.value.codex = ''
  toolWarnings.value.codex = ''
  if (!window.gaogeDesktop?.restartCodex) {
    toolErrors.value.codex = '当前桌面版本不支持自动重启 Codex。'
    return
  }
  if (!(await confirmCodexRestart('重启 Codex'))) return

  const codexOperation = openCodexOperationDialog(
    '正在重启 Codex',
    '正在加载配置并等待 Codex 完成打开',
  )
  isCodexRestarting.value = true
  const finishAccountMutation = beginCodexAccountMutation()
  try {
    const result = await window.gaogeDesktop.restartCodex({
      modelPolicyApiBaseUrl: getCurrentApiBaseUrl(),
      relayBaseUrl: currentCodexBaseUrl(),
    })
    applyCodexEnhancementResults(result.enhancements || result.launch)
    const warning = codexLaunchWarnings(result)
    if (result.codexLaunched) {
      if (fromPluginMarket) pluginMarketRestartRevision.value += 1
      showCodexLaunchFeedback(result, 'Codex 已重新打开。')
    } else if (result.codexLaunchQueued) {
      showCodexLaunchFeedback(result, '已提交 Codex 启动请求，正在打开，请稍候。')
    } else {
      toolErrors.value.codex = warning || 'Codex 未能自动打开，请到系统配置检查启动路径。'
    }
    await loadCodexLaunchTarget({ silent: true })
  } catch (error) {
    reportPageError('one-click-login', 'restart-codex', error)
    toolErrors.value.codex = getToolActionErrorMessage(error, 'codex')
  } finally {
    finishAccountMutation()
    codexOperation.close()
    isCodexRestarting.value = false
  }
}

function confirmPluginUninstall(name: string) {
  return confirmAction(`确定卸载“${name}”吗？卸载后，ChatGPT 将不再加载这个插件，需要时可以重新安装。`, {
    tone: 'warning',
    title: '卸载插件',
    confirmText: '卸载插件',
    cancelText: '保留插件',
  })
}

async function closeClaudeRelayFromLoginPage() {
  toolErrors.value.claude = ''
  toolNotices.value.claude = ''
  await nextTick()
  const canDisableClaudeRelay = Boolean(window.gaogeDesktop?.disableClaudeRelay) || hasTauriRuntime()
  if (!canDisableClaudeRelay) {
    toolErrors.value.claude = '当前不是桌面环境，无法退出 Claude 登录。'
    return
  }
  const confirmed = await confirmClaudeClose(
    '退出 Claude 中转',
    '关闭后将移除 Claude Code 与 Claude Desktop 的 Gaoge 中转路由，并保留原有账号状态。',
  )
  if (!confirmed) {
    toolNotices.value.claude = '已取消退出 Claude 中转。'
    return
  }
  isToolConnecting.value.claude = true
  try {
    if (window.gaogeDesktop?.disableClaudeRelay) {
      await window.gaogeDesktop.disableClaudeRelay()
    } else {
      await invoke('gaoge_disable_claude_relay')
    }
    setClaudeConfigured(false)
    toolNotices.value.claude = '已退出 Claude 中转，已恢复官方默认路由并保留原账号状态。'
    showManualOpenNotice('claude-login-close')
  } catch (error) {
    reportPageError('one-click-login', 'close-claude-relay', error)
    const message = getToolActionErrorMessage(error, 'claude')
    toolErrors.value.claude = message.includes('command')
      ? '当前桌面开发进程还没有加载 Claude 退出命令，请重启桌面开发程序后再试。'
      : message
  } finally {
    isToolConnecting.value.claude = false
  }
}

async function showMissingCodexFuelAccountDialog(error?: unknown) {
  const failure = error ? codexLoginFailureDetails(error) : null
  await confirmAction('未检测到已登录的gpt账号，请使用无账号登录', {
    tone: 'warning',
    title: '无法开始加油',
    details: failure?.code ? [`错误码：${failure.code}`, `原因：${failure.reason}`] : [],
    confirmText: '知道了',
    cancelText: '',
  })
}

async function connectToolForActivePage() {
  if (!activeTool.value || isLoginActionBusy.value) return
  if (activeTool.value === 'codex' && codexAccountMutationDepth > 0) return
  if (activeTool.value === 'codex' && isCodexLoginActionClose.value) {
    const closingFuel = activeCodexLoginMode.value === 'existing-account'
    if (closingFuel) isCodexFuelPackClosing.value = true
    try {
      await closeCodexRelayFromLoginPage()
    } finally {
      if (closingFuel) isCodexFuelPackClosing.value = false
    }
    return
  }
  if (activeCodexLoginMode.value === 'existing-account') {
    const finishLoginFeedback = beginCodexLoginFeedback()
    const generation = ++codexFuelAccountCheckGeneration
    const page = activePage.value
    const statusGeneration = codexStatusGeneration
    isCodexFuelAccountChecking.value = true
    toolErrors.value.codex = ''
    toolNotices.value.codex = ''
    toolWarnings.value.codex = ''
    try {
      const desktopApi = window.gaogeDesktop
      if (!desktopApi?.checkCodexFuelAccount) {
        throw new Error('当前桌面环境无法检测 ChatGPT 账号，请重启或更新软件后重试。')
      }
      const checked = await desktopApi.checkCodexFuelAccount()
      if (generation !== codexFuelAccountCheckGeneration || activePage.value !== page || codexAccountMutationDepth > 0) return
      if (statusGeneration !== codexStatusGeneration) {
        toolErrors.value.codex = 'Codex 状态已变化，请重新点击“开始加油”检测账号。'
        return
      }
      const account = normalizeCodexAccount(checked.currentAccount)
      if (!checked.canStart || checked.reason !== 'ready' || !account) {
        await showMissingCodexFuelAccountDialog()
        return
      }
      isCodexFuelAccountChecking.value = false
      isCodexFuelPackOpening.value = true
      try {
        await connectTool('codex', {
          accountKey: account.accountKey,
          forceApiMode: false,
          requireCurrentChatgptAccount: true,
        })
      } finally {
        isCodexFuelPackOpening.value = false
      }
    } catch (error) {
      if (generation !== codexFuelAccountCheckGeneration || activePage.value !== page) return
      reportPageError('existing-account-fuel', 'check-current-account', { message: codexLoginFailureDetails(error).reason, code: codexLoginFailureDetails(error).code })
      toolErrors.value.codex = `检测 ChatGPT 账号失败：${getCodexAccountErrorMessage(error)}`
      await showCodexLoginFailure(error, true)
    } finally {
      if (generation === codexFuelAccountCheckGeneration) isCodexFuelAccountChecking.value = false
      finishLoginFeedback()
    }
    return
  }
  if (activeCodexLoginMode.value === 'no-account') {
    await connectTool('codex', { forceApiMode: true })
    return
  }
  if (activeTool.value === 'claude' && connectedTools.value.claude) {
    await closeClaudeRelayFromLoginPage()
    return
  }
  await connectTool(activeTool.value)
}

async function loadCodexAccounts(options: { silent?: boolean; force?: boolean; refreshSnapshots?: boolean } = {}) {
  // Background reads during a login write can observe an intermediate auth.json.
  // The operation response (or a read after it finishes) owns the resulting state.
  if (codexAccountMutationDepth > 0) return
  const silent = options.silent === true
  const generation = invalidateCodexAccountsRequests()
  codexAccountsError.value = ''
  if (!window.gaogeDesktop?.getCodexAccounts) {
    codexAccountsError.value = '当前不是桌面环境，无法读取本机 Codex 账号。'
    return
  }
  if (!silent) isCodexAccountsLoading.value = true
  try {
    if (options.refreshSnapshots === true && window.gaogeDesktop.refreshCodexAccountSnapshots) {
      await window.gaogeDesktop.refreshCodexAccountSnapshots().catch((error) => {
        reportPageError('account-management', 'refresh-codex-account-snapshots', error)
      })
    }
    if (generation !== codexAccountsLoadGeneration || codexAccountMutationDepth > 0) return
    const state = normalizeCodexAccountsState(await window.gaogeDesktop.getCodexAccounts())
    if (generation !== codexAccountsLoadGeneration) return
    codexAccountsState.value = state
    ensureSelectedCodexAccount()
    syncOfficialSubscriptionRecordsFromAccounts()
    if (!silent) {
      if (codexAccountsRetryTimer !== null) window.clearTimeout(codexAccountsRetryTimer)
      codexAccountsRetryTimer = window.setTimeout(() => {
        codexAccountsRetryTimer = null
        if (window.gaogeDesktop?.getCodexAccounts && activePage.value === '账号管理') {
          void loadCodexAccounts({ silent: true })
        }
      }, 4500)
    }
  } catch (error) {
    if (generation !== codexAccountsLoadGeneration) return
    // A silent background read can overlap a native configuration writer.
    // Keep the last confirmed identity instead of reporting the user's
    // successful login/restart as a failed account switch.
    if (silent && isCodexConfigurationBusyError(error)) return
    reportPageError('account-management', 'load-codex-accounts', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    if (!silent && generation === codexAccountsLoadGeneration) isCodexAccountsLoading.value = false
  }
}

async function loadCodexSessionStats() {
  dashboardLocalStatsError.value = ''
  if (!window.gaogeDesktop?.getCodexSessionStats) {
    codexSessionStats.value = null
    dashboardLocalStatsError.value = '请重启桌面端读取本机会话。'
    return
  }
  try {
    codexSessionStats.value = await window.gaogeDesktop.getCodexSessionStats()
  } catch (error) {
    reportPageError('account-management', 'load-codex-session-stats', error)
    codexSessionStats.value = null
    dashboardLocalStatsError.value = getCodexAccountErrorMessage(error)
  }
}

function openAddAccountDialog() {
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  sessionJsonInput.value = ''
  codexOauthLoginId.value = ''
  codexOauthAuthUrl.value = ''
  codexOauthRedirectUri.value = ''
  codexOauthCallbackInput.value = ''
  overwriteSessionAccount.value = false
  activateOauthAccount.value = false
  showAddAccountDialog.value = true
}

function closeAddAccountDialog() {
  if (isSessionAccountAdding.value || isCodexOauthStarting.value || isCodexOauthCompleting.value) return
  showAddAccountDialog.value = false
}

async function openExternalUrl(url: string) {
  try {
    if (window.gaogeDesktop?.openPaymentWindow) {
      await window.gaogeDesktop.openPaymentWindow({ payUrl: url })
      return
    }
    window.open(url, '_blank', 'noopener,noreferrer')
  } catch (error) {
    reportPageError('account-management', 'open-external-url', error)
    window.open(url, '_blank', 'noopener,noreferrer')
  }
}

const trustedPaymentHostSuffixes = [
  'alipay.com',
  'alipayobjects.com',
  'alipay.hk',
  'alipayplus.com',
  'alicdn.com',
]

function urlHost(value: string) {
  try {
    return new URL(value).host.toLowerCase()
  } catch {
    return ''
  }
}

function isTrustedPaymentHost(host: string) {
  const normalized = host.toLowerCase()
  if (!normalized) return false
  const payHost = urlHost(getPayOrigin())
  if (payHost && normalized === payHost) return true
  const selected = selectedRuntimeServer.value
  const runtimeHosts = [
    selected?.urls.payOrigin,
    selected?.urls.apiOrigin,
  ].map((origin) => origin ? urlHost(origin) : '').filter(Boolean)
  if (runtimeHosts.includes(normalized)) return true
  return trustedPaymentHostSuffixes.some((suffix) => normalized === suffix || normalized.endsWith(`.${suffix}`))
}

function validatePaymentLink(value: string, label: string, options: { required?: boolean } = {}) {
  const raw = String(value || '').trim()
  if (!raw) {
    return options.required
      ? { ok: false, message: `${label}为空。` }
      : { ok: true, message: '' }
  }
  if (/^data:image\//i.test(raw)) return { ok: true, message: '' }
  let parsed: URL
  try {
    parsed = new URL(raw)
  } catch {
    return options.required
      ? { ok: false, message: `${label}不是有效链接。` }
      : { ok: true, message: '' }
  }
  const protocol = parsed.protocol.replace(':', '').toLowerCase()
  if (['alipay', 'alipays', 'alipayqr'].includes(protocol)) return { ok: true, message: '' }
  if (!['http', 'https'].includes(protocol)) {
    return { ok: false, message: `${label}协议不受支持。` }
  }
  if (isTrustedPaymentHost(parsed.host)) return { ok: true, message: '' }
  const expected = getPayOrigin() || selectedRuntimeServer.value?.urls.payOrigin || '当前服务器支付入口'
  return {
    ok: false,
    message: `${label}不属于当前服务器支付链路：${parsed.host}，当前支付入口应为 ${expected}。`,
  }
}

async function pasteSessionJsonFromClipboard() {
  codexAccountsError.value = ''
  try {
    sessionJsonInput.value = await navigator.clipboard.readText()
  } catch {
    codexAccountsError.value = '剪贴板读取失败，请手动粘贴 Session JSON。'
  }
}

async function startCodexOauthLogin() {
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  if (!window.gaogeDesktop?.startCodexOauthLogin) {
    codexAccountsError.value = '当前桌面端暂不支持 OAuth 授权添加账号，请更新客户端。'
    return
  }

  isCodexOauthStarting.value = true
  try {
    const result = await window.gaogeDesktop.startCodexOauthLogin()
    codexOauthLoginId.value = result.loginId
    codexOauthAuthUrl.value = result.authUrl || result.authorizationUrl || ''
    codexOauthRedirectUri.value = result.redirectUri
    codexOauthCallbackInput.value = ''
    if (codexOauthAuthUrl.value) await openExternalUrl(codexOauthAuthUrl.value)
    codexAccountsNotice.value = '授权链接已打开。登录完成后，把浏览器地址栏里的完整回调地址粘贴回来。'
  } catch (error) {
    reportPageError('account-management', 'start-codex-oauth-login', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    isCodexOauthStarting.value = false
  }
}

async function copyCodexOauthAuthUrl() {
  codexAccountsError.value = ''
  if (!codexOauthAuthUrl.value) {
    codexAccountsError.value = '请先生成 OAuth 授权链接。'
    return
  }
  try {
    await navigator.clipboard.writeText(codexOauthAuthUrl.value)
    codexAccountsNotice.value = 'OAuth 授权链接已复制。'
  } catch {
    codexAccountsError.value = '授权链接复制失败，请手动复制。'
  }
}

async function pasteCodexOauthCallbackFromClipboard() {
  codexAccountsError.value = ''
  try {
    codexOauthCallbackInput.value = await navigator.clipboard.readText()
  } catch {
    codexAccountsError.value = '剪贴板读取失败，请手动粘贴 OAuth 回调地址。'
  }
}

async function completeCodexOauthLogin() {
  if (isCodexOauthCompleting.value || codexAccountMutationDepth > 0) return
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  const callbackUrl = codexOauthCallbackInput.value.trim()
  if (!codexOauthLoginId.value || !codexOauthAuthUrl.value) {
    codexAccountsError.value = '请先生成并打开 OAuth 授权链接。'
    return
  }
  if (!callbackUrl) {
    codexAccountsError.value = '请粘贴授权后的完整回调地址。'
    return
  }
  if (!window.gaogeDesktop?.completeCodexOauthLogin) {
    codexAccountsError.value = '当前桌面端暂不支持 OAuth 授权添加账号，请更新客户端。'
    return
  }
  const setActive = activateOauthAccount.value
  if (setActive && !(await confirmCodexRestart('授权成功后立即切换 Codex 账号'))) {
    codexAccountsNotice.value = '已取消立即切换；取消勾选后可以只添加账号快照。'
    return
  }
  if (codexAccountMutationDepth > 0) return

  isCodexOauthCompleting.value = true
  const finishAccountMutation = beginCodexAccountMutation()
  try {
    const routeBeforeSwitch = setActive ? await readCodexAccountSwitchRoute() : null
    const result = await window.gaogeDesktop.completeCodexOauthLogin({
      loginId: codexOauthLoginId.value,
      callbackUrl,
      overwriteExisting: overwriteSessionAccount.value,
      setActive,
    })
    codexAccountsState.value = normalizeCodexAccountsState(result.state)
    if (result.activated) {
      const verifiedAccount = normalizeCodexAccount(codexAccountsState.value.currentAccount)
      if (!verifiedAccount || verifiedAccount.accountKey !== result.account.accountKey) {
        throw new Error('OAuth 账号切换已执行，但当前登录账号校验失败。请刷新账号状态后重试。')
      }
      applyCodexEnhancementResults(result.enhancements || result.launch)
      applyCodexAccountSwitchRoute(result, result.account.accountKey, routeBeforeSwitch || {
        preserveRelay: false, source: '', aggregate: undefined,
      })
    }
    selectedCodexAccountKey.value = result.account.accountKey
    const title = codexAccountTitle(result.account)
    const launchWarning = codexLaunchWarnings(result)
    const warning = [result.warning, launchWarning].filter(Boolean).join(' ')
    codexAccountsNotice.value = result.activated
      ? `已通过 OAuth 添加并切换到账号 ${title}。${result.codexLaunched ? 'Codex 已自动重新打开。' : '请手动重新打开 Codex。'}${warning ? ` ${warning}` : ''}`
      : `已通过 OAuth 添加账号 ${title}，登录快照已保存。${warning ? ` ${warning}` : ''}`
    showAddAccountDialog.value = false
    codexOauthLoginId.value = ''
    codexOauthAuthUrl.value = ''
    codexOauthRedirectUri.value = ''
    codexOauthCallbackInput.value = ''
  } catch (error) {
    reportPageError('account-management', 'complete-codex-oauth-login', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    finishAccountMutation()
    isCodexOauthCompleting.value = false
  }
}

async function submitSessionAccount() {
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  const sessionJson = sessionJsonInput.value.trim()
  if (!sessionJson) {
    codexAccountsError.value = '请先粘贴 Session JSON。'
    return
  }
  if (!window.gaogeDesktop?.addCodexAccountFromSession) {
    codexAccountsError.value = '当前桌面端暂不支持 Session JSON 添加账号，请更新客户端。'
    return
  }

  isSessionAccountAdding.value = true
  try {
    const result = await window.gaogeDesktop.addCodexAccountFromSession({
      sessionJson,
      overwriteExisting: overwriteSessionAccount.value,
      setActive: false,
    })
    codexAccountsState.value = normalizeCodexAccountsState(result.state)
    selectedCodexAccountKey.value = result.account.accountKey
    codexAccountsNotice.value = `已添加账号 ${codexAccountTitle(result.account)}。`
    showAddAccountDialog.value = false
    sessionJsonInput.value = ''
  } catch (error) {
    reportPageError('account-management', 'add-account-from-session', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    isSessionAccountAdding.value = false
  }
}

async function importCodexAccounts() {
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  if (!window.gaogeDesktop?.importCodexAccounts) {
    codexAccountsError.value = '当前不是桌面环境，无法导入 Codex 账号。'
    return
  }
  isCodexAccountsImporting.value = true
  try {
    const result = await window.gaogeDesktop.importCodexAccounts()
    codexAccountsState.value = normalizeCodexAccountsState(result.state)
    ensureSelectedCodexAccount()
    codexAccountsNotice.value = result.cancelled ? '已取消导入。' : `已导入 ${result.imported.length} 个账号。`
  } catch (error) {
    reportPageError('account-management', 'import-codex-accounts', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    isCodexAccountsImporting.value = false
  }
}

async function openExportAccountsDialog() {
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  exportSelectedAccountKeys.value = managedAccounts.value.map((account) => account.accountKey)
  if (exportSelectedAccountKeys.value.length === 0) {
    codexAccountsError.value = '没有可导出的账号快照，请先刷新账号或添加当前账号。'
  }
  showExportAccountsDialog.value = true
  if (window.gaogeDesktop?.getCodexAccounts) refreshExportAccountOptionsInBackground()
}

function closeExportAccountsDialog() {
  if (isCodexAccountsExporting.value) return
  showExportAccountsDialog.value = false
}

function refreshExportAccountOptionsInBackground() {
  const selectedBefore = new Set(exportSelectedAccountKeys.value)
  void loadCodexAccounts({ silent: true }).then(() => {
    if (!showExportAccountsDialog.value) return
    const nextKeys = managedAccounts.value.map((account) => account.accountKey)
    const keptKeys = nextKeys.filter((key) => selectedBefore.has(key))
    exportSelectedAccountKeys.value = selectedBefore.size > 0 && keptKeys.length > 0 ? keptKeys : nextKeys
    if (nextKeys.length === 0) {
      codexAccountsError.value = '没有可导出的账号快照，请先刷新账号或添加当前账号。'
    }
  })
}

const isAllExportAccountsSelected = computed(() => (
  managedAccounts.value.length > 0 &&
  exportSelectedAccountKeys.value.length === managedAccounts.value.length
))

function toggleExportAccount(accountKey: string) {
  if (exportSelectedAccountKeys.value.includes(accountKey)) {
    exportSelectedAccountKeys.value = exportSelectedAccountKeys.value.filter((key) => key !== accountKey)
  } else {
    exportSelectedAccountKeys.value = [...exportSelectedAccountKeys.value, accountKey]
  }
}

function toggleAllExportAccounts() {
  exportSelectedAccountKeys.value = isAllExportAccountsSelected.value
    ? []
    : managedAccounts.value.map((account) => account.accountKey)
}

async function exportSelectedCodexAccounts() {
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  if (exportSelectedAccountKeys.value.length === 0) {
    codexAccountsError.value = '请至少选择一个要导出的账号。'
    return
  }
  if (!window.gaogeDesktop?.exportCodexAccounts) {
    codexAccountsError.value = '当前不是桌面环境，无法导出 Codex 账号。'
    return
  }
  const selectedKeys = [...exportSelectedAccountKeys.value]
  const confirmed = await confirmAction(`即将把本机已保存的 ${selectedKeys.length} 个账号打包成一个备份文件。该文件包含可登录这些账号的凭据，请谨慎保管。`, {
    tone: 'warning',
    title: '导出账号备份？',
    confirmText: '我已了解，继续导出',
    cancelText: '取消',
    details: [
      '备份内容包含 OAuth Token / API Key，等同账号本身。',
      '切勿通过聊天软件、公共云盘或邮件附件分享。',
      '建议存放到加密磁盘 / 密码管理器，过期后及时销毁。',
    ],
  })
  if (!confirmed) {
    codexAccountsNotice.value = '已取消导出。'
    return
  }
  isCodexAccountsExporting.value = true
  try {
    await loadCodexAccounts({ silent: true })
    const availableKeys = new Set(managedAccounts.value.map((account) => account.accountKey))
    const exportKeys = selectedKeys.filter((key) => availableKeys.has(key))
    if (exportKeys.length === 0) {
      throw new Error('没有可导出的账号快照，请先刷新账号或添加当前账号。')
    }
    const result = await window.gaogeDesktop.exportCodexAccounts(exportKeys)
    codexAccountsNotice.value = result.cancelled ? '已取消导出。' : `已导出 ${result.count} 个账号到 ${result.filePath}。`
    if (!result.cancelled) showExportAccountsDialog.value = false
  } catch (error) {
    reportPageError('account-management', 'export-codex-accounts', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    isCodexAccountsExporting.value = false
  }
}

function codexAccountTitle(account: GaogeDesktopCodexAccount) {
  return account.alias || account.profileName || account.email || account.accountName || '未命名账号'
}

function officialIdentifiedAccountLabel() {
  return officialIdentifiedAccount.value?.email || officialIdentifiedAccount.value?.displayName || '未识别账号'
}

function officialSubscriptionPlanValueText(plan: OfficialSubscriptionPlan) {
  return officialRiskPlanValueMap[plan.id] || plan.officialPrice.replace(/\s*\/\s*月\s*$/u, '')
}

function clearOfficialIdentifiedAccount(accountKey?: string) {
  if (!accountKey || officialIdentifiedAccount.value?.accountKey !== accountKey) {
    officialIdentifiedAccount.value = null
  }
}

function ensureSelectedCodexAccount() {
  if (codexAccounts.value.some((account) => account.accountKey === selectedCodexAccountKey.value)) return
  selectedCodexAccountKey.value = activeCodexAccountKey.value || codexAccounts.value[0]?.accountKey || ''
}

function ensureOfficialSelectedAccount() {
  if (managedAccounts.value.some((account) => account.accountKey === officialSelectedAccountKey.value)) return
  officialSelectedAccountKey.value = (
    managedAccounts.value.find((account) => account.isCurrent)?.accountKey ||
    managedAccounts.value[0]?.accountKey ||
    ''
  )
}

function selectManagedAccount(account: ManagedAccount) {
  selectedCodexAccountKey.value = account.accountKey
}

function selectOfficialAccount(account: ManagedAccount) {
  officialSelectedAccountKey.value = account.accountKey
  clearOfficialIdentifiedAccount(account.accountKey)
  showOfficialAccountDialog.value = false
  officialSubscriptionError.value = ''
}

function normalizeOfficialIdentifiedAccount(
  result: GaogeDesktopCodexAccountSessionIdentifyResponse,
  fallbackAccountKey = '',
): OfficialIdentifiedAccount {
  const email = safeString(result.email)
  const sessionJson = safeString(result.sessionJson)
  const accountKey = safeString(result.accountKey) || fallbackAccountKey
  const isFullSessionJson = result.isFullSessionJson === true
  if (!email) throw new Error('实时获取到完整 Session JSON，但没有识别到邮箱。请重新登录 ChatGPT 后再识别。')
  if (!sessionJson) throw new Error('实时获取到账号信息，但 Session JSON 为空。请重新登录 ChatGPT 后再识别。')
  if (!isFullSessionJson) throw new Error('该账号没有完整 ChatGPT Session JSON，请重新登录 ChatGPT 后再订阅。')
  return {
    accountKey,
    email,
    displayName: safeString(result.displayName) || email,
    sessionJson,
    sessionSource: safeString(result.sessionSource) || 'official_chatgpt_window',
    sessionUrl: safeString(result.sessionUrl) || 'https://chatgpt.com/api/auth/session',
    isFullSessionJson,
    tokenStatus: result.tokenStatus || null,
    account: normalizeCodexAccount(result.account),
  }
}

function resetOfficialIdentifyFlow() {
  officialIdentifyStep.value = 'login'
  officialIdentifyStatus.value = '打开 GPT 登录需要订阅的账号'
  officialSessionTextInput.value = ''
  officialSubscriptionError.value = ''
  isOfficialIdentifying.value = false
}

function cancelOfficialIdentifyFlow() {
  if (isOfficialIdentifying.value) return
  showOfficialIdentifyDialog.value = false
  resetOfficialIdentifyFlow()
}

function cancelOfficialRiskNotice() {
  showOfficialRiskNoticeDialog.value = false
  officialRiskNoticeInput.value = ''
  officialRiskNoticeError.value = ''
}

function confirmOfficialRiskNotice() {
  officialRiskNoticeError.value = ''
  if (!isOfficialRiskNoticeInputValid.value) {
    officialRiskNoticeError.value = `请完整输入“${officialRiskNoticeConfirmText}”后继续。`
    return
  }
  showOfficialRiskNoticeDialog.value = false
  officialRiskNoticeInput.value = ''
  resetOfficialIdentifyFlow()
  showOfficialIdentifyDialog.value = true
}

async function openOfficialLoginInBrowser() {
  officialSubscriptionError.value = ''
  try {
    await openExternalUrl(chatgptOfficialLoginUrl)
    officialIdentifyStep.value = 'login-opened'
    officialIdentifyStatus.value = '已打开登录，进行下一步'
  } catch (error) {
    reportPageError('official-subscription', 'open-chatgpt-login', error, { planId: selectedOfficialPlanId.value })
    officialSubscriptionError.value = getErrorMessage(error)
  }
}

function continueOfficialAfterLogin() {
  officialSubscriptionError.value = ''
  officialIdentifyStep.value = 'session'
  officialIdentifyStatus.value = '点击获取 Session'
}

async function openOfficialSessionInBrowser() {
  officialSubscriptionError.value = ''
  try {
    await openExternalUrl(chatgptOfficialSessionUrl)
    officialIdentifyStep.value = 'paste'
    officialIdentifyStatus.value = '请把文本全部复制到框内'
  } catch (error) {
    reportPageError('official-subscription', 'open-chatgpt-session', error, { planId: selectedOfficialPlanId.value })
    officialSubscriptionError.value = getErrorMessage(error)
  }
}

async function pasteOfficialSessionTextFromClipboard() {
  officialSubscriptionError.value = ''
  try {
    officialSessionTextInput.value = await navigator.clipboard.readText()
  } catch {
    officialSubscriptionError.value = '剪贴板读取失败，请手动把网页文本全部复制到框内。'
  }
}

function backToOfficialLoginStep() {
  officialIdentifyStep.value = 'login'
  officialIdentifyStatus.value = '打开 GPT 登录需要订阅的账号'
  officialSessionTextInput.value = ''
  officialSubscriptionError.value = ''
}

async function submitOfficialSessionText() {
  if (isOfficialIdentifying.value) return
  officialSubscriptionError.value = ''
  const sessionJson = officialSessionTextInput.value.trim()
  if (!sessionJson) {
    officialSubscriptionError.value = '请把文本全部复制到框内。'
    return
  }
  if (!window.gaogeDesktop?.identifyOfficialChatgptSessionText) {
    officialSubscriptionError.value = '当前客户端暂不支持粘贴 Session 识别，请更新软件后再试。'
    return
  }

  isOfficialIdentifying.value = true
  officialIdentifyStatus.value = '正在识别账号'
  try {
    const result = await window.gaogeDesktop.identifyOfficialChatgptSessionText({ sessionJson })
    if (result.state) {
      codexAccountsState.value = normalizeCodexAccountsState(result.state)
      ensureSelectedCodexAccount()
      if (safeString(result.accountKey)) officialSelectedAccountKey.value = safeString(result.accountKey)
    }
    officialIdentifiedAccount.value = normalizeOfficialIdentifiedAccount(result)
    officialSubscriptionNotice.value = `识别成功：${officialIdentifiedAccount.value.email}，确认订阅套餐`
    showOfficialIdentifyDialog.value = false
    showOfficialConfirmDialog.value = true
  } catch (error) {
    reportPageError('official-subscription', 'identify-pasted-session', error, { planId: selectedOfficialPlanId.value })
    officialIdentifiedAccount.value = null
    officialIdentifyStep.value = 'failed'
    officialIdentifyStatus.value = '没有识别到账号'
    officialSubscriptionError.value = '没有识别到您的账号，请回到第一步登录好 GPT。'
    notify(officialSubscriptionError.value, 'error', '账号识别失败')
  } finally {
    isOfficialIdentifying.value = false
  }
}

async function requestOfficialSubscription(plan: OfficialSubscriptionPlan) {
  if (isOfficialIdentifying.value) return
  officialReferralSelection.value = null
  officialSubscriptionNotice.value = ''
  officialSubscriptionError.value = ''
  officialRiskNoticeInput.value = ''
  officialRiskNoticeError.value = ''
  officialIdentifyStatus.value = '打开 GPT 登录需要订阅的账号'
  selectedOfficialPlanId.value = plan.id
  showOfficialRiskNoticeDialog.value = true
  showOfficialIdentifyDialog.value = false
  showOfficialConfirmDialog.value = false
  showOfficialPaymentDialog.value = false
  showOfficialCardDialog.value = false
  showOfficialAccountDialog.value = false
  officialIdentifiedAccount.value = null
  resetOfficialIdentifyFlow()
}

function confirmOfficialSubscription() {
  if (!officialIdentifiedAccount.value) {
    officialSubscriptionError.value = '请先点击订阅并完成账号识别。'
    showOfficialConfirmDialog.value = false
    return
  }
  showOfficialConfirmDialog.value = false
  officialReferralSelection.value = null
  showOfficialPaymentDialog.value = true
}

function openOfficialCardPayment() {
  if (!officialIdentifiedAccount.value) {
    officialSubscriptionError.value = '请先点击订阅并完成账号识别。'
    showOfficialPaymentDialog.value = false
    return
  }
  officialCardCode.value = ''
  officialSubscriptionError.value = ''
  officialSubscriptionNotice.value = ''
  showOfficialPaymentDialog.value = false
  showOfficialCardDialog.value = true
}

async function submitOfficialCardPayment() {
  const code = officialCardCode.value.trim()
  const account = officialIdentifiedAccount.value
  const plan = selectedOfficialPlan.value
  officialSubscriptionError.value = ''
  officialSubscriptionNotice.value = ''
  if (!account) {
    officialSubscriptionError.value = '请先点击订阅并完成账号识别。'
    showOfficialCardDialog.value = false
    return
  }
  if (!code) {
    officialSubscriptionError.value = '请输入卡密。'
    return
  }
  if (!authToken.value) {
    officialSubscriptionError.value = '请先登录账户。'
    return
  }
  isOfficialSubscribing.value = true
  try {
    const owner = officialSubscriptionOwnerParams()
    const clientOrderId = `official-card-${Date.now()}-${getRandomText(6)}`
    const submittedAt = new Date().toISOString()
    const result = await submitOfficialSubscriptionCardSecretToSoftwareAdmin({
      userId: owner.userId,
      user: account.email || owner.email,
      email: account.email || owner.email,
      username: owner.username,
      planId: plan.id,
      planName: plan.name,
      source: 'card-secret',
      orderId: clientOrderId,
      orderNo: clientOrderId,
      clientOrderId,
      paymentStatus: 'card-secret-verified',
      amount: plan.localPrice,
      currency: 'CNY',
      sessionText: account.sessionJson,
      sessionSource: account.sessionSource,
      sessionUrl: account.sessionUrl,
      cardSecret: code,
      clientVersion: updateVersionText.value,
      platform: typeof navigator !== 'undefined' ? navigator.platform : '',
      note: `官方订阅卡密订单 ${clientOrderId}`,
      paymentMethod: 'card-secret',
      paymentInfo: {
        paid: true,
        status: 'card-secret-verified',
      },
      paidAt: submittedAt,
    }, authToken.value)
    if (!isOfficialSubscriptionDeliveryAccepted(result)) {
      throw new Error('服务器尚未确认收到订阅资料，请保留卡密并重试。')
    }
    const remoteOrder = result.order || {
      id: clientOrderId,
      orderId: clientOrderId,
      orderNo: clientOrderId,
      clientOrderId,
      planId: plan.id,
      planName: plan.name,
      source: 'card-secret',
      paymentStatus: 'card-secret-verified',
      rechargeStatus: 'processing',
      status: 'processing',
      amount: result.amount || plan.localPrice,
      currency: result.currency || 'CNY',
      email: account.email,
      userId: owner.userId,
      username: owner.username,
      submittedAt,
      paidAt: submittedAt,
      hasSessionText: true,
    }
    const record = normalizeOfficialSubscriptionRecordFromSoftwareAdmin(remoteOrder)
    if (record) mergeOfficialSubscriptionRecords([record])
    void syncOfficialSubscriptionRecordsWithSoftwareAdmin()
    officialCardCode.value = ''
    showOfficialCardDialog.value = false
    officialSubscriptionNotice.value = `已提交 ${plan.name} 卡密订阅请求，识别账号：${account.email}，进度已记录为订阅中。`
    notify(`已提交 ${plan.name} 卡密订阅请求。`, 'success', '官方订阅')
  } catch (error) {
    reportPageError('official-subscription', 'submit-official-card-subscription', error, {
      planId: plan.id,
      accountEmail: account.email,
    })
    officialSubscriptionError.value = getErrorMessage(error)
  } finally {
    isOfficialSubscribing.value = false
  }
}

async function openOfficialOnlinePayment() {
  if (isOfficialSubscribing.value) return
  clearPaymentPanelDismissTimer()
  const account = officialIdentifiedAccount.value
  const plan = selectedOfficialPlan.value
  const payAmount = Number(plan.localPrice)
  const referral = officialReferralSelection.value
  officialSubscriptionError.value = ''
  officialSubscriptionNotice.value = ''
  activePaymentPurpose.value = 'official-subscription'
  if (!account) {
    officialSubscriptionError.value = '请先点击订阅并完成账号识别。'
    showOfficialPaymentDialog.value = false
    return
  }
  if (!authToken.value) {
    officialSubscriptionError.value = '请先登录账户。'
    showOfficialPaymentDialog.value = false
    return
  }
  if (!Number.isFinite(payAmount) || payAmount <= 0) {
    officialSubscriptionError.value = '套餐价格配置不完整，请联系售后处理。'
    return
  }
  if (!referral?.ready || Math.abs(referral.baseAmount - payAmount) > 0.005) {
    officialSubscriptionError.value = '请先确认邀请信息及优惠金额。'
    return
  }
  const referralKey = JSON.stringify([payAmount, referral.inviterEmail, [...referral.couponIDs].sort((a, b) => a - b), referral.payableAmount])
  const ownerId = String(authUser.value?.id || '')
  const token = authToken.value
  let context: OfficialSubscriptionRequestContext | null = null
  isOfficialSubscribing.value = true
  try {
    const previous = activeOfficialSubscriptionRequest.value
    activeOfficialSubscriptionRequest.value = previous && previous.ownerId === ownerId
      && previous.planId === plan.id && previous.account === account.email
      && previous.sessionJson === account.sessionJson && previous.referralKey === referralKey
      ? previous
      : createOfficialSubscriptionRequestContext(plan, account, payAmount)
    // Capture Vue's reactive value, not the unwrapped object assigned to the ref.
    context = activeOfficialSubscriptionRequest.value
    context.referralKey = referralKey
    stopPaymentPolling()
    paymentQrCode.value = ''
    externalPaymentPageUrl.value = ''
    activePaymentCreditAmount.value = 0
    const order = await createPaymentOrder(payAmount, token, {
      orderType: 'official_sub',
      officialPlanId: plan.id,
      officialReferral: { inviter_email: referral.inviterEmail, coupon_ids: referral.couponIDs },
      idempotencyKey: context.idempotencyKey,
      officialSubscriptionSession: {
        plan_id: context.planId,
        plan_name: context.planName,
        account_email: context.account,
        account_key: context.accountKey,
        session_json: context.sessionJson,
        session_source: context.sessionSource,
        session_url: context.sessionUrl,
      },
    })
    if (String(authUser.value?.id || '') !== ownerId || authToken.value !== token
      || activeOfficialSubscriptionRequest.value !== context) return
    requireOfficialSubscriptionSessionSaved(order)
    requireOfficialReferralReceipt(order, referral)
    context.orderId = getPaymentOrderId(order)
    const actualPayAmount = getPaymentOrderAmount(order)
    context.amount = actualPayAmount
    rememberOfficialSubscriptionReceipt(order, context)
    if (actualPayAmount === 0 && ['paid', 'completed', 'recharging'].includes(String(order.status || '').toLowerCase())) {
      activePaymentOrder.value = { ...order, order_type: 'official_sub' }
      showOfficialPaymentDialog.value = false
      await refreshActivePaymentOrder()
      return
    }
    await renderPaymentOrder({
      ...order,
      amount: order.amount ?? actualPayAmount,
      pay_amount: order.pay_amount ?? actualPayAmount,
      order_type: order.order_type || 'official_sub',
    })
    if (String(authUser.value?.id || '') !== ownerId || authToken.value !== token
      || activeOfficialSubscriptionRequest.value !== context) return
    showOfficialPaymentDialog.value = false
    officialSubscriptionNotice.value = activePaymentPageUrl.value && !paymentQrCode.value
      ? `支付页面已打开，正在等待付款完成。完成后将提交 ${account.email} 的 ${plan.name} 官方订阅请求。`
      : `官方订阅订单已创建，请扫码支付。完成后将提交 ${account.email} 的 ${plan.name} 官方订阅请求。`
    notify(`已创建 ${plan.name} 在线支付订单。`, 'info', '官方订阅')
  } catch (error) {
    if (String(authUser.value?.id || '') !== ownerId || authToken.value !== token
      || (context && activeOfficialSubscriptionRequest.value !== context)) return
    activePaymentOrder.value = null
    reportPageError('official-subscription', 'create-official-subscription-order', error, {
      planId: plan.id,
      accountEmail: account.email,
    })
    officialSubscriptionError.value = getPaymentErrorMessage(error)
  } finally {
    isOfficialSubscribing.value = false
  }
}

function isCurrentCodexAccount(account: GaogeDesktopCodexAccount) {
  return Boolean(activeCodexAccountKey.value && account.accountKey === activeCodexAccountKey.value)
}

function codexAccountLoginStateText(account: ManagedAccount | GaogeDesktopCodexAccount | null | undefined) {
  if (!account) return '未知'
  const source = 'account' in account ? account.account : account
  if (source.isActive || source.isLiveCurrent) return '当前已登录'
  if (source.requiresReauth || source.loginState === 'invalid') return '账号已失效'
  if (source.loginState === 'refreshable') return '可切换登录'
  return '可切换登录'
}

function codexAccountSwitchButtonText(account: ManagedAccount) {
  if (account.isCurrent) return '当前已登录'
  if (isCodexAccountSwitching.value) return '切换中'
  if (account.requiresReauth || !account.canSwitch) return '账号已失效重新登录'
  return '切换到此账号'
}

function codexAccountSwitchDisabled(account: ManagedAccount) {
  return isCodexAccountSwitching.value || account.isCurrent || account.requiresReauth || !account.canSwitch
}

async function normalLoginCodexAccount(account?: GaogeDesktopCodexAccount | null) {
  if (isCodexAccountSwitching.value || codexAccountMutationDepth > 0) return
  const target = account || selectedCodexAccount.value
  if (!target) return
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  const managedTarget = managedAccounts.value.find((item) => item.accountKey === target.accountKey)
  if (managedTarget && (managedTarget.requiresReauth || !managedTarget.canSwitch)) {
    codexAccountsError.value = '账号已失效，请先重新登录该账号。'
    notify('账号已失效，请先重新登录该账号。', 'error')
    return
  }
  if (!window.gaogeDesktop?.activateCodexAccount) {
    codexAccountsError.value = '当前不是桌面环境，无法启用 Codex 账号。'
    return
  }
  if (!(await confirmCodexRestart(`切换到账号 ${codexAccountTitle(target)}`))) {
    codexAccountsNotice.value = '已取消切换账号。'
    return
  }
  if (codexAccountMutationDepth > 0) return
  const codexOperation = openCodexOperationDialog(
    '正在切换 Codex 账号',
    '正在读取配置',
  )
  isCodexAccountSwitching.value = true
  const finishAccountMutation = beginCodexAccountMutation()
  try {
    const desktopApi = window.gaogeDesktop
    // Account management can open before the login page has loaded its state.
    // Read the live route for legacy response display. The backend detects the
    // actual route under its mutation lock so an older read cannot disable it.
    const routeBeforeSwitch = await readCodexAccountSwitchRoute()
    codexOperation.update({ message: '正在写入中', detail: '' })
    invalidateCodexStatusRequests()
    const activationResult = await desktopApi.activateCodexAccount({
      accountKey: target.accountKey,
    })
    invalidateCodexStatusRequests()
    codexOperation.update({
      message: '正在同步状态',
      detail: '',
    })
    codexAccountsState.value = normalizeCodexAccountsState(activationResult)
    const verifiedAccount = normalizeCodexAccount(codexAccountsState.value?.currentAccount)
    if (!verifiedAccount || verifiedAccount.accountKey !== target.accountKey) {
      throw new Error('账号切换已执行，但当前登录账号校验失败。原登录凭据已保留，请重启 ChatGPT 后重试。')
    }
    applyCodexEnhancementResults(activationResult.enhancements || activationResult.launch)
    selectedCodexAccountKey.value = target.accountKey
    applyCodexAccountSwitchRoute(activationResult, target.accountKey, routeBeforeSwitch)
    const email = target.email || target.accountName || codexAccountTitle(target)
    const warning = codexLaunchWarnings(activationResult)
    codexAccountsNotice.value = `当前已登录账号：${email}。${activationResult.codexLaunched ? 'Codex 已自动重新打开。' : '请手动重新打开 Codex。'}${warning ? ` ${warning}` : ''}`
  } catch (error) {
    reportPageError('account-management', 'activate-codex-account', error)
    if (isCodexAccountInvalidError(error)) {
      codexOperation.close()
      finishAccountMutation()
      await loadCodexAccounts({ silent: true, force: true }).catch(() => undefined)
      codexAccountsError.value = '账号登录已失效，已取消当前登录状态。现在可以移除该账号，或重新登录后再切换。'
      notify('账号登录已失效。', 'error')
      return
    }
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    finishAccountMutation()
    codexOperation.close()
    isCodexAccountSwitching.value = false
  }
}

async function deleteCodexAccount(account?: GaogeDesktopCodexAccount | null) {
  const target = account || selectedCodexAccount.value
  if (!target) return
  codexAccountsError.value = ''
  codexAccountsNotice.value = ''
  if (!window.gaogeDesktop?.deleteCodexAccount) {
    codexAccountsError.value = '当前不是桌面环境，无法删除本机 Codex 账号。'
    return
  }
  const forceDelete = isCurrentCodexAccount(target)
  const accountTitle = codexAccountTitle(target)
  const confirmed = await confirmAction(forceDelete
    ? `当前账号 ${accountTitle} 已登录，是否强制删除？`
    : `删除账号 ${accountTitle} 会移除本机登录快照，是否继续？`, {
    tone: forceDelete ? 'error' : 'warning',
    title: forceDelete ? '强制删除当前账号' : '删除账号快照',
    details: forceDelete
      ? [
          '确认后会先关闭正在运行的 Codex，再清除当前登录和本机账号快照。',
          '删除完成后不会自动重新打开 Codex；如需再次使用该账号，必须重新授权登录。',
        ]
      : [],
    dangerDetails: forceDelete
      ? ['此操作无法撤销，请确认当前正在使用的账号已经不再需要。']
      : [],
    confirmText: forceDelete ? '是，关闭并强制删除' : '确认删除',
    cancelText: '取消',
  })
  if (!confirmed) {
    codexAccountsNotice.value = '已取消删除账号。'
    return
  }
  const codexOperation = forceDelete
    ? openCodexOperationDialog('正在强制删除当前账号', '正在关闭 Codex 并清除登录快照')
    : null
  isCodexAccountDeleting.value = true
  try {
    const result = await window.gaogeDesktop.deleteCodexAccount({
      accountKey: target.accountKey,
      force: forceDelete,
    })
    codexOperation?.update({ message: '正在刷新账号状态', detail: '' })
    codexAccountsState.value = normalizeCodexAccountsState(result.state)
    ensureSelectedCodexAccount()
    codexAccountsNotice.value = result.forced
      ? `已强制删除当前账号 ${accountTitle}。Codex 已关闭，如需再次使用请重新授权登录。`
      : `已删除账号 ${accountTitle}。`
    notify(
      result.forced ? '当前账号已强制删除，Codex 已关闭。' : `已删除账号 ${accountTitle}。`,
      'success',
    )
  } catch (error) {
    reportPageError('account-management', 'delete-codex-account', error)
    codexAccountsError.value = getCodexAccountErrorMessage(error)
  } finally {
    codexOperation?.close()
    isCodexAccountDeleting.value = false
  }
}

async function loadCompatibleAccessKeys(options: { silent?: boolean } = {}) {
  const silent = options.silent === true
  if (!silent) {
    compatibleAccessError.value = ''
    compatibleAccessNotice.value = ''
  }
  if (!authToken.value) return
  if (groups.value.length === 0) await syncGroups({ silent })
  const next = { ...compatibleKeys.value }
  let loaded = 0
  const failures: string[] = []
  isCompatibleKeysLoading.value = true
  try {
    for (const tool of ['codex', 'claude'] as ToolKey[]) {
      const groupId = selectedToolGroupId(tool)
      if (!groupId) {
        failures.push(`未找到 ${tool === 'codex' ? 'GPT' : 'Claude'} 分组`)
        continue
      }
      try {
        const apiKey = await ensureToolDefaultApiKeyForGroup(tool, groupId, { syncGroup: false })
        next[tool] = apiKey.key
        loaded += 1
      } catch (error) {
        failures.push(`${tool === 'codex' ? 'GPT' : 'Claude'} Key 读取失败：${getApiKeyErrorMessage(error)}`)
      }
    }
    const image2Group = image2Groups.value[0]
    if (!image2Group) {
      failures.push('未找到 Image2 生图分组')
    } else {
      try {
        const apiKey = await ensureDefaultApiKey(image2Group.id, authToken.value, 'image2')
        next.image2 = apiKey.key
        loaded += 1
      } catch (error) {
        failures.push(`Image2 生图 Key 读取失败：${getApiKeyErrorMessage(error)}`)
      }
    }
    compatibleKeys.value = next
    if (!silent) {
      if (loaded > 0) compatibleAccessNotice.value = `已读取 ${loaded} 个默认 Key。`
      if (failures.length > 0) compatibleAccessError.value = failures.join('；')
    }
  } finally {
    isCompatibleKeysLoading.value = false
  }
}

async function ensureImage2AccessKey() {
  const cachedKey = compatibleKeys.value.image2.trim()
  if (cachedKey) return cachedKey
  if (!authToken.value) {
    throw new Error('请先登录账户。')
  }
  if (groups.value.length === 0) {
    await syncGroups()
  }
  const image2Group = image2Groups.value[0]
  if (!image2Group) {
    throw new Error('未找到 Image2 生图分组，请联系售后处理。')
  }
  const apiKey = await ensureDefaultApiKey(image2Group.id, authToken.value, 'image2')
  compatibleKeys.value = { ...compatibleKeys.value, image2: apiKey.key }
  return apiKey.key
}

async function tryEnsureCodexImageTools() {
  try {
    return {
      key: await ensureImage2AccessKey(),
      warning: '',
    }
  } catch (error) {
    return {
      key: '',
      warning: `Codex 生图工具暂未配置：${getApiKeyErrorMessage(error)}`,
    }
  }
}

async function selectImage2OutputDir() {
  image2Error.value = ''
  image2Notice.value = ''
  if (!window.gaogeDesktop?.selectImageOutputDir) {
    image2Error.value = '当前不是桌面环境，无法选择图片保存位置。'
    return
  }
  if (isImage2SelectingOutputDir.value) return
  isImage2SelectingOutputDir.value = true
  try {
    const result = await window.gaogeDesktop.selectImageOutputDir()
    if (result.cancelled || !result.path) return
    image2OutputDir.value = result.path
    localStorage.setItem(IMAGE2_OUTPUT_DIR_STORAGE_KEY, result.path)
    image2Notice.value = '图片保存位置已选择。'
  } catch (error) {
    reportPageError('image2-local', 'select-output-dir', error)
    image2Error.value = getErrorMessage(error, { notFoundMessage: '无法选择图片保存位置，请重新选择。' })
  } finally {
    isImage2SelectingOutputDir.value = false
  }
}

async function selectImage2References() {
  image2Error.value = ''
  image2Notice.value = ''
  if (!window.gaogeDesktop?.selectImageReferences) {
    image2Error.value = '当前不是桌面环境，无法上传参考图。'
    return
  }
  if (isImage2SelectingReferences.value) return
  isImage2SelectingReferences.value = true
  try {
    const result = await window.gaogeDesktop.selectImageReferences()
    if (image2IsGif.value || result.cancelled || !result.images.length) return
    const merged = new Map(image2References.value.map((image) => [image.path, image]))
    for (const image of result.images) {
      if (merged.size >= IMAGE2_MAX_REFERENCES) break
      merged.set(image.path, image)
    }
    image2References.value = Array.from(merged.values()).slice(0, IMAGE2_MAX_REFERENCES)
    image2Mode.value = 'image'
    image2Notice.value = `已添加 ${image2References.value.length} 张参考图。`
  } catch (error) {
    reportPageError('image2-local', 'select-reference-images', error)
    image2Error.value = getErrorMessage(error, { notFoundMessage: '无法读取参考图，请重新选择。' })
  } finally {
    isImage2SelectingReferences.value = false
  }
}

function removeImage2Reference(path: string) {
  image2References.value = image2References.value.filter((image) => image.path !== path)
}

function clearImage2References() {
  image2References.value = []
}

function selectImage2Size(option: Image2SizeOption) {
  image2SizePreset.value = option.id
  image2Size.value = option.value
  isImage2SizeDialogOpen.value = false
}

function openImage2Preview(image: GaogeDesktopGeneratedLocalImage | null) {
  if (!image) return
  image2PreviewImage.value = image
}

function closeImage2Preview() {
  image2PreviewImage.value = null
}

function showPreviousImage2Result() {
  const total = image2Results.value.length
  if (total <= 1) return
  image2ActiveResultIndex.value = (image2ActiveResultIndex.value + total - 1) % total
}

function showNextImage2Result() {
  const total = image2Results.value.length
  if (total <= 1) return
  image2ActiveResultIndex.value = (image2ActiveResultIndex.value + 1) % total
}

function startImage2Swipe(event: PointerEvent) {
  if (!image2HasMultipleResults.value) return
  image2SwipeStartX.value = event.clientX
  image2SwipeStartY.value = event.clientY
}

function finishImage2Swipe(event: PointerEvent) {
  if (!image2HasMultipleResults.value || image2SwipeStartX.value === null || image2SwipeStartY.value === null) return
  const deltaX = event.clientX - image2SwipeStartX.value
  const deltaY = event.clientY - image2SwipeStartY.value
  image2SwipeStartX.value = null
  image2SwipeStartY.value = null
  if (Math.abs(deltaX) < 46 || Math.abs(deltaX) < Math.abs(deltaY) * 1.25) return
  if (deltaX > 0) showPreviousImage2Result()
  else showNextImage2Result()
}

function cancelImage2Swipe() {
  image2SwipeStartX.value = null
  image2SwipeStartY.value = null
}

function formatImage2ResultDetail(image: GaogeDesktopGeneratedLocalImage) {
  const parts = [image.fileName || '生成图片']
  if (image.bytes) parts.push(formatFileSize(image.bytes))
  if (image.path) parts.push(image.path)
  return parts.join(' · ')
}

function formatImage2FailureSummary(result: GaogeDesktopGenerateLocalImageResponse) {
  const failedImages = result.failedImages || []
  const failedCount = Number(result.failedCount || failedImages.length || 0)
  if (!Number.isFinite(failedCount) || failedCount <= 0) return ''
  const firstMessage = failedImages.find((item) => item.message)?.message || ''
  if (firstMessage.includes(IMAGE2_BUSY_MESSAGE)) return IMAGE2_BUSY_MESSAGE
  return firstMessage
    ? `${failedCount} 张失败：${firstMessage}`
    : `${failedCount} 张失败`
}

async function generateImage2Local() {
  image2Error.value = ''
  image2Notice.value = ''
  const outputDir = image2OutputDir.value.trim()
  const prompt = image2Prompt.value.trim()
  if (!outputDir) {
    image2Error.value = '请先选择图片保存路径。'
    return
  }
  if (!prompt) {
    image2Error.value = '请先填写提示词。'
    return
  }
  let parameters: ReturnType<typeof buildImageGenerationParameters>
  try {
    parameters = buildImageGenerationParameters(image2GenerationOptions.value)
  } catch (error) {
    image2Error.value = getImage2GenerationErrorMessage(error)
    return
  }
  if (parameters.mode === 'image' && parameters.referenceImagePaths.length === 0) {
    image2Error.value = '图片编辑模式需要先上传参考图。'
    return
  }
  if (!window.gaogeDesktop?.generateLocalImage) {
    image2Error.value = '当前不是桌面环境，无法执行本地生图。'
    return
  }
  if (isImage2Generating.value) return
  isImage2Generating.value = true
  image2Results.value = []
  image2ActiveResultIndex.value = 0
  image2PreviewImage.value = null
  try {
    const apiKey = await ensureImage2AccessKey()
    const result = await window.gaogeDesktop.generateLocalImage({
      apiKey,
      baseUrl: currentCodexBaseUrl(),
      prompt,
      ...parameters,
      outputDir,
    })
    image2OutputDir.value = result.outputDir || outputDir
    localStorage.setItem(IMAGE2_OUTPUT_DIR_STORAGE_KEY, image2OutputDir.value)
    image2Results.value = result.images || []
    image2ActiveResultIndex.value = 0
    const failureSummary = formatImage2FailureSummary(result)
    if (!image2Results.value.length) {
      image2Error.value = failureSummary
        ? `生图失败，${failureSummary}。`
        : '生图完成，但没有返回可显示的图片。'
      return
    }
    const resultLabel = parameters.outputFormat === 'gif' ? '个动图' : '张图片'
    image2Notice.value = failureSummary
      ? `已生成 ${image2Results.value.length} ${resultLabel}，${failureSummary}。`
      : `已生成 ${image2Results.value.length} ${resultLabel}。`
  } catch (error) {
    reportPageError('image2-local', 'generate-local-image', error, {
      mode: parameters.mode,
      model: parameters.model,
      size: parameters.size,
      quality: parameters.quality,
      outputFormat: parameters.outputFormat,
      complexity: parameters.complexity,
      frameCount: parameters.frameCount,
      frameDurationMs: parameters.frameDurationMs,
      imageCount: parameters.imageCount,
      referenceCount: parameters.referenceImagePaths.length,
    })
    image2Error.value = getImage2GenerationErrorMessage(error)
  } finally {
    isImage2Generating.value = false
  }
}

async function copyText(value: string, label: string) {
  if (!value || value === '未读取') {
    compatibleAccessError.value = `${label} 还没有可复制内容。`
    return
  }
  try {
    await navigator.clipboard.writeText(value)
    compatibleAccessNotice.value = `${label} 已复制。`
  } catch {
    compatibleAccessError.value = `${label} 复制失败，请手动复制。`
  }
}

