async function deleteApiKeyRow(row: ApiKeyRow) {
  apiKeysError.value = ''
  apiKeysNotice.value = ''
  if (!authToken.value) {
    apiKeysError.value = '请先登录账户。'
    return
  }
  if (!(await confirmAction(`删除 Key ${row.name} 后将无法继续使用该凭据，是否继续？`, {
    tone: 'warning',
    title: '删除 Key',
    confirmText: '确认删除',
    cancelText: '取消',
  }))) {
    apiKeysNotice.value = '已取消删除 Key。'
    return
  }
  isApiKeysLoading.value = true
  try {
    await deleteApiKey(row.id, authToken.value)
    const nextVisibleIds = { ...visibleApiKeyIds.value }
    delete nextVisibleIds[row.id]
    visibleApiKeyIds.value = nextVisibleIds
    await loadApiKeys({ silent: true })
    apiKeysNotice.value = `已删除 Key：${row.name}。`
  } catch (error) {
    reportPageError('api-keys', 'delete-api-key', error, { keyId: row.id })
    apiKeysError.value = getApiKeyErrorMessage(error)
  } finally {
    isApiKeysLoading.value = false
  }
}

async function submitCardRedeem() {
  rechargeError.value = ''
  rechargeNotice.value = ''
  activeRechargeFeedback.value = 'card'
  const code = cardRedeemCode.value.trim()
  if (!code) {
    rechargeError.value = '请输入卡密。'
    return
  }
  if (!authToken.value) {
    rechargeError.value = '请先登录账户。'
    return
  }
  isCardRedeeming.value = true
  try {
    const result = await redeemCode(code, authToken.value)
    if (typeof result.new_balance === 'number' && authUser.value) {
      authUser.value = { ...authUser.value, balance: result.new_balance }
    } else {
      await syncCurrentUser()
    }
    cardRedeemCode.value = ''
    rechargeNotice.value = result.message || '兑换成功。'
    void loadRechargeHistory({ silent: true })
  } catch (error) {
    rechargeError.value = getCardRedeemErrorMessage(error)
  } finally {
    isCardRedeeming.value = false
  }
}

function selectRechargeOption(option: RechargeOption) {
  if (isRechargeLoading.value) return
  selectedRechargePlanId.value = option.id || selectedRechargePlanId.value
}

function formatRechargeAmount(amount: number) {
  const value = Number(amount || 0)
  if (!Number.isFinite(value)) return '0'
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/\.?0+$/, '')
}

function getRechargeQuote(planOrAmount: OnlinePaymentPlan | RechargeOption) {
  const payAmount = Number(planOrAmount.payAmount || 0)
  const baseCreditAmount = Number(planOrAmount.baseCreditAmount ?? 0)
  const bonusAmount = Number(planOrAmount.bonusAmount ?? 0)
  const creditAmount = Number(planOrAmount.creditAmount ?? (baseCreditAmount + bonusAmount))
  return {
    creditAmount: Number.isFinite(creditAmount) ? creditAmount : 0,
    baseCreditAmount: Number.isFinite(baseCreditAmount) ? baseCreditAmount : 0,
    bonusAmount: Number.isFinite(bonusAmount) ? bonusAmount : 0,
    payAmount: Number.isFinite(payAmount) ? payAmount : 0,
  }
}

function formatRechargeHistoryAmount(amount: number, signed = false) {
  const value = Number(amount || 0)
  if (!Number.isFinite(value) || value === 0) return '0刀'
  const prefix = signed && value > 0 ? '+' : ''
  return `${prefix}${formatRechargeAmount(Math.abs(value))}刀`
}

function rechargeHistoryStatusClass(status?: string): RechargeHistoryRow['statusClass'] {
  const normalized = String(status || '').toUpperCase()
  if (['COMPLETED', 'SUCCESS', 'SUCCEEDED', 'FINISHED', 'TRADE_SUCCESS', 'USED', 'REDEEMED'].includes(normalized)) return 'success'
  if (['PENDING', 'WAITING', 'CREATED', 'PAID', 'RECHARGING', 'PROCESSING'].includes(normalized)) return 'pending'
  if (['CANCELLED', 'CANCELED', 'EXPIRED', 'FAILED', 'VOIDED'].includes(normalized)) return 'failed'
  return 'neutral'
}

function rechargeHistoryStatusText(status?: string) {
  const normalized = String(status || '').toUpperCase()
  if (['COMPLETED', 'SUCCESS', 'SUCCEEDED', 'FINISHED', 'TRADE_SUCCESS', 'USED', 'REDEEMED'].includes(normalized)) return '成功'
  if (normalized === 'PAID' || normalized === 'RECHARGING' || normalized === 'PROCESSING') return '处理中'
  if (normalized === 'PENDING' || normalized === 'WAITING' || normalized === 'CREATED') return '待支付'
  if (normalized === 'EXPIRED') return '已超时'
  if (normalized === 'CANCELLED' || normalized === 'CANCELED') return '已取消'
  if (normalized === 'FAILED') return '失败'
  if (normalized === 'VOIDED') return '已作废'
  return status || '未知'
}

function getRechargeHistoryCreditAmount(order: PaymentOrder | null) {
  const recordedAmount = getPaymentOrderRechargeAmount(order)
  // Historical credit must come from the order, never today's package or multiplier.
  return Number.isFinite(recordedAmount) && recordedAmount > 0 ? recordedAmount : 0
}

function getRechargeHistoryBonusAmount(order: PaymentOrder) {
  // This safe API field is an applied amount, not the package's promised bonus.
  const amount = order.bonus_amount
  return typeof amount === 'number' && Number.isFinite(amount) && amount > 0 ? amount : 0
}

function toRechargeOrderHistoryRow(order: PaymentOrder): RechargePaymentHistoryRow | null {
  const orderType = String(order.order_type || 'balance').toLowerCase()
  const rechargeAmount = getPaymentOrderAmount(order)
  if (orderType !== 'balance' || !isPaymentCompleted(order.status) || rechargeAmount <= 0) return null
  const rawTime = order.paid_at || order.completed_at || order.updated_at || order.created_at || ''
  const timestamp = parseTimestampMillis(rawTime) || 0
  const bonusAmount = getRechargeHistoryBonusAmount(order)
  return {
    id: `recharge-${getPaymentOrderId(order) || order.out_trade_no || timestamp}`,
    time: formatFullTime(rawTime),
    timestamp,
    rechargeAmount: formatCny(rechargeAmount),
    creditAmount: formatRechargeHistoryAmount(getRechargeHistoryCreditAmount(order), true),
    bonusAmount: bonusAmount > 0 ? formatRechargeHistoryAmount(bonusAmount, true) : '',
    bonusAppliedAt: bonusAmount > 0 && order.bonus_applied_at ? formatFullTime(order.bonus_applied_at) : '',
    status: rechargeHistoryStatusText(order.status),
    statusClass: 'success',
  }
}

function paymentHistorySourceText(order: PaymentOrder) {
  const orderType = String(order.order_type || 'balance').toLowerCase()
  return orderType === 'platform_sub' || orderType === 'subscription' ? '平台订阅' : '在线支付'
}

function toRechargePaymentHistoryRow(order: PaymentOrder): RechargeHistoryRow | null {
  const orderType = String(order.order_type || 'balance').toLowerCase()
  if (!['balance', 'platform_sub', 'subscription'].includes(orderType) || !isPaymentCompleted(order.status)) return null
  const rawTime = order.paid_at || order.completed_at || order.updated_at || order.created_at || ''
  const timestamp = parseTimestampMillis(rawTime) || 0
  const statusClass = rechargeHistoryStatusClass(order.status)
  const credited = getRechargeHistoryCreditAmount(order)
  return {
    id: `payment-${getPaymentOrderId(order) || order.out_trade_no || timestamp}`,
    time: formatFullTime(rawTime),
    timestamp,
    source: paymentHistorySourceText(order),
    added: formatRechargeHistoryAmount(Math.max(0, credited), true),
    deducted: formatRechargeHistoryAmount(0),
    status: rechargeHistoryStatusText(order.status),
    statusClass,
  }
}

function redeemHistorySourceText(item: RedeemHistoryItem, amount: number) {
  const type = String(item.type || '').toLowerCase()
  if (type === 'balance_bonus') return '赠送'
  const metadata = [item.type, item.source, item.code, item.notes, item.idempotency_key]
    .filter(Boolean)
    .join(' ')
    .toLowerCase()
  const isPlatformSubscription = [
    'sub2_balance_recharge',
    'platform-subscription',
    'platform_subscription',
    'platform subscription',
    '平台订阅',
  ].some((marker) => metadata.includes(marker))
  if (isPlatformSubscription) return amount < 0 ? '订阅扣除' : '平台订阅'
  if (type === 'admin_balance') return '后台调整'
  return '卡密兑换'
}

function toRechargeRedeemHistoryRow(item: RedeemHistoryItem): RechargeHistoryRow | null {
  const type = String(item.type || '').toLowerCase()
  const amount = Number(item.value || 0)
  if (!Number.isFinite(amount)) return null
  if (type === 'balance_bonus' && amount <= 0) return null
  const source = redeemHistorySourceText(item, amount)
  if (type && !type.includes('balance') && source !== '平台订阅' && source !== '订阅扣除') return null
  const rawTime = item.used_at || item.created_at || ''
  const timestamp = parseTimestampMillis(rawTime) || 0
  const added = Math.max(0, amount)
  const deducted = Math.max(0, -amount)
  const status = item.status || 'used'
  const statusClass = rechargeHistoryStatusClass(status)
  if (statusClass !== 'success') return null
  return {
    id: `redeem-${item.id || item.code || timestamp}`,
    time: formatFullTime(rawTime),
    timestamp,
    source,
    ...(type === 'balance_bonus' ? { kind: 'bonus' as const } : {}),
    added: formatRechargeHistoryAmount(added, true),
    deducted: formatRechargeHistoryAmount(deducted),
    status: rechargeHistoryStatusText(status),
    statusClass,
  }
}

function getRechargeHistoryDateBoundary(value: string, endExclusive = false) {
  const [year, month, day] = value.split('-').map(Number)
  if (!year || !month || !day) return null
  const boundary = new Date(year, month - 1, day)
  if (endExclusive) boundary.setDate(boundary.getDate() + 1)
  return boundary.getTime()
}

function isRechargeHistoryTimestampInRange(timestamp: number) {
  if (!rechargeHistoryStartDate.value && !rechargeHistoryEndDate.value) return true
  if (!timestamp) return false
  const start = rechargeHistoryStartDate.value
    ? getRechargeHistoryDateBoundary(rechargeHistoryStartDate.value)
    : null
  const end = rechargeHistoryEndDate.value
    ? getRechargeHistoryDateBoundary(rechargeHistoryEndDate.value, true)
    : null
  return (start === null || timestamp >= start) && (end === null || timestamp < end)
}

function selectRechargeHistoryTab(tab: RechargeHistoryTab) {
  activeRechargeHistoryTab.value = tab
  rechargeHistoryPage.value = 1
}

function applyRechargeHistoryDateFilter() {
  rechargeHistoryPage.value = 1
}

function clearRechargeHistoryDateFilter() {
  rechargeHistoryStartDate.value = ''
  rechargeHistoryEndDate.value = ''
  rechargeHistoryPage.value = 1
}

function changeRechargeHistoryPageSize() {
  rechargeHistoryPage.value = 1
}

function goRechargeHistoryPage(page: number) {
  rechargeHistoryPage.value = Math.min(Math.max(page, 1), rechargeHistoryPages.value)
}

function selectInvoiceRecordTab(tab: InvoiceRecordTab) {
  activeInvoiceRecordTab.value = tab
}

function changeInvoiceAvailablePageSize() {
  invoiceAvailablePage.value = 1
}

function changeInvoiceIssuedPageSize() {
  invoiceIssuedPage.value = 1
}

function goInvoiceAvailablePage(page: number) {
  invoiceAvailablePage.value = Math.min(Math.max(page, 1), invoiceAvailablePages.value)
}

function goInvoiceIssuedPage(page: number) {
  invoiceIssuedPage.value = Math.min(Math.max(page, 1), invoiceIssuedPages.value)
}

function togglePagedInvoiceOrders() {
  const pageIds = pagedInvoiceAvailableOrders.value.map((order) => order.id)
  if (!pageIds.length) return
  const pageIdSet = new Set(pageIds)
  if (areAllPagedInvoiceOrdersSelected.value) {
    invoiceSelectedOrderIds.value = invoiceSelectedOrderIds.value.filter((orderId) => !pageIdSet.has(orderId))
    return
  }
  invoiceSelectedOrderIds.value = Array.from(new Set([...invoiceSelectedOrderIds.value, ...pageIds]))
}

function buildOnlinePaymentSnapshot(option: RechargeOption, quote = getRechargeQuote(option)): OnlinePaymentSnapshot {
  return {
    planId: option.id,
    payAmount: Number(quote.payAmount.toFixed(2)),
    baseCreditAmount: Number(quote.baseCreditAmount.toFixed(2)),
    bonusAmount: Number(quote.bonusAmount.toFixed(2)),
    totalCreditAmount: Number(quote.creditAmount.toFixed(2)),
    multiplier: onlinePaymentConfig.value?.balanceRechargeMultiplier,
    createdAt: new Date().toISOString(),
  }
}

function getOnlinePaymentRequestContext() {
  const config = getRuntimeDomainConfig()
  return JSON.stringify([authToken.value, config.selectedServerId, config.softwareAdminApiBaseUrl, config.apiBaseUrl])
}

function invalidateOnlinePaymentConfig() {
  onlinePaymentConfigRequestGeneration += 1
  onlinePaymentConfigRequest = null
  onlinePaymentConfig.value = null
  selectedRechargePlanId.value = ''
  onlinePaymentConfigError.value = ''
  isOnlinePaymentConfigLoading.value = false
}

async function loadOnlinePaymentConfig(options: { silent?: boolean; force?: boolean } = {}): Promise<OnlinePaymentConfig | null> {
  if (!authToken.value) {
    invalidateOnlinePaymentConfig()
    return null
  }
  const context = getOnlinePaymentRequestContext()
  const requestToken = authToken.value
  if (!options.force && onlinePaymentConfigRequest?.context === context) {
    return onlinePaymentConfigRequest.promise
  }
  const generation = ++onlinePaymentConfigRequestGeneration
  const isCurrentRequest = () => generation === onlinePaymentConfigRequestGeneration && context === getOnlinePaymentRequestContext()
  isOnlinePaymentConfigLoading.value = true
  onlinePaymentConfigError.value = ''
  const promise = Promise.resolve().then(async () => {
    try {
      const response = await getOnlinePaymentConfigFromSoftwareAdmin(requestToken)
      if (!isCurrentRequest()) return null
      const config = requireOnlinePaymentConfig(response)
      onlinePaymentConfig.value = config
      if (!config.plans.some((plan) => plan.id === selectedRechargePlanId.value)) {
        selectedRechargePlanId.value = config.plans[0]?.id || ''
      }
      return config
    } catch (error) {
      if (!isCurrentRequest()) return null
      onlinePaymentConfig.value = null
      selectedRechargePlanId.value = ''
      onlinePaymentConfigError.value = `在线支付配置读取失败：${getErrorMessage(error)}`
      if (!options.silent) reportPageError('payment', 'load-online-payment-config', error)
      return null
    } finally {
      if (isCurrentRequest()) {
        isOnlinePaymentConfigLoading.value = false
        onlinePaymentConfigRequest = null
      }
    }
  })
  onlinePaymentConfigRequest = { context, promise }
  return promise
}

async function listAllPaymentOrders(orderType?: string, token = authToken.value) {
  const pageSize = 100
  const orders: PaymentOrder[] = []
  let page = 1
  let pages = 1
  do {
    const response = await listPaymentOrders(token, { page, pageSize, orderType })
    const items = Array.isArray(response.items) ? response.items : []
    orders.push(...items)
    pages = Math.max(1, Number(response.pages || Math.ceil(Number(response.total || 0) / pageSize) || 1))
    page += 1
    if (!items.length) break
  } while (page <= pages)
  return orders
}

async function loadRechargeHistory(options: { silent?: boolean } = {}) {
  const generation = ++rechargeHistoryRequestGeneration
  const token = authToken.value
  const context = getOnlinePaymentRequestContext()
  if (!token) {
    rechargeHistoryOrders.value = []
    rechargeHistoryRedeems.value = []
    rechargeHistoryError.value = '请先登录账户。'
    isRechargeHistoryLoading.value = false
    return
  }
  if (!options.silent) {
    isRechargeHistoryLoading.value = true
    rechargeHistoryError.value = ''
  }
  try {
    const [paymentResult, platformSubscriptionResult, redeemResult] = await Promise.allSettled([
      listAllPaymentOrders('balance', token),
      listAllPaymentOrders('platform_sub', token),
      listRedeemHistory(token, { includeBalanceBonus: true }),
    ])
    // A pre-settlement refresh must not overwrite a newer response containing the gift.
    if (generation !== rechargeHistoryRequestGeneration || context !== getOnlinePaymentRequestContext()) return
    const errors: string[] = []
    const paymentOrders: PaymentOrder[] = []
    if (paymentResult.status === 'fulfilled') {
      paymentOrders.push(...paymentResult.value)
    } else {
      errors.push('在线支付记录读取失败')
      reportPageError('payment', 'load-payment-history', paymentResult.reason)
    }
    if (platformSubscriptionResult.status === 'fulfilled') {
      paymentOrders.push(...platformSubscriptionResult.value)
    } else {
      errors.push('平台订阅记录读取失败')
      reportPageError('payment', 'load-platform-subscription-payment-history', platformSubscriptionResult.reason)
    }
    rechargeHistoryOrders.value = paymentOrders.filter((order) => isPaymentCompleted(order.status))
    if (redeemResult.status === 'fulfilled') {
      rechargeHistoryRedeems.value = Array.isArray(redeemResult.value) ? redeemResult.value : []
    } else {
      rechargeHistoryRedeems.value = []
      errors.push('卡密兑换记录读取失败')
      reportPageError('payment', 'load-redeem-history', redeemResult.reason)
    }
    rechargeHistoryError.value = errors.join('，')
  } finally {
    if (generation === rechargeHistoryRequestGeneration) {
      isRechargeHistoryLoading.value = false
    }
  }
}

function isOnlinePaymentPage(page = activePage.value) {
  return page === '在线充值-兑换'
}

async function refreshOnlinePaymentConfigInBackground() {
  if (!isOnlinePaymentPage() || isRechargeLoading.value) return
  await loadOnlinePaymentConfig({ silent: true })
}

function startOnlinePaymentConfigRefresh() {
  if (!isOnlinePaymentPage()) return
  void refreshOnlinePaymentConfigInBackground()
  if (onlinePaymentConfigRefreshTimer !== null) return
  onlinePaymentConfigRefreshTimer = window.setInterval(() => {
    void refreshOnlinePaymentConfigInBackground()
  }, ONLINE_PAYMENT_CONFIG_REFRESH_INTERVAL_MS)
}

function stopOnlinePaymentConfigRefresh() {
  if (onlinePaymentConfigRefreshTimer === null) return
  window.clearInterval(onlinePaymentConfigRefreshTimer)
  onlinePaymentConfigRefreshTimer = null
}

function waitForRechargeBonusRetry(delayMs: number) {
  return new Promise<void>((resolve) => window.setTimeout(resolve, delayMs))
}

function isRechargeBonusRetryableError(error: unknown) {
  const status = Number((error as ApiError)?.status)
  return isNetworkOrTimeoutError(error) ||
    !Number.isFinite(status) ||
    status === 408 ||
    status === 425 ||
    status === 429 ||
    status >= 500
}

function getRechargeBonusBackgroundRetryDelay(attempts: number) {
  const backgroundAttempt = Math.max(0, attempts - RECHARGE_BONUS_IMMEDIATE_RETRY_DELAYS_MS.length)
  return Math.min(
    RECHARGE_BONUS_BACKGROUND_RETRY_MAX_MS,
    RECHARGE_BONUS_BACKGROUND_RETRY_BASE_MS * (2 ** backgroundAttempt),
  )
}

function recordRechargeBonusFailure(job: PendingRechargeBonusJob, error: unknown, retryable: boolean) {
  const latest = findPendingRechargeBonusJob(job.orderId) || job
  const attempts = latest.attempts + 1
  return updatePendingRechargeBonusJob(latest, {
    attempts,
    nextRetryAt: Date.now() + getRechargeBonusBackgroundRetryDelay(attempts),
    autoRetry: retryable,
    lastAttemptAt: new Date().toISOString(),
    lastError: getPaymentErrorMessage(error),
  }) || latest
}

async function executeRechargeBonusJob(
  initialJob: PendingRechargeBonusJob,
  retryDelays: readonly number[],
) {
  let job = findPendingRechargeBonusJob(initialJob.orderId) || initialJob
  let lastError: unknown = null

  for (let index = 0; index < retryDelays.length; index += 1) {
    const delayMs = retryDelays[index]
    if (delayMs > 0) await waitForRechargeBonusRetry(delayMs)
    if (!authToken.value) throw new Error('请先登录账户。')

    try {
      const result = await applyOnlinePaymentBonus({
        sub2OrderId: job.orderId,
        planId: job.planId,
        snapshot: job.snapshot,
        userId: authUser.value?.id,
        email: authUser.value?.email || user.value.email,
        username: authUser.value?.username || user.value.name,
      }, authToken.value)
      removePendingRechargeBonusJob(job.orderId)
      return result
    } catch (error) {
      lastError = error
      const retryable = isRechargeBonusRetryableError(error)
      job = recordRechargeBonusFailure(job, error, retryable)
      reportPageError('payment', 'apply-online-payment-bonus', error, {
        orderId: job.orderId,
        planId: job.planId,
        attempt: job.attempts,
        retryable,
      })
      if (!retryable || index >= retryDelays.length - 1) break

      if (getPaymentOrderId(activePaymentOrder.value) === job.orderId) {
        rechargeError.value = ''
        rechargeNotice.value = `支付已完成，基础额度已到账；赠送额度正在自动重试（${index + 2}/${retryDelays.length}）。`
      }
    }
  }

  schedulePendingRechargeBonusRetry()
  throw lastError || new Error('赠送额度暂未确认。')
}

function runRechargeBonusJob(
  job: PendingRechargeBonusJob,
  retryDelays: readonly number[] = [0],
) {
  const existing = rechargeBonusOrderPromises.get(job.orderId)
  if (existing) return existing
  const promise = executeRechargeBonusJob(job, retryDelays).finally(() => {
    rechargeBonusOrderPromises.delete(job.orderId)
    schedulePendingRechargeBonusRetry()
  })
  rechargeBonusOrderPromises.set(job.orderId, promise)
  return promise
}

async function applyRechargeBonusForOrder(order: PaymentOrder | null) {
  const orderId = getPaymentOrderId(order)
  if (!orderId || !authToken.value) return null
  let job = findPendingRechargeBonusJob(orderId)
  if (!job && activeRechargeSnapshot.value) {
    job = enqueuePendingRechargeBonusJob(orderId, activeRechargeSnapshot.value)
  }
  if (!job) return null
  return runRechargeBonusJob(job, RECHARGE_BONUS_IMMEDIATE_RETRY_DELAYS_MS)
}

function stopPendingRechargeBonusRetryTimer() {
  if (rechargeBonusRetryTimer === null) return
  window.clearTimeout(rechargeBonusRetryTimer)
  rechargeBonusRetryTimer = null
}

function schedulePendingRechargeBonusRetry() {
  stopPendingRechargeBonusRetryTimer()
  if (!authToken.value || !isNewThemeAuthenticated.value) return
  const jobs = readPendingRechargeBonusJobs().filter((job) => job.autoRetry)
  if (!jobs.length) return
  const nextRetryAt = Math.min(...jobs.map((job) => job.nextRetryAt))
  const delayMs = Math.max(500, Math.min(RECHARGE_BONUS_BACKGROUND_RETRY_MAX_MS, nextRetryAt - Date.now()))
  rechargeBonusRetryTimer = window.setTimeout(() => {
    rechargeBonusRetryTimer = null
    void resumePendingRechargeBonusQueue()
  }, delayMs)
}

async function resumePendingRechargeBonusQueue(options: { force?: boolean; includeBlocked?: boolean } = {}) {
  if (rechargeBonusQueueProcessing || !authToken.value || !isNewThemeAuthenticated.value) return
  stopPendingRechargeBonusRetryTimer()
  rechargeBonusQueueProcessing = true
  try {
    const now = Date.now()
    const jobs = readPendingRechargeBonusJobs()
      .filter((job) => (job.autoRetry || options.includeBlocked) && (options.force || job.nextRetryAt <= now))
    for (const storedJob of jobs) {
      let job = findPendingRechargeBonusJob(storedJob.orderId)
      if (!job) continue
      let bonusAttempted = false
      try {
        const order = await getPaymentOrder(job.orderId, authToken.value)
        if (isBackupBridgePaymentOrder(order) || isPaymentClosed(order.status)) {
          removePendingRechargeBonusJob(job.orderId)
          continue
        }
        if (!isPaymentCompleted(order.status)) {
          updatePendingRechargeBonusJob(job, {
            nextRetryAt: Date.now() + RECHARGE_BONUS_PENDING_PAYMENT_RETRY_MS,
            autoRetry: true,
          })
          continue
        }

        bonusAttempted = true
        const result = await runRechargeBonusJob(job)
        await Promise.allSettled([
          syncCurrentUser({ silent: true }),
          syncUsageDashboardStats({ silent: true }),
        ])
        if (result?.applied) {
          const bonusAmount = Number(result.record?.bonusAmount || job.snapshot.bonusAmount || 0)
          notify(`订单 ${job.orderId} 的 ${formatRechargeAmount(bonusAmount)} 刀赠送额度已自动到账。`, 'success', '赠送已补发')
        }
        if (isOnlinePaymentPage()) {
          rechargeError.value = ''
          rechargeNotice.value = result?.applied
            ? '此前待确认的赠送额度已自动到账。'
            : '此前待确认的赠送额度已完成核对。'
          await loadRechargeHistory({ silent: true })
        }
      } catch (error) {
        if (bonusAttempted) continue
        job = findPendingRechargeBonusJob(job.orderId) || job
        const retryable = isRechargeBonusRetryableError(error)
        job = recordRechargeBonusFailure(job, error, retryable)
        reportPageError('payment', 'resume-online-payment-bonus', error, {
          orderId: job.orderId,
          planId: job.planId,
          attempt: job.attempts,
          retryable,
        })
      }
    }
  } finally {
    rechargeBonusQueueProcessing = false
    schedulePendingRechargeBonusRetry()
  }
}

function getPaymentOrderId(order: PaymentOrder | null) {
  return Number(order?.order_id || order?.id || 0)
}

function getPaymentOrderAmount(order: PaymentOrder | null) {
  if (!order) return 0
  return Number(order.pay_amount ?? order.amount ?? 0) || 0
}

function getPaymentOrderRechargeAmount(order: PaymentOrder | null, fallback = 0) {
  if (!order) return Number(fallback || 0) || 0
  return Number(order.amount ?? fallback ?? 0) || 0
}

function buildPlatformSubscriptionPaymentSnapshot(
  order: PaymentOrder | null,
  plan: PlatformSubscriptionPlan,
  previous?: PlatformSubscriptionPaymentSnapshot | null,
): PlatformSubscriptionPaymentSnapshot {
  const orderId = getPaymentOrderId(order) || previous?.sub2_order_id || ''
  const rechargeAmount = getPaymentOrderRechargeAmount(order, previous?.sub2_recharge_amount || plan.priceAmount)
  return {
    sub2_order_id: orderId,
    sub2_out_trade_no: order?.out_trade_no || previous?.sub2_out_trade_no || '',
    sub2_order_type: order?.order_type || previous?.sub2_order_type || 'platform_sub',
    sub2_recharge_amount: rechargeAmount,
    sub2_pay_amount: getPaymentOrderAmount(order) || previous?.sub2_pay_amount || plan.priceAmount,
    sub2_payment_status: order?.status || previous?.sub2_payment_status || '',
    paid_at: order?.paid_at || previous?.paid_at || null,
    completed_at: order?.completed_at || previous?.completed_at || null,
  }
}

function buildPlatformSubscriptionBalanceDeductionRequest(
  snapshot: PlatformSubscriptionPaymentSnapshot,
  plan: PlatformSubscriptionPlan,
  previous?: PlatformSubscriptionBalanceDeductionRequest | null,
): PlatformSubscriptionBalanceDeductionRequest | undefined {
  if (String(snapshot.sub2_order_type || '').trim().toLowerCase() !== 'balance') return undefined
  const orderId = String(snapshot.sub2_order_id || '').trim()
  const amount = Number(snapshot.sub2_recharge_amount || previous?.amount || 0)
  if (!orderId || !Number.isFinite(amount) || amount <= 0) return previous || undefined
  return {
    enabled: true,
    amount,
    source: 'sub2_balance_recharge',
    idempotency_key: previous?.idempotency_key || `platform-subscription-balance-deduction:${orderId}`,
    notes: previous?.notes || `平台订阅订单 ${orderId} 支付成功后扣回在线充值余额，用于开通 ${plan.name}`,
  }
}

function getActivePlatformSubscriptionPlanId() {
  return String(
    (activePlatformSubscription.value as (ActiveSubscription & { plan_id?: string }) | null)?.plan_id ||
    (activePlatformSubscriptionSummaryItem.value as (SubscriptionSummaryItem & { plan_id?: string }) | null)?.plan_id ||
    activePlatformSubscriptionPlan.value?.id ||
    '',
  ).trim()
}

function getActivePlatformSubscriptionId() {
  return (
    activePlatformSubscription.value?.id ||
    activePlatformSubscriptionSummaryItem.value?.id ||
    undefined
  )
}

function getActivePlatformSubscriptionGroupId() {
  return (
    getSubscriptionGroupId(activePlatformSubscription.value) ||
    Number(activePlatformSubscriptionSummaryItem.value?.group_id || 0) ||
    activePlatformSubscriptionPlan.value?.groupId ||
    undefined
  )
}

function isSamePlatformSubscriptionPlan(plan: PlatformSubscriptionPlan) {
  const activePlanId = getActivePlatformSubscriptionPlanId()
  if (activePlanId && plan.id) return activePlanId === plan.id
  const activeGroupId = Number(getActivePlatformSubscriptionGroupId() || 0)
  return Boolean(activeGroupId && plan.groupId && activeGroupId === Number(plan.groupId))
}

function buildPlatformSubscriptionActionContext(plan: PlatformSubscriptionPlan): PlatformSubscriptionActionContext {
  const currentSubscriptionId = getActivePlatformSubscriptionId()
  const currentPlanId = getActivePlatformSubscriptionPlanId()
  const currentPlanName = activePlatformSubscriptionName.value !== '暂无平台订阅'
    ? activePlatformSubscriptionName.value
    : undefined
  const currentGroupId = getActivePlatformSubscriptionGroupId()
  const hasActiveSubscription = Boolean(activePlatformSubscription.value || activePlatformSubscriptionSummaryItem.value)
  const subscriptionAction: PlatformSubscriptionAction = hasActiveSubscription && !isSamePlatformSubscriptionPlan(plan)
    ? 'replace'
    : 'renew'

  return {
    subscription_action: subscriptionAction,
    ...(currentSubscriptionId ? { current_subscription_id: currentSubscriptionId } : {}),
    ...(currentPlanId ? { current_plan_id: currentPlanId } : {}),
    ...(currentPlanName ? { current_plan_name: currentPlanName } : {}),
    ...(currentGroupId ? { current_group_id: currentGroupId } : {}),
    target_plan_id: plan.id,
    target_plan_name: plan.name,
    ...(plan.groupId ? { target_group_id: plan.groupId } : {}),
  }
}

function buildPlatformSubscriptionActivationRequest(
  order: PaymentOrder | null,
  plan: PlatformSubscriptionPlan,
  previous: PlatformSubscriptionActivationRequest | null = activePlatformSubscriptionActivationRequest.value,
  actionContext?: PlatformSubscriptionActionContext,
): PlatformSubscriptionActivationRequest {
  const payment = buildPlatformSubscriptionPaymentSnapshot(order, plan, previous?.payment)
  const balanceDeduction = buildPlatformSubscriptionBalanceDeductionRequest(payment, plan, previous?.balance_deduction)
  const context = actionContext || {
    subscription_action: previous?.subscription_action || 'renew',
    ...(previous?.current_subscription_id ? { current_subscription_id: previous.current_subscription_id } : {}),
    ...(previous?.current_plan_id ? { current_plan_id: previous.current_plan_id } : {}),
    ...(previous?.current_plan_name ? { current_plan_name: previous.current_plan_name } : {}),
    ...(previous?.current_group_id ? { current_group_id: previous.current_group_id } : {}),
    target_plan_id: previous?.target_plan_id || plan.id,
    target_plan_name: previous?.target_plan_name || plan.name,
    ...(previous?.target_group_id ? { target_group_id: previous.target_group_id } : plan.groupId ? { target_group_id: plan.groupId } : {}),
  }
  return {
    payment,
    ...context,
    ...(balanceDeduction ? { balance_deduction: balanceDeduction } : {}),
  }
}

function getPaymentOrderTime(order: PaymentOrder | null) {
  if (!order) return ''
  return order.paid_at || order.completed_at || order.updated_at || order.created_at || new Date().toISOString()
}

function normalizeOfficialSubscriptionProgress(value: unknown): OfficialSubscriptionProgress {
  const normalized = String(value || '').trim().toLowerCase()
  return ['completed', 'complete', 'done', 'success', 'succeeded', 'finished', '已完成'].includes(normalized)
    ? 'completed'
    : 'subscribing'
}

function officialSubscriptionProgressText(progress: OfficialSubscriptionProgress) {
  return progress === 'completed' ? '已完成' : '订阅中'
}

function normalizeOfficialPlanKey(value: unknown) {
  return normalizeOfficialSubscriptionPlan(value)
}

function findOfficialPlanByAmount(amount: number) {
  return officialSubscriptionPlans.value.find((plan) => Number(plan.localPrice) === Number(amount)) || null
}

function normalizeOfficialSubscriptionPriceKey(value: unknown) {
  return normalizeOfficialSubscriptionPlan(value)
}

function formatOfficialLocalPriceAmount(value: unknown) {
  const amount = Number(value)
  if (!Number.isFinite(amount) || amount <= 0) return ''
  return Number.isInteger(amount) ? amount.toFixed(0) : amount.toFixed(2)
}

function applyOfficialSubscriptionPrices(prices: OfficialSubscriptionPricePlan[]) {
  const priceMap = new Map<string, OfficialSubscriptionPricePlan>()
  ;(Array.isArray(prices) ? prices : []).forEach((price) => {
    const keys = [
      price.id,
      price.planId,
      price.name,
      price.planName,
    ].map(normalizeOfficialSubscriptionPriceKey).filter(Boolean)
    keys.forEach((key) => priceMap.set(key, price))
  })

  officialSubscriptionPlans.value = defaultOfficialSubscriptionPlans.map((plan) => {
    const price = priceMap.get(normalizeOfficialSubscriptionPriceKey(plan.id)) ||
      priceMap.get(normalizeOfficialSubscriptionPriceKey(plan.name))
    const localPrice = formatOfficialLocalPriceAmount(price?.amount)
    if (!price || !localPrice) return plan
    return {
      ...plan,
      localPrice,
      officialPrice: price.officialPrice || plan.officialPrice,
    }
  })
}

async function loadOfficialSubscriptionPrices() {
  try {
    const prices = await getOfficialSubscriptionPrices(authToken.value)
    applyOfficialSubscriptionPrices(prices)
  } catch (error) {
    applyOfficialSubscriptionPrices([])
    reportPageError('official-subscription', 'load-official-subscription-prices', error)
  }
}

function isOfficialSubscriptionPage(page = activePage.value) {
  return page === '官方订阅' || page === '官方订阅信息'
}

async function refreshOfficialSubscriptionPricesInBackground() {
  if (!isOfficialSubscriptionPage() || officialSubscriptionPriceRefreshInFlight) return
  officialSubscriptionPriceRefreshInFlight = true
  try {
    await loadOfficialSubscriptionPrices()
  } finally {
    officialSubscriptionPriceRefreshInFlight = false
  }
}

function startOfficialSubscriptionPriceRefresh() {
  if (!isOfficialSubscriptionPage()) return
  void refreshOfficialSubscriptionPricesInBackground()
  if (officialSubscriptionPriceRefreshTimer !== null) return
  officialSubscriptionPriceRefreshTimer = window.setInterval(() => {
    void refreshOfficialSubscriptionPricesInBackground()
  }, OFFICIAL_SUBSCRIPTION_PRICE_REFRESH_INTERVAL_MS)
}

function stopOfficialSubscriptionPriceRefresh() {
  if (officialSubscriptionPriceRefreshTimer === null) return
  window.clearInterval(officialSubscriptionPriceRefreshTimer)
  officialSubscriptionPriceRefreshTimer = null
}

function platformPlanToneFor(plan: PlatformSubscriptionPlanConfig, index: number): PlatformSubscriptionPlan['tone'] {
  const id = String(plan.id || '').toLowerCase()
  if (id.includes('diamond')) return 'diamond'
  if (id.includes('gold')) return 'gold'
  if (id.includes('silver')) return 'silver'
  if (id.includes('bronze')) return 'bronze'
  return (['bronze', 'silver', 'gold', 'diamond'] as const)[Math.min(index, 3)]
}

function formatPlatformPlanNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/\.?0+$/, '')
}

function normalizePlatformPlanConfig(
  plan: PlatformSubscriptionPlanConfig,
  index: number,
): PlatformSubscriptionPlan | null {
  const id = String(plan.id || '').trim()
  const name = String(plan.name || '').trim()
  const priceAmount = toFiniteMoney(plan.priceAmount, Number.NaN)
  const dailyLimitUsd = toFiniteMoney(plan.dailyLimitUsd, Number.NaN)
  const subscriptionDays = Math.max(1, Math.floor(Number(plan.subscriptionDays || 30)))
  if (!id || !name || !Number.isFinite(priceAmount) || priceAmount <= 0 || !Number.isFinite(dailyLimitUsd) || dailyLimitUsd <= 0) {
    return null
  }
  const fallback = defaultPlatformSubscriptionPlans.find((item) => item.id === id) || defaultPlatformSubscriptionPlans[index]
  const dailyQuota = String(plan.dailyQuota || '').trim() || `每日 ${formatPlatformPlanNumber(dailyLimitUsd)} 刀`
  return {
    id,
    name,
    badge: String(plan.badge || fallback?.badge || '平台订阅'),
    dailyQuota,
    dailyLimitUsd,
    price: String(plan.price || formatPlatformPlanNumber(priceAmount)),
    priceAmount,
    subscriptionDays,
    version: Number(plan.version || 1),
    tagline: fallback?.tagline || '适合希望按日控制 GPT 使用额度的用户。',
    description: String(plan.description || fallback?.description || `开通后每日自动获得 ${formatPlatformPlanNumber(dailyLimitUsd)} 刀平台额度，可自由选择可用分组。`),
    highlights: fallback?.highlights?.length
      ? fallback.highlights
      : [dailyQuota, `${subscriptionDays} 天有效期`, '可自由选择分组'],
    tone: fallback?.tone || platformPlanToneFor(plan, index),
    featured: fallback?.featured || index === 1,
  }
}

function applyPlatformSubscriptionPlans(plans: PlatformSubscriptionPlanConfig[]) {
  const normalized = Array.isArray(plans)
    ? plans.map((plan, index) => normalizePlatformPlanConfig(plan, index)).filter((plan): plan is PlatformSubscriptionPlan => Boolean(plan))
    : []
  if (!normalized.length) return
  platformSubscriptionPlans.value = normalized
  if (!platformSubscriptionPlans.value.some((plan) => plan.id === selectedPlatformPlanId.value)) {
    selectedPlatformPlanId.value = platformSubscriptionPlans.value[0]?.id || ''
  }
}

async function loadPlatformSubscriptionPlans() {
  try {
    const plans = await getPlatformSubscriptionPlansFromSoftwareAdmin(authToken.value)
    applyPlatformSubscriptionPlans(plans)
  } catch (error) {
    reportPageError('platform-subscription', 'load-platform-subscription-plans', error)
  }
}

function normalizeOfficialSubscriptionRecord(value: unknown): OfficialSubscriptionRecord | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<OfficialSubscriptionRecord> & Record<string, unknown>
  const orderId = String(source.orderId || source.id || '').trim()
  const planName = String(source.planName || '').trim()
  const account = String(source.account || '').trim()
  const amount = Number(source.amount)
  const paidAt = String(source.paidAt || '').trim()
  if (!orderId || !planName || !account || !paidAt || source.amount == null || !Number.isFinite(amount) || amount < 0) return null
  const now = new Date().toISOString()
  return {
    id: String(source.id || `official-sub-${orderId}`),
    orderId,
    orderNo: String(source.orderNo || orderId),
    planId: String(source.planId || normalizeOfficialPlanKey(planName)),
    planName,
    amount,
    account,
    accountKey: String(source.accountKey || ''),
    paidAt,
    progress: normalizeOfficialSubscriptionProgress(source.progress),
    hasSessionText: typeof source.hasSessionText === 'boolean' ? source.hasSessionText : undefined,
    createdAt: String(source.createdAt || paidAt || now),
    updatedAt: String(source.updatedAt || source.createdAt || paidAt || now),
  }
}

function loadOfficialSubscriptionRecords() {
  officialSubscriptionRecords.value = readStoredInvoiceArray(
    OFFICIAL_SUBSCRIPTION_RECORDS_STORAGE_KEY,
    normalizeOfficialSubscriptionRecord,
  )
  syncOfficialSubscriptionRecordsFromAccounts()
}

function saveOfficialSubscriptionRecords() {
  writeStoredInvoiceArray(OFFICIAL_SUBSCRIPTION_RECORDS_STORAGE_KEY, officialSubscriptionRecords.value)
}

function officialSubscriptionRecordRank(record: OfficialSubscriptionRecord) {
  const progressRank = record.progress === 'completed' ? 1_000_000_000_000_000 : 0
  return progressRank + (new Date(record.updatedAt || record.paidAt || record.createdAt).getTime() || 0)
}

function mergeOfficialSubscriptionRecords(nextRecords: OfficialSubscriptionRecord[]) {
  if (!nextRecords.length) return
  const recordMap = new Map<string, OfficialSubscriptionRecord>()
  ;[...officialSubscriptionRecords.value, ...nextRecords].forEach((record) => {
    const key = record.orderId || record.id
    const current = recordMap.get(key)
    if (!current || (record.hasSessionText === false && record.progress !== 'completed')
      || officialSubscriptionRecordRank(record) >= officialSubscriptionRecordRank(current)) {
      recordMap.set(key, record)
    } else if (typeof record.hasSessionText === 'boolean') {
      // A locally inferred completion must not hide the server's missing-data flag.
      recordMap.set(key, { ...current, hasSessionText: record.hasSessionText })
    }
  })
  officialSubscriptionRecords.value = Array.from(recordMap.values())
    .sort((left, right) => new Date(right.paidAt || right.updatedAt).getTime() - new Date(left.paidAt || left.updatedAt).getTime())
    .slice(0, 100)
  syncOfficialSubscriptionRecordsFromAccounts({ save: false })
  saveOfficialSubscriptionRecords()
}

function createOfficialSubscriptionRequestContext(
  plan: OfficialSubscriptionPlan,
  account: OfficialIdentifiedAccount,
  amount = Number(plan.localPrice),
): OfficialSubscriptionRequestContext {
  return {
    ownerId: String(authUser.value?.id || ''),
    idempotencyKey: `desktop-official:${Date.now()}-${getRandomText(16)}`,
    planId: plan.id,
    planName: plan.name,
    amount,
    account: account.email || account.displayName || '未命名账号',
    accountKey: account.accountKey,
    sessionJson: account.sessionJson,
    sessionSource: account.sessionSource,
    sessionUrl: account.sessionUrl,
  }
}

async function submitOfficialSubscriptionSessionForOrder(order: PaymentOrder | null) {
  const context = activeOfficialSubscriptionRequest.value
  const orderId = getPaymentOrderId(order)
  const token = authToken.value
  const owner = officialSubscriptionOwnerParams()
  if (!order || !orderId || !token || !owner.userId) return false
  if (order.official_session_saved === true) return true
  if (!context || context.orderId !== orderId || context.ownerId !== owner.userId) return false
  if (!context.sessionJson.trim()) return false
  const isCurrentRequest = () => authToken.value === token
    && String(authUser.value?.id || '') === owner.userId
    && activeOfficialSubscriptionRequest.value === context
  const orderNo = String(order.out_trade_no || order.order_id || order.id || orderId)
  const paidAt = order.paid_at || order.completed_at || getPaymentOrderTime(order) || null
  const paymentStatus = order.status || 'paid'
  const accepted = await deliverOfficialSubscriptionSession(
    () => submitOfficialSubscriptionSession(orderId, {
      plan_id: context.planId,
      plan_name: context.planName,
      account_email: context.account,
      account_key: context.accountKey,
      session_json: context.sessionJson,
      session_source: context.sessionSource,
      session_url: context.sessionUrl,
      order_no: orderNo,
      paid_at: paidAt,
    }, token),
    () => {
      if (!isCurrentRequest()) return Promise.resolve(null)
      return submitOfficialSubscriptionToSoftwareAdmin({
        userId: owner.userId,
        user: context.account || owner.email,
        email: context.account || owner.email,
        username: owner.username,
        planId: context.planId,
        planName: context.planName,
        source: 'online-payment',
        orderId: String(orderId),
        orderNo,
        clientOrderId: String(orderId),
        paymentStatus,
        amount: getPaymentOrderAmount(order),
        currency: 'CNY',
        sessionText: context.sessionJson,
        clientVersion: updateVersionText.value,
        platform: typeof navigator !== 'undefined' ? navigator.platform : '',
        note: `官方订阅在线支付订单 ${orderNo}`,
        paymentMethod: 'online-payment',
        paymentInfo: {
          paid: true,
          status: paymentStatus,
          order_type: order.order_type || 'official_sub',
          out_trade_no: order.out_trade_no || orderNo,
        },
        paidAt,
      }, token)
    },
  )
  if (!isCurrentRequest()) return false
  if (accepted) rememberOfficialSubscriptionReceipt(order, context)
  return accepted
}

function pendingOfficialSubscriptionReceipts(): OfficialSubscriptionReceipt[] {
  const userId = String(authUser.value?.id || '')
  return readStoredInvoiceArray(OFFICIAL_SUBSCRIPTION_RECEIPTS_STORAGE_KEY, normalizeOfficialSubscriptionReceipt)
    .filter((receipt) => receipt.userId === userId)
}

function rememberOfficialSubscriptionReceipt(order: PaymentOrder, context: OfficialSubscriptionRequestContext) {
  const receipt = normalizeOfficialSubscriptionReceipt({
    userId: String(authUser.value?.id || ''),
    orderId: getPaymentOrderId(order),
    outTradeNo: order.out_trade_no,
    planId: context.planId,
    planName: context.planName,
    amount: getPaymentOrderAmount(order),
    createdAt: order.created_at || new Date().toISOString(),
  })
  if (!receipt) throw new Error('订阅订单编号无效，请重试。')
  try {
    const receipts = pendingOfficialSubscriptionReceipts().filter((item) => item.orderId !== receipt.orderId)
    writeStoredInvoiceArray(OFFICIAL_SUBSCRIPTION_RECEIPTS_STORAGE_KEY, [...receipts, receipt])
  } catch (error) {
    // The encrypted server copy is authoritative even if local storage is unavailable.
    reportPageError('official-subscription', 'save-order-reference', error, { orderId: receipt.orderId })
  }
}

async function resumePendingOfficialSubscriptionOrders() {
  if (!authToken.value || !authUser.value?.id || officialSubscriptionRecoveryInFlight) return
  officialSubscriptionRecoveryInFlight = true
  const userId = String(authUser.value.id)
  const token = authToken.value
  try {
    try {
      await loadOfficialSubscriptionRecoveryOrders()
    } catch (error) {
      if (String(authUser.value?.id || '') !== userId || authToken.value !== token) return
      reportPageError('official-subscription', 'load-missing-session-orders', error)
      officialSubscriptionError.value = '暂时无法检查待补交资料的订单，请稍后刷新；已付款订单无需再次付款。'
    }
    if (String(authUser.value?.id || '') !== userId || authToken.value !== token) return
    const receipts = pendingOfficialSubscriptionReceipts()
    const finished = new Set<number>()
    for (const receipt of receipts) {
      if (String(authUser.value?.id || '') !== userId || authToken.value !== token) return
      try {
        // Verification also recovers a delayed provider callback. No Session is needed here.
        const order = receipt.outTradeNo
          ? await verifyPaymentOrderByOutTradeNo(receipt.outTradeNo, token)
          : await getPaymentOrder(receipt.orderId, token)
        if (isPaymentCompleted(order.status)
          || (isPaymentClosed(order.status) && !isOfficialSubscriptionPaidOrder(order))) {
          finished.add(receipt.orderId)
        }
      } catch (error) {
        reportPageError('official-subscription', 'recover-saved-order', error, { orderId: receipt.orderId })
      }
    }
    if (String(authUser.value?.id || '') !== userId || authToken.value !== token) return
    // Read again: a new checkout may have completed while recovery was awaiting the network.
    writeStoredInvoiceArray(OFFICIAL_SUBSCRIPTION_RECEIPTS_STORAGE_KEY,
      pendingOfficialSubscriptionReceipts().filter((receipt) => !finished.has(receipt.orderId)))
    const remoteOrders = await listOfficialSubscriptionsFromSoftwareAdmin(officialSubscriptionOwnerParams(), token)
    if (String(authUser.value?.id || '') !== userId || authToken.value !== token) return
    mergeOfficialSubscriptionRecords(remoteOrders.map(normalizeOfficialSubscriptionRecordFromSoftwareAdmin)
      .filter((record): record is OfficialSubscriptionRecord => Boolean(record)))
  } catch (error) {
    reportPageError('official-subscription', 'recover-saved-orders', error)
  } finally {
    officialSubscriptionRecoveryInFlight = false
  }
}

async function loadOfficialSubscriptionRecoveryOrders() {
  const token = authToken.value
  const userId = String(authUser.value?.id || '')
  if (!token || !userId) return
  const orders = await listAllPaymentOrders('official_sub', token)
  if (authToken.value !== token || String(authUser.value?.id || '') !== userId) return
  officialSubscriptionRecoveryOrders.value = orders.filter((order) => (
    order.order_type === 'official_sub' && order.official_session_saved === false
    && isOfficialSubscriptionPaidOrder(order) && !isPaymentCompleted(order.status)
  ))
}

function onOfficialSubscriptionSessionRecovered(orderId: number) {
  officialSubscriptionRecoveryOrders.value = officialSubscriptionRecoveryOrders.value
    .filter((order) => getPaymentOrderId(order) !== orderId)
  void refreshOfficialSubscriptionInfo()
}

function officialSubscriptionOwnerParams() {
  return {
    userId: authUser.value?.id ? String(authUser.value.id) : '',
    email: authUser.value?.email || user.value.email || '',
    username: authUser.value?.username || user.value.name || '',
  }
}

function officialSubscriptionStatusForBackend(record: OfficialSubscriptionRecord) {
  return record.progress === 'completed' ? 'done' : 'processing'
}

function findMatchingOfficialSubscriptionRecord(item: OfficialSubscriptionSoftwareAdminOrder) {
  const orderId = safeString(item.orderId || item.clientOrderId || item.id)
  const orderNo = safeString(item.orderNo)
  return officialSubscriptionRecords.value.find((record) => (
    (orderId && (record.orderId === orderId || record.orderNo === orderId)) ||
    (orderNo && (record.orderNo === orderNo || record.orderId === orderNo))
  )) || null
}

async function uploadOfficialSubscriptionRecordStatus(
  record: OfficialSubscriptionRecord,
  token = authToken.value,
  owner = officialSubscriptionOwnerParams(),
) {
  if (!token || record.hasSessionText === false) return false
  await submitOfficialSubscriptionToSoftwareAdmin({
    userId: owner.userId,
    user: record.account || owner.email,
    email: record.account || owner.email,
    username: owner.username,
    planId: record.planId,
    planName: record.planName,
    source: 'official-subscription-sync',
    orderId: record.orderId,
    orderNo: record.orderNo,
    clientOrderId: record.orderId,
    paymentStatus: 'paid',
    amount: record.amount,
    currency: 'CNY',
    sessionText: '',
    clientVersion: updateVersionText.value,
    platform: typeof navigator !== 'undefined' ? navigator.platform : '',
    note: '本机官方订阅状态补传，无 Session 文本。',
    paymentMethod: 'online-payment',
    paymentInfo: {
      paid: true,
      status: 'paid',
      statusOnly: true,
    },
    paidAt: record.paidAt,
    statusOnly: true,
    status: officialSubscriptionStatusForBackend(record),
  }, token)
  return true
}

function normalizeOfficialSubscriptionRecordFromSoftwareAdmin(item: OfficialSubscriptionSoftwareAdminOrder): OfficialSubscriptionRecord | null {
  if (!item || typeof item !== 'object') return null
  const existing = findMatchingOfficialSubscriptionRecord(item)
  const orderId = safeString(item.orderId || item.clientOrderId || item.orderNo || item.id || existing?.orderId)
  const planName = safeString(item.planName || existing?.planName)
  const account = safeString(item.email || item.user || item.username || existing?.account || user.value.email)
  const amount = Number(item.amount ?? existing?.amount)
  const paidAt = safeString(item.paidAt || item.submittedAt || existing?.paidAt)
  if (!orderId || !planName || !account || !paidAt || !Number.isFinite(amount) || amount < 0) return null
  const now = new Date().toISOString()
  return {
    id: existing?.id || `official-sub-${orderId}`,
    orderId,
    orderNo: safeString(item.orderNo || existing?.orderNo || orderId),
    planId: safeString(item.planId || existing?.planId || normalizeOfficialPlanKey(planName)),
    planName,
    amount,
    account,
    accountKey: existing?.accountKey || '',
    paidAt,
    progress: normalizeOfficialSubscriptionProgress(item.rechargeStatus || item.status || existing?.progress),
    hasSessionText: typeof item.hasSessionText === 'boolean' ? item.hasSessionText : existing?.hasSessionText,
    createdAt: existing?.createdAt || paidAt,
    updatedAt: safeString(item.submittedAt || existing?.updatedAt) || now,
  }
}

async function syncOfficialSubscriptionRecordsWithSoftwareAdmin() {
  const token = authToken.value
  const owner = officialSubscriptionOwnerParams()
  if (!token || !owner.userId) return
  const localRecords = [...officialSubscriptionRecords.value]
  const uploadResults = await Promise.allSettled(
    localRecords.map((record) => uploadOfficialSubscriptionRecordStatus(record, token, owner)),
  )
  uploadResults.forEach((result, index) => {
    if (result.status === 'rejected') {
      reportPageError('official-subscription', 'sync-local-official-subscription', result.reason, {
        orderId: localRecords[index]?.orderId,
      })
    }
  })
  if (authToken.value !== token || String(authUser.value?.id || '') !== owner.userId) return
  const remoteOrders = await listOfficialSubscriptionsFromSoftwareAdmin(owner, token)
  if (authToken.value !== token || String(authUser.value?.id || '') !== owner.userId) return
  const remoteRecords = remoteOrders
    .map((item) => normalizeOfficialSubscriptionRecordFromSoftwareAdmin(item))
    .filter((record): record is OfficialSubscriptionRecord => Boolean(record))
  mergeOfficialSubscriptionRecords(remoteRecords)
}

async function refreshOfficialSubscriptionInfo() {
  if (isOfficialSubscriptionSyncing.value) return
  isOfficialSubscriptionSyncing.value = true
  officialSubscriptionError.value = ''
  try {
    loadOfficialSubscriptionRecords()
    await Promise.allSettled([
      resumePendingOfficialSubscriptionOrders(),
      loadCodexAccounts({ silent: true }).then(() => ensureOfficialSelectedAccount()),
      syncOfficialSubscriptionRecordsWithSoftwareAdmin().catch((error) => {
        reportPageError('official-subscription', 'refresh-official-subscription-info', error)
        officialSubscriptionError.value = getErrorMessage(error, { notFoundMessage: '软件后台订阅同步接口暂不可用。' })
      }),
    ])
  } finally {
    isOfficialSubscriptionSyncing.value = false
  }
}

function normalizeOfficialSubscriptionRecordFromPayment(
  order: PaymentOrder | null,
  context?: OfficialSubscriptionRequestContext | null,
): OfficialSubscriptionRecord | null {
  const orderId = getPaymentOrderId(order)
  if (!order || !orderId || !isOfficialSubscriptionPaidOrder(order)) return null
  const paidAt = String(order.paid_at || order.completed_at || getPaymentOrderTime(order) || '').trim()
  if (!paidAt) return null
  const amount = Number(order.pay_amount ?? order.amount ?? context?.amount)
  if (!Number.isFinite(amount) || amount < 0) return null
  const matchedPlan = context?.planId
    ? officialSubscriptionPlans.value.find((plan) => plan.id === context.planId)
    : findOfficialPlanByAmount(amount)
  const planName = context?.planName || matchedPlan?.name || '官方订阅'
  const now = new Date().toISOString()
  return {
    id: `official-sub-${orderId}`,
    orderId: String(orderId),
    orderNo: String(order.out_trade_no || order.order_id || order.id || orderId),
    planId: context?.planId || matchedPlan?.id || normalizeOfficialPlanKey(planName),
    planName,
    amount,
    account: context?.account || officialIdentifiedAccountLabel(),
    accountKey: context?.accountKey || officialIdentifiedAccount.value?.accountKey || '',
    paidAt,
    progress: 'subscribing',
    hasSessionText: order.official_session_saved,
    createdAt: paidAt,
    updatedAt: now,
  }
}

function isOfficialPlanCompatible(recordPlan: string, accountPlan: string) {
  if (!recordPlan || !accountPlan) return true
  if (recordPlan === accountPlan) return true
  return recordPlan.startsWith('pro') && accountPlan === 'pro'
}

function isOfficialSubscriptionRecordCompleted(record: OfficialSubscriptionRecord) {
  if (record.hasSessionText === false) return false
  const recordAccount = record.account.trim().toLowerCase()
  const recordPlan = normalizeOfficialPlanKey(record.planId || record.planName)
  return managedAccounts.value.some((account) => {
    if (!account.account.hasActiveSubscription) return false
    const accountMatches = Boolean(
      (record.accountKey && account.accountKey === record.accountKey) ||
      (recordAccount && account.email.trim().toLowerCase() === recordAccount),
    )
    if (!accountMatches) return false
    return isOfficialPlanCompatible(recordPlan, normalizeOfficialPlanKey(account.plan))
  })
}

function syncOfficialSubscriptionRecordsFromAccounts(options: { save?: boolean } = {}) {
  if (!officialSubscriptionRecords.value.length) return
  let changed = false
  const now = new Date().toISOString()
  officialSubscriptionRecords.value = officialSubscriptionRecords.value.map((record) => {
    if (record.progress === 'completed' || !isOfficialSubscriptionRecordCompleted(record)) return record
    changed = true
    return {
      ...record,
      progress: 'completed',
      updatedAt: now,
    }
  })
  if (changed && options.save !== false) saveOfficialSubscriptionRecords()
}

function persistOfficialSubscriptionRecord(order: PaymentOrder | null) {
  const record = normalizeOfficialSubscriptionRecordFromPayment(order, activeOfficialSubscriptionRequest.value)
  if (!record) return
  mergeOfficialSubscriptionRecords([record])
}

function getPlatformSubscriptionExpiresAt(subscription?: ActiveSubscription | SubscriptionSummaryItem | null) {
  const activeSubscription = subscription as ActiveSubscription | null | undefined
  return subscription?.expires_at || activeSubscription?.valid_until || activeSubscription?.end_at || null
}

function isPlatformSubscriptionClosedStatus(status?: string | null) {
  const normalized = String(status || '').toLowerCase()
  return ['cancelled', 'canceled', 'expired', 'inactive', 'disabled', 'ended', 'deleted', 'banned'].includes(normalized) ||
    normalized.includes('failed')
}

function isPlatformSubscriptionExpired(expiresAt?: string | null) {
  if (!expiresAt) return false
  const expiresTime = new Date(expiresAt).getTime()
  return Number.isFinite(expiresTime) && expiresTime <= Date.now()
}

function isPlatformSubscriptionRecordActive(subscription?: ActiveSubscription | SubscriptionSummaryItem | null) {
  if (!subscription) return false
  return !isPlatformSubscriptionClosedStatus(subscription.status) &&
    !isPlatformSubscriptionExpired(getPlatformSubscriptionExpiresAt(subscription))
}

function formatPlatformSubscriptionExpiresAt(subscription?: ActiveSubscription | null, summary?: SubscriptionSummaryItem | null) {
  const expiresAt = getPlatformSubscriptionExpiresAt(summary || subscription)
  return expiresAt ? formatFullTime(expiresAt) : '有效期 30 天'
}

function getSubscriptionGroupId(subscription?: ActiveSubscription | null) {
  return Number(subscription?.group_id || subscription?.group?.id || 0)
}

function normalizeActiveSubscriptionPayload(payload: ActiveSubscription | ActiveSubscription[] | null) {
  const list = (Array.isArray(payload) ? payload : payload ? [payload] : [])
    .filter((item): item is ActiveSubscription => Boolean(item && typeof item === 'object'))
  if (!list.length) return null

  return list.find((item) => isPlatformSubscriptionRecordActive(item)) || null
}

function toFiniteMoney(value: unknown, fallback = 0) {
  const amount = Number(value)
  return Number.isFinite(amount) ? amount : fallback
}

function toSubscriptionUsageRow(label: string, rawUsed: unknown, rawLimit: unknown): SubscriptionUsageRow | null {
  const used = toFiniteMoney(rawUsed)
  const limit = toFiniteMoney(rawLimit, Number.NaN)
  if (!Number.isFinite(limit) || limit <= 0) return null
  const remaining = Math.max(0, limit - used)
  return {
    label,
    used: formatMoney(used),
    limit: formatMoney(limit),
    remaining: formatMoney(remaining),
    percent: Math.min(100, Math.max(0, (used / limit) * 100)),
  }
}

function formatSubscriptionDailyLimit(
  subscription?: ActiveSubscription | null,
  plan?: PlatformSubscriptionPlan | null,
  summary?: SubscriptionSummaryItem | null,
) {
  const rawLimit =
    summary?.daily_limit_usd ??
    subscription?.daily_limit_usd ??
    subscription?.group?.daily_limit_usd ??
    plan?.dailyLimitUsd
  const amount = Number(rawLimit)
  if (Number.isFinite(amount) && amount > 0) {
    return `每日 ${amount.toFixed(amount % 1 === 0 ? 0 : 2)} 刀`
  }
  return plan?.dailyQuota || '每日额度待同步'
}

function formatPlatformSubscriptionStatus(status?: string | null, expiresAt?: string | null) {
  const normalized = String(status || 'active').toLowerCase()
  if (normalized === 'expired') return '已到期'
  if (normalized === 'deleted') return '已删除'
  if (normalized === 'banned') return '已封禁'
  if (normalized === 'cancelled' || normalized === 'canceled') return '已取消'
  if (isPlatformSubscriptionExpired(expiresAt)) return '已到期'
  if (normalized === 'active') return '生效中'
  if (normalized === 'pending') return '待生效'
  if (normalized.includes('failed')) return '异常'
  return status || '待同步'
}

function formatPlatformQuotaAmount(plan: PlatformSubscriptionPlan) {
  const amount = Number(plan.dailyLimitUsd)
  if (Number.isFinite(amount) && amount > 0) {
    return `${amount.toFixed(amount % 1 === 0 ? 0 : 2)} 刀`
  }
  return plan.dailyQuota.replace(/^每日\s*/, '') || '额度待同步'
}

function isPaymentCompleted(status?: string) {
  return ['COMPLETED', 'SUCCESS', 'SUCCEEDED', 'FINISHED', 'TRADE_SUCCESS'].includes(String(status || '').toUpperCase())
}

function isPaymentProcessing(status?: string) {
  return ['PAID', 'RECHARGING'].includes(String(status || '').toUpperCase())
}

function isPaymentClosed(status?: string) {
  return ['CANCELLED', 'CANCELED', 'EXPIRED', 'FAILED'].includes(String(status || '').toUpperCase())
}

function isBackupBridgePaymentOrder(order: PaymentOrder | null) {
  const provider = String(order?.provider_key || order?.payment_mode || '').trim().toLowerCase()
  return provider === 'backup_bridge'
}

function paymentStatusText(status?: string, purpose: ActivePaymentPurpose = 'recharge') {
  const normalized = String(status || '').toUpperCase()
  const isSubscription = purpose === 'platform-subscription'
  const isOfficialSubscription = purpose === 'official-subscription'
  if (['COMPLETED', 'SUCCESS', 'SUCCEEDED', 'FINISHED', 'TRADE_SUCCESS'].includes(normalized)) {
    if (isOfficialSubscription) return '支付完成，官方订阅请求已提交。'
    return isSubscription ? '支付完成，平台订阅正在确认开通。' : '支付完成，余额已到账。'
  }
  if (normalized === 'PAID' || normalized === 'RECHARGING') {
    if (isOfficialSubscription) return '支付完成，官方订阅请求正在处理，请稍后刷新。'
    return isSubscription ? '支付完成，订阅正在开通，请稍后刷新。' : '支付完成，余额同步可能稍有延迟，请稍后刷新。'
  }
  if (normalized === 'EXPIRED') return isSubscription || isOfficialSubscription ? '订单已超时，请重新发起订阅。' : '订单已超时，请重新发起充值。'
  if (normalized === 'CANCELLED' || normalized === 'CANCELED') return '订单已取消。'
  if (normalized === 'FAILED') return isSubscription || isOfficialSubscription ? '订单支付失败，请重新发起订阅。' : '订单支付失败，请重新发起充值。'
  if (isOfficialSubscription) return '等待支付完成，完成后自动提交官方订阅请求。'
  return isSubscription ? '等待支付完成，完成后自动开通订阅。' : '等待支付完成。'
}

function normalizeInvoiceTitle(value: unknown): InvoiceTitle | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<InvoiceTitle>
  const title = String(source.title || '').trim()
  const taxNumber = String(source.taxNumber || '').trim()
  if (!title || !taxNumber) return null
  return {
    id: String(source.id || `invoice-title-${Date.now()}-${getRandomText(6)}`),
    title,
    taxNumber,
    createdAt: String(source.createdAt || new Date().toISOString()),
  }
}

function normalizeInvoiceStoredOrder(value: unknown): InvoiceStoredOrder | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<InvoiceStoredOrder>
  const id = String(source.id || '').trim()
  const orderNo = String(source.orderNo || '').trim()
  const amount = Number(source.amount || 0)
  const createdAt = String(source.createdAt || source.paidAt || '').trim()
  if (!id || !orderNo || !Number.isFinite(amount) || amount <= 0 || !createdAt) return null
  return {
    id,
    orderNo,
    amount,
    status: String(source.status || 'PAID'),
    createdAt,
    paidAt: String(source.paidAt || createdAt),
    source: String(source.source || '在线充值'),
  }
}

function normalizeInvoiceTimestamp(value: unknown) {
  if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString()
  const millis = parseTimestampMillis(value)
  if (typeof millis === 'number') return new Date(millis).toISOString()
  return ''
}

function pickInvoiceTimestamp(...values: unknown[]) {
  for (const value of values) {
    const normalized = normalizeInvoiceTimestamp(value)
    if (normalized) return normalized
  }
  return ''
}

function getInvoiceTimestampFromId(id: string) {
  const match = id.match(/(?:^|[-_])(\d{10,13})(?:[-_]|$)/)
  return match ? normalizeInvoiceTimestamp(match[1]) : ''
}

function normalizeInvoiceApplicationOrder(value: unknown): DesktopInvoiceOrderItem | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<DesktopInvoiceOrderItem> & Record<string, unknown> & { id?: string; amount?: number }
  const orderId = String(source.orderId || source.order_id || source.id || '').trim()
  const orderNo = String(source.orderNo || source.order_no || orderId).trim()
  const orderAmount = Number(source.orderAmount ?? source.order_amount ?? source.amount ?? 0)
  const orderTime = pickInvoiceTimestamp(
    source.orderTime,
    source.order_time,
    source.time,
    source.paid_at,
    source.completed_at,
    source.created_at,
    source.updated_at,
  )
  if (!orderId || !orderNo || !Number.isFinite(orderAmount) || orderAmount <= 0 || !orderTime) return null
  return {
    orderId,
    orderNo,
    orderAmount,
    orderTime,
    source: String(source.source || '在线充值').trim() || '在线充值',
  }
}

function normalizeInvoiceApplication(value: unknown): InvoiceApplication | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<InvoiceApplication> & Partial<DesktopInvoiceApplication> & Record<string, unknown>
  const id = String(source.id || '').trim()
  const titleName = String(source.titleName || source.title_name || '').trim()
  const taxNumber = String(source.taxNumber || source.tax_number || '').trim()
  const fallbackRequestedAt = getInvoiceTimestampFromId(id)
  const payloadRequestedAt = pickInvoiceTimestamp(
    source.requestedAt,
    source.requested_at,
    source.submittedAt,
    source.submitted_at,
    source.createdAt,
    source.created_at,
    source.updatedAt,
    source.updated_at,
  )
  const rawOrders = Array.isArray(source.orders) ? source.orders : []
  const orders = rawOrders
    .map(normalizeInvoiceApplicationOrder)
    .filter((item): item is DesktopInvoiceOrderItem => Boolean(item))
  if (!orders.length && (source.orderId || source.order_id)) {
    const legacyOrder = normalizeInvoiceApplicationOrder({
      orderId: source.orderId || source.order_id,
      orderNo: source.orderNo || source.order_no,
      orderAmount: source.orderAmount ?? source.order_amount,
      orderTime: pickInvoiceTimestamp(source.orderTime, source.order_time, payloadRequestedAt, fallbackRequestedAt),
    })
    if (legacyOrder) orders.push(legacyOrder)
  }
  const requestedAt = payloadRequestedAt || fallbackRequestedAt || pickInvoiceTimestamp(source.orderTime, source.order_time, orders[0]?.orderTime)
  const orderId = String(source.orderId || source.order_id || orders[0]?.orderId || '').trim()
  const orderNo = String(source.orderNo || source.order_no || orders[0]?.orderNo || '').trim()
  const itemTotal = orders.reduce((total, item) => total + item.orderAmount, 0)
  const orderAmount = Number(source.orderAmount ?? source.order_amount ?? source.totalAmount ?? source.total_amount ?? itemTotal ?? 0)
  if (!id || !orderId || !orderNo || !orders.length || !titleName || !taxNumber || !Number.isFinite(orderAmount) || !requestedAt) return null
  const pdfUrl = String(source.pdfUrl || source.pdf_url || '').trim()
  const pdfDataUrl = String(source.pdfDataUrl || source.pdf_data_url || '').trim()
  const hasPdf = Boolean(pdfUrl || pdfDataUrl)
  return {
    id,
    orderId,
    orderNo,
    orderAmount,
    orderTime: pickInvoiceTimestamp(source.orderTime, source.order_time, orders[0]?.orderTime, requestedAt),
    orderIds: orders.map((item) => item.orderId),
    orderNos: orders.map((item) => item.orderNo),
    orderCount: orders.length,
    orders,
    titleId: String(source.titleId || source.title_id || ''),
    titleName,
    taxNumber,
    invoiceType: String(source.invoiceType || source.invoice_type || invoiceTypeLabel),
    invoiceKind: String(source.invoiceKind || source.invoice_kind || invoiceKindLabel),
    status: hasPdf ? 'completed' : source.status === 'completed' ? 'completed' : 'waiting',
    requestedAt,
    pdfUrl,
    pdfDataUrl,
    pdfName: String(source.pdfName || source.pdf_name || `invoice-${id}.pdf`),
  }
}

function normalizeInvoiceApplicationFromRemote(value: DesktopInvoiceApplication): InvoiceApplication | null {
  return normalizeInvoiceApplication(value)
}

function invoiceApplicationRank(application: InvoiceApplication) {
  return (isInvoiceApplicationCompleted(application) ? 1_000_000_000_000_000 : 0) + (new Date(application.requestedAt).getTime() || 0)
}

function mergeInvoiceApplications(nextApplications: InvoiceApplication[]) {
  const applicationMap = new Map<string, InvoiceApplication>()
  ;[...invoiceApplications.value, ...nextApplications].forEach((application) => {
    const key = application.id
    const current = applicationMap.get(key)
    if (!current || invoiceApplicationRank(application) >= invoiceApplicationRank(current)) {
      applicationMap.set(key, application)
    }
  })
  invoiceApplications.value = Array.from(applicationMap.values())
    .sort((left, right) => (new Date(right.requestedAt).getTime() || 0) - (new Date(left.requestedAt).getTime() || 0))
}

function replaceInvoiceApplicationsFromRemote(nextApplications: InvoiceApplication[]) {
  const applicationMap = new Map<string, InvoiceApplication>()
  nextApplications.forEach((application) => {
    const key = application.id
    const current = applicationMap.get(key)
    if (!current || invoiceApplicationRank(application) >= invoiceApplicationRank(current)) {
      applicationMap.set(key, application)
    }
  })
  invoiceApplications.value = Array.from(applicationMap.values())
    .sort((left, right) => (new Date(right.requestedAt).getTime() || 0) - (new Date(left.requestedAt).getTime() || 0))
}

function ensureInvoiceOrdersFromApplications(applications: InvoiceApplication[]) {
  const existingIds = new Set(invoiceOrders.value.map((order) => order.id))
  const nextOrders = applications.reduce<InvoiceStoredOrder[]>((result, application) => {
    application.orders.forEach((item) => {
      if (existingIds.has(item.orderId)) return
      const amount = Number(item.orderAmount || 0)
      if (!item.orderId || !item.orderNo || !Number.isFinite(amount) || amount <= 0) return
      existingIds.add(item.orderId)
      result.push({
        id: item.orderId,
        orderNo: item.orderNo,
        amount,
        status: 'COMPLETED',
        createdAt: item.orderTime || application.requestedAt,
        paidAt: item.orderTime || application.requestedAt,
        source: item.source || '在线充值',
      })
    })
    return result
  }, [])
  if (!nextOrders.length) return
  invoiceOrders.value = [...nextOrders, ...invoiceOrders.value]
  saveInvoiceOrders()
}

function invoiceOrderRank(order: InvoiceStoredOrder) {
  return new Date(order.paidAt || order.createdAt).getTime() || 0
}

function mergeInvoiceOrders(nextOrders: InvoiceStoredOrder[]) {
  if (!nextOrders.length) return
  const orderMap = new Map<string, InvoiceStoredOrder>()
  ;[...invoiceOrders.value, ...nextOrders].forEach((order) => {
    const current = orderMap.get(order.id)
    if (!current || invoiceOrderRank(order) >= invoiceOrderRank(current)) {
      orderMap.set(order.id, order)
    }
  })
  invoiceOrders.value = Array.from(orderMap.values())
    .sort((left, right) => invoiceOrderRank(right) - invoiceOrderRank(left))
  saveInvoiceOrders()
}

function getInvoicePaymentOrderSource(orderType: string) {
  if (orderType === 'platform_sub' || orderType === 'subscription') return '平台订阅'
  if (orderType === 'official_sub') return '官方订阅'
  return '在线充值'
}

function normalizeInvoiceOrderFromPayment(order: PaymentOrder | null): InvoiceStoredOrder | null {
  const orderId = getPaymentOrderId(order)
  const amount = getPaymentOrderAmount(order)
  const orderType = String(order?.order_type || 'balance').trim().toLowerCase()
  if (!order || !orderId || !INVOICEABLE_PAYMENT_ORDER_TYPES.has(orderType) || amount <= 0 || !isPaymentCompleted(order.status)) return null
  const createdAt = getPaymentOrderTime(order)
  if (!createdAt) return null
  return {
    id: String(orderId),
    orderNo: String(order.out_trade_no || order.order_id || order.id || orderId),
    amount,
    status: order.status || 'PAID',
    createdAt,
    paidAt: order.paid_at || order.completed_at || createdAt,
    source: getInvoicePaymentOrderSource(orderType),
  }
}

function isApiNotFound(error: unknown) {
  return (error as ApiError)?.status === 404
}

function getInvoiceOwnerParams() {
  return {
    userId: authUser.value?.id ? String(authUser.value.id) : '',
    email: authUser.value?.email || user.value.email || '',
  }
}

function normalizeProjectOutsourcingRecord(value: DesktopProjectOutsourcingRequest | unknown): ProjectOutsourcingRecord | null {
  if (!value || typeof value !== 'object') return null
  const source = value as Partial<DesktopProjectOutsourcingRequest>
  const id = String(source.id || '').trim()
  const requirement = String(source.requirement || '').trim()
  const content = String(source.content || '').trim()
  const contact = String(source.contact || '').trim()
  const submittedAt = String(source.submittedAt || source.updatedAt || '').trim()
  const status = String(source.status || 'pending').trim()
  if (!id || !requirement || !content || !contact || !submittedAt) return null
  const normalizedStatus: ProjectOutsourcingStatus = status === 'approved' || status === 'rejected' ? status : 'pending'
  return {
    id,
    requirement,
    content,
    contact,
    status: normalizedStatus,
    submittedAt,
    updatedAt: String(source.updatedAt || submittedAt),
  }
}

function projectOutsourcingRecordRank(record: ProjectOutsourcingRecord) {
  return parseTimestampMillis(record.updatedAt || record.submittedAt) || 0
}

function replaceProjectOutsourcingRecords(nextRecords: ProjectOutsourcingRecord[]) {
  projectOutsourcingRecords.value = [...nextRecords]
    .sort((left, right) => projectOutsourcingRecordRank(right) - projectOutsourcingRecordRank(left))
    .slice(0, 100)
}

function mergeProjectOutsourcingRecords(nextRecords: ProjectOutsourcingRecord[]) {
  const recordMap = new Map<string, ProjectOutsourcingRecord>()
  ;[...projectOutsourcingRecords.value, ...nextRecords].forEach((record) => {
    const current = recordMap.get(record.id)
    if (!current || projectOutsourcingRecordRank(record) >= projectOutsourcingRecordRank(current)) {
      recordMap.set(record.id, record)
    }
  })
  replaceProjectOutsourcingRecords(Array.from(recordMap.values()))
}

function getProjectOutsourcingOwnerParams() {
  return getInvoiceOwnerParams()
}

function projectOutsourcingStatusText(status: ProjectOutsourcingStatus) {
  if (status === 'approved') return '已同意'
  if (status === 'rejected') return '已拒绝'
  return '等待回应'
}

function projectOutsourcingStatusClass(status: ProjectOutsourcingStatus) {
  if (status === 'approved') return 'approved'
  if (status === 'rejected') return 'rejected'
  return 'waiting'
}

async function syncProjectOutsourcingRecords(options: { silent?: boolean } = {}) {
  if (isProjectOutsourcingLoading.value) return
  if (!authToken.value) {
    projectOutsourcingRecords.value = []
    return
  }
  const owner = getProjectOutsourcingOwnerParams()
  if (!owner.userId && !owner.email) {
    if (!options.silent) projectOutsourcingError.value = '未读取到当前账号信息，请重新登录后再试。'
    return
  }
  if (!options.silent) {
    projectOutsourcingError.value = ''
  }
  isProjectOutsourcingLoading.value = true
  try {
    const records = await listDesktopProjectOutsourcingRequests(owner, authToken.value)
    replaceProjectOutsourcingRecords(
      records
        .map(normalizeProjectOutsourcingRecord)
        .filter((item): item is ProjectOutsourcingRecord => Boolean(item)),
    )
  } catch (error) {
    reportPageError('project-outsourcing', 'sync-project-outsourcing-records', error)
    if (!options.silent) {
      projectOutsourcingError.value = getErrorMessage(error, { notFoundMessage: '暂未找到项目外包提交记录。' })
    }
  } finally {
    isProjectOutsourcingLoading.value = false
  }
}

async function submitProjectOutsourcingRequest() {
  if (isProjectOutsourcingSubmitting.value) return
  projectOutsourcingError.value = ''
  projectOutsourcingNotice.value = ''
  const requirement = projectOutsourcingForm.value.requirement.trim()
  const content = projectOutsourcingForm.value.content.trim()
  const contact = projectOutsourcingForm.value.contact.trim()
  if (!requirement) {
    projectOutsourcingError.value = '请填写客户的需求。'
    return
  }
  if (!content) {
    projectOutsourcingError.value = '请填写需求的大致内容。'
    return
  }
  if (!contact) {
    projectOutsourcingError.value = '请填写客户的联系方式。'
    return
  }
  if (!authToken.value) {
    projectOutsourcingError.value = '请先登录账户。'
    return
  }
  const owner = getProjectOutsourcingOwnerParams()
  if (!owner.userId && !owner.email) {
    projectOutsourcingError.value = '未读取到当前账号信息，请重新登录后再试。'
    return
  }
  isProjectOutsourcingSubmitting.value = true
  try {
    const remoteRecord = await createDesktopProjectOutsourcingRequest({
      id: `project-${Date.now()}-${getRandomText(6)}`,
      userId: owner.userId || owner.email,
      email: owner.email,
      user: owner.email || owner.userId,
      requirement,
      content,
      contact,
      clientVersion: updateVersionText.value,
      version: updateVersionText.value,
      platform: typeof navigator !== 'undefined' ? navigator.platform : '',
      os: typeof navigator !== 'undefined' ? navigator.userAgent : '',
    }, authToken.value)
    const record = normalizeProjectOutsourcingRecord(remoteRecord)
    if (!record) throw new Error('项目外包申请返回数据不完整。')
    mergeProjectOutsourcingRecords([record])
    projectOutsourcingForm.value = { requirement: '', content: '', contact: '' }
    projectOutsourcingNotice.value = '项目需求已提交，我们会尽快评估并回应。'
  } catch (error) {
    reportPageError('project-outsourcing', 'submit-project-outsourcing-request', error, {
      requirement,
    })
    projectOutsourcingError.value = getErrorMessage(error, { notFoundMessage: '项目外包接口暂不可用，请稍后重试。' })
  } finally {
    isProjectOutsourcingSubmitting.value = false
  }
}

function loadInvoiceLocalData() {
  invoiceTitles.value = readStoredInvoiceArray(INVOICE_TITLES_STORAGE_KEY, normalizeInvoiceTitle)
  invoiceOrders.value = readStoredInvoiceArray(INVOICE_ORDERS_STORAGE_KEY, normalizeInvoiceStoredOrder)
  invoiceApplications.value = readStoredInvoiceArray(INVOICE_APPLICATIONS_STORAGE_KEY, normalizeInvoiceApplication)
}

function saveInvoiceTitles() {
  writeStoredInvoiceArray(INVOICE_TITLES_STORAGE_KEY, invoiceTitles.value)
}

function saveInvoiceOrders() {
  writeStoredInvoiceArray(INVOICE_ORDERS_STORAGE_KEY, invoiceOrders.value)
}

function saveInvoiceApplications() {
  writeStoredInvoiceArray(INVOICE_APPLICATIONS_STORAGE_KEY, invoiceApplications.value)
}

async function syncInvoicePaymentOrders() {
  const paymentOrders = await listAllPaymentOrders()
  const orderMap = new Map<string, InvoiceStoredOrder>()
  paymentOrders.forEach((paymentOrder) => {
    const order = normalizeInvoiceOrderFromPayment(paymentOrder)
    if (!order) return
    const current = orderMap.get(order.id)
    if (!current || invoiceOrderRank(order) >= invoiceOrderRank(current)) {
      orderMap.set(order.id, order)
    }
  })
  const nextOrders = Array.from(orderMap.values())
    .sort((left, right) => invoiceOrderRank(right) - invoiceOrderRank(left))
  invoiceOrders.value = nextOrders
  saveInvoiceOrders()
  return nextOrders.length
}

async function syncInvoiceApplications(options: { silent?: boolean } = {}) {
  if (!authToken.value || isInvoiceSyncing.value) return
  const owner = getInvoiceOwnerParams()
  if (!owner.userId && !owner.email) return
  isInvoiceSyncing.value = true
  if (!options.silent) {
    invoiceError.value = ''
    invoiceNotice.value = ''
  }
  try {
    let syncedOrderCount = 0
    let orderSyncError: unknown = null
    try {
      syncedOrderCount = await syncInvoicePaymentOrders()
    } catch (error) {
      reportPageError('invoice', 'sync-invoice-payment-orders', error)
      orderSyncError = error
    }

    let remoteApplications: DesktopInvoiceApplication[] = []
    try {
      remoteApplications = await listDesktopInvoiceBatchApplications(owner, authToken.value)
    } catch (error) {
      if (!isApiNotFound(error)) throw error
      remoteApplications = await listDesktopInvoices(owner, authToken.value)
    }
    const nextApplications = remoteApplications
      .map(normalizeInvoiceApplicationFromRemote)
      .filter((application): application is InvoiceApplication => Boolean(application))
    replaceInvoiceApplicationsFromRemote(nextApplications)
    ensureInvoiceOrdersFromApplications(nextApplications)
    saveInvoiceApplications()
    if (!options.silent) {
      if (orderSyncError) {
        invoiceError.value = getErrorMessage(orderSyncError, { notFoundMessage: '暂未找到支付订单。' })
      } else {
        invoiceNotice.value = nextApplications.length
          ? '发票状态已同步。'
          : syncedOrderCount
            ? '已刷新可开票订单，当前账号暂无开票申请。'
            : '当前账号暂无开票申请。'
      }
    }
  } catch (error) {
    reportPageError('invoice', 'sync-invoice-applications', error)
    if (!options.silent) {
      invoiceError.value = getErrorMessage(error, { notFoundMessage: '暂未找到开票申请。' })
    }
  } finally {
    isInvoiceSyncing.value = false
  }
}

function resetInvoiceUiState() {
  invoiceTitleForm.value = { title: '', taxNumber: '' }
  invoiceNotice.value = ''
  invoiceError.value = ''
  invoiceSelectedTitleId.value = ''
  invoiceSelectedOrderIds.value = []
  activeInvoiceRecordTab.value = 'available'
  invoiceAvailablePage.value = 1
  invoiceIssuedPage.value = 1
  pendingInvoiceOrders.value = []
  showInvoiceApplyDialog.value = false
}

function isInvoiceApplicationCompleted(application?: InvoiceApplication | null) {
  return Boolean(application && (application.status === 'completed' || application.pdfUrl || application.pdfDataUrl))
}

function invoiceApplicationStatusText(application?: InvoiceApplication | null) {
  if (!application) return '可申请'
  return isInvoiceApplicationCompleted(application) ? '已完成' : '等待中'
}

function invoiceApplicationStatusClass(application?: InvoiceApplication | null) {
  if (!application) return 'ready'
  return isInvoiceApplicationCompleted(application) ? 'completed' : 'waiting'
}

function persistInvoiceOrder(order: PaymentOrder | null) {
  const storedOrder = normalizeInvoiceOrderFromPayment(order)
  if (!storedOrder) return
  mergeInvoiceOrders([storedOrder])
}

function submitInvoiceTitle() {
  invoiceError.value = ''
  invoiceNotice.value = ''
  const title = invoiceTitleForm.value.title.trim()
  const taxNumber = invoiceTitleForm.value.taxNumber.trim()
  if (!title || !taxNumber) {
    invoiceError.value = '请填写抬头和税号。'
    return
  }
  const exists = invoiceTitles.value.some((item) => (
    item.title.trim().toLowerCase() === title.toLowerCase() &&
    item.taxNumber.trim().toLowerCase() === taxNumber.toLowerCase()
  ))
  if (exists) {
    invoiceError.value = '该开票信息已存在。'
    return
  }
  invoiceTitles.value = [{
    id: `invoice-title-${Date.now()}-${getRandomText(6)}`,
    title,
    taxNumber,
    createdAt: new Date().toISOString(),
  }, ...invoiceTitles.value].slice(0, 20)
  invoiceTitleForm.value = { title: '', taxNumber: '' }
  saveInvoiceTitles()
  invoiceNotice.value = '开票信息已添加。'
}

async function deleteInvoiceTitle(title: InvoiceTitle) {
  invoiceError.value = ''
  invoiceNotice.value = ''
  if (!(await confirmAction(`删除开票信息「${title.title}」后，后续申请需重新添加，是否继续？`, {
    tone: 'warning',
    title: '删除开票信息',
    confirmText: '确认删除',
    cancelText: '取消',
  }))) {
    return
  }
  invoiceTitles.value = invoiceTitles.value.filter((item) => item.id !== title.id)
  if (invoiceSelectedTitleId.value === title.id) invoiceSelectedTitleId.value = ''
  saveInvoiceTitles()
  invoiceNotice.value = '开票信息已删除。'
}

function isInvoiceOrderSelected(orderId: string) {
  return invoiceSelectedOrderIds.value.includes(orderId)
}

function toggleInvoiceOrderSelection(order: InvoiceCandidate) {
  if (order.application) return
  invoiceSelectedOrderIds.value = isInvoiceOrderSelected(order.id)
    ? invoiceSelectedOrderIds.value.filter((orderId) => orderId !== order.id)
    : [...invoiceSelectedOrderIds.value, order.id]
}

function clearInvoiceOrderSelection() {
  invoiceSelectedOrderIds.value = []
}

function showInvoiceMinimumAmountNotice(amount: number) {
  const currentAmount = Math.max(0, Number(amount) || 0)
  return confirmAction(
    '因近期开票需求量较大，单次申请开票金额需满 ¥100.00。',
    {
      tone: 'warning',
      title: '暂不满足开票金额',
      details: [
        `当前已选金额：${formatCny(currentAmount)}，暂未满足 ${formatCny(INVOICE_MINIMUM_APPLICATION_AMOUNT)}。`,
        '未开票订单会继续保留，您可在后续订单累计满 ¥100.00 后一并提交申请。',
        '给您带来的不便，敬请谅解。如有加急开票需求，请联系人工客服处理。',
      ],
      confirmText: '我知道了',
      cancelText: '',
    },
  )
}

function openInvoiceApplyDialog(order?: InvoiceCandidate) {
  invoiceError.value = ''
  invoiceNotice.value = ''
  if (order && !order.application && !isInvoiceOrderSelected(order.id)) {
    invoiceSelectedOrderIds.value = [...invoiceSelectedOrderIds.value, order.id]
  }
  if (!invoiceTitles.value.length) {
    invoiceError.value = '请先添加开票信息。'
    return
  }
  const selectedOrders = invoiceSelectedOrders.value
  if (!selectedOrders.length) {
    invoiceError.value = '请至少选择一笔可开票在线支付订单。'
    return
  }
  const selectedAmount = selectedOrders.reduce((total, item) => total + item.amount, 0)
  if (selectedAmount < INVOICE_MINIMUM_APPLICATION_AMOUNT) {
    void showInvoiceMinimumAmountNotice(selectedAmount)
    return
  }
  pendingInvoiceOrders.value = selectedOrders.map((item) => ({ ...item }))
  invoiceSelectedTitleId.value = invoiceTitles.value[0]?.id || ''
  showInvoiceApplyDialog.value = true
}

function closeInvoiceApplyDialog() {
  showInvoiceApplyDialog.value = false
  pendingInvoiceOrders.value = []
  invoiceSelectedTitleId.value = ''
}

async function submitInvoiceApplication() {
  if (isInvoiceSubmitting.value) return
  invoiceError.value = ''
  invoiceNotice.value = ''
  const orders = pendingInvoiceOrders.value
  if (!orders.length) return
  const orderAmount = orders.reduce((total, order) => total + order.amount, 0)
  if (orderAmount < INVOICE_MINIMUM_APPLICATION_AMOUNT) {
    closeInvoiceApplyDialog()
    void showInvoiceMinimumAmountNotice(orderAmount)
    return
  }
  if (!authToken.value) {
    invoiceError.value = '请先登录账户。'
    return
  }
  const selectedTitle = invoiceTitles.value.find((item) => item.id === invoiceSelectedTitleId.value) || null
  if (!selectedTitle) {
    invoiceError.value = '请选择一个开票抬头。'
    return
  }
  const submittedOrderIds = new Set(invoiceApplications.value.flatMap((application) => application.orderIds))
  if (orders.some((order) => submittedOrderIds.has(order.id))) {
    invoiceError.value = '部分在线支付订单已经提交过开票申请，请刷新后重新选择。'
    closeInvoiceApplyDialog()
    return
  }
  const owner = getInvoiceOwnerParams()
  if (!owner.userId && !owner.email) {
    invoiceError.value = '未读取到当前账号信息，请重新登录后再试。'
    return
  }
  isInvoiceSubmitting.value = true
  try {
    const remoteApplication = await createDesktopInvoiceBatchApplication({
      userId: owner.userId || owner.email,
      email: owner.email,
      user: owner.email || owner.userId,
      orders: orders.map((order) => ({
        orderId: order.id,
        orderNo: order.orderNo,
        orderAmount: order.amount,
        orderTime: order.time,
        source: order.source,
      })),
      titleId: selectedTitle.id,
      titleName: selectedTitle.title,
      taxNumber: selectedTitle.taxNumber,
      invoiceType: invoiceTypeLabel,
      invoiceKind: invoiceKindLabel,
    }, authToken.value)
    const application = normalizeInvoiceApplicationFromRemote(remoteApplication)
    if (!application) throw new Error('开票申请返回数据不完整。')
    mergeInvoiceApplications([application])
    ensureInvoiceOrdersFromApplications([application])
    saveInvoiceApplications()
    clearInvoiceOrderSelection()
    closeInvoiceApplyDialog()
    invoiceNotice.value = `已合并提交 ${application.orderCount} 笔在线支付订单，后台会尽快处理。`
  } catch (error) {
    reportPageError('invoice', 'submit-invoice-application', error, {
      orderIds: orders.map((order) => order.id),
      orderCount: orders.length,
    })
    invoiceError.value = getErrorMessage(error, { notFoundMessage: '开票接口暂不可用，请稍后重试。' })
  } finally {
    isInvoiceSubmitting.value = false
  }
}

function getInvoiceDownloadFileName(application: InvoiceApplication) {
  const fallback = `invoice-${application.orderNo || application.id || Date.now()}.pdf`
  const baseName = String(application.pdfName || fallback).split(/[\\/]/).pop() || fallback
  const safeName = baseName.replace(/[<>:"/\\|?*\u0000-\u001f]/g, '_').trim()
  return safeName || fallback
}

function clearInvoiceDownloadAutoCloseTimer() {
  if (invoiceDownloadAutoCloseTimer !== null) {
    window.clearTimeout(invoiceDownloadAutoCloseTimer)
    invoiceDownloadAutoCloseTimer = null
  }
}

function closeInvoiceDownloadDialog() {
  clearInvoiceDownloadAutoCloseTimer()
  invoiceDownloadDialog.value.open = false
}

function scheduleInvoiceDownloadDialogClose(jobId: string) {
  clearInvoiceDownloadAutoCloseTimer()
  invoiceDownloadAutoCloseTimer = window.setTimeout(() => {
    if (invoiceDownloadDialog.value.jobId === jobId) {
      invoiceDownloadDialog.value.open = false
    }
    invoiceDownloadAutoCloseTimer = null
  }, 650)
}

async function downloadInvoicePdf(application?: InvoiceApplication | null) {
  const href = application?.pdfDataUrl || application?.pdfUrl || ''
  if (!href) {
    invoiceError.value = '发票 PDF 暂未上传，请等待后台处理。'
    return
  }

  if (!application || invoiceDownloadingIds.value.includes(application.id)) return
  const desktopDownload = window.gaogeDesktop?.downloadInvoiceFile
  if (!desktopDownload) {
    const link = document.createElement('a')
    link.href = href
    link.download = getInvoiceDownloadFileName(application)
    link.rel = 'noopener'
    document.body.appendChild(link)
    link.click()
    link.remove()
    return
  }

  const jobId = `invoice-download-${Date.now()}-${getRandomText(6)}`
  const fileName = getInvoiceDownloadFileName(application)
  let hasOpenedDialog = false
  invoiceDownloadingIds.value = [...invoiceDownloadingIds.value, application.id]
  invoiceError.value = ''

  try {
    const result = await desktopDownload({ url: href, fileName }, (status) => {
      if (!hasOpenedDialog) {
        hasOpenedDialog = true
        clearInvoiceDownloadAutoCloseTimer()
        invoiceDownloadDialog.value = {
          open: true,
          jobId,
          invoiceId: application.id,
          state: 'downloading',
          fileName: status.fileName || fileName,
          filePath: status.filePath,
          downloadedBytes: status.downloadedBytes,
          totalBytes: status.totalBytes,
          progress: status.progress,
          error: '',
        }
        return
      }
      if (invoiceDownloadDialog.value.jobId !== jobId) return
      invoiceDownloadDialog.value = {
        ...invoiceDownloadDialog.value,
        state: status.state,
        fileName: status.fileName || fileName,
        filePath: status.filePath,
        downloadedBytes: status.downloadedBytes,
        totalBytes: status.totalBytes,
        progress: status.progress,
        error: status.error || '',
      }
      if (status.state === 'completed') {
        scheduleInvoiceDownloadDialogClose(jobId)
      }
    })
    if (result.cancelled) return
    notify(`发票已保存到：${result.filePath}`, 'success', '发票下载完成')
  } catch (error) {
    const message = getErrorMessage(error)
    reportPageError('invoice', 'download-invoice-file', error, {
      invoiceId: application.id,
      orderNo: application.orderNo,
    })
    if (invoiceDownloadDialog.value.jobId === jobId) {
      invoiceDownloadDialog.value = {
        ...invoiceDownloadDialog.value,
        state: 'error',
        error: message,
      }
    }
    notify(message, 'error', '发票下载失败')
  } finally {
    invoiceDownloadingIds.value = invoiceDownloadingIds.value.filter((id) => id !== application.id)
  }
}

function stopPaymentPolling() {
  if (paymentPollTimer !== null) {
    window.clearInterval(paymentPollTimer)
    paymentPollTimer = null
  }
  if (paymentCountdownTimer !== null) {
    window.clearInterval(paymentCountdownTimer)
    paymentCountdownTimer = null
  }
  isPaymentPolling.value = false
}

function clearPaymentPanelDismissTimer() {
  if (paymentPanelDismissTimer !== null) {
    window.clearTimeout(paymentPanelDismissTimer)
    paymentPanelDismissTimer = null
  }
}

function hidePaymentPanel() {
  activePaymentOrder.value = null
  activePaymentCreditAmount.value = 0
  activeRechargeSnapshot.value = null
  paymentQrCode.value = ''
  externalPaymentPageUrl.value = ''
  paymentCountdown.value = 0
  rechargeNotice.value = ''
  rechargeError.value = ''
  activeRechargeFeedback.value = ''
  activePlatformSubscriptionOrderId.value = ''
  activePlatformSubscriptionActivationRequest.value = null
  activePaymentPurpose.value = ''
}

function schedulePaymentPanelDismiss(delay = 3000) {
  clearPaymentPanelDismissTimer()
  paymentPanelDismissTimer = window.setTimeout(() => {
    paymentPanelDismissTimer = null
    hidePaymentPanel()
  }, delay)
}

function startPaymentCountdown(expiresAt?: string) {
  if (paymentCountdownTimer !== null) {
    window.clearInterval(paymentCountdownTimer)
  }

  const fallbackExpiresTime = Date.now() + 5 * 60 * 1000
  const updateCountdown = () => {
    const expiresTime = expiresAt ? new Date(expiresAt).getTime() : fallbackExpiresTime
    paymentCountdown.value = Math.max(0, Math.ceil((expiresTime - Date.now()) / 1000))
  }

  updateCountdown()
  paymentCountdownTimer = window.setInterval(updateCountdown, 1000)
}

function paymentCountdownText() {
  const minutes = Math.floor(paymentCountdown.value / 60)
  const seconds = paymentCountdown.value % 60
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
}

async function refreshActivePaymentOrder(options: { manual?: boolean } = {}) {
  const isManualRefresh = options.manual === true
  const currentOrder = activePaymentOrder.value
  const orderId = getPaymentOrderId(currentOrder)
  const paymentPurpose = activePaymentPurpose.value || 'recharge'
  const currentOwnerId = String(authUser.value?.id || '')
  const currentOfficialContext = activeOfficialSubscriptionRequest.value
  const isPlatformSubscriptionPayment = paymentPurpose === 'platform-subscription'
  const isOfficialSubscriptionPayment = paymentPurpose === 'official-subscription'
  if (!orderId || !authToken.value) {
    if (isManualRefresh) {
      const message = orderId ? '请先登录账户。' : '未找到可刷新的订单。'
      if (isPlatformSubscriptionPayment) platformSubscriptionError.value = message
      else if (isOfficialSubscriptionPayment) officialSubscriptionError.value = message
      else rechargeError.value = message
    }
    return
  }
  if (paymentOrderRefreshInFlight) {
    if (isManualRefresh) {
      if (isPlatformSubscriptionPayment) platformSubscriptionNotice.value = '正在检查订单状态，请稍候。'
      else if (isOfficialSubscriptionPayment) officialSubscriptionNotice.value = '正在检查订单状态，请稍候。'
      else rechargeNotice.value = '正在检查订单状态，请稍候。'
    }
    return
  }
  paymentOrderRefreshInFlight = true
  if (isManualRefresh) {
    isPaymentRefreshing.value = true
    if (isPlatformSubscriptionPayment) {
      platformSubscriptionError.value = ''
      platformSubscriptionNotice.value = '正在检查订单状态...'
    } else if (isOfficialSubscriptionPayment) {
      officialSubscriptionError.value = ''
      officialSubscriptionNotice.value = '正在检查订单状态...'
    } else {
      rechargeError.value = ''
      rechargeNotice.value = '正在检查订单状态...'
    }
  }
  try {
    let order: PaymentOrder | null = null
    const outTradeNo = String(currentOrder?.out_trade_no || '').trim()
    if (outTradeNo) {
      try {
        order = await verifyPaymentOrderByOutTradeNo(outTradeNo, authToken.value)
      } catch (error) {
        reportPageError('payment', 'verify-payment-order', error, {
          orderId,
          outTradeNo,
          purpose: paymentPurpose,
        })
      }
    }
    if (!order) {
      order = await getPaymentOrder(orderId, authToken.value)
    }
    // A late response for A must never inherit B's saved receipt or Session.
    if (getPaymentOrderId(activePaymentOrder.value) !== orderId
      || (activePaymentPurpose.value || 'recharge') !== paymentPurpose
      || String(authUser.value?.id || '') !== currentOwnerId
      || (isOfficialSubscriptionPayment && activeOfficialSubscriptionRequest.value !== currentOfficialContext)) return
    const returnedOrderId = getPaymentOrderId(order)
    if (returnedOrderId && returnedOrderId !== orderId) throw new Error('支付订单响应与当前订单不一致，请重试。')
    const nextOrder = { ...(currentOrder || {}), ...order }
    activePaymentOrder.value = nextOrder
    if (isPlatformSubscriptionPayment) {
      activePlatformSubscriptionActivationRequest.value = buildPlatformSubscriptionActivationRequest(
        nextOrder,
        selectedPlatformPlan.value,
      )
    }
    if (isPaymentCompleted(nextOrder.status)
      || (isOfficialSubscriptionPayment && isOfficialSubscriptionPaidOrder(nextOrder))) {
      stopPaymentPolling()
      persistInvoiceOrder(nextOrder)
      if (isPlatformSubscriptionPayment) {
        const platformOrderId = activePlatformSubscriptionOrderId.value
        if (!platformOrderId) {
          platformSubscriptionNotice.value = ''
          platformSubscriptionError.value = '支付已完成，但未找到平台订阅登记订单，请联系客服处理。'
          notify('平台订阅支付成功，但激活资料缺失。', 'error', '平台订阅')
          return
        }
        try {
          await activatePlatformSubscriptionOrder(
            platformOrderId,
            authToken.value,
            buildPlatformSubscriptionActivationRequest(nextOrder, selectedPlatformPlan.value),
          )
        } catch (error) {
          reportPageError('platform-subscription', 'activate-subscription-order', error, {
            orderId: platformOrderId,
            sub2OrderId: orderId,
          })
          platformSubscriptionNotice.value = '支付已完成，后台会继续自动重试；如果长时间未到账，可以联系售后或后台手动重试。'
          platformSubscriptionError.value = getPlatformSubscriptionActivationErrorMessage(error)
          notify('平台订阅支付成功，但自动激活失败。', 'error', '平台订阅')
          await Promise.allSettled([
            syncCurrentUser(),
            syncUsageDashboardStats({ silent: true }),
          ])
          return
        }
        await Promise.allSettled([
          syncCurrentUser(),
          syncUsageDashboardStats({ silent: true }),
          syncActivePlatformSubscription({ silent: true }),
          syncPlatformSubscriptionSummary({ silent: true }),
        ])
        platformSubscriptionError.value = ''
        platformSubscriptionNotice.value = ''
        activePlatformSubscriptionOrderId.value = ''
        hidePaymentPanel()
        notify('订阅成功，平台每日额度已发放。', 'success', '平台订阅')
      } else if (isOfficialSubscriptionPayment) {
        persistOfficialSubscriptionRecord(nextOrder)
        let sessionSubmitted = false
        try {
          sessionSubmitted = await submitOfficialSubscriptionSessionForOrder(nextOrder)
        } catch (error) {
          reportPageError('official-subscription', 'submit-official-session', error, {
            orderId: getPaymentOrderId(nextOrder),
            planId: activeOfficialSubscriptionRequest.value?.planId,
            account: activeOfficialSubscriptionRequest.value?.account,
          })
        }
        await Promise.allSettled([
          syncCurrentUser(),
          syncUsageDashboardStats({ silent: true }),
        ])
        if (getPaymentOrderId(activePaymentOrder.value) !== orderId
          || String(authUser.value?.id || '') !== currentOwnerId
          || activeOfficialSubscriptionRequest.value !== currentOfficialContext) return
        officialSubscriptionError.value = sessionSubmitted
          ? ''
          : '支付已完成，订阅资料暂未确认接收。资料已保留，请点击刷新状态重试，无需再次付款。'
        officialSubscriptionNotice.value = sessionSubmitted
          ? `已收到 ${activeOfficialSubscriptionRequest.value?.planName || selectedOfficialPlan.value.name} 在线支付，识别账号 ${activeOfficialSubscriptionRequest.value?.account || officialIdentifiedAccountLabel()} 的官方订阅请求已提交，进度已记录为订阅中。`
          : `已收到 ${activeOfficialSubscriptionRequest.value?.planName || selectedOfficialPlan.value.name} 在线支付，但订阅资料暂未上传成功。`
        if (sessionSubmitted) {
          activeOfficialSubscriptionRequest.value = null
          hidePaymentPanel()
          void resumePendingOfficialSubscriptionOrders()
        }
        notify(
          sessionSubmitted ? '官方订阅支付成功，开通请求已提交。' : '官方订阅支付成功，但资料上传失败。',
          sessionSubmitted ? 'success' : 'error',
          '官方订阅',
        )
      } else {
        if (isBackupBridgePaymentOrder(nextOrder)) {
          removePendingRechargeBonusJob(orderId)
          await Promise.allSettled([
            syncCurrentUser(),
            syncUsageDashboardStats({ silent: true }),
          ])
          const creditedAmount = activeRechargeCreditAmount.value || getRechargeHistoryCreditAmount(nextOrder)
          rechargeError.value = ''
          rechargeNotice.value = `支付成功，已到账 ${formatRechargeAmount(Number(creditedAmount))} 刀。`
        } else {
          try {
            const bonusResult = await applyRechargeBonusForOrder(nextOrder)
            await Promise.allSettled([
              syncCurrentUser(),
              syncUsageDashboardStats({ silent: true }),
            ])
            const creditedAmount = bonusResult?.record?.totalCreditAmount || activeRechargeCreditAmount.value
            rechargeError.value = ''
            rechargeNotice.value = bonusResult?.applied
              ? `支付成功，已到账 ${formatRechargeAmount(Number(creditedAmount))} 刀（含赠送 ${formatRechargeAmount(Number(bonusResult.record?.bonusAmount || 0))} 刀）。`
              : `支付成功，已到账 ${formatRechargeAmount(Number(creditedAmount))} 刀。`
          } catch (error) {
            await Promise.allSettled([
              syncCurrentUser(),
              syncUsageDashboardStats({ silent: true }),
            ])
            rechargeError.value = ''
            rechargeNotice.value = isRechargeBonusRetryableError(error)
              ? '支付已完成，基础额度已到账；赠送额度已进入自动补发队列，网络恢复后会继续处理。'
              : `支付已完成，基础额度已到账；赠送额度暂未确认：${getPaymentErrorMessage(error)}`
            schedulePendingRechargeBonusRetry()
          }
        }
        await loadRechargeHistory({ silent: true })
      }
    } else if (isPaymentProcessing(nextOrder.status)) {
      const message = paymentStatusText(nextOrder.status, paymentPurpose)
      if (isPlatformSubscriptionPayment) {
        platformSubscriptionError.value = ''
        platformSubscriptionNotice.value = message
      } else if (isOfficialSubscriptionPayment) {
        officialSubscriptionError.value = ''
        officialSubscriptionNotice.value = message
      } else {
        rechargeError.value = ''
        rechargeNotice.value = message
      }
    } else if (isPaymentClosed(nextOrder.status)) {
      stopPaymentPolling()
      const message = paymentStatusText(nextOrder.status, paymentPurpose)
      if (isPlatformSubscriptionPayment) {
        platformSubscriptionNotice.value = ''
        platformSubscriptionError.value = message
        activePlatformSubscriptionOrderId.value = ''
      } else if (isOfficialSubscriptionPayment) {
        officialSubscriptionNotice.value = ''
        officialSubscriptionError.value = message
        activeOfficialSubscriptionRequest.value = null
      } else {
        removePendingRechargeBonusJob(orderId)
        rechargeNotice.value = ''
        rechargeError.value = message
        void loadRechargeHistory({ silent: true })
      }
    } else if (isManualRefresh) {
      if (isPlatformSubscriptionPayment) platformSubscriptionNotice.value = '已检查，订单仍在等待支付。'
      else if (isOfficialSubscriptionPayment) officialSubscriptionNotice.value = '已检查，订单仍在等待支付。'
      else {
        rechargeNotice.value = '已检查，订单仍在等待支付。'
        void loadRechargeHistory({ silent: true })
      }
    }
  } catch (error) {
    reportPageError('payment', 'poll-payment-order', error)
    if (isPlatformSubscriptionPayment) platformSubscriptionError.value = getPaymentErrorMessage(error)
    else if (isOfficialSubscriptionPayment) officialSubscriptionError.value = getPaymentErrorMessage(error)
    else rechargeError.value = getPaymentErrorMessage(error)
  } finally {
    paymentOrderRefreshInFlight = false
    if (isManualRefresh) isPaymentRefreshing.value = false
  }
}

function startPaymentPolling() {
  stopPaymentPolling()
  isPaymentPolling.value = true
  startPaymentCountdown(activePaymentOrder.value?.expires_at)
  paymentPollTimer = window.setInterval(() => {
    void refreshActivePaymentOrder()
  }, 3000)
}

async function openPaymentPage() {
  const payUrl = activePaymentPageUrl.value
  if (!payUrl) return
  try {
    const validation = validatePaymentLink(payUrl, '支付链接', { required: true })
    if (!validation.ok) throw new Error(validation.message)
    if (window.gaogeDesktop?.openPaymentWindow) {
      await window.gaogeDesktop.openPaymentWindow({ payUrl })
    } else {
      window.open(payUrl, '_blank', 'noopener,noreferrer')
    }
  } catch (error) {
    reportPageError('payment', 'open-payment-page', error)
    if (activePaymentPurpose.value === 'platform-subscription') {
      platformSubscriptionError.value = getPaymentErrorMessage(error)
    } else if (activePaymentPurpose.value === 'official-subscription') {
      officialSubscriptionError.value = getPaymentErrorMessage(error)
    } else {
      rechargeError.value = getPaymentErrorMessage(error)
    }
  }
}

async function renderPaymentOrder(order: PaymentOrder, options: { preferPaymentPage?: boolean } = {}) {
  activePaymentOrder.value = order
  const payUrl = String(order.pay_url || '').trim()
  if (payUrl) {
    const validation = validatePaymentLink(payUrl, '支付链接', { required: true })
    if (!validation.ok) throw new Error(validation.message)
  }
  if (order.qr_code_img) {
    const validation = validatePaymentLink(order.qr_code_img, '支付二维码图片')
    if (!validation.ok) throw new Error(validation.message)
  }
  if (order.qr_code) {
    const validation = validatePaymentLink(order.qr_code, '支付二维码内容')
    if (!validation.ok) throw new Error(validation.message)
  }
  if (options.preferPaymentPage && payUrl) {
    paymentQrCode.value = ''
    externalPaymentPageUrl.value = payUrl
    void openPaymentPage()
  } else if (order.qr_code_img) {
    paymentQrCode.value = order.qr_code_img
  } else if (order.qr_code) {
    paymentQrCode.value = await QRCode.toDataURL(order.qr_code, {
      width: 220,
      margin: 2,
      errorCorrectionLevel: 'M',
    })
  } else if (payUrl) {
    externalPaymentPageUrl.value = payUrl
    void openPaymentPage()
  } else {
    throw new Error('订单创建成功，但未返回支付二维码或支付链接。')
  }
  startPaymentPolling()
  void refreshActivePaymentOrder()
}

async function submitRecharge() {
  if (isRechargeLoading.value) return
  clearPaymentPanelDismissTimer()
  rechargeError.value = ''
  rechargeNotice.value = ''
  activeRechargeFeedback.value = 'payment'
  activePaymentPurpose.value = 'recharge'
  if (!authToken.value) {
    rechargeError.value = '请先登录账户。'
    return
  }
  const option = selectedRechargeOption.value
  if (!option?.id || option.payAmount <= 0) {
    rechargeError.value = onlinePaymentConfigMessage.value || '请选择固定充值金额。'
    return
  }
  const paymentToken = authToken.value
  const paymentContext = getOnlinePaymentRequestContext()
  let createdRechargeOrder: PaymentOrder | null = null
  let rechargeReceiptConfirmed = false
  isRechargeLoading.value = true
  try {
    // A checkout always gets a fresh quote, even if a background read is already pending.
    const config = await loadOnlinePaymentConfig({ silent: true, force: true })
    if (!config || paymentContext !== getOnlinePaymentRequestContext()) {
      rechargeError.value = onlinePaymentConfigMessage.value || '账户或服务器已切换，请确认充值配置后重试。'
      return
    }
    const currentPlan = config.enabled ? config.plans.find((plan) => plan.id === option.id) : undefined
    if (!currentPlan || !sameRechargeQuote(option, currentPlan)) {
      rechargeNotice.value = '充值套餐已更新或停用，请核对当前金额、到账额度和赠送额度后重新选择并支付。'
      return
    }
    stopPaymentPolling()
    paymentQrCode.value = ''
    externalPaymentPageUrl.value = ''
    const quote = getRechargeQuote(currentPlan)
    const snapshot = buildOnlinePaymentSnapshot(option, quote)
    const order = await createPaymentOrder(Number(quote.payAmount.toFixed(2)), paymentToken, {
      onlinePaymentPlanId: currentPlan.id,
    })
    createdRechargeOrder = order
    const orderId = getPaymentOrderId(order)
    if (!orderId) {
      throw new Error('订单创建成功，但未返回订单编号。')
    }
    if (paymentContext !== getOnlinePaymentRequestContext()) {
      throw new Error('账户或服务器已切换，请重新确认后支付。')
    }
    const registration = await registerOnlinePaymentOrderSnapshot({
      sub2OrderId: orderId,
      snapshot,
      userId: authUser.value?.id,
      email: authUser.value?.email || user.value.email,
      username: authUser.value?.username || user.value.name,
    }, paymentToken)
    if (paymentContext !== getOnlinePaymentRequestContext()) {
      throw new Error('账户或服务器已切换，请重新确认后支付。')
    }
    const confirmedSnapshot = requireMatchingRechargeReceipt(registration, snapshot, orderId)
    rechargeReceiptConfirmed = true
    enqueuePendingRechargeBonusJob(orderId, confirmedSnapshot)
    activeRechargeSnapshot.value = confirmedSnapshot
    activePaymentCreditAmount.value = confirmedSnapshot.totalCreditAmount
    await renderPaymentOrder(order)
    void loadRechargeHistory({ silent: true })
    if (order.pay_url && !paymentQrCode.value) {
      rechargeNotice.value = '支付页面已打开，正在等待付款完成。'
    }
  } catch (error) {
    activePaymentOrder.value = null
    activePaymentCreditAmount.value = 0
    activeRechargeSnapshot.value = null
    reportPageError('payment', 'create-payment-order', error)
    rechargeError.value = getPaymentErrorMessage(error)
    const unconfirmedOrderId = !rechargeReceiptConfirmed ? getPaymentOrderId(createdRechargeOrder) : 0
    if (unconfirmedOrderId) {
      paymentQrCode.value = ''
      externalPaymentPageUrl.value = ''
      let cancelled = false
      try {
        await cancelPaymentOrder(unconfirmedOrderId, paymentToken)
        cancelled = true
      } catch (cancelError) {
        reportPageError('payment', 'cancel-unconfirmed-recharge-order', cancelError)
      }
      await loadOnlinePaymentConfig({ silent: true, force: true })
      rechargeError.value = `${getPaymentErrorMessage(error)}${cancelled ? '未付款订单已取消，请核对最新套餐后重试。' : '付款入口已关闭，订单取消尚未确认，请稍后检查充值记录。'}`
    }
  } finally {
    isRechargeLoading.value = false
  }
}

function buildPlatformSubscriptionNoticeDetails(plan: PlatformSubscriptionPlan, actionContext: PlatformSubscriptionActionContext) {
  const details = [
    `您现在订阅的是 ${formatCny(plan.priceAmount)} 的 ${plan.name} 套餐。`,
    `每天是 ${formatPlatformPlanNumber(plan.dailyLimitUsd)} 刀，系统会在每日 00:00 自动充值到自己的账号上。`,
    '没有用完的额度会在每日 24:00 清空。',
    '不可倒卖额度，不可共享额度，后台发现异常会封号处理。',
  ]
  if (actionContext.subscription_action === 'replace') {
    return [
      `当前套餐：${actionContext.current_plan_name || '已开通的平台订阅'}。`,
      `覆盖后新套餐「${plan.name}」会在支付成功后立即生效。`,
      '原套餐不会继续叠加到期时间，请确认后再继续支付。',
      ...details,
    ]
  }
  if (actionContext.current_subscription_id || actionContext.current_plan_id || actionContext.current_group_id) {
    return [
      `当前套餐：${actionContext.current_plan_name || plan.name}。`,
      '本次为同套餐续期，支付成功后只增加到期时间，不会覆盖当前套餐。',
      ...details,
    ]
  }
  return details
}

async function cancelUnregisteredPlatformSubscriptionPaymentOrder(order: PaymentOrder | null) {
  const orderId = getPaymentOrderId(order)
  if (!orderId || !authToken.value) return false
  try {
    await cancelPaymentOrder(orderId, authToken.value)
    return true
  } catch (error) {
    reportPageError('platform-subscription', 'cancel-unregistered-payment-order', error, {
      sub2OrderId: orderId,
      outTradeNo: order?.out_trade_no,
    })
    return false
  }
}

async function confirmPlatformSubscription(plan: PlatformSubscriptionPlan) {
  if (isPlatformSubscribing.value) return
  selectedPlatformPlanId.value = plan.id
  const actionContext = buildPlatformSubscriptionActionContext(plan)
  const isReplace = actionContext.subscription_action === 'replace'
  const confirmed = await confirmAction(
    isReplace
      ? `您当前已有「${actionContext.current_plan_name || '平台订阅'}」，继续订阅「${plan.name}」会覆盖当前套餐。`
      : '请确认本次平台订阅说明。',
    {
      tone: isReplace ? 'warning' : 'info',
      title: isReplace ? '确认覆盖套餐' : '订阅说明',
      details: buildPlatformSubscriptionNoticeDetails(plan, actionContext),
      confirmText: '确定',
      cancelText: '取消',
    },
  )
  if (!confirmed) return
  await submitPlatformSubscription(plan, actionContext)
}

async function submitPlatformSubscription(plan: PlatformSubscriptionPlan, actionContext = buildPlatformSubscriptionActionContext(plan)) {
  clearPaymentPanelDismissTimer()
  selectedPlatformPlanId.value = plan.id
  platformSubscriptionError.value = ''
  platformSubscriptionNotice.value = ''
  activePlatformSubscriptionOrderId.value = ''
  activePlatformSubscriptionActivationRequest.value = null
  activePaymentPurpose.value = 'platform-subscription'
  if (!authToken.value) {
    platformSubscriptionError.value = '请先登录账户。'
    return
  }
  if (!plan.id || plan.priceAmount <= 0 || plan.dailyLimitUsd <= 0) {
    platformSubscriptionError.value = '套餐配置不完整，请联系售后处理。'
    return
  }
  isPlatformSubscribing.value = true
  let createdPaymentOrder: PaymentOrder | null = null
  let cancelledUnregisteredPaymentOrder = false
  let submitStage: PlatformSubscriptionSubmitStage = 'create-payment'
  try {
    stopPaymentPolling()
    paymentQrCode.value = ''
    externalPaymentPageUrl.value = ''
    activePaymentCreditAmount.value = 0
    const owner = await ensurePlatformSubscriptionOwnerParams()
    if (!owner.userId && !owner.email) {
      throw new Error('无法识别当前登录用户，请重新登录后再订阅。')
    }
    const order = await createPaymentOrder(plan.priceAmount, authToken.value, {
      orderType: 'platform_sub',
    })
    createdPaymentOrder = order
    const sub2OrderId = getPaymentOrderId(order)
    if (!sub2OrderId) {
      throw new Error('支付订单创建成功，但没有返回订单编号。')
    }
    const activationRequest = buildPlatformSubscriptionActivationRequest(order, plan, null, actionContext)
    let registeredOrder
    submitStage = 'register-subscription'
    try {
      registeredOrder = await registerPlatformSubscriptionOrder({
        sub2_order_id: sub2OrderId,
        sub2_out_trade_no: order.out_trade_no,
        sub2_order_type: order.order_type || 'platform_sub',
        sub2_recharge_amount: activationRequest.balance_deduction?.amount,
        sub2_pay_amount: getPaymentOrderAmount(order) || plan.priceAmount,
        sub2_payment_status: order.status || 'PENDING',
        subscription_action: activationRequest.subscription_action,
        current_subscription_id: activationRequest.current_subscription_id,
        current_plan_id: activationRequest.current_plan_id,
        current_plan_name: activationRequest.current_plan_name,
        current_group_id: activationRequest.current_group_id,
        target_plan_id: activationRequest.target_plan_id,
        target_plan_name: activationRequest.target_plan_name,
        target_group_id: activationRequest.target_group_id,
        balance_deduction: activationRequest.balance_deduction,
        userId: owner.userId,
        email: owner.email,
        planId: plan.id,
      }, authToken.value)
    } catch (error) {
      cancelledUnregisteredPaymentOrder = await cancelUnregisteredPlatformSubscriptionPaymentOrder(order)
      throw error
    }
    activePlatformSubscriptionOrderId.value = registeredOrder.id
    activePlatformSubscriptionActivationRequest.value = activationRequest
    submitStage = 'render-payment'
    await renderPaymentOrder({
      ...order,
      amount: order.amount || plan.priceAmount,
      pay_amount: order.pay_amount || plan.priceAmount,
      order_type: order.order_type || 'platform_sub',
      subscription_days: order.subscription_days || plan.subscriptionDays,
    }, { preferPaymentPage: true })
    platformSubscriptionNotice.value = activePaymentPageUrl.value && !paymentQrCode.value
      ? '支付页面已打开，正在等待付款完成。'
      : '订阅订单已创建，请扫码完成在线支付。'
  } catch (error) {
    activePaymentOrder.value = null
    activePlatformSubscriptionOrderId.value = ''
    activePlatformSubscriptionActivationRequest.value = null
    reportPageError('platform-subscription', 'create-subscription-order', error, {
      planId: plan.id,
      planVersion: plan.version,
      action: actionContext.subscription_action,
      submitStage,
      sub2OrderId: getPaymentOrderId(createdPaymentOrder),
      cancelledUnregisteredPaymentOrder,
    })
    platformSubscriptionNotice.value = cancelledUnregisteredPaymentOrder
      ? '未生成平台订阅订单，已自动取消本次未支付的在线支付订单。'
      : ''
    platformSubscriptionError.value = getPlatformSubscriptionSubmitErrorMessage(error, actionContext, submitStage)
  } finally {
    isPlatformSubscribing.value = false
  }
}

async function cancelActivePaymentOrder() {
  const orderId = getPaymentOrderId(activePaymentOrder.value)
  const isPlatformSubscriptionPayment = activePaymentPurpose.value === 'platform-subscription'
  const isOfficialSubscriptionPayment = activePaymentPurpose.value === 'official-subscription'
  if (isPlatformSubscriptionPayment) {
    platformSubscriptionError.value = ''
    platformSubscriptionNotice.value = ''
  } else if (isOfficialSubscriptionPayment) {
    officialSubscriptionError.value = ''
    officialSubscriptionNotice.value = ''
  } else {
    rechargeError.value = ''
    rechargeNotice.value = ''
    activeRechargeFeedback.value = 'payment'
    activePaymentPurpose.value = 'recharge'
  }
  if (!orderId) {
    if (isPlatformSubscriptionPayment) platformSubscriptionError.value = '未找到可取消的订单。'
    else if (isOfficialSubscriptionPayment) officialSubscriptionError.value = '未找到可取消的订单。'
    else rechargeError.value = '未找到可取消的订单。'
    return
  }
  if (!authToken.value) {
    if (isPlatformSubscriptionPayment) platformSubscriptionError.value = '请先登录账户。'
    else if (isOfficialSubscriptionPayment) officialSubscriptionError.value = '请先登录账户。'
    else rechargeError.value = '请先登录账户。'
    return
  }

  isPaymentCancelling.value = true
  try {
    const cancelledOrder = await cancelPaymentOrder(orderId, authToken.value)
    stopPaymentPolling()
    paymentCountdown.value = 0
    activePaymentOrder.value = {
      ...(activePaymentOrder.value || { amount: activeRechargePayAmount.value }),
      ...(cancelledOrder || {}),
      status: cancelledOrder?.status || 'CANCELLED',
    }
    if (isPlatformSubscriptionPayment) {
      platformSubscriptionNotice.value = '订单已取消。'
      hidePaymentPanel()
    } else if (isOfficialSubscriptionPayment) {
      officialSubscriptionNotice.value = '订单已取消。'
      activeOfficialSubscriptionRequest.value = null
      hidePaymentPanel()
    } else {
      removePendingRechargeBonusJob(orderId)
      rechargeNotice.value = '订单已取消。'
      void loadRechargeHistory({ silent: true })
      schedulePaymentPanelDismiss()
    }
  } catch (error) {
    reportPageError('payment', 'cancel-payment-order', error)
    if (isPlatformSubscriptionPayment) platformSubscriptionError.value = getPaymentErrorMessage(error)
    else if (isOfficialSubscriptionPayment) officialSubscriptionError.value = getPaymentErrorMessage(error)
    else rechargeError.value = getPaymentErrorMessage(error)
    if (isPlatformSubscriptionPayment || isOfficialSubscriptionPayment) {
      stopPaymentPolling()
      hidePaymentPanel()
    }
  } finally {
    isPaymentCancelling.value = false
  }
}

async function handlePaymentPanelCloseAction() {
  if (canCancelPaymentOrder.value) {
    await cancelActivePaymentOrder()
    return
  }
  stopPaymentPolling()
  hidePaymentPanel()
}

function paymentPanelCloseActionText() {
  if (!canCancelPaymentOrder.value) return '关闭'
  return isPaymentCancelling.value ? '取消中' : '取消支付'
}

function isCodexInstallTerminal(state: GaogeDesktopCodexInstallState) {
  return state === 'idle' || state === 'done' || state === 'cancelled' || state === 'error' || state === 'unsupported'
}

async function loadCodexInstallStatus() {
  if (!window.gaogeDesktop?.getCodexInstallStatus) return
  try {
    const status = await window.gaogeDesktop.getCodexInstallStatus()
    codexInstallStatus.value = status
    isCodexInstalling.value = !isCodexInstallTerminal(status.state)
  } catch (error) {
    reportPageError('system-config', 'load-codex-install-status', error)
    codexInstallStatus.value = { ...codexInstallStatus.value, state: 'error', error: getInstallErrorMessage(error) }
  }
}

async function cancelCodexInstall() {
  if (!window.gaogeDesktop?.cancelCodexInstall) return
  isCodexCancelling.value = true
  try {
    codexInstallStatus.value = await window.gaogeDesktop.cancelCodexInstall()
  } catch (error) {
    reportPageError('system-config', 'cancel-codex-install', error)
    codexInstallStatus.value = { ...codexInstallStatus.value, state: 'error', error: getInstallErrorMessage(error) }
  } finally {
    isCodexCancelling.value = false
    isCodexInstalling.value = !isCodexInstallTerminal(codexInstallStatus.value.state)
  }
}

function showCodexManualInstallDialog() {
  void confirmAction('云端下载流量已用完，暂时无法直接下载安装包。', {
    tone: 'info',
    title: 'Codex 安装包下载',
    details: [
      '请从官方渠道或当前服务提供方获取 Codex 安装包。',
      ...(MIGRATION_SUPPORT_GROUP ? [`支持群：${MIGRATION_SUPPORT_GROUP}`] : []),
    ],
    confirmText: '知道了',
    cancelText: '',
  })
}

async function loadUpdateStatus(options: { silent?: boolean } = {}) {
  if (!window.gaogeDesktop?.getUpdateStatus) {
    if (options.silent) return
    updateStatus.value = {
      ...updateStatus.value,
      state: 'disabled',
      canCheck: false,
      error: '当前环境无法读取客户端版本。',
    }
    return
  }
  try {
    updateStatus.value = await window.gaogeDesktop.getUpdateStatus()
  } catch (error) {
    reportPageError('client-update', 'load-update-status', error)
    if (!options.silent) {
      updateStatus.value = { ...updateStatus.value, error: getUpdateErrorMessage(error), message: '客户端更新状态读取失败。' }
    }
  }
}

function shouldShowUpdatePrompt(status: GaogeDesktopUpdateStatus, source: 'auto' | 'manual' = 'manual') {
  if (status.forceUpdate) {
    if (status.state === 'disabled' || status.state === 'idle' || status.state === 'not-available') return false
    return true
  }
  if (status.state === 'error' && status.error) {
    return source === 'manual' || isMacReadOnlyUpdateError(status.error)
  }
  if (!status.downloaded && status.state !== 'downloading') return false
  const latestVersion = status.latestVersion || status.version
  return !latestVersion || updateDialogDismissedVersion.value !== latestVersion
}

function openUpdateDialog() {
  showUpdateDialog.value = true
}

function closeUpdateDialog() {
  if (isForceUpdateRequired.value) {
    showUpdateDialog.value = true
    return
  }
  const latestVersion = updateStatus.value.latestVersion || updateStatus.value.version
  updateDialogDismissedVersion.value = latestVersion
  showUpdateDialog.value = false
}

async function installDownloadedUpdate() {
  if (!window.gaogeDesktop?.installUpdate) {
    updateStatus.value = {
      ...updateStatus.value,
      state: 'disabled',
      canCheck: false,
      error: '当前环境无法安装客户端更新。',
    }
    return
  }
  isUpdateInstalling.value = true
  try {
    const result = await window.gaogeDesktop.installUpdate()
    if (!result.installing) {
      isUpdateInstalling.value = false
      updateStatus.value = {
        ...updateStatus.value,
        error: '更新包尚未准备好，请重新检测更新。',
      }
      return
    }
    if (result.restarting) {
      updateStatus.value = {
        ...updateStatus.value,
        state: 'restarting',
        downloaded: false,
        progress: 100,
        error: '',
        message: updateStatus.value.message || '更新已安装完成，应用正在重启。',
      }
    }
  } catch (error) {
    reportPageError('client-update', 'install-update', error)
    updateStatus.value = {
      ...updateStatus.value,
      state: 'error',
      downloaded: false,
      error: getUpdateErrorMessage(error),
      message: getUpdateErrorMessage(error),
    }
    openUpdateDialog()
    isUpdateInstalling.value = false
  }
}

async function checkForClientUpdates(source: 'auto' | 'manual' = 'manual') {
  if (updateStatus.value.state === 'checking' || updateStatus.value.state === 'downloading') return
  if (updateStatus.value.downloaded) {
    openUpdateDialog()
    return
  }
  if (!window.gaogeDesktop?.checkForUpdates) {
    updateStatus.value = {
      ...updateStatus.value,
      state: 'disabled',
      canCheck: false,
      error: '当前环境无法检测更新。',
    }
    return
  }
  updateCheckSource.value = source
  try {
    updateStatus.value = await window.gaogeDesktop.checkForUpdates()
    if (shouldShowUpdatePrompt(updateStatus.value, source)) {
      openUpdateDialog()
    }
  } catch (error) {
    reportPageError('client-update', 'check-for-updates', error)
    const message = getUpdateErrorMessage(error)
    updateStatus.value = {
      ...updateStatus.value,
      error: source === 'manual' || isMacReadOnlyUpdateError(message) ? message : '',
      message: source === 'manual' ? '检测更新失败。' : '',
    }
    if (source === 'manual' || isMacReadOnlyUpdateError(message)) {
      openUpdateDialog()
    }
  } finally {
    updateCheckSource.value = ''
  }
}

async function handleUpdateAction() {
  if (updateStatus.value.downloaded) {
    await installDownloadedUpdate()
    return
  }
  await checkForClientUpdates('manual')
}

async function handleUpdateDialogPrimary() {
  if (updateStatus.value.downloaded) {
    await installDownloadedUpdate()
    return
  }
  await checkForClientUpdates('manual')
}

function scheduleStartupUpdateCheck() {
  if (updateAutoCheckStarted || !window.gaogeDesktop?.checkForUpdates) return
  updateAutoCheckStarted = true
  updateAutoCheckTimer = window.setTimeout(() => {
    updateAutoCheckTimer = null
    if (updateStatus.value.downloaded) {
      openUpdateDialog()
      return
    }
    void checkForClientUpdates('auto')
  }, 1800)
}

async function runSystemConfigAction(label: string) {
  if (label === '同步会话') {
    await toggleSetting('sessionSync')
  } else if (label === '官方插件') {
    await toggleSetting('plugins')
  } else if (label === '删除会话') {
    await toggleSetting('sessionDelete')
  } else if (label === 'Codex 主题') {
    openCodexThemeDialog()
  } else if (label === '强制中文' || label === '中文设置') {
    await toggleSetting('language')
  } else if (label === '安装 Codex') {
    if (isCodexInstalling.value) await cancelCodexInstall()
    else if (codexInstallStatus.value.state === 'done') await loadCodexInstallStatus()
    else showCodexManualInstallDialog()
  }
}

function formatInteger(value: number) {
  return Math.round(Number(value || 0)).toLocaleString('en-US')
}

function formatCompactNumber(value: number) {
  const number = Number(value || 0)
  if (number >= 1_000_000) return `${(number / 1_000_000).toFixed(1)}M`
  if (number >= 1_000) return `${(number / 1_000).toFixed(1)}K`
  return formatInteger(number)
}

function formatUsageSummaryTokens(value: number) {
  const number = Number(value || 0)
  const absoluteNumber = Math.abs(number)
  const units = [
    { threshold: 1_000_000_000, suffix: 'B' },
    { threshold: 1_000_000, suffix: 'M' },
    { threshold: 1_000, suffix: 'K' },
  ]
  const unit = units.find((item) => absoluteNumber >= item.threshold)
  if (!unit) return formatInteger(number)
  const compactValue = Math.round((number / unit.threshold) * 100) / 100
  return `${compactValue.toLocaleString('en-US', { maximumFractionDigits: 2 })}${unit.suffix}`
}

function formatMoney(value: number, precision = 2) {
  return `$${Number(value || 0).toFixed(precision)}`
}

function formatCny(value: number, precision = 2) {
  return `¥${Number(value || 0).toFixed(precision)}`
}

function formatPlainAmount(value: number, precision = 2) {
  return Number(value || 0).toFixed(precision).replace(/\.?0+$/, '')
}

function normalizeSmsReceiverStatus(status?: string) {
  return String(status || '').trim().toLowerCase()
}

function isSmsReceiverServiceInProject(service: SmsReceiverServiceItem, project: SmsReceiverProjectKey) {
  const haystack = [
    service.key,
    service.name,
    service.keyword,
    service.lubanServiceName,
    service.notes,
  ].map((value) => String(value || '').toLowerCase()).join(' ')
  if (project === 'gmail') {
    return ['gmail', 'google', '谷歌', '邮箱'].some((keyword) => haystack.includes(keyword))
  }
  return ['gpt', 'openai', 'chatgpt'].some((keyword) => haystack.includes(keyword))
}

function isSmsReceiverOrderClosed(order: SmsReceiverOrder) {
  const status = normalizeSmsReceiverStatus(order.status)
  return order.cancelled === true || smsReceiverClosedStatuses.includes(status)
}

function readSmsReceiverOrderString(order: SmsReceiverOrder, keys: string[]) {
  const payload = order as SmsReceiverOrder & Record<string, unknown>
  for (const key of keys) {
    const value = payload[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
    if (typeof value === 'number' && Number.isFinite(value)) return String(value)
  }
  const sms = payload.sms
  if (sms && typeof sms === 'object' && !Array.isArray(sms)) {
    const smsPayload = sms as Record<string, unknown>
    for (const key of keys) {
      const value = smsPayload[key]
      if (typeof value === 'string' && value.trim()) return value.trim()
      if (typeof value === 'number' && Number.isFinite(value)) return String(value)
    }
  }
  return ''
}

function readSmsReceiverPayloadString(payload: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const value = payload[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
    if (typeof value === 'number' && Number.isFinite(value)) return String(value)
  }
  return ''
}

function extractSmsReceiverCodeFromText(text: string) {
  const normalized = String(text || '').trim()
  if (!normalized) return ''
  const preferred = normalized.match(/(?:\u9a8c\u8bc1\u7801|\u9a8c\u8bc1\u4ee3\u7801|\u6821\u9a8c\u7801|\u52a8\u6001\u7801|verification\s*code|verify\s*code|code|otp)[^\d]{0,24}(\d{4,8})/i)
  if (preferred?.[1]) return preferred[1]
  const fallback = normalized.match(/\b\d{4,8}\b/)
  return fallback?.[0] || ''
}

function isSmsReceiverPlaceholderText(text: string) {
  const normalized = String(text || '').trim().toLowerCase()
  if (!normalized) return true
  if (/^\d+$/.test(normalized)) return false
  if (extractSmsReceiverCodeFromText(normalized)) return false
  return [
    '等待候取',
    '等待获取',
    '等待短信',
    '等待接收',
    '等待中',
    '待获取',
    '待接收',
    '处理中',
    '已取号',
    '未收到',
    '暂无短信',
    '没有短信',
    '查询成功',
    '查询完成',
    '请求成功',
    '请求完成',
    '操作成功',
    '获取成功',
    '已收到验证码',
    '验证码已收到',
    '短信已收到',
    '还需',
    '可以取消',
    '暂不能取消',
    '上游暂',
    '取消',
    '退款',
    '失败',
    '超时',
    'wait',
    'waiting',
    'pending',
    'processing',
    'no sms',
    'not received',
    'success',
  ].some((keyword) => normalized.includes(keyword))
}

function normalizeSmsReceiverVerificationCode(value: string) {
  const normalized = String(value || '').trim()
  if (!normalized) return ''
  if (/^\d{4,8}$/.test(normalized)) return normalized
  return extractSmsReceiverCodeFromText(normalized)
}

function getSmsReceiverOrderRawText(order: SmsReceiverOrder) {
  const payload = order as SmsReceiverOrder & Record<string, unknown>
  const topLevelText = readSmsReceiverPayloadString(payload, ['smsText', 'sms_text', 'text', 'content', 'body'])
  const smsPayload = payload.sms
  const nestedText = smsPayload && typeof smsPayload === 'object' && !Array.isArray(smsPayload)
    ? readSmsReceiverPayloadString(smsPayload as Record<string, unknown>, ['text', 'smsText', 'sms_text', 'content', 'body', 'message', 'msg'])
    : typeof smsPayload === 'string'
      ? smsPayload.trim()
      : ''
  const explicitText = topLevelText || nestedText
  if (explicitText) return explicitText
  const genericMessage = readSmsReceiverPayloadString(payload, ['message', 'msg'])
  return extractSmsReceiverCodeFromText(genericMessage) ? genericMessage : ''
}

function getSmsReceiverOrderCode(order: SmsReceiverOrder) {
  const code = normalizeSmsReceiverVerificationCode(readSmsReceiverOrderString(order, [
    'smsCode',
    'sms_code',
    'verificationCode',
    'verification_code',
    'verifyCode',
    'verify_code',
    'otp',
    'code',
  ]))
  if (code && !isSmsReceiverPlaceholderText(code)) return code
  const text = getSmsReceiverOrderRawText(order)
  if (isSmsReceiverPlaceholderText(text)) return ''
  return extractSmsReceiverCodeFromText(text)
}

function getSmsReceiverOrderMessage(order: SmsReceiverOrder) {
  const text = getSmsReceiverOrderRawText(order)
  if (text && !isSmsReceiverPlaceholderText(text)) return text
  return getSmsReceiverOrderCode(order)
}

function isSmsReceiverOrderReceived(order: SmsReceiverOrder) {
  return Boolean(getSmsReceiverOrderMessage(order))
}

function inferSmsReceiverReceivedAt(order: SmsReceiverOrder, fallback = Date.now()) {
  const payload = order as SmsReceiverOrder & Record<string, unknown>
  return parseTimestampMillis(payload.receivedAt) ||
    parseTimestampMillis(payload.received_at) ||
    parseTimestampMillis(payload.updatedAt) ||
    parseTimestampMillis(payload.updated_at) ||
    parseTimestampMillis(payload.createdAt) ||
    parseTimestampMillis(payload.created_at) ||
    fallback
}

function withSmsReceiverReceivedAt(order: SmsReceiverOrder, previous?: SmsReceiverOrder): SmsReceiverOrder {
  const mergedOrder = {
    ...(previous || {}),
    ...order,
  }
  if (!isSmsReceiverOrderReceived(mergedOrder)) return mergedOrder
  const previousReceivedAt = previous ? parseTimestampMillis(previous.receivedAt) : null
  return {
    ...mergedOrder,
    receivedAt: previousReceivedAt || inferSmsReceiverReceivedAt(order, Date.now()),
  }
}

function formatSmsReceiverReceivedTime(order: SmsReceiverOrder) {
  const receivedAt = inferSmsReceiverReceivedAt(order, 0)
  return receivedAt > 0 ? formatFullTime(new Date(receivedAt).toISOString()) : '-'
}

function shouldDisplaySmsReceiverOrder(order: SmsReceiverOrder) {
  if (isSmsReceiverOrderClosed(order)) return false
  return isSmsReceiverOrderReceived(order) || Boolean(order.number && order.number !== '-')
}

function normalizeSmsReceiverOrdersForDisplay(orders: SmsReceiverOrder[], previousOrders = smsReceiverOrders.value) {
  const previousById = new Map(previousOrders.map((order) => [order.id, order]))
  return orders
    .map((order) => withSmsReceiverReceivedAt(order, previousById.get(order.id)))
    .filter(shouldDisplaySmsReceiverOrder)
}

function getSmsReceiverOptionCountry(option: SmsReceiverOption) {
  return option.countryNameZh || option.countryNameEn || option.country || '未知国家'
}

function getSmsReceiverOptionKey(option: SmsReceiverOption) {
  return [
    option.serviceKey,
    option.serviceId,
    option.country,
    option.provider,
    option.costUsd,
  ].map((value) => String(value ?? '').trim()).join(':')
}

function getSmsReceiverOrderCountry(order: SmsReceiverOrder) {
  const option = smsReceiverOptions.value.find((item) => (
    item.country === order.country ||
    item.serviceKey === order.service ||
    item.serviceId === order.serviceId
  ))
  return option ? getSmsReceiverOptionCountry(option) : (order.country || '未知国家')
}

function getSmsReceiverServiceName(serviceKey?: string) {
  const service = smsReceiverEnabledServices.value.find((item) => item.key === serviceKey)
  return service?.name || smsReceiverProjectOptions.find((item) => item.key === serviceKey)?.label || serviceKey || '短信服务'
}

function formatSmsReceiverPrice(value: number | null | undefined) {
  const amount = Number(value || 0)
  if (!Number.isFinite(amount)) return '0.00 刀'
  return `${amount.toFixed(2)} 刀`
}

function formatSmsReceiverCancelWait(order: SmsReceiverOrder) {
  const seconds = Number(order.cancelRemainingSeconds || 0)
  if (!Number.isFinite(seconds) || seconds <= 0) return ''
  if (seconds >= 60) {
    return `上游暂不能取消，约 ${Math.ceil(seconds / 60)} 分钟后再试`
  }
  return `上游暂不能取消，约 ${Math.ceil(seconds)} 秒后再试`
}

function formatSmsReceiverOrderWaitingText(_order: SmsReceiverOrder) {
  return '等待短信中'
}

function setSmsReceiverNotice(
  message: string,
  tone: NotificationTone = 'info',
  title = '短信接码',
) {
  smsReceiverNotice.value = message
  notify(message, tone, title)
}

function isSmsReceiverOrderRefunded(order: SmsReceiverOrder) {
  const payload = order as SmsReceiverOrder & Record<string, unknown>
  const statusText = [
    order.status,
    order.refundStatus,
    order.lubanCancelStatus,
    payload.refund_status,
    payload.luban_cancel_status,
  ].map((value) => String(value || '').toLowerCase()).join(' ')
  return ['refunded', 'refund_success', 'refund success', '退款成功', '已退款'].some((marker) => statusText.includes(marker))
}

function getSmsReceiverClosedNotice(order: SmsReceiverOrder, options: { automatic?: boolean } = {}) {
  const number = order.number || '当前号码'
  const action = options.automatic ? '已自动取消' : '已取消'
  return isSmsReceiverOrderRefunded(order)
    ? `号码 ${number} ${action}，扣费已退回。`
    : `号码 ${number} ${action}，退款余额正在同步。`
}

function mergeSmsReceiverOrder(order: SmsReceiverOrder) {
  const existingIndex = smsReceiverOrders.value.findIndex((item) => item.id === order.id)
  if (existingIndex === -1) {
    smsReceiverOrders.value = normalizeSmsReceiverOrdersForDisplay([order, ...smsReceiverOrders.value])
    return
  }
  const nextOrders = [...smsReceiverOrders.value]
  nextOrders[existingIndex] = order
  smsReceiverOrders.value = normalizeSmsReceiverOrdersForDisplay(nextOrders)
}

function getSmsReceiverUserId() {
  return String(authUser.value?.id || authUser.value?.email || user.value.email || 'desktop-user')
}

function createSmsReceiverClientOrderId(option: SmsReceiverOption) {
  const randomId = globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`
  return [
    'gaoge-desktop',
    getSmsReceiverUserId(),
    option.serviceKey,
    option.serviceId,
    option.country,
    Date.now(),
    randomId,
  ]
    .map((part) => String(part || '').trim().replace(/[^a-zA-Z0-9_-]+/g, '-'))
    .filter(Boolean)
    .join('-')
    .slice(0, 160)
}

function getSmsReceiverCountryRequestValue(country = smsReceiverSelectedCountry.value) {
  const keyword = smsReceiverCountrySearch.value.trim()
  if (!keyword) return ''
  if (!country) return keyword

  const normalizedKeyword = keyword.toLowerCase()
  const countryTokens = [
    country.nameZh,
    country.nameEn,
    country.code,
    country.id,
  ].map((value) => String(value || '').trim().toLowerCase())

  return countryTokens.includes(normalizedKeyword) ? country.nameZh : keyword
}

function toggleSmsReceiverPriceSort() {
  smsReceiverPriceSort.value = smsReceiverPriceSort.value === 'asc' ? 'desc' : 'asc'
}

function selectSmsReceiverCountry(country: LubanSmsCountry) {
  smsReceiverSelectedCountryId.value = country.id
  smsReceiverCountrySearch.value = country.nameZh
  isSmsReceiverCountryDropdownOpen.value = false
  smsReceiverOptions.value = []
  void loadSmsReceiverOptions()
}

function applySmsReceiverCountrySearch() {
  const keyword = smsReceiverCountrySearch.value.trim()
  if (!keyword) {
    smsReceiverSelectedCountryId.value = ''
    isSmsReceiverCountryDropdownOpen.value = false
    smsReceiverOptions.value = []
    void loadSmsReceiverOptions(smsReceiverSelectedService.value, '')
    return
  }

  const country = smsReceiverFilteredCountries.value[0]
  if (country) {
    selectSmsReceiverCountry(country)
    return
  }
  smsReceiverSelectedCountryId.value = ''
  isSmsReceiverCountryDropdownOpen.value = false
  void loadSmsReceiverOptions(smsReceiverSelectedService.value, keyword)
}

function ensureSmsReceiverSelectedService() {
  const services = smsReceiverProjectServices.value
  if (!services.length) return
  if (!services.some((service) => service.key === smsReceiverSelectedService.value)) {
    smsReceiverSelectedService.value = services[0].key
  }
}

function stopSmsReceiverPolling() {
  if (smsReceiverPollTimer !== null) {
    window.clearInterval(smsReceiverPollTimer)
    smsReceiverPollTimer = null
  }
}

function stopSmsReceiverCleanupTimer() {
  if (smsReceiverCleanupTimer !== null) {
    window.clearInterval(smsReceiverCleanupTimer)
    smsReceiverCleanupTimer = null
  }
}

function startSmsReceiverCleanupTimer() {
  stopSmsReceiverCleanupTimer()
  if (activePage.value !== '短信接码台') return
  smsReceiverCleanupTimer = window.setInterval(() => {
    void syncSmsReceiverOrderStatuses({ notifyClosed: true })
  }, SMS_RECEIVER_STATUS_SYNC_INTERVAL_MS)
}

function startSmsReceiverPolling() {
  stopSmsReceiverPolling()
  if (activePage.value !== '短信接码台' || !smsReceiverPollingOrders.value.length) return
  const intervalSeconds = Math.max(3, Number(smsReceiverConfig.value?.pollIntervalSeconds || 8))
  smsReceiverPollTimer = window.setInterval(() => {
    void pollSmsReceiverActiveOrders(true)
  }, intervalSeconds * 1000)
}

async function syncSmsReceiverOrderStatuses(options: { notifyClosed?: boolean } = {}) {
  if (!authToken.value || activePage.value !== '短信接码台' || smsReceiverStatusSyncInFlight) return [] as string[]
  smsReceiverStatusSyncInFlight = true
  const previousWaitingOrders = [...smsReceiverActiveOrders.value]
  try {
    const serverOrders = await listSmsReceiverOrders(authToken.value)
    const serverOrdersById = new Map(serverOrders.map((order) => [order.id, order]))
    const newlyReceivedOrders = previousWaitingOrders
      .map((order) => serverOrdersById.get(order.id))
      .filter((order): order is SmsReceiverOrder => Boolean(order && isSmsReceiverOrderReceived(order) && !isSmsReceiverOrderClosed(order)))
    const closedOrders = previousWaitingOrders
      .filter((order) => {
        const updated = serverOrdersById.get(order.id)
        return !updated || isSmsReceiverOrderClosed(updated)
      })
      .map((order) => serverOrdersById.get(order.id) || order)

    smsReceiverOrders.value = normalizeSmsReceiverOrdersForDisplay(serverOrders)

    if (newlyReceivedOrders.length) {
      const latest = newlyReceivedOrders[0]
      setSmsReceiverNotice(
        newlyReceivedOrders.length === 1
          ? `号码 ${latest.number || ''} 已收到短信。`
          : `${newlyReceivedOrders.length} 个号码已收到短信。`,
        'success',
        '验证码已收到',
      )
    }

    await syncCurrentUser({ silent: true })

    if (closedOrders.length) {
      if (options.notifyClosed) {
        const latest = closedOrders[0]
        setSmsReceiverNotice(
          closedOrders.length === 1
            ? getSmsReceiverClosedNotice(latest, { automatic: true })
            : `${closedOrders.length} 个未收到短信的号码已自动取消，退款余额已同步。`,
          'info',
          '号码已自动取消',
        )
      }
    }

    startSmsReceiverPolling()
    return closedOrders.map((order) => order.id)
  } catch (error) {
    reportPageError('sms-receiver', 'sync-order-statuses', error)
    return [] as string[]
  } finally {
    smsReceiverStatusSyncInFlight = false
  }
}

async function loadSmsReceiverOptions(service = smsReceiverSelectedService.value, country = getSmsReceiverCountryRequestValue()) {
  if (!authToken.value) {
    smsReceiverError.value = '请先登录账户。'
    return
  }
  const requestSeq = ++smsReceiverOptionsRequestSeq
  isSmsReceiverOptionsLoading.value = true
  smsReceiverError.value = ''
  try {
    const options = await listSmsReceiverOptions(authToken.value, {
      service,
      country: country.trim(),
      pages: country.trim() ? 1 : 8,
      language: 'zh',
      sort: smsReceiverPriceSort.value === 'desc' ? 'price_desc' : 'price_asc',
    })
    if (requestSeq !== smsReceiverOptionsRequestSeq) return
    smsReceiverOptions.value = options
  } catch (error) {
    if (requestSeq !== smsReceiverOptionsRequestSeq) return
    reportPageError('sms-receiver', 'load-options', error, { service, country })
    smsReceiverError.value = getSmsReceiverErrorMessage(error, { notFoundMessage: '暂未找到可接码国家。' })
  } finally {
    if (requestSeq === smsReceiverOptionsRequestSeq) {
      isSmsReceiverOptionsLoading.value = false
    }
  }
}

async function loadSmsReceiverOrders() {
  if (!authToken.value) {
    smsReceiverError.value = '请先登录账户。'
    return
  }
  isSmsReceiverOrdersLoading.value = true
  try {
    const orders = await listSmsReceiverOrders(authToken.value)
    smsReceiverOrders.value = normalizeSmsReceiverOrdersForDisplay(orders)
    await syncCurrentUser({ silent: true })
    startSmsReceiverCleanupTimer()
    startSmsReceiverPolling()
  } catch (error) {
    reportPageError('sms-receiver', 'load-orders', error)
    smsReceiverError.value = getSmsReceiverErrorMessage(error, { notFoundMessage: '暂未找到接码记录。' })
  } finally {
    isSmsReceiverOrdersLoading.value = false
  }
}

async function loadSmsReceiverDesk() {
  if (!authToken.value) {
    smsReceiverError.value = '请先登录账户。'
    return
  }
  isSmsReceiverLoading.value = true
  smsReceiverError.value = ''
  try {
    const [config, services, orders] = await Promise.all([
      getSmsReceiverConfig(authToken.value),
      listSmsReceiverServices(authToken.value),
      listSmsReceiverOrders(authToken.value),
    ])
    smsReceiverConfig.value = config
    smsReceiverServices.value = services
    smsReceiverOrders.value = normalizeSmsReceiverOrdersForDisplay(orders)
    await syncCurrentUser({ silent: true })
    ensureSmsReceiverSelectedService()
    await loadSmsReceiverOptions(smsReceiverSelectedService.value, getSmsReceiverCountryRequestValue())
    startSmsReceiverCleanupTimer()
    startSmsReceiverPolling()
  } catch (error) {
    reportPageError('sms-receiver', 'load-desk', error)
    smsReceiverError.value = getSmsReceiverErrorMessage(error, { notFoundMessage: '短信接码服务暂未配置。' })
  } finally {
    isSmsReceiverLoading.value = false
  }
}

function selectSmsReceiverProject(project: SmsReceiverProjectKey) {
  if (smsReceiverSelectedProject.value === project) return
  smsReceiverSelectedProject.value = project
  smsReceiverOptions.value = []
  ensureSmsReceiverSelectedService()
  void loadSmsReceiverOptions()
}

async function requestSmsReceiverOption(option: SmsReceiverOption) {
  if (!authToken.value) {
    smsReceiverError.value = '请先登录账户。'
    return
  }
  if (smsReceiverRequestingServiceKey.value) {
    smsReceiverError.value = '已有取号请求正在处理中，请稍候。'
    return
  }
  const optionKey = getSmsReceiverOptionKey(option)
  const serviceId = String(option.serviceId || '').trim()
  const serviceName = String(option.serviceName || option.lubanServiceName || option.serviceKey || '').trim()
  const lubanServiceName = String(option.lubanServiceName || option.serviceName || '').trim()
  const countryNameZh = String(option.countryNameZh || '').trim()
  const countryNameEn = String(option.countryNameEn || '').trim()
  const countryName = String(countryNameEn || countryNameZh || option.country || '').trim()
  if (!serviceId) {
    smsReceiverNotice.value = ''
    smsReceiverError.value = '接码服务编号缺失，请刷新国家列表后再取号。'
    return
  }
  smsReceiverRequestingServiceKey.value = optionKey
  smsReceiverError.value = ''
  smsReceiverNotice.value = ''
  try {
    const order = await requestSmsReceiverNumber({
      userId: getSmsReceiverUserId(),
      service: option.serviceKey,
      serviceKey: option.serviceKey,
      serviceName,
      lubanServiceName,
      serviceId,
      service_id: serviceId,
      country: countryName,
      countryNameZh,
      countryNameEn,
      countryCode: option.country,
      costUsd: option.costUsd,
      provider: option.provider,
      language: 'en',
      clientOrderId: createSmsReceiverClientOrderId(option),
      client: 'gaogeaii-desktop',
    }, authToken.value)
    mergeSmsReceiverOrder(order)
    setSmsReceiverNotice(`已取号：${order.number || '等待号码返回'}。`, 'success', '取号成功')
    startSmsReceiverPolling()
  } catch (error) {
    reportPageError('sms-receiver', 'request-number', error, {
      service: option.serviceKey,
      serviceName,
      lubanServiceName,
      country: countryName || option.country,
      countryNameZh,
      countryNameEn,
      serviceId,
      provider: option.provider,
    })
    smsReceiverError.value = getSmsReceiverErrorMessage(error, { notFoundMessage: '未获取号码' })
  } finally {
    if (smsReceiverRequestingServiceKey.value === optionKey) {
      smsReceiverRequestingServiceKey.value = ''
    }
  }
}

async function pollSmsReceiverOrder(order: SmsReceiverOrder, silent = false) {
  if (!authToken.value || !order.id) return
  const previousOrder = smsReceiverOrders.value.find((item) => item.id === order.id) || order
  const wasReceived = isSmsReceiverOrderReceived(previousOrder)
  smsReceiverPollingOrderId.value = order.id
  if (!silent) {
    smsReceiverError.value = ''
    smsReceiverNotice.value = ''
  }
  try {
    const updated = await pollSmsReceiverCode(order.id, authToken.value)
    const isReceived = isSmsReceiverOrderReceived(updated)
    const isClosed = isSmsReceiverOrderClosed(updated)
    mergeSmsReceiverOrder(updated)
    if (isClosed) {
      await syncCurrentUser({ silent: true })
      setSmsReceiverNotice(getSmsReceiverClosedNotice(updated, { automatic: true }), 'info', '号码已自动取消')
    } else if (isReceived && !wasReceived) {
      setSmsReceiverNotice(`号码 ${updated.number || order.number || ''} 已收到短信。`, 'success', '验证码已收到')
    } else if (!silent) {
      setSmsReceiverNotice(`号码 ${updated.number || order.number || ''} 暂未收到短信，系统会继续自动刷新。`, 'info', '仍在等待短信')
    }
  } catch (error) {
    reportPageError('sms-receiver', 'poll-code', error, { orderId: order.id })
    const closedOrderIds = await syncSmsReceiverOrderStatuses({ notifyClosed: true })
    if (!silent && !closedOrderIds.includes(order.id)) {
      smsReceiverError.value = getSmsReceiverErrorMessage(error, { notFoundMessage: '短信记录暂未找到。' })
    }
  } finally {
    smsReceiverPollingOrderId.value = ''
    startSmsReceiverPolling()
  }
}

async function pollSmsReceiverActiveOrders(silent = true) {
  if (smsReceiverPollInFlight || !smsReceiverPollingOrders.value.length) return
  smsReceiverPollInFlight = true
  try {
    for (const order of smsReceiverPollingOrders.value) {
      await pollSmsReceiverOrder(order, silent)
    }
  } finally {
    smsReceiverPollInFlight = false
  }
}

async function cancelSmsReceiverOrder(order: SmsReceiverOrder) {
  if (!authToken.value || !order.id) return
  smsReceiverCancellingOrderId.value = order.id
  smsReceiverError.value = ''
  smsReceiverNotice.value = ''
  try {
    const updated = await cancelSmsReceiverNumber(order.id, authToken.value)
    mergeSmsReceiverOrder(updated)
    const cancelWaitMessage = formatSmsReceiverCancelWait(updated)
    if (isSmsReceiverOrderClosed(updated)) {
      await syncCurrentUser({ silent: true })
      setSmsReceiverNotice(getSmsReceiverClosedNotice(updated), 'success', '号码已取消')
    } else if (cancelWaitMessage) {
      setSmsReceiverNotice(cancelWaitMessage, 'info', '暂不能取消')
    } else {
      setSmsReceiverNotice('上游暂未取消成功，请稍后再试。', 'warning', '取消未完成')
    }
    startSmsReceiverPolling()
  } catch (error) {
    reportPageError('sms-receiver', 'cancel-number', error, { orderId: order.id })
    smsReceiverError.value = getSmsReceiverErrorMessage(error, { notFoundMessage: '当前号码暂无法取消。' })
  } finally {
    smsReceiverCancellingOrderId.value = ''
  }
}

function formatFileSize(value: number) {
  const bytes = Math.max(0, Number(value || 0))
  if (bytes >= 1024 * 1024 * 1024) return `${(bytes / 1024 / 1024 / 1024).toFixed(2)} GB`
  if (bytes >= 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`
  if (bytes >= 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${Math.round(bytes)} B`
}

function safeString(value: unknown) {
  return typeof value === 'string' ? value.trim() : ''
}

function finiteNumberOrNull(value: unknown) {
  const number = Number(value)
  return Number.isFinite(number) ? number : null
}

function parseTimestampMillis(value: unknown) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.abs(value) < 10_000_000_000 ? value * 1000 : value
  }
  if (typeof value === 'string') {
    const trimmed = value.trim()
    if (!trimmed) return null
    const numeric = Number(trimmed)
    if (Number.isFinite(numeric)) return Math.abs(numeric) < 10_000_000_000 ? numeric * 1000 : numeric
    const parsed = Date.parse(trimmed)
    if (Number.isFinite(parsed)) return parsed
  }
  return null
}

function timestampSecondsOrNull(value: unknown) {
  const millis = parseTimestampMillis(value)
  return typeof millis === 'number' ? Math.floor(millis / 1000) : null
}

function formatFullTime(value: string | number | Date | null | undefined) {
  const date = value instanceof Date ? value : new Date(value || '')
  if (Number.isNaN(date.getTime())) return '-'
  return date.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  })
}

function formatUnixTime(value?: number | string | null) {
  const millis = parseTimestampMillis(value)
  return typeof millis === 'number' ? formatFullTime(millis) : '未获取'
}

function normalizeUsageWindow(value: unknown): GaogeDesktopCodexUsageWindow | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const source = value as Record<string, unknown>
  return {
    usedPercent: finiteNumberOrNull(source.usedPercent),
    remainingPercent: finiteNumberOrNull(source.remainingPercent),
    windowMinutes: finiteNumberOrNull(source.windowMinutes),
    resetsAt: timestampSecondsOrNull(source.resetsAt),
  }
}

function normalizeTokenStatus(value: unknown): GaogeDesktopCodexAccountTokenStatus {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return { code: 'unknown' }
  }
  const source = value as Record<string, unknown>
  return {
    code: safeString(source.code) || 'unknown',
    accessTokenExpiresAt: timestampSecondsOrNull(source.accessTokenExpiresAt),
    idTokenExpiresAt: timestampSecondsOrNull(source.idTokenExpiresAt),
    hasRefreshToken: typeof source.hasRefreshToken === 'boolean' ? source.hasRefreshToken : false,
  }
}

function normalizeCodexAccount(value: unknown): GaogeDesktopCodexAccount | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null
  const source = value as CodexAccountRaw
  const accountKey = safeString(source.accountKey)
  if (!accountKey) return null
  return {
    accountKey,
    userId: safeString(source.userId),
    accountId: safeString(source.accountId),
    organizationId: safeString(source.organizationId),
    email: safeString(source.email),
    alias: safeString(source.alias),
    accountName: safeString(source.accountName),
    workspaceName: safeString(source.workspaceName),
    profileName: safeString(source.profileName),
    plan: safeString(source.plan),
    authMode: safeString(source.authMode),
    hasActiveSubscription: Boolean(source.hasActiveSubscription),
    subscriptionExpiresAt: timestampSecondsOrNull(source.subscriptionExpiresAt),
    subscriptionWillRenew: typeof source.subscriptionWillRenew === 'boolean' ? source.subscriptionWillRenew : null,
    createdAt: timestampSecondsOrNull(source.createdAt),
    lastUsedAt: timestampSecondsOrNull(source.lastUsedAt),
    primaryWindow: normalizeUsageWindow(source.primaryWindow),
    secondaryWindow: normalizeUsageWindow(source.secondaryWindow),
    usageSource: safeString(source.usageSource),
    tokenStatus: normalizeTokenStatus(source.tokenStatus),
    hasFullSessionJson: source.hasFullSessionJson === true,
    loginState: safeString(source.loginState),
    requiresReauth: source.requiresReauth === true,
    reauthReason: safeString(source.reauthReason),
    canSwitch: source.canSwitch !== false,
    isLiveCurrent: source.isLiveCurrent === true,
    isActive: Boolean(source.isActive),
  }
}

function normalizeCodexAccountList(value: unknown) {
  if (!Array.isArray(value)) return []
  const byDedupeKey = new Map<string, GaogeDesktopCodexAccount>()
  const dedupeKeys: string[] = []
  value
    .map(normalizeCodexAccount)
    .forEach((account) => {
      if (!account) return false
      const dedupeKey = account.accountKey
      const existing = byDedupeKey.get(dedupeKey)
      if (!existing) {
        byDedupeKey.set(dedupeKey, account)
        dedupeKeys.push(dedupeKey)
        return
      }
      if (
        (!existing.isActive && account.isActive) ||
        (!existing.hasFullSessionJson && account.hasFullSessionJson)
      ) {
        byDedupeKey.set(dedupeKey, account)
      }
    })
  return dedupeKeys
    .map((key) => byDedupeKey.get(key))
    .filter((account): account is GaogeDesktopCodexAccount => Boolean(account))
}

function normalizeCodexAccountsState(value: unknown): GaogeDesktopCodexAccountsState {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Partial<GaogeDesktopCodexAccountsState> & Record<string, unknown>
    : {}
  const accounts = normalizeCodexAccountList(source.accounts)
  const current = normalizeCodexAccount(source.currentAccount)
  const activeAccountKey = safeString(source.activeAccountKey) || current?.accountKey || ''
  return {
    authPath: safeString(source.authPath),
    registryPath: safeString(source.registryPath),
    activeAccountKey,
    savedActiveAccountKey: safeString(source.savedActiveAccountKey),
    currentAccount: current
      ? accounts.find((account) => account.accountKey === current.accountKey) || current
      : accounts.find((account) => account.isActive) || null,
    accounts,
  }
}

function formatDuration(value?: number | null) {
  if (value == null) return '-'
  const duration = Number(value)
  if (!Number.isFinite(duration)) return '-'
  if (duration < 1000) return `${Math.max(0, duration).toFixed(0)}ms`
  return `${(duration / 1000).toFixed(2)}s`
}

function formatVisibleKey(key: string, visible: boolean) {
  if (!key) return '未读取'
  if (visible) return key
  if (key.length <= 12) return '••••••••'
  return `${key.slice(0, 6)}••••••••${key.slice(-4)}`
}

function formatApiKeyStatus(status?: string) {
  const normalized = String(status || '').toLowerCase()
  if (normalized === 'active') return '可用'
  if (normalized === 'inactive') return '已停用'
  if (normalized === 'quota_exhausted') return '额度耗尽'
  if (normalized === 'expired') return '已过期'
  return status || '未知'
}

function toUsageDetailRow(row: UsageLog): UsageDetailRow {
  const inputTokens = Number(row.input_tokens || 0)
  const outputTokens = Number(row.output_tokens || 0)
  const cacheWriteTokens = Number(row.cache_creation_tokens || 0)
  const cacheReadTokens = Number(row.cache_read_tokens || 0)
  const totalTokens = inputTokens + outputTokens + cacheWriteTokens + cacheReadTokens
  const inputCost = Number(row.input_cost || 0)
  const outputCost = Number(row.output_cost || 0)
  const cacheWriteCost = Number(row.cache_creation_cost || 0)
  const cacheReadCost = Number(row.cache_read_cost || 0)
  const originalCost = Number(row.total_cost || 0)
  const billedCost = Number(row.actual_cost ?? row.total_cost ?? 0)
  return {
    apiKey: row.api_key?.name || '默认',
    model: row.model || '-',
    token: formatInteger(totalTokens),
    tokenInput: formatCompactNumber(inputTokens),
    tokenOutput: formatCompactNumber(outputTokens),
    tokenCache: formatCompactNumber(cacheWriteTokens + cacheReadTokens),
    tokenLines: [
      { label: '输入 Token', value: formatInteger(inputTokens) },
      { label: '输出 Token', value: formatInteger(outputTokens) },
      { label: '缓存写入 Token', value: formatInteger(cacheWriteTokens) },
      { label: '缓存读取 Token', value: formatInteger(cacheReadTokens) },
      { label: '总 Token', value: formatInteger(totalTokens), accent: true },
    ],
    cost: formatMoney(billedCost, 6),
    costLines: [
      { label: '输入成本', value: formatMoney(inputCost, 6) },
      { label: '输出成本', value: formatMoney(outputCost, 6) },
      { label: '缓存写入成本', value: formatMoney(cacheWriteCost, 6) },
      { label: '缓存读取成本', value: formatMoney(cacheReadCost, 6) },
      { label: '原始费用', value: formatMoney(originalCost, 6) },
      { label: '计费费用', value: formatMoney(billedCost, 6), accent: true },
    ],
    firstToken: formatDuration(row.first_token_ms),
    duration: formatDuration(row.duration_ms),
    time: formatFullTime(row.created_at),
  }
}

function codexUsageRemainingPercent(windowInfo?: GaogeDesktopCodexUsageWindow | null) {
  if (typeof windowInfo?.remainingPercent === 'number') {
    return Math.min(Math.max(windowInfo.remainingPercent, 0), 100)
  }
  if (typeof windowInfo?.usedPercent === 'number') {
    return Math.min(Math.max(100 - windowInfo.usedPercent, 0), 100)
  }
  return null
}

function codexUsagePercentText(windowInfo?: GaogeDesktopCodexUsageWindow | null) {
  const remaining = codexUsageRemainingPercent(windowInfo)
  return typeof remaining === 'number' ? `${remaining.toFixed(0)}%` : '-'
}

function formatResetCountdown(resetsAt?: number | null) {
  if (!resetsAt) return '暂无重置信息'
  const seconds = Math.max(0, Math.ceil(resetsAt - Date.now() / 1000))
  if (seconds <= 0) return '正在重置'
  if (seconds < 3600) return `剩余 ${Math.ceil(seconds / 60)} 分`
  if (seconds < 86400) {
    const hours = Math.floor(seconds / 3600)
    const minutes = Math.ceil((seconds % 3600) / 60)
    return minutes > 0 ? `剩余 ${hours} 小时 ${minutes} 分` : `剩余 ${hours} 小时`
  }
  const days = Math.floor(seconds / 86400)
  const hours = Math.floor((seconds % 86400) / 3600)
  return hours > 0 ? `剩余 ${days} 天 ${hours} 小时` : `剩余 ${days} 天`
}

function formatCodexUsageResetDetail(windowInfo?: GaogeDesktopCodexUsageWindow | null) {
  if (!windowInfo?.resetsAt) return '暂无重置信息'
  const resetAt = new Date(windowInfo.resetsAt * 1000)
  const resetText = resetAt.toLocaleString('zh-CN', {
    month: 'numeric',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  })
  return `${resetText} 重置 | ${formatResetCountdown(windowInfo.resetsAt)}`
}

function accountMetersFromCodexAccount(account?: GaogeDesktopCodexAccount | null): AccountMeter[] {
  const primary = codexUsageRemainingPercent(account?.primaryWindow)
  const secondary = codexUsageRemainingPercent(account?.secondaryWindow)
  return [
    {
      label: '5小时',
      value: typeof primary === 'number' ? `${primary.toFixed(0)}%` : '-',
      detail: formatCodexUsageResetDetail(account?.primaryWindow),
      progress: primary ?? 0,
      tone: 'rose',
    },
    {
      label: '1周',
      value: typeof secondary === 'number' ? `${secondary.toFixed(0)}%` : '-',
      detail: formatCodexUsageResetDetail(account?.secondaryWindow),
      progress: secondary ?? 0,
      tone: 'emerald',
    },
  ]
}

function formatCodexPlan(account: GaogeDesktopCodexAccount) {
  const rawPlan = String(account.plan || '').trim()
  const normalizedPlan = rawPlan.toLowerCase().replace(/[\s_-]+/g, '')
  if (normalizeOfficialSubscriptionPlan(rawPlan) === 'pro25x') return '25x Pro'
  if (normalizeOfficialSubscriptionPlan(rawPlan) === 'pro20x') return '10x Pro'
  if (normalizedPlan === 'chatgptpro5x' || normalizedPlan === 'pro5x' || normalizedPlan === '5xpro') return '5x Pro'
  if (normalizedPlan.includes('plus')) return 'Plus'
  if (normalizedPlan.includes('pro')) return 'Pro'
  if (normalizedPlan.includes('free')) return 'Free'
  return rawPlan || (account.hasActiveSubscription ? 'Pro' : 'Free')
}

function codexSubscriptionStatus(account: GaogeDesktopCodexAccount) {
  return account.hasActiveSubscription ? '有效订阅' : '无有效订阅'
}

function formatCodexSubscriptionExpiresAt(account: GaogeDesktopCodexAccount) {
  return account.subscriptionExpiresAt ? formatUnixTime(account.subscriptionExpiresAt) : '未获取'
}

function toggleSidebar() {
  isCollapsed.value = !isCollapsed.value
  openUserMenu.value = false
  activeUtilityPanel.value = ''
}

function toggleUtilityPanel(panel: Exclude<UtilityPanel, ''>) {
  const nextPanel = activeUtilityPanel.value === panel ? '' : panel
  activeUtilityPanel.value = nextPanel
  feedbackNotice.value = ''
  openUserMenu.value = false
  if (nextPanel === 'contact') {
    void loadDesktopContact()
  } else if (nextPanel === 'announcement') {
    void loadDesktopAnnouncements()
  }
}

function getDesktopContactIcon(icon?: string): LucideIcon {
  const normalized = String(icon || '').trim().toLowerCase()
  if (['clock', 'time', 'service-time'].includes(normalized)) return Clock
  if (['headphones', 'support', 'customer-service', 'service'].includes(normalized)) return Headphones
  return MessageSquareText
}

function resolveDesktopAssetUrl(url?: string) {
  const value = String(url || '').trim()
  if (!value) return ''
  if (/^(https?:)?\/\//i.test(value) || value.startsWith('data:') || value.startsWith('blob:')) return value
  const normalizedPath = value.startsWith('/') ? value : `/${value}`
  return `${getSoftwareAdminOrigin()}${normalizedPath}`
}

function normalizeDesktopContactItem(item: DesktopContactItem): ContactItemView | null {
  const label = String(item.title || '').trim()
  const value = String(item.content || '').trim()
  const imageUrl = resolveDesktopAssetUrl(item.imageUrl || item.image_url)
  if (!label && !value && !imageUrl) return null
  return {
    id: String(item.id || label || value || `contact-${Date.now()}`).trim(),
    label: label || '联系方式',
    value: value || '-',
    detail: String(item.description || '').trim(),
    imageUrl,
    icon: getDesktopContactIcon(item.icon),
  }
}

function normalizeDesktopAnnouncementItem(item: DesktopAnnouncementItem): ClientAnnouncementView | null {
  const title = String(item.title || '').trim()
  const detail = String(item.detail || item.content || '').trim()
  if (!title && !detail) return null
  const rawTime = String(item.time || item.updatedAt || '').trim()
  const parsedTime = parseTimestampMillis(rawTime)
  return {
    id: String(item.id || [title, rawTime, detail].filter(Boolean).join('|') || 'announcement').trim(),
    title: title || '公告',
    detail,
    time: typeof parsedTime === 'number' ? formatFullTime(parsedTime) : rawTime,
  }
}

function normalizeDesktopAnnouncementItems(payload: DesktopAnnouncementsResponse | null) {
  return Array.isArray(payload?.items)
    ? payload.items
      .map(normalizeDesktopAnnouncementItem)
      .filter((item): item is ClientAnnouncementView => Boolean(item))
    : []
}

async function loadDesktopContact() {
  if (isDesktopContactLoading.value) return
  isDesktopContactLoading.value = true
  try {
    desktopContactPayload.value = await getDesktopContact(authToken.value)
  } catch (error) {
    reportPageError('topbar-contact', 'load-desktop-contact', error)
  } finally {
    isDesktopContactLoading.value = false
  }
}

async function loadDesktopAnnouncements() {
  if (isDesktopAnnouncementsLoading.value) return
  isDesktopAnnouncementsLoading.value = true
  try {
    desktopAnnouncementsPayload.value = await getDesktopAnnouncements(authToken.value)
  } catch (error) {
    reportPageError('topbar-announcement', 'load-desktop-announcements', error)
  } finally {
    isDesktopAnnouncementsLoading.value = false
  }
}

function showNextAnnouncementPopup() {
  if (activeAnnouncementPopup.value || pendingAnnouncementPopups.value.length === 0) return
  const [nextAnnouncement, ...remainingAnnouncements] = pendingAnnouncementPopups.value
  pendingAnnouncementPopups.value = remainingAnnouncements
  activeAnnouncementPopup.value = nextAnnouncement
}

function queueUnreadAnnouncements(announcements: ClientAnnouncementView[]) {
  const readIds = readAnnouncementReadIds()
  const alreadyQueuedIds = new Set([
    ...(activeAnnouncementPopup.value ? [activeAnnouncementPopup.value.id] : []),
    ...pendingAnnouncementPopups.value.map((item) => item.id),
  ])
  const unreadItems = announcements.filter((item) => (
    item.id &&
    !readIds.has(item.id) &&
    !alreadyQueuedIds.has(item.id)
  ))
  if (unreadItems.length === 0) return
  pendingAnnouncementPopups.value = [...pendingAnnouncementPopups.value, ...unreadItems]
  showNextAnnouncementPopup()
}

async function checkUnreadDesktopAnnouncements() {
  if (!isNewThemeAuthenticated.value || desktopAnnouncementPollInFlight) return
  desktopAnnouncementPollInFlight = true
  try {
    const payload = await getDesktopAnnouncements(authToken.value)
    desktopAnnouncementsPayload.value = payload
    queueUnreadAnnouncements(normalizeDesktopAnnouncementItems(payload))
  } catch (error) {
    reportPageError('topbar-announcement', 'poll-desktop-announcements', error)
  } finally {
    desktopAnnouncementPollInFlight = false
  }
}

function startDesktopAnnouncementPolling() {
  if (desktopAnnouncementPollTimer !== null) return
  void checkUnreadDesktopAnnouncements()
  desktopAnnouncementPollTimer = window.setInterval(() => {
    void checkUnreadDesktopAnnouncements()
  }, ANNOUNCEMENT_POLL_INTERVAL_MS)
}

function stopDesktopAnnouncementPolling() {
  if (desktopAnnouncementPollTimer !== null) {
    window.clearInterval(desktopAnnouncementPollTimer)
    desktopAnnouncementPollTimer = null
  }
  desktopAnnouncementPollInFlight = false
  activeAnnouncementPopup.value = null
  pendingAnnouncementPopups.value = []
}

function dismissAnnouncementPopup() {
  activeAnnouncementPopup.value = null
  showNextAnnouncementPopup()
}

function markActiveAnnouncementRead() {
  const announcement = activeAnnouncementPopup.value
  if (!announcement?.id) {
    dismissAnnouncementPopup()
    return
  }
  const readIds = readAnnouncementReadIds()
  readIds.add(announcement.id)
  writeAnnouncementReadIds(readIds)
  activeAnnouncementPopup.value = null
  showNextAnnouncementPopup()
}

function storePendingFeedback(payload: SubmitDesktopFeedbackRequest) {
  const pendingFeedback = {
    ...payload,
    id: payload.id || `feedback-${Date.now()}`,
    createdAt: new Date().toISOString(),
  }
  const raw = localStorage.getItem('gaoge_desktop_pending_feedback')
  let queue: unknown[] = []
  try {
    queue = raw ? JSON.parse(raw) as unknown[] : []
  } catch {
    queue = []
  }
  localStorage.setItem('gaoge_desktop_pending_feedback', JSON.stringify([pendingFeedback, ...queue].slice(0, 20)))
}

async function submitClientFeedback() {
  const content = feedbackContent.value.trim()
  if (!content) {
    feedbackNotice.value = '请先填写反馈内容。'
    return
  }
  if (isFeedbackSubmitting.value) return

  const payload: SubmitDesktopFeedbackRequest = {
    id: `feedback-${Date.now()}`,
    type: feedbackType.value,
    content,
    contact: feedbackContact.value.trim(),
    page: activePage.value,
    user: user.value.email || user.value.name,
    userId: authUser.value?.id,
    email: authUser.value?.email || user.value.email,
    clientVersion: updateVersionText.value,
    version: updateVersionText.value,
    platform: typeof navigator !== 'undefined' ? navigator.platform : '',
    os: typeof navigator !== 'undefined' ? navigator.userAgent : '',
  }

  isFeedbackSubmitting.value = true
  try {
    await submitDesktopFeedback(payload, authToken.value)
    feedbackContent.value = ''
    feedbackNotice.value = '反馈已提交，感谢您的建议。'
  } catch (error) {
    storePendingFeedback(payload)
    feedbackContent.value = ''
    feedbackNotice.value = '暂时无法连接反馈服务，已先为您暂存在本地。'
    reportPageError('topbar-feedback', 'submit-desktop-feedback', error, { feedbackType: payload.type })
  } finally {
    isFeedbackSubmitting.value = false
  }
}

function splitTutorialParagraphs(value?: string) {
  return String(value || '')
    .split(/\r?\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
}

function getTutorialSearchText(section: TutorialSectionView) {
  return [
    section.title,
    section.description,
  ].join(' ')
}

function normalizeTutorialSearchValue(value: string) {
  return value.toLowerCase().replace(/\s+/g, '')
}

function getTutorialSearchTokens(value: string) {
  const raw = value.trim().toLowerCase()
  if (!raw) return []
  const compactTokens = raw.match(/[a-z0-9]+|[\u4e00-\u9fff]+/g) || []
  const spacedTokens = raw.split(/\s+/)
  return Array.from(new Set([...spacedTokens, ...compactTokens]
    .map((token) => normalizeTutorialSearchValue(token))
    .filter(Boolean)))
}

function doesTutorialMatchSearch(section: TutorialSectionView, tokens: string[]) {
  const searchText = normalizeTutorialSearchValue(getTutorialSearchText(section))
  return tokens.every((token) => searchText.includes(token))
}

function getTutorialCardSummary(section: TutorialSectionView) {
  return section.description || section.paragraphs[0] || section.items[0] || '点击查看教程内容。'
}

function selectMigrationTutorial(title: string) {
