}

async function loadMigrationSupportQrCode() {
  migrationSupportQrCode.value = migrationSupportQrImage
}

function normalizeTutorialSection(section: DesktopTutorialSection): TutorialSectionView | null {
  const title = String(section.title || '').trim()
  const description = String(section.description || section.summary || '').trim()
  const content = String(section.content || section.body || '').trim()
  const paragraphs = splitTutorialParagraphs(content)
  const items = Array.isArray(section.items)
    ? section.items.map((item) => String(item || '').trim()).filter(Boolean)
    : []
  const images: TutorialImageView[] = Array.isArray(section.images)
    ? section.images.reduce<TutorialImageView[]>((result, image) => {
      const src = String(image.src || image.url || '').trim()
      if (!src) return result
      const alt = String(image.alt || image.caption || title || '教程配图').trim()
      const caption = String(image.caption || '').trim()
      result.push(caption ? { src, alt, caption } : { src, alt })
      return result
    }, [])
    : []
  if (!title && paragraphs.length === 0 && items.length === 0 && images.length === 0) return null
  return {
    title: title || '教程内容',
    description,
    paragraphs,
    items,
    images,
  }
}

function normalizeTutorialPage(payload: DesktopTutorialResponse | null): TutorialPageView {
  if (!payload || typeof payload !== 'object') return defaultTutorial
  const remoteSections = Array.isArray(payload.sections)
    ? payload.sections.map(normalizeTutorialSection).filter((section): section is TutorialSectionView => Boolean(section))
    : []
  const content = String(payload.content || payload.markdown || '').trim()
  const contentSections: TutorialSectionView[] = content
    ? [{
      title: '教程内容',
      description: '',
      paragraphs: splitTutorialParagraphs(content),
      items: [],
      images: [],
    }]
    : []
  const extraSections = remoteSections.length > 0 ? remoteSections : contentSections
  if (extraSections.length === 0) return defaultTutorial

  return {
    title: String(payload.title || defaultTutorial.title).trim(),
    subtitle: String(payload.subtitle || payload.description || defaultTutorial.subtitle).trim(),
    updatedAt: String(payload.updatedAt || payload.updated_at || '后台同步').trim(),
    source: '内置 + 后台教程',
    sections: [...defaultTutorial.sections, ...extraSections],
  }
}

async function loadTutorialPage() {
  tutorialError.value = ''
  isTutorialLoading.value = true
  try {
    tutorialPayload.value = await getDesktopTutorial(authToken.value)
  } catch (error) {
    reportPageError('tutorial', 'load-desktop-tutorial', error)
    tutorialPayload.value = null
  } finally {
    isTutorialLoading.value = false
  }
}

function toggleGroup(title: string) {
  if (isCollapsed.value) {
    isCollapsed.value = false
    openGroups.value[title] = true
    return
  }

  openGroups.value[title] = !openGroups.value[title]
}

function isProjectActive(project: ProjectItem) {
  return activePage.value === (project.page || project.name) ||
    Boolean(project.items?.some((item) => item.page === activePage.value))
}

function handleProjectClick(project: ProjectItem) {
  if (project.items?.length) {
    toggleGroup(project.name)
  }
  setPage(project.page || project.name)
}

function setPage(page: string) {
  if (activePage.value !== page) {
    stopCodexUltraStatusCheck()
    codexFuelAccountCheckGeneration += 1
    isCodexFuelAccountChecking.value = false
  }
  activePage.value = page
  if (page === '安装插件') pluginMarketRestartRequested.value = false
  if (page === '仪表盘') {
    startDashboardAutoRefresh()
  } else {
    stopDashboardAutoRefresh()
  }
  loginModelsNotice.value = ''
  loginModelsError.value = ''
  if (page === '聚合登录') {
    aggregateLoginError.value = ''
    aggregateLoginNotice.value = ''
  }
  toolLatencyErrors.value = { codex: '', claude: '' }
  toolLatencyNotices.value = { codex: '', claude: '' }
  const loginPanel = loginPanels.value[page]
  const loginTool: ToolKey | null = page === '已有账号加油' || page === '无账号登录'
    ? 'codex'
    : page === '使用 Claude'
      ? 'claude'
      : null
  if (loginPanel) {
    if (loginTool) syncSelectedLoginModelForTool(loginTool)
    updateSelectedGroups()
    if (loginTool === 'codex') void loadCodexRouterStatus({ silent: true })
  }
  if (page === '账号管理' || page === '已有账号加油') {
    void loadCodexAccounts()
  } else if (page === '系统配置') {
    syncRuntimeServerState()
    void loadCodexLanguageSettings({ silent: true })
    void loadCodexPluginsStatus({ silent: true })
    void loadCodexSessionDeleteStatus({ silent: true })
    void loadCodexLaunchTarget({ silent: true })
    if (runtimeServers.value.some((server) => server.status.status === 'idle')) {
      void testRuntimeServerList({ silent: true })
    }
  } else if (page === '官方订阅') {
    startOfficialSubscriptionPriceRefresh()
    void loadCodexAccounts({ silent: true }).then(() => ensureOfficialSelectedAccount())
  } else if (page === 'Gaoge-平台订阅') {
    void loadPlatformSubscriptionPlans()
    void refreshPlatformSubscriptionInfo({ silent: true })
  } else if (page === '官方订阅信息') {
    openGroups.value['codex-官方订阅'] = true
    startOfficialSubscriptionPriceRefresh()
    void refreshOfficialSubscriptionInfo()
  } else if (page === '平台订阅信息') {
    openGroups.value['Gaoge-平台订阅'] = true
    void loadPlatformSubscriptionPlans()
    void refreshPlatformSubscriptionInfo({ silent: true })
  } else if (page === '仪表盘') {
    void refreshDashboardSnapshot({ force: true })
  } else if (page === '使用明细') {
    void syncUsage({ silent: true, force: true })
  } else if (page === '短信接码台') {
    void loadSmsReceiverDesk()
  } else if (page === '在线充值-兑换') {
    startOnlinePaymentConfigRefresh()
    void loadRechargeHistory()
    void resumePendingRechargeBonusQueue({ force: true })
  } else if (page === '自定义接入') {
    void loadCompatibleAccessKeys()
  } else if (page === '使用教程') {
    void loadTutorialPage()
  } else if (page === '发票管理') {
    loadInvoiceLocalData()
    invoiceError.value = ''
    invoiceNotice.value = ''
    void syncInvoiceApplications()
  } else if (page === '项目外包') {
    projectOutsourcingError.value = ''
    projectOutsourcingNotice.value = ''
    void syncProjectOutsourcingRecords()
  } else if (page === '我的邀请') {
    void loadInvitationData()
  }
  if (page !== '短信接码台') {
    stopSmsReceiverPolling()
    stopSmsReceiverCleanupTimer()
  }
  if (!isOfficialSubscriptionPage(page)) {
    stopOfficialSubscriptionPriceRefresh()
  }
  if (!isOnlinePaymentPage(page)) {
    stopOnlinePaymentConfigRefresh()
  }
  if (loginPanel) {
    void syncGroups({ silent: true }).then(async () => {
      if (activePage.value !== page || !loginPanels.value[activePage.value]) return
      if (loginTool) syncSelectedLoginModelForTool(loginTool)
      updateSelectedGroups()
      if (loginTool === 'codex') await refreshCodexModels()
    })
  } else if (page === '聚合登录') {
    void loadAggregateLoginStatus({ silent: true })
    void syncGroups({ silent: true }).then(async () => {
      if (activePage.value !== '聚合登录') return
      await refreshAggregateModels()
    })
  }
  openUserMenu.value = false
  activeUtilityPanel.value = ''
}

function handleWindowFocus() {
  if (!isNewThemeAuthenticated.value) return
  if (activePage.value === '系统配置') void loadCodexLanguageSettings({ silent: true })
  refreshAuthSessionIfNeeded('focus')
  void loadCodexRouterStatus({ silent: true })
  void checkUnreadDesktopAnnouncements()
  if (loginPanels.value[activePage.value]) {
    void syncGroups({ silent: true })
    return
  }
  if (activePage.value === '聚合登录') {
    void syncGroups({ silent: true }).then(() => refreshAggregateModels())
    return
  }
  if (activePage.value === '短信接码台') {
    void loadSmsReceiverOrders()
  }
  if (activePage.value === '在线充值-兑换') {
    void refreshOnlinePaymentConfigInBackground()
    void resumePendingRechargeBonusQueue({ force: true })
  }
  if (isOfficialSubscriptionPage()) {
    void refreshOfficialSubscriptionPricesInBackground()
  }
  if (activePage.value === 'Gaoge-平台订阅' || activePage.value === '平台订阅信息') {
    void loadPlatformSubscriptionPlans()
    void refreshPlatformSubscriptionInfo({ silent: true })
  }
  if (activePage.value === '发票管理') {
    void syncInvoiceApplications({ silent: true })
  }
  if (activePage.value === '项目外包') {
    void syncProjectOutsourcingRecords({ silent: true })
  }
}

function resetRefreshStateAfterWindowRestore() {
  isUsageLoading.value = false
  isCodexAccountsLoading.value = false
  dashboardRefreshInFlight = false
  usageSyncGeneration += 1
  codexAccountsLoadGeneration += 1
  if (codexAccountsRetryTimer !== null) {
    window.clearTimeout(codexAccountsRetryTimer)
    codexAccountsRetryTimer = null
  }
  stopDashboardAutoRefresh()
  if (activePage.value === '仪表盘') {
    startDashboardAutoRefresh()
  }
}

function refreshCurrentPageAfterWindowRestore() {
  if (!isNewThemeAuthenticated.value) return
  if (activePage.value === '系统配置') void loadCodexLanguageSettings({ silent: true })
  resetRefreshStateAfterWindowRestore()
  void resumePendingRechargeBonusQueue({ force: true })
  void resumePendingOfficialSubscriptionOrders()

  void Promise.allSettled([
    loadCodexRouterStatus({ silent: true }),
    loadCodexSessionStats(),
    loadCodexAccounts({ silent: true, force: true, refreshSnapshots: true }),
    checkUnreadDesktopAnnouncements(),
  ])

  if (activePage.value === '短信接码台') {
    void loadSmsReceiverOrders()
  } else if (isOfficialSubscriptionPage()) {
    void refreshOfficialSubscriptionPricesInBackground()
    void refreshOfficialSubscriptionInfo()
  } else if (activePage.value === 'Gaoge-平台订阅' || activePage.value === '平台订阅信息') {
    void loadPlatformSubscriptionPlans()
    void refreshPlatformSubscriptionInfo({ silent: true })
  } else if (activePage.value === '发票管理') {
    void syncInvoiceApplications({ silent: true })
  } else if (activePage.value === '项目外包') {
    void syncProjectOutsourcingRecords({ silent: true })
  }
}

function handleMainWindowRestored() {
  if (mainWindowRestoreRefreshTimer !== null) {
    window.clearTimeout(mainWindowRestoreRefreshTimer)
  }
  mainWindowRestoreRefreshTimer = window.setTimeout(() => {
    mainWindowRestoreRefreshTimer = null
    refreshCurrentPageAfterWindowRestore()
  }, 100)
}

function handleDocumentPointerDown(event: PointerEvent) {
  const target = event.target
  if (!(target instanceof Node)) return
  if (!userMenuRef.value?.contains(target)) {
    openUserMenu.value = false
  }
  if (!utilityPanelRef.value?.contains(target)) {
    activeUtilityPanel.value = ''
  }
  if (!smsReceiverCountryFieldRef.value?.contains(target)) {
    isSmsReceiverCountryDropdownOpen.value = false
  }
}

function handleDocumentKeydown(event: KeyboardEvent) {
  if (event.key !== 'Escape') return
  if (isCodexThemeDialogOpen.value) {
    closeCodexThemeDialog()
    return
  }
  if (activeContactQrPreview.value) {
    closeContactQrPreview()
    return
  }
  if (isLoginContactDialogOpen.value) {
    closeLoginContactDialog()
    return
  }
  if (image2PreviewImage.value) {
    closeImage2Preview()
    return
  }
  if (activeAnnouncementPopup.value) {
    dismissAnnouncementPopup()
    return
  }
  if (confirmDialog.value.open) {
    closeConfirmDialog(false)
    return
  }
  if (showInvoiceApplyDialog.value) {
    closeInvoiceApplyDialog()
    return
  }
  showAccountSettingsDialog.value = false
  showRedeemSecurityDialog.value = false
  openUserMenu.value = false
  activeUtilityPanel.value = ''
}

watchFeedback(newThemeAuthNotice, 'success')
watchFeedback(newThemeAuthError, 'error')
watchFeedback(accountSettingsNotice, 'success')
watchFeedback(accountSettingsError, 'error')
watchFeedback(apiKeysNotice, 'success', true)
watchFeedback(apiKeysError, 'error', true)
watchFeedback(aggregateLoginNotice, 'success', true)
watchFeedback(aggregateLoginError, 'error', true)
watchFeedback(codexAccountsNotice, 'success', true)
watchFeedback(codexAccountsError, 'error', true)
watchFeedback(compatibleAccessNotice, 'success')
watchFeedback(compatibleAccessError, 'error')
watchFeedback(image2Notice, 'success')
watchFeedback(image2Error, 'error')
watchFeedback(smsReceiverError, 'error')
watchFeedback(rechargeNotice, 'success')
watchFeedback(rechargeError, 'error')
watchFeedback(invoiceNotice, 'success')
watchFeedback(invoiceError, 'error')
watchFeedback(projectOutsourcingNotice, 'success')
watchFeedback(projectOutsourcingError, 'error')
watchFeedback(feedbackNotice, 'info')
watchFeedback(tutorialError, 'error')
watchFeedback(usageError, 'error')
watchFeedback(loginModelsNotice, 'info', true)
watchFeedback(loginModelsError, 'error', true)
watchFeedbackGetter(() => toolNotices.value.codex, 'success', true)
watchFeedbackGetter(() => toolNotices.value.claude, 'success', true)
watchFeedbackGetter(() => toolWarnings.value.codex, 'warning', true)
watchFeedbackGetter(() => toolWarnings.value.claude, 'warning', true)
watchFeedbackGetter(() => toolErrors.value.codex, 'error', true)
watchFeedbackGetter(() => toolErrors.value.claude, 'error', true)
watchFeedbackGetter(() => toolLatencyNotices.value.codex, 'info')
watchFeedbackGetter(() => toolLatencyNotices.value.claude, 'info')
watchFeedbackGetter(() => toolLatencyErrors.value.codex, 'error')
watchFeedbackGetter(() => toolLatencyErrors.value.claude, 'error')
watchFeedbackGetter(() => settingNotices.value.sessionSync, 'success', true)
watchFeedbackGetter(() => settingNotices.value.sessionDelete, 'success', true)
watchFeedbackGetter(() => settingNotices.value.language, 'success', true)
watchFeedbackGetter(() => settingErrors.value.sessionSync, 'error', true)
watchFeedbackGetter(() => settingErrors.value.plugins ? '插件操作未完成，请重试。' : '', 'error', true)
watchFeedbackGetter(() => settingErrors.value.sessionDelete, 'error', true)
watchFeedbackGetter(() => settingErrors.value.language, 'error', true)
watchFeedback(runtimeServerNotice, 'info')
watchFeedback(runtimeServerError, 'error')
watchFeedbackGetter(() => updateCheckSource.value === 'auto' ? '' : updateStatus.value.error, 'error')
watchFeedbackGetter(() => (
  updateCheckSource.value === 'auto' &&
  (updateStatus.value.state === 'checking' || updateStatus.value.state === 'not-available')
    ? ''
    : updateStatus.value.message
), 'info')
watch(
  () => updateStatus.value,
  (status) => {
    if (shouldShowUpdatePrompt(status, updateCheckSource.value || 'auto')) {
      openUpdateDialog()
    }
  },
)

function startRuntimeServicesAfterServerSelection() {
  if (runtimeServicesStarted || isMigrationLandingVisible.value || !hasConfirmedRuntimeServerSelection.value) return
  runtimeServicesStarted = true
  removeCodexInstallStatusListener = window.gaogeDesktop?.onCodexInstallStatus?.((status) => {
    codexInstallStatus.value = status
    isCodexInstalling.value = !isCodexInstallTerminal(status.state)
  }) || null
  removeUpdateStatusListener = window.gaogeDesktop?.onUpdateStatus?.((status) => {
    updateStatus.value = status
  }) || null
  removeMainWindowRestoredListener = window.gaogeDesktop?.onMainWindowRestored?.(() => {
    handleMainWindowRestored()
  }) || null
  removeCodexThemeDownloadStatusListener =
    window.gaogeDesktop?.onCodexThemeDownloadStatus?.(handleCodexThemeDownloadStatus) || null
  window.addEventListener(DESKTOP_AUTH_REFRESHED_EVENT, handleDesktopAuthRefreshed)
  window.addEventListener(API_CONNECTION_STATE_EVENT, handleApiConnectionState)
  window.addEventListener('online', handleAuthRefreshOnline)
  document.addEventListener('visibilitychange', handleAuthRefreshVisibilityChange)
  window.addEventListener(RUNTIME_SERVER_CHANGED_EVENT, handleRuntimeServerChanged)
  void restoreSavedSession()
  void loadCodexRouterStatus({ silent: true })
  void loadCodexPluginsStatus({ silent: true })
  void loadCodexSessionDeleteStatus({ silent: true })
  void loadCodexLaunchTarget({ silent: true })
  void loadCodexThemeCatalog({ silent: true })
  void loadCodexSessionStats()
  void loadCodexInstallStatus()
  void loadUpdateStatus({ silent: true })
  void loadOnlinePaymentConfig({ silent: true })
  void loadOfficialSubscriptionPrices()
  void loadPlatformSubscriptionPlans()
  void loadMigrationSupportQrCode()
  scheduleStartupUpdateCheck()
  startDashboardAutoRefresh()
  document.addEventListener('pointerdown', handleDocumentPointerDown)
  document.addEventListener('keydown', handleDocumentKeydown)
  window.addEventListener('focus', handleWindowFocus)
}

onMounted(() => {
  void loadCodexLanguageSettings({ silent: true })
  document.documentElement.dataset.theme = colorMode.value
  document.documentElement.style.colorScheme = colorMode.value
  syncRuntimeServerState()
  if (shouldShowRuntimeServerGate.value) setDesktopWindowLayout('server')
  const runtimeConfig = getRuntimeDomainConfig()
  if (runtimeConfig.source === 'cache') {
    notify('配置入口暂不可用，当前使用上次成功缓存配置。', 'warning', '配置兜底')
  } else if (runtimeConfig.source === 'builtin') {
    notify('配置入口和缓存都不可用，服务器配置不可用。', 'warning', '配置兜底')
  }
  if (isMigrationLandingVisible.value) {
    void loadMigrationSupportQrCode()
    return
  }
  if (codexThemePreviewMode) {
    void nextTick(openCodexThemeDialog)
  }
  if (runtimeServers.value.length > 0) void testRuntimeServerList({ silent: true })
  startRuntimeServicesAfterServerSelection()
})

watch(shouldShowRuntimeServerGate, (show) => {
  if (isMigrationLandingVisible.value) return
  if (show) {
    setDesktopWindowLayout('server')
  } else if (isNewThemeAuthenticated.value) {
    setDesktopWindowLayout('app')
  } else {
    setDesktopWindowLayout('login')
  }
})

onUnmounted(() => {
  pluginStatusDisposed = true
  stopCodexPluginStatusCheck()
  stopCodexUltraStatusCheck()
  removeCodexLoginProgressListener?.()
  removeCodexLoginProgressListener = null
  if (codexOperationElapsedTimer !== null) {
    window.clearInterval(codexOperationElapsedTimer)
    codexOperationElapsedTimer = null
  }
  codexOperationStartedAt = 0
  runtimeServicesStarted = false
  removeCodexInstallStatusListener?.()
  removeCodexInstallStatusListener = null
  removeUpdateStatusListener?.()
  removeUpdateStatusListener = null
  removeMainWindowRestoredListener?.()
  removeMainWindowRestoredListener = null
  removeCodexThemeDownloadStatusListener?.()
  removeCodexThemeDownloadStatusListener = null
  clearInvoiceDownloadAutoCloseTimer()
  if (updateAutoCheckTimer !== null) {
    window.clearTimeout(updateAutoCheckTimer)
    updateAutoCheckTimer = null
  }
  if (mainWindowRestoreRefreshTimer !== null) {
    window.clearTimeout(mainWindowRestoreRefreshTimer)
    mainWindowRestoreRefreshTimer = null
  }
  if (codexThemeCarouselMoveTimer !== null) {
    window.clearTimeout(codexThemeCarouselMoveTimer)
    codexThemeCarouselMoveTimer = null
  }
  stopAuthRefreshScheduler()
  stopDashboardAutoRefresh()
  if (codexAccountsRetryTimer !== null) {
    window.clearTimeout(codexAccountsRetryTimer)
    codexAccountsRetryTimer = null
  }
  stopPaymentPolling()
  stopPendingRechargeBonusRetryTimer()
  stopDesktopAnnouncementPolling()
  stopSmsReceiverPolling()
  stopSmsReceiverCleanupTimer()
  stopOfficialSubscriptionPriceRefresh()
  stopOnlinePaymentConfigRefresh()
  invalidateOnlinePaymentConfig()
  clearPaymentPanelDismissTimer()
  document.removeEventListener('pointerdown', handleDocumentPointerDown)
  document.removeEventListener('keydown', handleDocumentKeydown)
  document.removeEventListener('visibilitychange', handleAuthRefreshVisibilityChange)
  window.removeEventListener('online', handleAuthRefreshOnline)
  window.removeEventListener(DESKTOP_AUTH_REFRESHED_EVENT, handleDesktopAuthRefreshed)
  window.removeEventListener(API_CONNECTION_STATE_EVENT, handleApiConnectionState)
  window.removeEventListener(RUNTIME_SERVER_CHANGED_EVENT, handleRuntimeServerChanged)
  window.removeEventListener('focus', handleWindowFocus)
})

void [
  currentMigrationWindowsDownloadUrl,
  migrationWebEntryUrl,
  MIGRATION_SUPPORT_GROUP,
  migrationDownloadPackages,
  migrationInstallHelpVideos,
  migrationQuickTutorials,
  migrationFeatures,
  migrationTutorialSections,
  selectedMigrationTutorial,
  isMigrationVideoModalOpen,
  migrationVideoModalEyebrow,
  migrationVideoModalOptions,
  selectedMigrationVideoTutorial,
  migrationSupportQrCode,
  openMigrationInstallHelp,
  openMigrationQuickTutorial,
  closeMigrationVideoModal,
  selectMigrationVideoTutorial,
  codexRelaySource,
  openUpgradeUnavailableDialog,
  closeAccountSettingsDialog,
  applyEnabledCodexSettings,
  saveAccountProfile,
  openImage2Preview,
  submitAccountSettingsChange,
  confirmRedeemSecurityPrompt,
]
</script>

<template>
  <section v-if="isMigrationLandingVisible" class="migration-landing" aria-label="Gaoge Free 软件版推荐">
    <main class="migration-shell">
      <header class="migration-hero">
        <div class="migration-topbar">
          <span class="migration-kicker">
            <img :src="gaogeThemeLogo" alt="" @error="handleThemeLogoError" />
            Gaoge Free 软件版
          </span>
          <a class="migration-ghost-link" :href="migrationWebEntryUrl" target="_blank" rel="noopener noreferrer">
            <ExternalLink :size="15" />
            <span>网页端入口</span>
          </a>
        </div>
        <div class="migration-hero-copy">
          <span class="migration-eyebrow">
            <Megaphone :size="16" />
            使用公告
          </span>
          <h1>现已推出软件版 功能强大 操作简单</h1>
          <p>
            软件版集中支持聚合登录、ChatGPT 已有账号加油、无账号 API 登录、Claude 登录、多账号切换、会话同步和插件开启，日常使用更稳定，操作也更清楚。
          </p>
          <div class="migration-hero-points" aria-label="软件版能力摘要">
            <span>
              <ShieldCheck :size="15" />
              稳定下载链接
            </span>
            <span>
              <Sparkles :size="15" />
              内置图文教程
            </span>
            <span>
              <Headphones :size="15" />
              售后群支持
            </span>
          </div>
        </div>
      </header>

      <section class="migration-section migration-download-section" aria-label="下载安装包与网页入口">
        <div class="migration-section-head">
          <span>
            <Download :size="15" />
            选择系统下载
          </span>
          <strong>三个系统安装包</strong>
          <p>下载按钮继续使用现有固定地址，后续发版只需要替换服务器上的稳定别名文件。</p>
        </div>
        <div class="migration-download-stack">
          <article v-for="item in migrationDownloadPackages" :key="item.platform" :class="['migration-download-card', `tone-${item.tone}`]">
            <div class="migration-download-card-head">
              <span :class="['migration-card-icon', 'migration-os-icon', `os-${item.osLogo}`]" aria-hidden="true">
                <svg v-if="item.osLogo === 'windows'" viewBox="0 0 24 24" role="img">
                  <path d="M3 5.2 10.9 4v7.1H3V5.2Zm9.2-1.4L21 2.5v8.6h-8.8V3.8ZM3 12.9h7.9V20L3 18.9v-6Zm9.2 0H21v8.6l-8.8-1.3v-7.3Z" />
                </svg>
                <svg v-else-if="item.osLogo === 'macos'" viewBox="0 0 24 24" role="img">
                  <path d="M15.7 2.4c.2 1.4-.4 2.8-1.2 3.8-.9 1.1-2.4 1.8-3.6 1.7-.2-1.3.5-2.7 1.3-3.6.9-1 2.4-1.8 3.5-1.9Z" />
                  <path d="M20.2 17.2c-.5 1.2-.8 1.7-1.5 2.8-1 1.5-2.4 3.4-4.1 3.4-1.5 0-1.9-1-3.9-1s-2.5 1-3.9 1c-1.7 0-3-1.7-4-3.2-2.7-4.1-3-8.9-1.3-11.4 1.2-1.8 3-2.8 4.7-2.8 1.8 0 2.9 1 4.3 1 1.4 0 2.3-1 4.3-1 1.5 0 3.1.8 4.3 2.2-3.8 2.1-3.2 7.5 1.1 9Z" />
                </svg>
                <svg v-else viewBox="0 0 24 24" role="img">
                  <path d="M12 2.8c2.1 0 3.8 1.8 3.8 4.3 0 1 .3 1.9.9 2.9.9 1.4 1.7 3 1.7 5.2 0 3.8-2.7 6-6.4 6s-6.4-2.2-6.4-6c0-2.1.8-3.8 1.7-5.2.6-1 .9-1.9.9-2.9 0-2.5 1.7-4.3 3.8-4.3Z" fill="none" stroke="currentColor" stroke-linejoin="round" stroke-width="1.7" />
                  <path d="M8 18.4c-1.1.4-2 .9-2.6 1.5-.7.7-.4 1.4.6 1.4h3.5c.8 0 1.3-.5 1.1-1.2-.2-.8-1.2-1.5-2.6-1.7ZM16 18.4c1.1.4 2 .9 2.6 1.5.7.7.4 1.4-.6 1.4h-3.5c-.8 0-1.3-.5-1.1-1.2.2-.8 1.2-1.5 2.6-1.7Z" />
                  <circle cx="10.2" cy="8.2" r="0.7" />
                  <circle cx="13.8" cy="8.2" r="0.7" />
                  <path d="M10.8 10.4h2.4L12 11.6l-1.2-1.2Z" />
                </svg>
              </span>
              <div>
                <small>{{ item.platform }}</small>
                <strong>{{ item.label }}</strong>
              </div>
            </div>
            <div class="migration-download-card-body">
              <p>{{ item.detail }}</p>
              <div class="migration-download-card-meta">
                <span>{{ item.placeholder }}</span>
                <button
                  v-if="item.installHelp"
                  type="button"
                  class="migration-install-help-link"
                  @click="openMigrationInstallHelp"
                >
                  查看报错安装方法
                </button>
              </div>
            </div>
            <a
              v-if="item.url"
              class="migration-download-action"
              :href="item.url"
              download
            >
              <Download :size="16" />
              <span>{{ item.actionLabel }}</span>
            </a>
            <button v-else type="button" class="migration-download-action" disabled>
              <component :is="item.icon" :size="16" />
              <span>{{ item.actionLabel }}</span>
            </button>
          </article>
        </div>
      </section>

      <section class="migration-quick-tutorial-row" aria-label="Codex 使用提示教程">
        <button
          v-for="tutorial in migrationQuickTutorials"
          :key="tutorial.title"
          type="button"
          :class="['migration-quick-tutorial-card', `tone-${tutorial.tone}`]"
          @click="openMigrationQuickTutorial(tutorial)"
        >
          <span class="migration-card-icon" aria-hidden="true">
            <component :is="tutorial.icon" :size="19" />
          </span>
          <span class="migration-quick-tutorial-copy">
            <small>{{ tutorial.eyebrow }}</small>
            <strong>{{ tutorial.title }}</strong>
            <span>{{ tutorial.detail }}</span>
          </span>
          <span class="migration-quick-tutorial-action">
            <Play :size="14" />
            {{ tutorial.badge }}
          </span>
        </button>
      </section>

      <section class="migration-section migration-feature-section" aria-label="软件版本介绍">
        <div class="migration-section-head">
          <span>
            <BadgeCheck :size="15" />
            软件版能力
          </span>
          <strong>把常用操作集中到客户端</strong>
          <p>保留现有功能描述，但用更紧凑的方式展示，方便用户快速判断是否需要下载。</p>
        </div>
        <div class="migration-feature-grid">
          <article v-for="feature in migrationFeatures" :key="feature.title" :class="['migration-feature-card', `tone-${feature.tone}`]">
            <span class="migration-card-icon" aria-hidden="true">
              <component :is="feature.icon" :size="18" />
            </span>
            <div>
              <strong>{{ feature.title }}</strong>
              <p>{{ feature.detail }}</p>
            </div>
          </article>
        </div>
      </section>

      <section class="migration-section migration-support-strip" aria-label="售后支持与教程导航">
        <div class="migration-support-copy">
          <span>
            <Headphones :size="16" />
            售后支持
          </span>
          <strong>{{ MIGRATION_SUPPORT_GROUP || migrationSupportQrCode ? '遇到问题联系当前服务提供方' : '请参考使用教程或联系服务提供方' }}</strong>
          <p>安装、登录、账号切换或教程操作遇到问题，请参考教程；支持方式由当前服务提供方配置。</p>
        </div>
        <div v-if="MIGRATION_SUPPORT_GROUP || migrationSupportQrCode" class="migration-support-card">
          <img v-if="migrationSupportQrCode" :src="migrationSupportQrCode" alt="售后 QQ 群二维码" />
          <div v-else class="migration-qr-fallback">QQ群</div>
          <div>
            <small>售后 QQ 群</small>
            <strong>{{ MIGRATION_SUPPORT_GROUP }}</strong>
            <p>扫码或搜索群号加入。</p>
          </div>
        </div>
        <nav class="migration-tutorial-jump" aria-label="教程快捷导航">
          <span>
            <BookOpen :size="15" />
            教程导航
          </span>
          <button
            v-for="(section, index) in migrationTutorialSections"
            :key="section.title"
            type="button"
            :class="{ 'is-active': selectedMigrationTutorial?.title === section.title }"
            @click="selectMigrationTutorialAndScroll(section.title)"
          >
            <small>{{ String(index + 1).padStart(2, '0') }}</small>
            <strong>{{ section.title }}</strong>
          </button>
        </nav>
      </section>

      <section id="migration-tutorials" class="migration-section migration-tutorial-section" aria-label="使用教程">
        <div class="migration-section-head">
          <span>
            <BookOpen :size="15" />
            使用教程
          </span>
          <strong>软件版内置教程</strong>
          <p>点击左侧教程即可在当前页面查看步骤和配图，下载前后都可以按这里操作。</p>
        </div>
        <div class="migration-tutorial-layout">
          <div class="migration-tutorial-card-grid">
            <button
              v-for="(section, index) in migrationTutorialSections"
              :key="section.title"
              type="button"
              :class="['migration-tutorial-card', { 'is-active': selectedMigrationTutorial?.title === section.title }]"
              @click="selectMigrationTutorial(section.title)"
            >
              <span>{{ String(index + 1).padStart(2, '0') }}</span>
              <strong>{{ section.title }}</strong>
              <small>{{ getTutorialCardSummary(section) }}</small>
            </button>
          </div>

          <article v-if="selectedMigrationTutorial" class="migration-tutorial-detail">
            <header>
              <span>当前教程</span>
              <h2>{{ selectedMigrationTutorial.title }}</h2>
              <p>{{ selectedMigrationTutorial.description }}</p>
            </header>
            <div class="migration-tutorial-copy">
              <p v-for="paragraph in selectedMigrationTutorial.paragraphs" :key="paragraph">{{ paragraph }}</p>
            </div>
            <ul v-if="selectedMigrationTutorial.items.length" class="migration-tutorial-list">
              <li v-for="item in selectedMigrationTutorial.items" :key="item">{{ item }}</li>
            </ul>
            <div v-if="selectedMigrationTutorial.images.length" class="migration-tutorial-media-grid">
              <figure v-for="image in selectedMigrationTutorial.images" :key="image.src">
                <img :src="image.src" :alt="image.alt" loading="lazy" />
                <figcaption>{{ image.caption || image.alt }}</figcaption>
              </figure>
            </div>
          </article>
        </div>
      </section>
    </main>
  </section>
  <section v-else-if="shouldShowRuntimeServerGate" class="new-theme-runtime-gate" aria-label="选择服务器">
    <article class="new-theme-runtime-gate-shell">
      <header class="new-theme-runtime-gate-head">
        <div class="new-theme-runtime-gate-title">
          <span class="new-theme-runtime-gate-logo" aria-hidden="true">
            <img :src="gaogeThemeLogo" alt="" @error="handleThemeLogoError" />
          </span>
          <div class="new-theme-runtime-gate-copy">
            <span>服务器选择</span>
            <h1>选择一个可用服务器</h1>
            <p>根据链接的延时速度与可连性选择适合的服务器。</p>
          </div>
        </div>
        <div class="new-theme-runtime-gate-actions">
          <button type="button" :disabled="isRuntimeServerRefreshing" @click="refreshRuntimeServersFromOss">
            <RefreshCcw :class="{ 'official-spin': isRuntimeServerRefreshing }" :size="15" />
            {{ isRuntimeServerRefreshing ? '刷新中' : '刷新服务器' }}
          </button>
          <button type="button" :disabled="isRuntimeServerTesting || !runtimeServers.length" @click="testRuntimeServerList()">
            <Gauge :class="{ 'official-spin': isRuntimeServerTesting }" :size="15" />
            {{ isRuntimeServerTesting ? '测速中' : '刷新测速' }}
          </button>
        </div>
      </header>

      <div v-if="runtimeServers.length" class="new-theme-runtime-gate-list">
        <article
          v-for="server in runtimeServers"
          :key="server.id"
          :class="['new-theme-runtime-gate-card', runtimeServerStatusClass(server), { selected: server.selected }]"
        >
          <div class="new-theme-runtime-gate-card-top">
            <div class="new-theme-runtime-gate-server-line">
              <span>{{ server.name }}</span>
              <strong>{{ server.urls.apiOrigin }}</strong>
            </div>
            <small :class="['new-theme-runtime-server-reachability', runtimeServerReachabilityClass(server)]">
              {{ runtimeServerReachabilityText(server) }}
            </small>
            <small class="new-theme-runtime-server-choice">{{ runtimeServerSelectionLabel(server) }}</small>
          </div>
          <div class="new-theme-runtime-gate-meta">
            <span class="new-theme-runtime-server-latency">
              <CheckCircle2 v-if="server.status.status === 'ok'" :size="14" />
              <CircleAlert v-else-if="server.status.status === 'failed'" :size="14" />
              <Clock v-else :size="14" />
              <b>测速耗时：</b>
              <strong>{{ runtimeServerStatusText(server) }}</strong>
            </span>
            <small>{{ runtimeServerStatusDetail(server) }}</small>
          </div>
          <button type="button" :disabled="isRuntimeServerRefreshing" @click="selectRuntimeServerFromUi(server)">
            {{ runtimeServerActionText(server) }}
          </button>
        </article>
      </div>

      <div v-else class="new-theme-runtime-gate-empty">
        <CircleAlert :size="24" />
        <strong>没有读取到可用服务器</strong>
        <p>请检查发布环境是否注入 OSS 原始 JSON 地址，或确认阿里 OSS / 腾讯 OSS 文件可以直接访问。</p>
      </div>

      <div v-if="runtimeServerNotice || runtimeServerError" class="new-theme-runtime-gate-feedback">
        <p v-if="runtimeServerNotice">{{ runtimeServerNotice }}</p>
        <p v-if="runtimeServerError" class="error">{{ runtimeServerError }}</p>
      </div>

      <footer class="new-theme-runtime-gate-footer">
        <span>服务器都连不上？</span>
        <button type="button" @click="openLoginContactDialog">
          <Headphones :size="15" />
          联系我们
        </button>
      </footer>
    </article>
  </section>
  <section v-else-if="!isNewThemeAuthenticated" class="new-theme-login-gate" aria-label="Gaoge Free 登录">
    <div class="new-theme-login-layout">
      <div class="new-theme-auth-area">
        <article class="new-theme-auth-shell">
          <form class="new-theme-auth-card" @submit.prevent="submitNewThemeAuth">
            <div class="new-theme-auth-form">
              <span class="new-theme-auth-logo" aria-hidden="true">
                <img :src="gaogeThemeLogo" alt="" @error="handleThemeLogoError" />
              </span>

              <header class="new-theme-auth-header">
                {{ newThemeLoginMode === 'register' ? '注册 Gaoge Free' : '登录 Gaoge Free' }}
              </header>

              <div v-if="runtimeConfigUnavailable" class="new-theme-runtime-login-alert">
                <CircleAlert :size="16" />
                <span>{{ runtimeConfigBlockedTitle }}</span>
                <small>{{ runtimeConfigBlockedDetail }}</small>
                <button type="button" :disabled="isRuntimeServerRefreshing" @click="refreshRuntimeServersFromOss">
                  {{ isRuntimeServerRefreshing ? '刷新中' : '刷新服务器' }}
                </button>
              </div>

              <div v-if="newThemeLoginMode === 'redeem'" class="new-theme-auth-fields">
                <input
                  v-model="newThemeRedeemCode"
                  class="new-theme-auth-input"
                  :disabled="isNewThemeAuthLoading"
                  autocomplete="off"
                  placeholder="填写兑换码"
                />
              </div>

              <div v-else-if="newThemeLoginMode === 'account'" class="new-theme-auth-fields">
                <input
                  v-model="newThemeLoginAccount"
                  class="new-theme-auth-input"
                  :disabled="isNewThemeAuthLoading"
                  autocomplete="email"
                  placeholder="填写账号"
                />
                <input
                  v-model="newThemeLoginPassword"
                  class="new-theme-auth-input"
                  :disabled="isNewThemeAuthLoading"
                  autocomplete="current-password"
                  placeholder="填写密码"
                  type="password"
                />
              </div>

              <div v-else class="new-theme-auth-fields">
                <input
                  v-model="newThemeRegisterEmail"
                  class="new-theme-auth-input"
                  :disabled="isNewThemeAuthLoading"
                  autocomplete="email"
                  placeholder="输入邮箱"
                  type="email"
                />
                <input
                  v-model="newThemeRegisterPassword"
                  class="new-theme-auth-input"
                  :disabled="isNewThemeAuthLoading"
                  autocomplete="new-password"
                  placeholder="输入密码"
                  type="password"
                />
                <input
                  v-model="newThemeRegisterConfirmPassword"
                  class="new-theme-auth-input"
                  :disabled="isNewThemeAuthLoading"
                  autocomplete="new-password"
                  placeholder="确定密码"
                  type="password"
                />
              </div>

              <label v-if="newThemeLoginMode === 'account'" class="new-theme-auth-remember">
                <input
                  v-model="rememberPassword"
                  type="checkbox"
                  :disabled="isNewThemeAuthLoading"
                  @change="handleRememberPasswordChange"
                />
                <span aria-hidden="true">
                  <CheckCircle2 v-if="rememberPassword" :size="14" />
                </span>
                <strong>记住密码</strong>
                <small>默认保存账号和密码</small>
              </label>

              <button class="new-theme-auth-submit sign-in" type="submit" :disabled="isNewThemeAuthLoading || runtimeConfigUnavailable">
                {{ isNewThemeAuthLoading ? (newThemeLoginMode === 'register' ? '正在注册...' : '正在进入...') : newThemeLoginMode === 'register' ? '注册进入' : newThemeLoginMode === 'redeem' ? '淘宝兑换码登录' : '登录进入' }}
              </button>

              <button
                v-if="newThemeLoginMode !== 'register'"
                class="new-theme-auth-submit new-theme-auth-secondary"
                type="button"
                :disabled="isNewThemeAuthLoading"
                @click="setNewThemeLoginMode(newThemeLoginMode === 'redeem' ? 'account' : 'redeem')"
              >
                {{ newThemeLoginMode === 'redeem' ? '已有账号登录' : '淘宝兑换码登录' }}
              </button>

              <button
                v-if="newThemeLoginMode === 'redeem'"
                class="new-theme-auth-submit new-theme-auth-secondary"
                type="button"
                :disabled="isNewThemeAuthLoading"
                @click="setNewThemeLoginMode('register')"
              >
                注册账号
              </button>

              <button
                v-if="newThemeLoginMode === 'redeem'"
                class="new-theme-auth-submit new-theme-auth-contact-submit"
                type="button"
                :disabled="isNewThemeAuthLoading"
                @click="openLoginContactDialog"
              >
                <Headphones :size="15" />
                联系我们
              </button>

              <footer v-if="newThemeLoginMode !== 'redeem'" class="new-theme-auth-footer">
                <button v-if="newThemeLoginMode === 'account'" type="button" @click="showForgotPasswordDialog">
                  忘记密码
                </button>
                <span v-else aria-hidden="true"></span>
                <button
                  class="new-theme-auth-contact-link"
                  type="button"
                  :disabled="isNewThemeAuthLoading"
                  @click="openLoginContactDialog"
                >
                  <Headphones :size="13" />
                  联系我们
                </button>
                <button
                  type="button"
                  :disabled="isNewThemeAuthLoading"
                  @click="setNewThemeLoginMode(newThemeLoginMode === 'account' ? 'register' : 'account')"
                >
                  {{ newThemeLoginMode === 'account' ? '注册账号' : '已有账号登录' }}
                </button>
              </footer>

            </div>
          </form>
        </article>
      </div>
      <LoginBrandPanel class="new-theme-login-brand" />
    </div>
  </section>

  <main v-else :class="['new-theme-shell', { 'is-collapsed': isCollapsed, 'mode-dark': colorMode === 'dark' }]">
    <aside class="new-theme-sidebar">
      <header class="new-theme-sidebar-header">
        <div ref="userMenuRef" class="new-theme-menu-wrap">
          <button
            :class="['new-theme-user-button', 'new-theme-user-button-top', { open: openUserMenu }]"
            type="button"
            aria-haspopup="menu"
            :aria-expanded="openUserMenu"
            @click="openUserMenu = !openUserMenu"
          >
            <span class="new-theme-team-logo" aria-hidden="true">
              <img :src="gaogeUserAvatarLogo" alt="" />
            </span>
            <span class="new-theme-user-copy">
              <strong>{{ user.name }}</strong>
              <small>{{ user.email }}</small>
            </span>
            <ChevronsUpDown class="new-theme-menu-chevron" :size="16" />
          </button>

          <div v-if="openUserMenu && !isCollapsed" class="new-theme-popover user-popover top-user-popover" role="menu">
            <div class="new-theme-user-card">
              <span class="new-theme-team-logo" aria-hidden="true">
                <img :src="gaogeUserAvatarLogo" alt="" />
              </span>
              <div>
                <strong>{{ user.name }}</strong>
                <small>{{ user.email }}</small>
              </div>
            </div>
            <button type="button" role="menuitem" @click="setPage('Gaoge-平台订阅')">
              <Sparkles :size="15" />
              <span>升级到专业版</span>
            </button>
            <button type="button" role="menuitem" @click="openAccountSettingsDialog">
              <BadgeCheck :size="15" />
              <span>账户 / 账号</span>
            </button>
            <button type="button" role="menuitem" @click="returnToRuntimeServerGate">
              <RefreshCcw :size="15" />
              <span>返回服务器</span>
            </button>
            <button type="button" role="menuitem" @click="handleNewThemeLogout">
              <LogOut :size="15" />
              <span>退出登录</span>
            </button>
          </div>
        </div>
      </header>

      <section class="new-theme-sidebar-content">
        <div class="new-theme-sidebar-group">
          <span class="new-theme-group-label">平台</span>
          <div class="new-theme-menu-list">
            <article
              v-for="item in navMain"
              :key="item.title"
              :class="['new-theme-menu-item', { open: openGroups[item.title] }]"
            >
              <button
                :class="['new-theme-menu-button', item.tone ? `tone-${item.tone}` : '', { active: activePage === item.title || item.items?.includes(activePage) }]"
                type="button"
                @click="item.items?.length ? toggleGroup(item.title) : setPage(item.title)"
              >
                <component :is="item.icon" :size="16" />
                <span>{{ item.title }}</span>
                <ChevronRight v-if="item.items?.length" class="new-theme-item-chevron" :size="16" />
              </button>
              <div v-if="item.items?.length && openGroups[item.title] && !isCollapsed" class="new-theme-submenu">
                <button
                  v-for="subItem in item.items"
                  :key="subItem"
                  :class="{ active: activePage === subItem }"
                  type="button"
                  @click="setPage(subItem)"
                >
                  <span>{{ subItem }}</span>
                </button>
              </div>
            </article>
          </div>
        </div>

        <div class="new-theme-sidebar-group new-theme-projects-group">
          <span class="new-theme-group-label">个人</span>
          <div class="new-theme-menu-list">
            <article
              v-for="project in projects"
              :key="project.name"
              :class="['new-theme-menu-item', 'new-theme-project-item', { open: openGroups[project.name] }]"
            >
              <button
                :class="['new-theme-menu-button', project.tone ? `tone-${project.tone}` : '', { active: isProjectActive(project) }]"
                type="button"
                @click="handleProjectClick(project)"
              >
                <component :is="project.icon" :size="16" />
                <span>{{ project.name }}</span>
                <ChevronRight v-if="project.items?.length" class="new-theme-item-chevron" :size="16" />
              </button>
              <div v-if="project.items?.length && openGroups[project.name] && !isCollapsed" class="new-theme-submenu">
                <button
                  v-for="subItem in project.items"
                  :key="subItem.page"
                  :class="{ active: activePage === subItem.page }"
                  type="button"
                  @click="setPage(subItem.page)"
                >
                  <span>{{ subItem.label }}</span>
                </button>
              </div>
            </article>
          </div>
        </div>
      </section>

      <footer class="new-theme-sidebar-footer">
        <button
          :class="['new-theme-sidebar-utility-button', 'is-contact', { active: activeUtilityPanel === 'contact' }]"
          type="button"
          title="联系我们"
          aria-label="联系我们"
          @click="openContactPanel"
        >
          <Headphones :size="15" />
          <span v-if="!isCollapsed">联系我们</span>
        </button>
        <button
          :class="['new-theme-sidebar-utility-button', 'is-share', { active: activePage === '我的邀请' }]"
          type="button"
          title="我的邀请"
          aria-label="我的邀请"
          @click="openInvitationPage"
        >
          <Send :size="15" />
          <span v-if="!isCollapsed">我的邀请</span>
        </button>
        <div class="new-theme-mode-toggle" role="group" aria-label="主题模式">
          <template v-if="!isCollapsed">
            <button
              :class="{ active: colorMode === 'light' }"
              type="button"
              @click="setColorMode('light')"
            >
              <Sun :size="15" />
              <span>浅色</span>
            </button>
            <button
              :class="{ active: colorMode === 'dark' }"
              type="button"
              @click="setColorMode('dark')"
            >
              <Moon :size="15" />
              <span>深色</span>
            </button>
          </template>
          <button
            v-else
            class="icon-only"
            type="button"
            :aria-label="colorMode === 'light' ? '浅色模式' : '深色模式'"
            @click="setColorMode(colorMode === 'light' ? 'dark' : 'light')"
          >
            <Sun v-if="colorMode === 'light'" :size="16" />
            <Moon v-else :size="16" />
          </button>
        </div>
      </footer>

      <button class="new-theme-rail" type="button" aria-label="Toggle sidebar" @click="toggleSidebar" />
    </aside>

    <section class="new-theme-inset">
      <header class="new-theme-topbar">
        <div class="new-theme-topbar-inner">
          <button class="new-theme-trigger" type="button" aria-label="Toggle sidebar" @click="toggleSidebar">
            <PanelLeft :size="18" />
          </button>
          <span class="new-theme-separator" aria-hidden="true" />
          <nav class="new-theme-breadcrumb" aria-label="当前页面">
            <strong>{{ activePage }}</strong>
          </nav>
          <div v-if="activePage === '使用教程'" class="new-theme-tutorial-top-tools">
            <label class="new-theme-tutorial-search">
              <Search :size="15" />
              <input
                v-model="tutorialSearchQuery"
                type="search"
                placeholder="搜索教程关键词"
                aria-label="搜索教程关键词"
              />
            </label>
            <button type="button" :disabled="isTutorialLoading" @click="loadTutorialPage">
              <RefreshCcw :size="15" />
              {{ isTutorialLoading ? '同步中' : '刷新教程' }}
            </button>
          </div>
        </div>

        <div ref="utilityPanelRef" class="new-theme-topbar-actions">
          <button
            :class="['new-theme-topbar-action', 'is-contact', { active: activeUtilityPanel === 'contact' }]"
            type="button"
            title="联系我们"
            aria-label="联系我们"
            @click="toggleUtilityPanel('contact')"
          >
            <Headphones :size="17" />
          </button>
          <button
            :class="['new-theme-topbar-action', 'is-announcement', { active: activeUtilityPanel === 'announcement' }]"
            type="button"
            title="公告"
            aria-label="公告"
            @click="toggleUtilityPanel('announcement')"
          >
            <Bell :size="17" />
          </button>
          <button
            :class="['new-theme-topbar-action', 'is-feedback', { active: activeUtilityPanel === 'feedback' }]"
            type="button"
            title="意见反馈"
            aria-label="意见反馈"
            @click="toggleUtilityPanel('feedback')"
          >
            <MessageSquareText :size="17" />
          </button>

          <article v-if="activeUtilityPanel" class="new-theme-topbar-panel">
            <template v-if="activeUtilityPanel === 'contact'">
              <header class="new-theme-topbar-panel-head">
                <span>
                  <Headphones :size="18" />
                </span>
                <div>
                  <strong>联系我们</strong>
                </div>
              </header>
              <div class="new-theme-contact-list">
                <div v-if="isDesktopContactLoading" class="new-theme-contact-item loading">
                  <RefreshCcw :size="17" />
                  <div>
                    <span>同步中</span>
                    <strong>正在加载联系方式</strong>
                    <small>请稍等片刻</small>
                  </div>
                </div>
                <div
                  v-for="item in contactItems"
                  :key="item.id"
                  :class="['new-theme-contact-item', 'qr-card', { clickable: item.imageUrl }]"
                >
                  <div>
                    <span>{{ item.label }}</span>
                    <button
                      v-if="item.imageUrl"
                      class="new-theme-contact-qr-trigger"
                      type="button"
                      :aria-label="`查看${item.label}完整二维码`"
                      @click="openContactQrPreview(item)"
                    >
                      <img v-if="item.imageUrl" :src="item.imageUrl" :alt="`${item.label}二维码`" />
                    </button>
                    <figure v-else>
                      <strong>{{ item.value }}</strong>
                    </figure>
                    <small>{{ item.detail }}</small>
                  </div>
                </div>
              </div>
            </template>

            <template v-else-if="activeUtilityPanel === 'announcement'">
              <header class="new-theme-topbar-panel-head">
                <span>
                  <Megaphone :size="18" />
                </span>
                <div>
                  <strong>公告</strong>
                </div>
              </header>
              <div class="new-theme-announcement-list">
                <article v-if="isDesktopAnnouncementsLoading" class="new-theme-announcement-item empty">
                  <div>
                    <strong>公告同步中</strong>
                    <small>正在加载后台公告</small>
                  </div>
                </article>
                <article v-else-if="clientAnnouncements.length === 0" class="new-theme-announcement-item empty">
                  <div>
                    <strong>暂无公告</strong>
                  </div>
                </article>
                <template v-else>
                  <article v-for="item in clientAnnouncements" :key="item.id" class="new-theme-announcement-item">
                    <div>
                      <strong>{{ item.title }}</strong>
                      <small>{{ item.time }}</small>
                    </div>
                    <p>{{ item.detail }}</p>
                  </article>
                </template>
              </div>
            </template>

            <template v-else>
              <header class="new-theme-topbar-panel-head">
                <span>
                  <MessageSquareText :size="18" />
                </span>
                <div>
                  <strong>意见反馈</strong>
                </div>
              </header>
              <div class="new-theme-feedback-form">
                <label>
                  <span>反馈类型</span>
                  <select v-model="feedbackType">
                    <option v-for="type in feedbackTypeOptions" :key="type" :value="type">
                      {{ type }}
                    </option>
                  </select>
                </label>
                <label>
                  <span>联系方式</span>
                  <input v-model="feedbackContact" placeholder="请写您的联系微信或者 QQ" />
                </label>
                <label>
                  <span>反馈内容</span>
                  <textarea v-model="feedbackContent" rows="4" placeholder="请写下遇到的问题、建议或希望我们优化的地方。" />
                </label>
                <button
                  class="new-theme-feedback-submit"
                  type="button"
                  :disabled="isFeedbackSubmitting"
                  @click="submitClientFeedback"
                >
                  <Send :size="15" />
                  <span>{{ isFeedbackSubmitting ? '提交中' : '提交反馈' }}</span>
                </button>
              </div>
            </template>
          </article>
        </div>
      </header>

      <section class="new-theme-content">
        <section v-if="runtimeConfigUnavailable && activePage !== '系统配置' && activePage !== '连接手机'" class="new-theme-runtime-blocked-panel" aria-label="服务器配置不可用">
          <div>
            <CircleAlert :size="24" />
            <span>服务器配置</span>
            <strong>{{ runtimeConfigBlockedTitle }}</strong>
            <p>{{ runtimeConfigBlockedDetail }}</p>
          </div>
          <div class="new-theme-runtime-blocked-actions">
            <button type="button" :disabled="isRuntimeServerRefreshing" @click="refreshRuntimeServersFromOss">
              <RefreshCcw :class="{ 'official-spin': isRuntimeServerRefreshing }" :size="15" />
              {{ isRuntimeServerRefreshing ? '刷新中' : '刷新服务器' }}
            </button>
            <button type="button" @click="setPage('系统配置')">
              <Settings2 :size="15" />
              进入系统配置
            </button>
          </div>
        </section>

        <section v-else-if="activePage === '仪表盘'" class="new-theme-dashboard" aria-label="仪表盘">
          <div class="new-theme-dashboard-grid">
            <article v-for="card in overviewCards" :key="card.label" :class="['new-theme-stat-card', `tone-${card.tone}`]">
              <span class="new-theme-card-accent" aria-hidden="true" />
              <div class="new-theme-stat-head">
                <span>{{ card.label }}</span>
                <component :is="card.icon" :size="18" />
              </div>
              <strong>{{ card.value }}</strong>
              <p>{{ card.detail }}</p>
            </article>
          </div>

          <div class="new-theme-metric-grid">
            <article v-for="metric in usageMetrics" :key="metric.label" :class="['new-theme-metric-card', `tone-${metric.tone}`]">
              <span class="new-theme-metric-tag">{{ metric.tag }}</span>
              <div>
                <span>{{ metric.label }}</span>
                <strong>{{ metric.value }}</strong>
              </div>
              <small>{{ metric.detail }}</small>
            </article>
          </div>

          <article class="new-theme-account-strip">
            <div class="new-theme-account-main">
              <span class="new-theme-account-avatar" aria-hidden="true">
                <img :src="gaogeUserAvatarLogo" alt="" />
              </span>
              <div class="new-theme-account-copy">
                <span>当前登录账号</span>
                <strong>{{ currentCodexAccount?.email || user.email }}</strong>
                <small>{{ currentCodexAccount?.workspaceName || 'Personal' }}</small>
              </div>
            </div>

            <div class="new-theme-account-status">
              <span class="new-theme-plan-pill">
                <Gauge :size="14" />
                {{ selectedAccount?.plan || 'Free' }}
              </span>
              <span class="new-theme-api-pill">
                <span aria-hidden="true" />
                API 通信正常
              </span>
            </div>

            <div class="new-theme-account-meters">
              <div v-for="meter in accountMeters" :key="meter.label" :class="['new-theme-account-meter', `tone-${meter.tone}`]">
                <div>
                  <span>{{ meter.label }}</span>
                  <strong>{{ meter.value }}</strong>
                </div>
                <span class="new-theme-meter-track">
                  <span :style="{ width: `${meter.progress}%` }" />
                </span>
                <small>
                  <Timer :size="13" />
                  {{ meter.detail }}
                </small>
              </div>
            </div>
          </article>

          <article class="new-theme-subscription-panel tone-violet">
            <span class="new-theme-card-accent" aria-hidden="true" />
            <div class="new-theme-subscription-title">
              <span>当前系统订阅</span>
              <strong>{{ activePlatformSubscriptionName }}</strong>
              <small v-if="platformSubscriptionExpiresDetail">{{ platformSubscriptionExpiresDetail }}</small>
            </div>
            <div class="new-theme-subscription-state">
              <div class="new-theme-subscription-balance">
                <Wallet :size="16" />
                <span>账户余额</span>
                <strong>{{ platformSubscriptionBalanceText }}</strong>
              </div>
              <div v-if="platformSubscriptionUsageRows.length" class="new-theme-subscription-usage-list">
                <div v-for="row in platformSubscriptionUsageRows" :key="row.label" class="new-theme-subscription-usage">
                  <div>
                    <span>{{ row.label }}</span>
                    <strong>剩余 {{ row.remaining }}</strong>
                  </div>
                  <small>已用 {{ row.used }} / {{ row.limit }}</small>
                  <span class="new-theme-subscription-progress" aria-hidden="true">
                    <span :style="{ width: `${row.percent}%` }" />
                  </span>
                </div>
              </div>
            </div>
          </article>
        </section>

        <section v-else-if="activePage === '聚合登录'" class="new-theme-aggregate-page tone-cyan" aria-label="聚合登录">
          <article class="new-theme-aggregate-hero">
            <div class="new-theme-login-title">
              <span class="new-theme-login-icon" aria-hidden="true">
                <Layers3 :size="22" />
              </span>
              <div>
                <span>Unified Model Gateway</span>
                <h1>聚合登录</h1>
                <p>接入不同供应商，选择模型时自动使用对应接口与 Key。</p>
              </div>
            </div>
            <div :class="['new-theme-login-status', { active: isAggregateLoginActive }]">
              <span aria-hidden="true" />
              {{ aggregateStatusText }}
            </div>
          </article>

          <article class="new-theme-aggregate-intro">
            <div class="new-theme-aggregate-intro-copy">
              <span>统一模型入口</span>
              <strong>一个 Codex，下方直接切换不同供应商模型</strong>
              <p>聚合登录会把已支持供应商的模型合并写入 Codex 模型目录。本地安全路由只根据当前模型选择对应 Key，Key 不会注入 Codex 页面。</p>
            </div>
            <div class="new-theme-aggregate-benefits">
              <span><ShieldCheck :size="15" />供应商独立 Key</span>
              <span><RefreshCcw :size="15" />模型实时切换</span>
              <span><Layers3 :size="15" />新供应商可扩展</span>
            </div>
          </article>

          <div class="new-theme-aggregate-section-head">
            <div>
              <span>模型供应商</span>
              <strong>已经接入的上游网络</strong>
            </div>
            <div class="new-theme-aggregate-toolbar">
              <button
                type="button"
                :disabled="isAggregateConnectionsTesting || isAnyAggregateConnectionTesting || isAggregateModelsLoading || isAggregateLoginLoading || aggregateCanvasProviders.length === 0"
                @click="testAllAggregateConnections"
              >
                <Activity :class="{ 'official-spin': isAggregateConnectionsTesting }" :size="15" />
                {{ isAggregateConnectionsTesting ? '正在测试' : '测试全部连接' }}
              </button>
              <button type="button" :disabled="isAggregateModelsLoading || isAggregateLoginLoading || isAggregateConnectionsTesting" @click="refreshAggregateModels({ force: true })">
                <RefreshCcw :class="{ 'official-spin': isAggregateModelsLoading }" :size="15" />
                {{ isAggregateModelsLoading ? '聚合中' : '刷新模型' }}
              </button>
            </div>
          </div>

          <article :class="['new-theme-aggregate-explorer', { 'detail-open': selectedAggregateProvider }]">
            <div class="new-theme-aggregate-canvas" aria-label="已接入模型供应商画布">
              <span class="new-theme-aggregate-orbit orbit-one" aria-hidden="true" />
              <span class="new-theme-aggregate-orbit orbit-two" aria-hidden="true" />
              <button
                v-for="(provider, providerIndex) in aggregateCanvasProviders"
                :key="provider.id"
                type="button"
                :class="[
                  'new-theme-aggregate-node',
                  `tone-${provider.tone}`,
                  `shape-${providerIndex % 5}`,
                  { active: selectedAggregateProviderId === provider.id, connected: provider.connected },
                ]"
                :aria-pressed="selectedAggregateProviderId === provider.id"
                @click="openAggregateProvider(provider.id)"
              >
                <span class="new-theme-aggregate-node-glow" aria-hidden="true" />
                <span class="new-theme-aggregate-node-logo">
                  <img v-if="provider.logo" :src="provider.logo" :alt="`${provider.name} Logo`" />
                  <component v-else :is="provider.icon" :size="24" />
                </span>
                <span class="new-theme-aggregate-node-copy">
                  <small>{{ provider.eyebrow }}</small>
                  <strong>{{ provider.name }}</strong>
                  <span>{{ provider.groups.length }} 个分组 · {{ provider.models.length }} 个模型</span>
                </span>
                <span :class="['new-theme-aggregate-node-state', { active: provider.connected }]">
                  <span aria-hidden="true" />
                  {{ provider.connected ? '已聚合' : provider.loading ? '同步中' : '已添加' }}
                </span>
                <ChevronRight class="new-theme-aggregate-node-arrow" :size="18" />
              </button>

              <div v-if="aggregateCanvasProviders.length === 0" class="new-theme-aggregate-canvas-empty">
                <Layers3 :size="24" />
                <strong>{{ isAggregateModelsLoading ? '正在发现上游供应商' : '暂未发现已接入的上游' }}</strong>
                <span>这里只展示已经添加账号分组的供应商，不再显示未接入的占位平台。</span>
              </div>
              <p v-else class="new-theme-aggregate-canvas-hint">点击任意上游节点，查看分组、支持模型并测试真实调用。</p>
            </div>

            <Transition name="aggregate-detail">
              <aside v-if="selectedAggregateProvider" class="new-theme-aggregate-detail" :class="`tone-${selectedAggregateProvider.tone}`">
                <header class="new-theme-aggregate-detail-head">
                  <span class="new-theme-aggregate-detail-logo">
                    <img v-if="selectedAggregateProvider.logo" :src="selectedAggregateProvider.logo" :alt="`${selectedAggregateProvider.name} Logo`" />
                    <component v-else :is="selectedAggregateProvider.icon" :size="24" />
                  </span>
                  <div>
                    <small>上游供应商</small>
                    <strong>{{ selectedAggregateProvider.name }}</strong>
                    <span>{{ selectedAggregateProvider.groups.length }} 个计费分组 · {{ selectedAggregateProvider.models.length }} 个可选模型</span>
                  </div>
                  <button type="button" aria-label="关闭供应商详情" @click="closeAggregateProvider">
                    <X :size="17" />
                  </button>
                </header>

                <p class="new-theme-aggregate-detail-description">{{ selectedAggregateProvider.description }}</p>
                <div class="new-theme-aggregate-capabilities">
                  <span v-for="capability in selectedAggregateProvider.capabilities" :key="capability">{{ capability }}</span>
                </div>

                <div class="new-theme-aggregate-detail-actions">
                  <span>模型只来自当前已添加的上游分组</span>
                  <button
                    type="button"
                    :disabled="isAnyAggregateConnectionTesting || isAggregateConnectionsTesting"
                    @click="testAggregateProviderConnections(selectedAggregateProvider)"
                  >
                    <Activity :class="{ 'official-spin': aggregateProviderIsTesting(selectedAggregateProvider) }" :size="14" />
                    {{ aggregateProviderIsTesting(selectedAggregateProvider) ? '测试中' : '测试此供应商' }}
                  </button>
                </div>

                <div class="new-theme-aggregate-detail-groups">
                  <details
                    v-for="(group, groupIndex) in selectedAggregateProvider.groups"
                    :key="group.id"
                    class="new-theme-aggregate-detail-group"
                    :open="groupIndex === 0"
                  >
                    <summary>
                      <span class="new-theme-aggregate-detail-group-index">{{ String(groupIndex + 1).padStart(2, '0') }}</span>
                      <span class="new-theme-aggregate-detail-group-name">
                        <strong>{{ group.name }}</strong>
                        <small>{{ group.models.length }} 个模型 · {{ group.rateText || '标准倍率' }}</small>
                      </span>
                      <span
                        :class="[
                          'new-theme-aggregate-test-badge',
                          aggregateConnectionTestState(selectedAggregateProvider.id, group.id).status,
                        ]"
                      >
                        {{ aggregateConnectionTestLabel(selectedAggregateProvider.id, group.id) }}
                      </span>
                      <ChevronsUpDown :size="15" />
                    </summary>
                    <div class="new-theme-aggregate-detail-group-body">
                      <div class="new-theme-aggregate-detail-group-meta">
                        <span :class="{ ready: group.keyReady, error: group.keyError }">
                          <KeyRound :size="13" />{{ group.keyError ? 'Key 异常' : group.keyReady ? '独立 Key 已就绪' : 'Key 待准备' }}
                        </span>
                        <span :class="{ ready: group.modelReady, error: group.modelError, fallback: group.fallback, builtin: group.builtinCatalog }">
                          <Database :size="13" />{{ group.modelError ? '模型目录异常' : group.loading ? '模型目录读取中' : group.fallback ? '内置兜底目录' : group.builtinCatalog ? '默认支持目录' : group.modelReady ? '上游模型目录已就绪' : '模型目录待准备' }}
                        </span>
                      </div>

                      <div v-if="group.modelReady && group.models.length" class="new-theme-aggregate-detail-models">
                        <span v-for="model in group.models" :key="model" :title="model">
                          <img v-if="selectedAggregateProvider.logo" :src="selectedAggregateProvider.logo" alt="" />
                          {{ model }}
                        </span>
                      </div>
                      <div v-else class="new-theme-aggregate-model-empty compact">
                        <Clock :size="15" />
                        {{ group.loading ? '正在读取模型' : group.modelError ? '模型目录读取失败' : '该分组暂未返回模型' }}
                      </div>

                      <p v-if="group.keyError" class="new-theme-aggregate-group-message error">
                        {{ group.keyError }}
                      </p>
                      <p v-else-if="group.modelError" class="new-theme-aggregate-group-message error">
                        {{ group.modelError }}
                      </p>
                      <p v-else-if="group.fallback && group.message" class="new-theme-aggregate-group-message">
                        上游目录暂不可用，当前展示并写入的是内置兼容模型。
                      </p>
                      <p v-else-if="group.builtinCatalog && group.message" class="new-theme-aggregate-group-message builtin">
                        {{ group.message }}
                      </p>

                      <div
                        v-if="aggregateConnectionTestState(selectedAggregateProvider.id, group.id).status !== 'idle'"
                        :class="[
                          'new-theme-aggregate-test-result',
                          aggregateConnectionTestState(selectedAggregateProvider.id, group.id).status,
                        ]"
                      >
                        <CheckCircle2 v-if="aggregateConnectionTestState(selectedAggregateProvider.id, group.id).status === 'success'" :size="15" />
                        <RefreshCcw v-else-if="aggregateConnectionTestState(selectedAggregateProvider.id, group.id).status === 'testing'" class="official-spin" :size="15" />
                        <CircleAlert v-else :size="15" />
                        <span>
                          <strong>{{ aggregateConnectionTestState(selectedAggregateProvider.id, group.id).message }}</strong>
                          <small v-if="aggregateConnectionTestState(selectedAggregateProvider.id, group.id).testedAt">
                            {{ aggregateConnectionTestTime(aggregateConnectionTestState(selectedAggregateProvider.id, group.id).testedAt) }}
                          </small>
                        </span>
                      </div>

                      <button
                        class="new-theme-aggregate-group-test"
                        type="button"
                        :disabled="isAnyAggregateConnectionTesting || isAggregateConnectionsTesting"
                        @click="testAggregateGroupConnection(selectedAggregateProvider, group)"
                      >
                        <Activity :size="14" />
                        {{ aggregateConnectionTestState(selectedAggregateProvider.id, group.id).status === 'testing' ? '正在执行最小模型调用' : '测试连接与模型调用' }}
                      </button>
                    </div>
                  </details>
                </div>
              </aside>
            </Transition>
          </article>

          <AggregateModelSettings :groups="aggregateModelSettingsGroups" @saved="onAggregateModelSettingsSaved" />

          <article class="new-theme-aggregate-action">
            <span class="new-theme-card-accent" aria-hidden="true" />
            <div class="new-theme-aggregate-summary">
              <span>聚合配置</span>
              <strong>{{ aggregateAvailableProviders.length + aggregateEnabledExternalProviders.length }} 个供应商 · {{ aggregateGroupCount + aggregateEnabledExternalProviders.length }} 个分组 · {{ aggregateModelChoices.length + aggregateExternalModelCount }} 条模型路由</strong>
              <p>启用后，把鼠标移到 Codex 底部模型位置，即可按“供应商 → 分组 → 模型”逐级选择；最终仍只显示当前模型。</p>
            </div>
            <div class="new-theme-aggregate-actions">
              <button
                v-if="isAggregateLoginActive"
                class="secondary"
                type="button"
                :disabled="isAggregateLoginLoading"
                @click="disableAggregateLogin"
              >
                <X :size="16" />
                退出聚合登录
              </button>
              <button type="button" :disabled="!aggregateCanStart" @click="startAggregateLogin">
                <Play :size="16" />
                {{ aggregateActionButtonText }}
              </button>
            </div>
          </article>

          <article class="new-theme-aggregate-rule">
            <CircleAlert :size="18" />
            <div>
              <strong>配置优先级</strong>
              <p>启用聚合登录后，它会接管 Codex 中转配置；之后再使用“使用 ChatGPT”里的已有账号加油或无账号登录，或在账号管理中切换官方账号，系统会自动退出聚合模式并恢复对应配置。独立“使用 Claude”不会覆盖 Codex 聚合配置。</p>
            </div>
          </article>

          <div v-if="aggregateLoginNotice || aggregateLoginError" class="new-theme-aggregate-feedback">
            <p v-if="aggregateLoginNotice">{{ aggregateLoginNotice }}</p>
            <p v-if="aggregateLoginError" class="error">{{ aggregateLoginError }}</p>
          </div>
        </section>

        <section v-else-if="currentLoginPanel" :class="['new-theme-login-page', `tone-${currentLoginPanel.tone}`]" :aria-label="currentLoginPanel.title">
          <article class="new-theme-login-hero">
            <div class="new-theme-login-title">
              <span class="new-theme-login-icon" aria-hidden="true">
                <Bot :size="22" />
              </span>
              <div>
                <span>{{ currentLoginPanel.provider }}</span>
                <h1>{{ currentLoginPanel.title }}</h1>
                <p>{{ currentLoginPanel.subtitle }}</p>
              </div>
            </div>
            <div class="new-theme-login-status">
              <span aria-hidden="true" />
              {{ currentLoginPanel.status }}
            </div>
          </article>

          <div class="new-theme-login-grid">
            <article class="new-theme-login-card">
              <div class="new-theme-login-card-head">
                <div>
                  <span>选择分组</span>
                  <strong>账号分组</strong>
                </div>
                <Layers3 :size="18" />
              </div>
              <div class="new-theme-choice-list">
                <button
                  v-for="group in currentLoginPanel.groups"
                  :key="group.name"
                  :class="{ active: selectedLoginGroup === group.name }"
                  type="button"
                  :disabled="activeTool ? isToolGroupSyncing[activeTool] : false"
                  @click="selectLoginGroup(group)"
                >
                  <span class="new-theme-login-group-body">
                    <span class="new-theme-login-group-title">
                      <strong>{{ group.name }}</strong>
                      <span v-if="group.rateValue || group.rateText" class="new-theme-login-rate-badge">
                        <template v-if="group.rateValue">
                          <span class="new-theme-rate-value">{{ group.rateValue }}</span>
                          <span class="new-theme-rate-label">倍率</span>
                        </template>
                        <span v-else class="new-theme-rate-label">{{ group.rateText }}</span>
                      </span>
                    </span>
                    <small>
                      <span>{{ group.detail }}</span>
                    </small>
                  </span>
                  <CheckCircle2 v-if="selectedLoginGroup === group.name" :size="17" />
                </button>
              </div>
            </article>

            <article class="new-theme-login-card new-theme-model-card">
              <div class="new-theme-login-card-head">
                <div>
                  <span>获取模型</span>
                  <strong>可用模型</strong>
                </div>
                <div class="new-theme-login-card-actions">
                  <button class="new-theme-refresh-button" type="button" :disabled="isCurrentModelLoading" @click="refreshLoginModels">
                    <RefreshCcw :size="15" />
                    {{ isCurrentModelLoading ? '刷新中' : '刷新' }}
                  </button>
                  <button class="new-theme-refresh-button" type="button" :disabled="activeTool ? isToolLatencyTesting[activeTool] : false" @click="testLatencyForActivePage">
                    <Gauge :size="15" />
                    {{ activeTool && isToolLatencyTesting[activeTool] ? '测速中' : '测速' }}
                  </button>
                </div>
              </div>
              <div class="new-theme-model-list">
                <button
                  v-for="model in currentLoginPanel.models"
                  :key="model.name"
                  :class="{ active: selectedLoginModel === model.name }"
