                  @click="selectLoginModel(model)"
                >
                  <span class="new-theme-model-tag">{{ model.tag }}</span>
                  <span>
                    <strong>{{ model.name }}</strong>
                    <small>{{ model.detail }}</small>
                  </span>
                </button>
                <div v-if="activeTool === 'codex'" class="new-theme-codex-catalog">
                  <small>{{ codexModelCatalogSource === 'upstream' ? '已获取模型目录' : '兼容模型目录' }} · {{ codexModelOptions.length }} 个</small>
