                    <span v-for="model in codexModelOptions" :key="model" role="listitem" :title="model">{{ model }}</span>
                  </div>
                </div>
              </div>
            </article>

            <article class="new-theme-login-action-card">
              <span class="new-theme-card-accent" aria-hidden="true" />
              <div>
                <span>{{ loginActionLabel }}</span>
                <strong>{{ currentLoginPanel.provider }}</strong>
