              </button>
              <button
                v-if="activeTool === 'codex'"
                class="restart-codex"
                type="button"
                :disabled="isLoginActionBusy"
                @click="restartCodexForActivePage"
              >
                <RefreshCcw :class="{ 'official-spin': isCodexRestarting }" :size="17" />
                {{ isCodexRestarting ? '重启中' : '重启 ChatGPT' }}
              </button>
              <button
                v-if="activeTool === 'codex'"
                class="force-official-login"
                type="button"
                :disabled="isForceOfficialCodexBusy"
                @click="forceOfficialCodexForActivePage"
              >
                <RefreshCcw :size="17" />
                {{ isForceOfficialCodexBusy ? '恢复中' : '强制官方' }}
              </button>
            </article>
          </div>


          <div class="new-theme-login-steps">
            <article v-for="step in currentLoginPanel.steps" :key="step.label" class="new-theme-login-step">
              <span>
                <component :is="step.icon" :size="17" />
              </span>
              <div>
                <strong>{{ step.label }}</strong>
                <small>{{ step.detail }}</small>
              </div>
            </article>
          </div>
        </section>

        <CodexPluginMarket
          v-else-if="activePage === '安装插件'"
          :restart-busy="isCodexRestarting"
          :restart-notice="pluginMarketRestartRequested ? toolNotices.codex : ''"
          :restart-error="pluginMarketRestartRequested ? toolErrors.codex : ''"
          :restart-warning="pluginMarketRestartRequested ? toolWarnings.codex : ''"
          :restart-revision="pluginMarketRestartRevision"
          :confirm-uninstall="confirmPluginUninstall"
          @restart="restartCodexForActivePage"
        />

