        <section v-else-if="activePage === '添加 Key'" class="new-theme-api-key-page" aria-label="添加 Key">
          <div class="new-theme-page-head">
            <div>
              <span>添加 Key</span>
              <strong>创建与查看 Key 钥匙</strong>
            </div>
            <div class="new-theme-page-actions">
              <button type="button" :disabled="isApiKeysLoading" @click="loadApiKeys()">
                <RefreshCcw :size="15" />
                {{ isApiKeysLoading ? '刷新中' : '刷新' }}
              </button>
            </div>
          </div>

          <article class="new-theme-api-key-create">
            <label>
              <span>Key 名称</span>
              <input v-model="newApiKeyName" type="text" :disabled="isApiKeysLoading" placeholder="例如：Codex 默认 Key" />
            </label>
            <label>
              <span>账号分组</span>
              <select v-model.number="selectedApiKeyGroupId" :disabled="isApiKeysLoading || apiKeyGroupOptions.length === 0">
                <option v-for="group in apiKeyGroupOptions" :key="group.id" :value="group.id">
                  {{ group.name }} · {{ group.badge }} · {{ group.rateText }}
                </option>
              </select>
            </label>
            <button type="button" :disabled="isApiKeysLoading || apiKeyGroupOptions.length === 0" @click="createNewApiKey">
              <Plus :size="15" />
              {{ isApiKeysLoading ? '处理中' : '创建 Key' }}
            </button>
          </article>

          <div class="new-theme-api-key-grid">
            <article v-for="row in apiKeyRows" :key="row.id" class="new-theme-api-key-card">
              <div>
                <span>{{ row.groupName }} · {{ row.groupBadge }} · {{ row.groupRateText }}</span>
                <strong>{{ row.name }}</strong>
                <small>{{ row.visibleValue }}</small>
              </div>
              <div class="new-theme-api-key-meta">
                <span>{{ row.status }}</span>
                <small>{{ row.createdAt }}</small>
              </div>
              <div class="new-theme-key-actions">
                <button type="button" aria-label="复制" @click="copyApiKey(row)">
                  <Copy :size="15" />
                  复制
                </button>
                <button class="danger" type="button" aria-label="删除" :disabled="isApiKeysLoading" @click="deleteApiKeyRow(row)">
                  <Trash2 :size="15" />
                  删除
                </button>
              </div>
            </article>
            <p v-if="!apiKeyRows.length" class="new-theme-empty-copy">
              暂无 Key，选择分组后创建一个即可使用。
            </p>
          </div>
        </section>

        <section v-else-if="activePage === '账号管理'" class="new-theme-account-page" aria-label="账号管理">
