                  <span>已选账户</span>
                  <strong>{{ selectedAccount.email }}</strong>
                  <small>
                    快照密钥：
                    <span class="new-theme-secret-mask">{{ maskedSnapshotSecret }}</span>
                    <button class="new-theme-copy-icon-button" type="button" aria-label="复制快照密钥" @click="copyAccountSnapshotSecret">
                      <Copy :size="14" />
                    </button>
                  </small>
                </div>
                <span class="new-theme-plan-pill">{{ selectedAccount.plan }}</span>
              </div>

              <div class="new-theme-detail-meters">
                <div v-for="meter in accountQuotaMeters" :key="meter.label" :class="['new-theme-account-meter', `tone-${meter.tone}`]">
                  <div>
                    <span>{{ meter.label }}</span>
                    <strong>{{ meter.value }}</strong>
                  </div>
                  <span class="new-theme-meter-track">
                    <span :style="{ width: `${meter.progress}%` }" />
                  </span>
                  <small>
                    <Timer :size="13" />
                    {{ meter.detail }}
                  </small>
                </div>
              </div>

              <div class="new-theme-account-info-table">
                <div v-for="row in accountInfoRows" :key="row.label">
                  <span>{{ row.label }}</span>
                  <strong>{{ row.value }}</strong>
