              <div class="new-theme-detail-actions">
                <button class="primary" type="button" :disabled="codexAccountSwitchDisabled(selectedAccount)" @click="normalLoginCodexAccount(selectedAccount.account)">
                  <CheckCircle2 v-if="selectedAccount.isCurrent" :size="15" />
                  <RefreshCcw v-else :size="15" />
                  {{ codexAccountSwitchButtonText(selectedAccount) }}
                </button>
                <button class="danger" type="button" :disabled="isCodexAccountDeleting" @click="deleteCodexAccount(selectedAccount.account)">
                  <Trash2 :size="15" />
                  {{ isCodexAccountDeleting ? '移除中' : '移除快照' }}
                </button>
              </div>
            </article>
            <article v-else class="new-theme-account-detail-panel">
              <div class="new-theme-detail-head">
                <div>
                  <span>已选账户</span>
                  <strong>暂无账号</strong>
                  <small>请先添加或导入 Codex 账号快照。</small>
                </div>
              </div>
            </article>
          </div>
