              </div>
              <button type="button" :disabled="isOfficialIdentifying || !plan.localPrice" @click="requestOfficialSubscription(plan)">
                <RefreshCcw v-if="isOfficialIdentifying && selectedOfficialPlanId === plan.id" class="official-spin" :size="15" />
                {{ isOfficialIdentifying && selectedOfficialPlanId === plan.id ? '正在识别账号' : '点击订阅' }}
              </button>
            </article>
          </div>

