                  <span>
                    <strong>{{ row.amount }}</strong>
                  </span>
                  <span>{{ row.progress }}</span>
                </div>
                <div v-if="!officialSubscriptionInfoRows.length" class="new-theme-subscription-info-row official">
                  <span class="new-theme-muted-cell">暂无官方订阅</span>
                  <span>-</span>
                  <span>-</span>
                  <span>-</span>
                  <span>-</span>
                </div>
              </div>
