              <span>按月订阅 / 每日额度</span>
            </div>
          </article>

          <div class="new-theme-official-plans new-theme-platform-plans">
            <article
              v-for="plan in platformSubscriptionPlans"
              :key="plan.id"
              :class="['new-theme-official-plan-card', 'new-theme-platform-plan-card', `tone-${plan.tone}`, { featured: plan.featured }]"
            >
              <div class="new-theme-official-plan-top">
                <span>{{ plan.badge }}</span>
                <strong>{{ plan.name }}</strong>
                <small>{{ plan.tagline }}</small>
              </div>
              <p>{{ plan.description }}</p>
              <div class="new-theme-official-plan-list">
