              v-for="card in systemConfigCards"
              :key="card.label"
              :class="['new-theme-stat-card', 'new-theme-config-card', `tone-${card.tone}`, { 'has-secondary-action': card.secondaryActionText, 'is-language-card': card.label === '强制中文' }]"
            >
              <span class="new-theme-card-accent" aria-hidden="true" />
              <div class="new-theme-stat-head">
                <span>{{ card.label }}<small v-if="card.label === '强制中文' && codexLanguageNeedsRestart" class="new-theme-language-restart">需重启</small></span>
                <component v-if="card.label !== '强制中文'" :is="card.icon" :size="18" />
              </div>
              <p v-if="card.label === '官方插件'" class="new-theme-plugin-help">API 用户可强制开启官方插件，未找到的插件请前往插件市场自行下载。</p>
              <template v-if="card.label !== '官方插件'">
                <strong v-if="card.label !== '强制中文'">{{ card.value }}</strong>
