        <p v-if="officialSubscriptionError" class="official-dialog-error">{{ officialSubscriptionError }}</p>

        <footer class="new-theme-dialog-actions">
          <button type="button" :disabled="isOfficialSubscribing" @click="showOfficialCardDialog = false">取消</button>
          <button class="primary" type="button" :disabled="isOfficialSubscribing" @click="submitOfficialCardPayment">
            {{ isOfficialSubscribing ? '提交中' : '确定' }}
          </button>
        </footer>
      </section>
