  gap: 0.8rem;
  width: 100%;
  max-width: 100%;
}

.new-theme-aggregate-page {
  display: grid;
  gap: 0.68rem;
  width: 100%;
  max-width: 100%;
}

.new-theme-aggregate-hero,
.new-theme-aggregate-intro,
