  gap: 0.75rem;
  padding: 0.72rem 0.86rem;
}

.new-theme-aggregate-hero .new-theme-login-title {
  gap: 0.68rem;
}

.new-theme-aggregate-hero .new-theme-login-icon {
  width: 2.18rem;
  height: 2.18rem;
  border-radius: 0.7rem;
}

.new-theme-aggregate-hero .new-theme-login-title > div {
  gap: 0.12rem;
}

.new-theme-aggregate-hero .new-theme-login-title span {
