}

.new-theme-aggregate-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.85rem;
  padding: 0.72rem 0.86rem;
}

.new-theme-aggregate-intro-copy {
  display: grid;
  gap: 0.22rem;
}

.new-theme-aggregate-intro-copy > span,
.new-theme-aggregate-section-head span,
.new-theme-aggregate-summary > span {
  color: #64748b;
  font-size: 0.78rem;
