  text-transform: uppercase;
}

.new-theme-aggregate-intro-copy strong,
.new-theme-aggregate-section-head strong,
.new-theme-aggregate-summary strong {
  color: #111827;
  font-size: 1.08rem;
  font-weight: 900;
}

.new-theme-aggregate-intro-copy p,
.new-theme-aggregate-summary p {
  margin: 0;
  color: #667085;
  font-size: 0.86rem;
  line-height: 1.65;
}

.new-theme-aggregate-intro-copy > span {
  font-size: 0.7rem;
}

.new-theme-aggregate-intro-copy strong {
  font-size: 0.98rem;
}

.new-theme-aggregate-intro-copy p {
  font-size: 0.76rem;
  line-height: 1.5;
}

.new-theme-aggregate-benefits {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.42rem;
}

.new-theme-aggregate-benefits span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.32rem;
  min-height: 2.45rem;
  border: 1px solid color-mix(in srgb, var(--tone) 24%, #e3e7ee);
  border-radius: 0.68rem;
  padding: 0.38rem 0.58rem;
  color: var(--tone-strong);
  background: var(--tone-pill);
  font-size: 0.7rem;
  font-weight: 850;
  text-align: center;
  white-space: nowrap;
}

.new-theme-aggregate-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.12rem 0.15rem;
}

.new-theme-aggregate-section-head > div {
  display: grid;
  gap: 0.18rem;
}

.new-theme-aggregate-section-head button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.42rem;
  min-height: 2.2rem;
  border: 1px solid #dbe3ec;
  border-radius: 0.72rem;
  padding: 0 0.78rem;
  color: #0f172a;
  background: #ffffff;
  font-size: 0.82rem;
  font-weight: 850;
}

.new-theme-aggregate-section-head > .new-theme-aggregate-toolbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.45rem;
}

.new-theme-aggregate-explorer {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-height: 29rem;
  overflow: hidden;
  border: 1px solid #e1e7ef;
  border-radius: 1.15rem;
  background: #f8fafc;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.06);
  transition: grid-template-columns 240ms ease;
}

.new-theme-aggregate-explorer.detail-open {
  grid-template-columns: minmax(24rem, 1.2fr) minmax(21rem, 0.8fr);
}

.new-theme-aggregate-canvas {
  position: relative;
  display: flex;
  align-content: center;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 1.65rem 2rem;
  min-width: 0;
  min-height: 29rem;
  padding: 3.1rem 2.25rem 3.4rem;
  overflow: hidden;
  background:
    radial-gradient(circle at 18% 24%, rgba(59, 130, 246, 0.12), transparent 24%),
    radial-gradient(circle at 78% 72%, rgba(139, 92, 246, 0.12), transparent 28%),
    radial-gradient(circle, rgba(100, 116, 139, 0.2) 1px, transparent 1.2px),
    linear-gradient(145deg, #ffffff 0%, #f7faff 54%, #fbf8ff 100%);
  background-position: center, center, 0 0, center;
  background-size: auto, auto, 22px 22px, auto;
}

.new-theme-aggregate-orbit {
  position: absolute;
  pointer-events: none;
  border: 1px dashed rgba(100, 116, 139, 0.17);
  border-radius: 50%;
}

.new-theme-aggregate-orbit.orbit-one {
  width: 23rem;
  height: 11rem;
  transform: rotate(-12deg);
}

.new-theme-aggregate-orbit.orbit-two {
  width: 34rem;
  height: 18rem;
  transform: rotate(16deg);
}

.new-theme-aggregate-node {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.78rem;
  width: min(20rem, calc(50% - 1rem));
  min-height: 6.2rem;
  border: 1px solid color-mix(in srgb, var(--tone) 24%, #dce4ee);
  border-radius: 1.2rem;
  padding: 0.92rem 0.95rem;
  color: #172033;
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 18px 36px rgba(15, 23, 42, 0.09);
  text-align: left;
  backdrop-filter: blur(14px);
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
}

.new-theme-aggregate-node.shape-0 {
  width: min(20.5rem, calc(52% - 1rem));
  transform: translateY(-1.15rem) rotate(-0.7deg);
}

.new-theme-aggregate-node.shape-1 {
  width: min(18.2rem, calc(46% - 1rem));
  transform: translateY(2.25rem) rotate(0.85deg);
}

.new-theme-aggregate-node.shape-2 {
  width: min(17.5rem, calc(43% - 1rem));
  transform: translateY(-0.2rem) rotate(0.5deg);
}

.new-theme-aggregate-node.shape-3 {
  width: min(21rem, calc(55% - 1rem));
  transform: translateY(1.3rem) rotate(-0.45deg);
}

.new-theme-aggregate-node.shape-4 {
  width: min(18.8rem, calc(48% - 1rem));
  transform: translateY(-0.8rem) rotate(0.65deg);
}

.new-theme-aggregate-node:hover,
.new-theme-aggregate-node.active {
  z-index: 2;
  border-color: color-mix(in srgb, var(--tone) 58%, #cbd5e1);
  box-shadow: 0 24px 48px color-mix(in srgb, var(--tone) 16%, rgba(15, 23, 42, 0.12));
}

.new-theme-aggregate-node.shape-0:hover,
.new-theme-aggregate-node.shape-0.active {
  transform: translateY(-1.32rem) rotate(0deg) scale(1.025);
}

.new-theme-aggregate-node.shape-1:hover,
.new-theme-aggregate-node.shape-1.active {
  transform: translateY(2.08rem) rotate(0deg) scale(1.025);
}

.new-theme-aggregate-node.shape-2:hover,
.new-theme-aggregate-node.shape-2.active,
.new-theme-aggregate-node.shape-3:hover,
.new-theme-aggregate-node.shape-3.active,
.new-theme-aggregate-node.shape-4:hover,
.new-theme-aggregate-node.shape-4.active {
  transform: translateY(0) rotate(0deg) scale(1.025);
}

.new-theme-aggregate-node-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: linear-gradient(120deg, var(--tone-soft), transparent 48%);
  opacity: 0.7;
}

.new-theme-aggregate-node-logo,
.new-theme-aggregate-detail-logo {
  position: relative;
  display: grid;
  place-items: center;
  width: 3.05rem;
  height: 3.05rem;
