  border-radius: 1rem;
  color: var(--tone-strong);
  background: color-mix(in srgb, var(--tone-pill) 62%, #ffffff);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.new-theme-aggregate-node-logo img,
.new-theme-aggregate-detail-logo img {
