  font-size: 0.65rem;
  font-weight: 720;
}

.new-theme-aggregate-test-badge {
  border-radius: 999px;
  padding: 0.22rem 0.45rem;
  color: #64748b;
  background: #eef2f7;
  font-size: 0.62rem;
  font-weight: 860;
