  align-items: center;
  gap: 0.28rem;
  border-radius: 999px;
  padding: 0.25rem 0.46rem;
  color: #64748b;
  background: #eef2f7;
  font-size: 0.63rem;
  font-weight: 800;
}

.new-theme-aggregate-detail-group-meta span.ready {
  color: #047857;
  background: rgba(16, 185, 129, 0.12);
}

.new-theme-aggregate-detail-group-meta span.error {
  color: #dc2626;
  background: rgba(239, 68, 68, 0.12);
}

.new-theme-aggregate-detail-group-meta span.fallback {
  color: #b45309;
  background: rgba(245, 158, 11, 0.13);
}

.new-theme-aggregate-detail-group-meta span.builtin {
  color: #0369a1;
  background: rgba(14, 165, 233, 0.12);
}

.new-theme-aggregate-detail-models {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
  gap: 0.36rem;
  max-height: 9rem;
  overflow-y: auto;
  padding-right: 0.12rem;
  scrollbar-width: thin;
}

.new-theme-aggregate-detail-models > span {
  display: flex;
  align-items: center;
  gap: 0.34rem;
  min-width: 0;
  border: 1px solid color-mix(in srgb, var(--tone) 18%, #e3e8ef);
  border-radius: 0.58rem;
  padding: 0.38rem 0.45rem;
  overflow: hidden;
  color: #334155;
  background: rgba(255, 255, 255, 0.78);
  font-size: 0.66rem;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-aggregate-detail-models img {
  width: 1.08rem;
  height: 1.08rem;
  flex: 0 0 auto;
  box-sizing: border-box;
  border-radius: 0.3rem;
  padding: 0.08rem;
  object-fit: contain;
