  font-size: 0.86rem;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-invoice-title-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-invoice-table {
  display: grid;
  overflow-x: auto;
  border: 1px solid #e6edf6;
  border-radius: 0.82rem;
}

.new-theme-invoice-table-head,
.new-theme-invoice-row {
  display: grid;
  align-items: center;
  gap: 0.56rem;
  padding: 0 0.72rem;
}

.new-theme-invoice-table-head.invoice-orders-grid,
.new-theme-invoice-row.invoice-orders-grid {
  grid-template-columns: minmax(4.4rem, 0.38fr) minmax(9.2rem, 1fr) minmax(8.5rem, 1.05fr) minmax(5.8rem, 0.5fr) minmax(5.5rem, 0.52fr) minmax(5.2rem, 0.45fr) minmax(6rem, 0.48fr);
  min-width: 56rem;
}

.new-theme-invoice-table-head.invoice-applications-grid,
.new-theme-invoice-row.invoice-applications-grid {
  grid-template-columns: minmax(9.2rem, 0.9fr) minmax(10rem, 1fr) minmax(5.6rem, 0.45fr) minmax(6.2rem, 0.52fr) minmax(8rem, 0.75fr) minmax(5.2rem, 0.45fr) minmax(7.5rem, 0.62fr);
  min-width: 65rem;
}

.new-theme-invoice-table-head {
  min-height: 2.35rem;
  background: #f8fbff;
}

.new-theme-invoice-row {
  min-height: 3.2rem;
  border-top: 1px solid #e6edf6;
}

.new-theme-invoice-row strong {
  overflow: hidden;
