  margin: 0;
  accent-color: #0891b2;
  cursor: pointer;
}

.new-theme-invoice-check-cell input:disabled {
  cursor: not-allowed;
}

.new-theme-invoice-source {
  color: #475569;
  font-size: 0.78rem;
  font-weight: 780;
}

.new-theme-invoice-amount {
  color: #059669;
  font-size: 0.8rem;
  font-weight: 900;
}

.new-theme-invoice-status {
  width: fit-content;
  border-radius: 999px;
  padding: 0.18rem 0.52rem;
  font-size: 0.72rem;
  font-weight: 880;
