}

.new-theme-invoice-status.ready {
  color: #0369a1;
  background: rgba(14, 165, 233, 0.12);
}

.new-theme-invoice-status.waiting {
  color: #92400e;
  background: rgba(245, 158, 11, 0.14);
}

.new-theme-invoice-status.completed {
  color: #047857;
  background: rgba(16, 185, 129, 0.13);
}

.new-theme-invoice-actions {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.4rem;
  min-width: 0;
}

.new-theme-invoice-actions button:disabled {
  color: #94a3b8;
  background: #f8fafc;
  cursor: not-allowed;
  transform: none;
}

.new-theme-invoice-selection-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  position: sticky;
  bottom: 0.5rem;
  z-index: 3;
  border: 1px solid rgba(8, 145, 178, 0.24);
  border-radius: 0.82rem;
  padding: 0.7rem 0.78rem;
  background: rgba(240, 249, 255, 0.96);
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.12);
  backdrop-filter: blur(14px);
}

.new-theme-invoice-selection-bar > div {
  display: flex;
  align-items: center;
  gap: 0.62rem;
}

.new-theme-invoice-selection-bar span {
  color: #475569;
  font-size: 0.78rem;
  font-weight: 800;
}

