}

.new-theme-invoice-selection-bar button.primary {
  color: #ffffff;
  border-color: #0891b2;
  background: #0891b2;
}

.new-theme-invoice-selection-bar button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.invoice-apply-dialog {
  width: min(34rem, calc(100vw - 1.5rem));
}

.new-theme-invoice-apply-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  padding: 1rem 1rem 0;
}

.new-theme-invoice-apply-summary div {
  display: grid;
  gap: 0.16rem;
  border: 1px solid #e6edf6;
  border-radius: 0.72rem;
