}

.new-theme-tutorial-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "tag action"
    "title action"
    "summary action";
  align-items: center;
  gap: 0.18rem 0.9rem;
  width: 100%;
  min-height: 5.6rem;
  border-color: #dbe3ef;
  padding: 0.9rem 1rem;
  color: inherit;
  text-align: left;
  background:
    linear-gradient(135deg, rgba(239, 68, 68, 0.08), transparent 44%),
    #ffffff;
  cursor: pointer;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.new-theme-tutorial-card:hover,
.new-theme-tutorial-card.active {
  border-color: rgba(239, 68, 68, 0.52);
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.08);
}

