  color: #111827;
  font-size: 0.96rem;
  font-weight: 860;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-image2-canvas {
  position: relative;
  display: grid;
  place-items: center;
  min-height: clamp(20rem, 46vh, 34rem);
  overflow: hidden;
  border: 1px solid #dbe3ef;
  border-radius: 0.82rem;
  background:
    linear-gradient(45deg, rgba(148, 163, 184, 0.11) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(148, 163, 184, 0.11) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(148, 163, 184, 0.11) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(148, 163, 184, 0.11) 75%),
    #f8fafc;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0;
  background-size: 20px 20px;
  touch-action: pan-y;
  user-select: none;
}

.new-theme-image2-canvas img {
  width: 100%;
  height: 100%;
  max-height: clamp(20rem, 46vh, 34rem);
  object-fit: contain;
  pointer-events: none;
}

.new-theme-image2-result-preview {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  min-height: inherit;
  border: 0;
  padding: 0;
  background: transparent;
  cursor: zoom-in;
}

.new-theme-image2-result-preview > span {
  position: absolute;
  right: 0.78rem;
  bottom: 0.78rem;
  border: 1px solid rgba(255, 255, 255, 0.55);
  border-radius: 999px;
  padding: 0.32rem 0.62rem;
  color: #ffffff;
  background: rgba(15, 23, 42, 0.58);
  box-shadow: 0 10px 26px rgba(15, 23, 42, 0.18);
  font-size: 0.72rem;
  font-weight: 820;
  opacity: 0;
  transform: translateY(0.25rem);
  transition: opacity 0.18s ease, transform 0.18s ease;
  backdrop-filter: blur(10px);
}

.new-theme-image2-result-preview:hover > span,
.new-theme-image2-result-preview:focus-visible > span {
  opacity: 1;
  transform: translateY(0);
}

.new-theme-image2-empty {
  display: grid;
  justify-items: center;
  gap: 0.36rem;
  padding: 1.2rem;
  color: #64748b;
  text-align: center;
}

.new-theme-image2-empty svg {
  color: #2563eb;
}

.new-theme-image2-empty strong {
  color: #111827;
  font-size: 0.98rem;
  font-weight: 860;
}

.new-theme-image2-empty span {
  max-width: 16rem;
  color: #64748b;
  font-size: 0.78rem;
  line-height: 1.5;
}

.new-theme-image2-generating-state {
  gap: 0.62rem;
}

.new-theme-image2-generation-loading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.82rem;
  margin-bottom: 0.08rem;
}

.new-theme-image2-generation-loader {
  --path: #2563eb;
  --dot: #0891b2;
  --fill: rgba(255, 255, 255, 0.86);
  --duration: 3s;
  position: relative;
  width: 2.82rem;
  height: 2.82rem;
  filter: drop-shadow(0 12px 20px rgba(37, 99, 235, 0.16));
}

.new-theme-image2-generation-loader::before {
  content: '';
  position: absolute;
  top: 2.35rem;
  left: 1.22rem;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--dot);
  box-shadow: 0 0 0 0.28rem rgba(8, 145, 178, 0.14);
  transform: translate(-1.15rem, -1.15rem);
  animation: image2GenerationDot var(--duration) cubic-bezier(0.785, 0.135, 0.15, 0.86) infinite;
}

.new-theme-image2-generation-loader svg {
  display: block;
  width: 100%;
  height: 100%;
}

.new-theme-image2-generation-loader rect {
  fill: var(--fill);
  stroke: var(--path);
  stroke-width: 9px;
  stroke-dasharray: 192 64 192 64;
  stroke-dashoffset: 0;
  stroke-linecap: round;
  stroke-linejoin: round;
  animation: image2GenerationPath var(--duration) cubic-bezier(0.785, 0.135, 0.15, 0.86) infinite;
}

.new-theme-image2-generation-loader text {
  fill: #0f172a;
  font-size: 1.35rem;
  font-weight: 900;
  dominant-baseline: middle;
}

.new-theme-image2-generation-loader:nth-child(2)::before,
.new-theme-image2-generation-loader:nth-child(2) rect {
  animation-delay: 0.12s;
}

.new-theme-image2-generation-loader:nth-child(3)::before,
.new-theme-image2-generation-loader:nth-child(3) rect {
  animation-delay: 0.24s;
}

.new-theme-image2-generation-loader:nth-child(4)::before,
.new-theme-image2-generation-loader:nth-child(4) rect {
  animation-delay: 0.36s;
}

@keyframes image2GenerationPath {
  25% {
    stroke-dashoffset: 64;
  }

  50% {
    stroke-dashoffset: 128;
  }

  75% {
    stroke-dashoffset: 192;
  }

  100% {
    stroke-dashoffset: 256;
  }
}

@keyframes image2GenerationDot {
  25% {
    transform: translate(0, 0);
  }

  50% {
    transform: translate(1.15rem, -1.15rem);
  }

  75% {
    transform: translate(0, -2.3rem);
  }

  100% {
    transform: translate(-1.15rem, -1.15rem);
  }
}

