  min-height: 2rem;
  border: 1px solid rgba(6, 182, 212, 0.34);
  border-radius: 0.58rem;
  padding: 0 0.72rem;
  color: #0e7490;
  background: rgba(6, 182, 212, 0.1);
  font-size: 0.76rem;
  font-weight: 900;
}

.new-theme-invitation-code-box button:hover:not(:disabled) {
  border-color: rgba(6, 182, 212, 0.52);
  background: rgba(6, 182, 212, 0.16);
}

.new-theme-invitation-code-box button:disabled {
  cursor: default;
  opacity: 0.52;
}

.new-theme-invitation-reward-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) repeat(2, minmax(0, 0.75fr));
  gap: 0.52rem;
}

.new-theme-invitation-reward-grid > div {
  display: grid;
  gap: 0.24rem;
  min-width: 0;
  border: 1px solid rgba(245, 158, 11, 0.2);
  border-radius: 0.72rem;
  padding: 0.62rem 0.7rem;
  background: rgba(255, 251, 235, 0.62);
}

.new-theme-invitation-reward-pool {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.5rem;
}

.new-theme-invitation-reward-copy {
  display: grid;
  gap: 0.24rem;
  min-width: 0;
}

.new-theme-invitation-reward-grid span,
.new-theme-invitation-reward-grid small {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 820;
}

.new-theme-invitation-reward-grid small b {
  color: #b45309;
  font-weight: 950;
}

.new-theme-invitation-reward-grid strong {
  color: #b45309;
  font-size: 1.18rem;
  font-weight: 950;
  line-height: 1;
}

.new-theme-invitation-reward-actions {
  display: grid;
  gap: 0.34rem;
  min-width: 4.15rem;
}

.new-theme-invitation-reward-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 1.5rem;
  border: 1px solid rgba(245, 158, 11, 0.32);
  border-radius: 0.54rem;
  padding: 0 0.56rem;
  color: #b45309;
  background: rgba(245, 158, 11, 0.1);
  font-size: 0.7rem;
  font-weight: 900;
  white-space: nowrap;
}

.new-theme-invitation-reward-actions button:hover {
  border-color: rgba(245, 158, 11, 0.52);
  background: rgba(245, 158, 11, 0.16);
}

.new-theme-invitation-stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.52rem;
}

.new-theme-invitation-stat-card {
  display: grid;
  gap: 0.32rem;
  min-height: 6rem;
  padding: 0.72rem;
}

.new-theme-invitation-stat-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4rem;
  min-width: 0;
}

.new-theme-invitation-stat-card span {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 850;
}

.new-theme-invitation-stat-head b {
  color: #ef4444;
  font-size: 0.7rem;
  font-weight: 900;
  white-space: nowrap;
}

.new-theme-invitation-stat-card strong {
  color: var(--tone-strong);
  font-size: 1.38rem;
  font-weight: 950;
  line-height: 1;
}

.new-theme-invitation-stat-card small {
  overflow: hidden;
  color: #64748b;
  font-size: 0.7rem;
  font-weight: 760;
  line-height: 1.32;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-invitation-bind-card {
  display: grid;
  grid-column: span 2;
  grid-template-columns: minmax(7.4rem, 0.75fr) minmax(0, 1.25fr);
  align-items: center;
  gap: 0.68rem;
  min-height: 6rem;
  padding: 0.72rem;
}

.new-theme-invitation-bind-copy {
  display: grid;
  gap: 0.26rem;
  min-width: 0;
}

.new-theme-invitation-bind-copy span {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 850;
}

.new-theme-invitation-bind-copy strong {
  overflow: hidden;
  color: #111316;
  font-size: 1rem;
  font-weight: 930;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-invitation-bind-copy small {
  overflow: hidden;
  color: #64748b;
  font-size: 0.7rem;
  font-weight: 760;
  line-height: 1.32;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-invitation-bind-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.36rem;
  min-width: 0;
}

.new-theme-invitation-bind-form input {
  width: 100%;
  min-width: 0;
  height: 2.18rem;
  border: 1px solid #d9e0ea;
  border-radius: 0.62rem;
  padding: 0 0.72rem;
  color: #111316;
  background: #ffffff;
  font-size: 0.78rem;
  font-weight: 820;
  outline: none;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.new-theme-invitation-bind-form input:focus {
  border-color: rgba(6, 182, 212, 0.52);
  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.12);
}

.new-theme-invitation-bind-form input::placeholder {
  color: #9aa5b1;
}

.new-theme-invitation-bind-form input:disabled {
  cursor: default;
  color: #64748b;
  background: #f1f5f9;
}

.new-theme-invitation-bind-form button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.34rem;
  width: 100%;
  min-height: 2.18rem;
  border: 1px solid rgba(6, 182, 212, 0.34);
  border-radius: 0.62rem;
  padding: 0 0.78rem;
  color: #ffffff;
  background: linear-gradient(135deg, #06b6d4, #0e7490);
  box-shadow: 0 10px 22px rgba(6, 182, 212, 0.17);
  font-size: 0.76rem;
  font-weight: 900;
  white-space: nowrap;
}

.new-theme-invitation-bind-form button:hover:not(:disabled) {
  filter: brightness(1.04);
}

.new-theme-invitation-bind-form button:disabled {
  cursor: default;
  border-color: rgba(148, 163, 184, 0.26);
  color: #64748b;
  background: #eef2f7;
  box-shadow: none;
}

.new-theme-invitation-table-panel {
  --tone: #3b82f6;
  --tone-soft: rgba(59, 130, 246, 0.1);
  display: grid;
  gap: 0.6rem;
  padding: 0.76rem;
}

.new-theme-invitation-table-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.new-theme-invitation-table-head div {
  display: grid;
  gap: 0.18rem;
}

.new-theme-invitation-table-head span {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 850;
}

.new-theme-invitation-table-head strong {
  color: #111316;
  font-size: 0.96rem;
  font-weight: 920;
}

.new-theme-invitation-table {
  overflow: auto;
  border: 1px solid #e2e8f0;
  border-radius: 0.68rem;
  background: #ffffff;
}

.new-theme-invitation-row {
  display: grid;
  grid-template-columns: minmax(9rem, 1.1fr) minmax(5rem, 0.5fr) minmax(6.6rem, 0.65fr) minmax(8rem, 0.85fr) minmax(7rem, 0.7fr);
  gap: 0.58rem;
  align-items: center;
  min-width: 42rem;
  min-height: 2.48rem;
  border-bottom: 1px solid #eef2f7;
  padding: 0.48rem 0.65rem;
  color: #334155;
  font-size: 0.74rem;
  font-weight: 760;
}

.new-theme-invitation-row:last-child {
  border-bottom: 0;
}

.new-theme-invitation-row.is-head {
  position: sticky;
  z-index: 1;
  top: 0;
  min-height: 2.08rem;
  color: #64748b;
  background: #f1f5f9;
  font-size: 0.68rem;
  font-weight: 920;
}

.new-theme-invitation-row span,
.new-theme-invitation-row strong {
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-invitation-row strong {
  color: #111316;
  font-weight: 900;
}

.new-theme-invitation-row .reward {
  color: #047857;
  font-variant-numeric: tabular-nums;
  font-weight: 940;
}

.new-theme-invitation-empty {
  display: grid;
  place-items: center;
  min-height: 7.2rem;
  padding: 1rem;
  color: #64748b;
  font-size: 0.78rem;
  font-weight: 840;
  text-align: center;
}

.platform-payment-dialog {
  width: min(38rem, calc(100vw - 1.8rem));
}

.platform-payment-countdown {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 4.2rem;
  min-height: 2rem;
  border: 1px solid rgba(14, 165, 233, 0.24);
  border-radius: 999px;
  color: #0369a1;
  background: rgba(14, 165, 233, 0.1);
  font-size: 0.84rem;
  font-weight: 900;
}

.platform-payment-body {
  display: grid;
  grid-template-columns: minmax(13rem, 0.78fr) minmax(0, 1fr);
  gap: 0.9rem;
  padding: 1rem 1.6rem 0;
}

.platform-payment-qr-wrap {
  min-width: 0;
}

.platform-payment-qr,
.platform-payment-link-card {
  min-height: 14.2rem;
}

.platform-payment-qr {
  width: 100%;
}

.platform-payment-link-card {
  display: grid;
  place-items: center;
  gap: 0.36rem;
  border: 1px dashed rgba(14, 165, 233, 0.36);
  border-radius: 0.9rem;
  padding: 1rem;
  color: #0369a1;
  background: rgba(14, 165, 233, 0.08);
  text-align: center;
}

.platform-payment-link-card strong {
  color: #0f172a;
  font-size: 0.94rem;
  font-weight: 900;
}

.platform-payment-link-card span {
  color: #475569;
  font-size: 0.78rem;
  font-weight: 760;
  line-height: 1.45;
}

.platform-payment-info {
  align-content: start;
}

.platform-payment-feedback {
  margin: 0.8rem 1.6rem 0;
  display: grid;
  gap: 0.36rem;
}

.platform-payment-feedback p {
  margin: 0;
  border: 1px solid rgba(14, 165, 233, 0.16);
  border-radius: 0.75rem;
  padding: 0.62rem 0.75rem;
  color: #0f766e;
  background: rgba(240, 253, 250, 0.88);
  font-size: 0.78rem;
  font-weight: 780;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.platform-payment-feedback p.error {
  border-color: rgba(248, 113, 113, 0.24);
  color: #b91c1c;
  background: rgba(254, 242, 242, 0.92);
}

.platform-payment-actions {
  margin-top: 1rem;
}

.platform-payment-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.38rem;
}

.platform-payment-actions button.danger {
  border-color: rgba(239, 68, 68, 0.28);
  color: #b91c1c;
  background: rgba(239, 68, 68, 0.08);
}

.new-theme-dialog-backdrop {
  position: fixed;
  z-index: 80;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background: rgba(248, 250, 252, 0.6);
  backdrop-filter: blur(10px);
}

.new-theme-account-dialog {
  display: grid;
  width: min(52rem, calc(100vw - 2rem));
  max-height: calc(100vh - 3rem);
  overflow: auto;
  border: 1px solid #e2e8f0;
  border-radius: 1rem;
  background: #ffffff;
  box-shadow: 0 28px 80px rgba(15, 23, 42, 0.22);
}

.new-theme-codex-session-manager {
  grid-template-rows: auto auto minmax(0, 1fr) auto auto;
  width: min(76rem, calc(100vw - 2rem));
  height: min(46rem, calc(100vh - 3rem));
  overflow: hidden;
}

.codex-session-manager-head {
  align-items: center;
  padding-block: 1rem;
}

.codex-session-manager-head-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.codex-session-manager-head-actions button {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border: 0;
  border-radius: 999px;
  color: #5f6673;
  background: transparent;
}

.codex-session-manager-head-actions button:hover:not(:disabled) {
  color: #2563eb;
  background: #eff6ff;
}

.codex-session-manager-head-actions button:disabled {
  opacity: 0.55;
}

.codex-session-manager-summary {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.72rem 1.25rem;
  border-bottom: 1px solid #e7ebf1;
  background: #f8fafc;
}

.codex-session-manager-summary span {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  min-height: 1.75rem;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  padding: 0 0.66rem;
  color: #64748b;
  background: #ffffff;
  font-size: 0.76rem;
}

.codex-session-manager-summary strong {
  color: #172033;
  font-size: 0.8rem;
}

.codex-session-manager-summary .running {
  margin-left: auto;
  border-color: rgba(245, 158, 11, 0.28);
  color: #a16207;
  background: rgba(245, 158, 11, 0.08);
}

.codex-session-manager-summary .safe {
  margin-left: auto;
  border-color: rgba(34, 197, 94, 0.25);
  color: #15803d;
  background: rgba(34, 197, 94, 0.08);
}

.codex-session-manager-body {
  display: grid;
  grid-template-columns: 15rem minmax(0, 1fr);
  min-height: 0;
  overflow: hidden;
}

.codex-session-project-list {
  min-height: 0;
  overflow: auto;
  border-right: 1px solid #e7ebf1;
  padding: 0.75rem;
  background: #f8fafc;
}

.codex-session-project-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.35rem 0.42rem 0.55rem;
  color: #64748b;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.codex-session-project-title small {
  display: grid;
  place-items: center;
  min-width: 1.4rem;
  height: 1.4rem;
  border-radius: 999px;
  color: #64748b;
  background: #e8edf4;
  font-size: 0.68rem;
}

.codex-session-project-list > button {
  display: grid;
  grid-template-columns: 1.9rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  margin: 0.16rem 0;
  border: 1px solid transparent;
  border-radius: 0.72rem;
  padding: 0.58rem 0.55rem;
  color: #334155;
  background: transparent;
  text-align: left;
}

.codex-session-project-list > button:hover {
  border-color: #dbe4ef;
  background: #ffffff;
}

.codex-session-project-list > button.active {
  border-color: rgba(59, 130, 246, 0.22);
  color: #1d4ed8;
  background: #eaf2ff;
}

.codex-session-project-list > button.native:not(.active) {
  border-color: rgba(59, 130, 246, 0.12);
  background: rgba(239, 246, 255, 0.62);
}

.codex-session-project-list > button.native strong::after {
  content: '原生';
  display: inline-flex;
  margin-left: 0.4rem;
  border-radius: 999px;
  padding: 0.08rem 0.34rem;
  color: #2563eb;
  background: #dbeafe;
  font-size: 0.56rem;
  font-weight: 800;
  vertical-align: 0.08rem;
}

.codex-session-project-list > button.unassigned:not(.active) {
  border-style: dashed;
}

.codex-session-project-icon {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 0.58rem;
  color: #64748b;
  background: #e8edf4;
}

.codex-session-project-list > button.active .codex-session-project-icon {
  color: #2563eb;
  background: #dbeafe;
}

.codex-session-project-list > button > span:nth-child(2) {
  display: grid;
  min-width: 0;
  gap: 0.12rem;
}

.codex-session-project-list strong,
.codex-session-project-list small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.codex-session-project-list strong {
  font-size: 0.82rem;
  font-weight: 800;
}

.codex-session-project-list small {
  color: #8490a2;
  font-size: 0.68rem;
}

.codex-session-project-list em {
  min-width: 1.5rem;
  border-radius: 999px;
  padding: 0.16rem 0.4rem;
  color: #64748b;
  background: #e8edf4;
  font-size: 0.66rem;
  font-style: normal;
  font-weight: 800;
  text-align: center;
}

.codex-session-manager-workspace {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #ffffff;
}

.codex-session-manager-toolbar {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.72rem 0.85rem;
  border-bottom: 1px solid #edf0f5;
}

.codex-session-manager-toolbar > label {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
  height: 2.15rem;
  border: 1px solid #dce3ed;
  border-radius: 0.68rem;
  padding: 0 0.65rem;
  color: #8490a2;
  background: #f8fafc;
}

.codex-session-manager-toolbar input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  color: #172033;
  background: transparent;
  font-size: 0.8rem;
}

.codex-session-manager-toolbar label button {
  display: grid;
  place-items: center;
  border: 0;
  padding: 0;
  color: #8490a2;
  background: transparent;
}

.codex-session-manager-toolbar .select-visible {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  min-height: 2.15rem;
  border: 1px solid #dce3ed;
  border-radius: 0.68rem;
  padding: 0 0.72rem;
  color: #475569;
  background: #ffffff;
  font-size: 0.74rem;
  font-weight: 800;
  white-space: nowrap;
}

.codex-session-table-head,
.codex-session-table-row {
  display: grid;
  grid-template-columns: 1.15rem minmax(13rem, 1.7fr) minmax(7.5rem, 0.7fr) 10.5rem 5rem;
  align-items: center;
  gap: 0.7rem;
}

.codex-session-table-head {
  min-height: 2rem;
  border-bottom: 1px solid #edf0f5;
  padding: 0 0.9rem;
  color: #8490a2;
  background: #fbfcfe;
  font-size: 0.67rem;
  font-weight: 800;
}

.codex-session-table-body {
  min-height: 0;
  overflow: auto;
  padding: 0.35rem 0.48rem 0.6rem;
}

.codex-session-table-row {
  min-height: 3.9rem;
  margin: 0.18rem 0;
  border: 1px solid transparent;
  border-radius: 0.7rem;
  padding: 0.42rem 0.48rem;
  color: #334155;
  background: transparent;
  cursor: pointer;
}

.codex-session-table-row:hover {
  border-color: #e0e7f0;
  background: #f8fafc;
}

.codex-session-table-row.selected {
  border-color: rgba(59, 130, 246, 0.25);
  background: #eff6ff;
}

.codex-session-table-row > input {
  width: 0.95rem;
  height: 0.95rem;
  accent-color: #2563eb;
}

.codex-session-row-main,
.codex-session-row-model,
.codex-session-row-time {
  display: grid;
  min-width: 0;
  gap: 0.2rem;
}

.codex-session-table-row strong,
.codex-session-table-row small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.codex-session-table-row strong {
  color: #263247;
  font-size: 0.78rem;
  font-weight: 800;
}

.codex-session-row-main > strong {
  color: #172033;
  font-size: 0.84rem;
}

.codex-session-table-row small {
  color: #8490a2;
  font-size: 0.66rem;
}

.codex-session-row-size {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 700;
  text-align: right;
}

.codex-session-manager-state {
  display: grid;
  place-items: center;
  align-content: center;
  min-height: 16rem;
  gap: 0.45rem;
  color: #94a3b8;
  text-align: center;
}

.codex-session-manager-state strong {
  color: #475569;
  font-size: 0.9rem;
}

.codex-session-manager-state span {
  max-width: 26rem;
  font-size: 0.75rem;
  line-height: 1.5;
}

.codex-session-manager-feedback {
  display: grid;
  gap: 0.3rem;
  border-top: 1px solid #edf0f5;
  padding: 0.55rem 1.25rem;
  background: #fbfcfe;
}

.codex-session-manager-feedback p {
  margin: 0;
  font-size: 0.75rem;
}

.codex-session-manager-feedback .error { color: #dc2626; }
.codex-session-manager-feedback .success { color: #15803d; }
.codex-session-manager-feedback .warning { color: #a16207; }

.codex-session-manager-footer {
  flex-wrap: wrap;
  margin-top: 0;
  padding-block: 0.75rem;
}

.codex-session-manager-footer > span {
  margin-right: auto;
  color: #64748b;
  font-size: 0.76rem;
}

.codex-session-manager-footer button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  min-height: 2.15rem;
  padding-inline: 0.78rem;
  font-size: 0.76rem;
}

.codex-session-manager-footer button.danger {
  border-color: rgba(239, 68, 68, 0.35);
  color: #ffffff;
  background: #dc2626;
}

.codex-session-manager-footer button.danger.subtle {
  color: #dc2626;
  background: rgba(239, 68, 68, 0.06);
}

.codex-session-manager-footer button.danger:hover:not(:disabled) {
  background: #b91c1c;
}

.codex-session-manager-footer button.danger.subtle:hover:not(:disabled) {
  color: #ffffff;
}

.codex-session-manager-head-actions .spinning,
.codex-session-manager-state .spinning {
  animation: codex-session-manager-spin 900ms linear infinite;
}

@keyframes codex-session-manager-spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 900px) {
  .new-theme-codex-session-manager {
    width: calc(100vw - 1rem);
    height: calc(100vh - 1rem);
  }

  .codex-session-manager-body {
    grid-template-columns: 12rem minmax(0, 1fr);
  }

  .codex-session-table-head,
  .codex-session-table-row {
    grid-template-columns: 1.15rem minmax(12rem, 1.6fr) minmax(7rem, 0.7fr) 9rem;
  }

  .codex-session-table-head > :last-child,
  .codex-session-row-size {
    display: none;
  }
}

.export-account-dialog {
  width: min(40rem, calc(100vw - 2rem));
}

.account-settings-dialog {
  width: min(44rem, calc(100vw - 2rem));
}

.security-account-dialog {
  width: min(34rem, calc(100vw - 2rem));
}

.new-theme-share-dialog {
  width: min(58rem, calc(100vw - 2rem));
}

.new-theme-codex-theme-dialog {
