  width: min(72rem, calc(100vw - 2rem));
  overflow: hidden;
}

.new-theme-dialog-head.new-theme-codex-theme-head {
  display: grid;
}

.new-theme-codex-theme-head {
  grid-template-columns: minmax(15rem, 0.72fr) minmax(20rem, 1.28fr) 2rem;
  align-items: start;
}

.new-theme-codex-theme-head > button {
