}

.new-theme-codex-theme-copyright {
  display: flex;
  align-items: flex-start;
  gap: 0.52rem;
  margin-top: 0.28rem;
  border-left: 2px solid rgba(245, 158, 11, 0.46);
  padding: 0.1rem 0 0.1rem 0.72rem;
  color: #b45309;
}

.new-theme-codex-theme-copyright > svg {
  flex: 0 0 auto;
  margin-top: 0.08rem;
}

.new-theme-codex-theme-copyright p {
