  font-size: 0.69rem;
  line-height: 1.55;
}

.new-theme-codex-theme-badge,
.new-theme-codex-theme-current-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.new-theme-codex-theme-badge {
  gap: 0.34rem;
  width: fit-content;
  margin-bottom: 0.72rem;
  border-radius: 999px;
  padding: 0.3rem 0.62rem;
  color: #0e7490;
  background: rgba(8, 145, 178, 0.1);
  font-size: 0.74rem;
  font-weight: 860;
}

.new-theme-codex-theme-tabs {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  border-bottom: 1px solid #e5e7eb;
  padding: 0 1.35rem;
  background: #fafbfc;
}

.new-theme-codex-theme-tabs button {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  min-height: 2.85rem;
  border: 0;
  padding: 0 0.82rem;
  color: #697386;
  background: transparent;
  font-size: 0.84rem;
  font-weight: 820;
}

.new-theme-codex-theme-tabs button::after {
  position: absolute;
  right: 0.72rem;
  bottom: -1px;
  left: 0.72rem;
  height: 2px;
  border-radius: 999px 999px 0 0;
  background: transparent;
  content: "";
}

.new-theme-codex-theme-tabs button.active {
  color: #0891b2;
}

.new-theme-codex-theme-tabs button.active::after {
  background: #06b6d4;
}

.new-theme-codex-theme-body,
.new-theme-codex-theme-tutorial {
  min-height: 0;
  overflow-y: auto;
  padding: 1rem 1.35rem 1.15rem;
}

.new-theme-codex-theme-body {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.new-theme-codex-theme-body > * {
  flex: 0 0 auto;
}

.new-theme-codex-theme-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.7rem;
  border-bottom: 1px solid #edf1f5;
  padding-bottom: 0.85rem;
}

.new-theme-codex-theme-current,
.new-theme-codex-theme-toolbar-actions,
.new-theme-codex-theme-toolbar-actions button {
  display: flex;
  align-items: center;
}

.new-theme-codex-theme-current {
  gap: 0.7rem;
  min-width: 0;
}

.new-theme-codex-theme-current-icon {
  width: 2.25rem;
  height: 2.25rem;
  flex: 0 0 auto;
  border-radius: 0.65rem;
  color: #059669;
  background: rgba(16, 185, 129, 0.1);
}

.new-theme-codex-theme-current-icon.is-pending {
  color: #64748b;
  background: rgba(100, 116, 139, 0.1);
}

.new-theme-codex-theme-current div {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.new-theme-codex-theme-current small {
  color: #7b8492;
  font-size: 0.72rem;
}

.new-theme-codex-theme-current strong {
  overflow: hidden;
  color: #111827;
  font-size: 0.9rem;
  font-weight: 880;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-codex-theme-toolbar-actions {
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.new-theme-codex-theme-toolbar-actions button {
  white-space: nowrap;
}

.new-theme-codex-theme-toolbar-actions button,
.new-theme-codex-theme-prompt .new-theme-codex-theme-section-title > button {
  justify-content: center;
  gap: 0.38rem;
  min-height: 2.2rem;
  border: 1px solid #dbe3ec;
  border-radius: 0.62rem;
  padding: 0 0.78rem;
  color: #334155;
  background: #ffffff;
  font-size: 0.78rem;
  font-weight: 820;
}

.new-theme-codex-theme-toolbar-actions button:hover,
.new-theme-codex-theme-prompt .new-theme-codex-theme-section-title > button:hover {
  border-color: rgba(6, 182, 212, 0.42);
  color: #0e7490;
  background: rgba(6, 182, 212, 0.06);
}

.new-theme-codex-theme-toolbar-actions button:disabled,
.new-theme-codex-theme-catalog-notice button:disabled,
.new-theme-codex-theme-card-action:disabled {
  cursor: default;
  opacity: 0.58;
}

.new-theme-codex-theme-catalog-notice {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.55rem;
  border: 1px solid rgba(245, 158, 11, 0.26);
  border-radius: 0.5rem;
  padding: 0.58rem 0.7rem;
  color: #92400e;
  background: rgba(255, 251, 235, 0.88);
  font-size: 0.74rem;
  line-height: 1.45;
}

.new-theme-codex-theme-catalog-notice > svg {
  color: #d97706;
}

.new-theme-codex-theme-catalog-notice button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  min-height: 1.9rem;
  border: 1px solid rgba(217, 119, 6, 0.25);
  border-radius: 0.45rem;
  padding: 0 0.55rem;
  color: #92400e;
  background: #ffffff;
  font-size: 0.7rem;
  font-weight: 820;
}

.new-theme-codex-theme-gallery {
  min-width: 0;
}

.new-theme-codex-theme-gallery-head,
.new-theme-codex-theme-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.new-theme-codex-theme-gallery-head {
  margin-bottom: 0.72rem;
  padding: 0 2.85rem;
}

.new-theme-codex-theme-gallery-head h3,
.new-theme-codex-theme-tutorial h3,
.new-theme-codex-theme-section-title h4 {
  margin: 0;
  color: #111827;
  letter-spacing: 0;
}

.new-theme-codex-theme-gallery-head h3 {
  font-size: 0.98rem;
  font-weight: 900;
}

.new-theme-codex-theme-gallery-head p {
  margin: 0.2rem 0 0;
  color: #7b8492;
  font-size: 0.76rem;
}

.new-theme-codex-theme-gallery-head > span {
  flex: 0 0 auto;
  white-space: nowrap;
  color: #64748b;
  font-size: 0.76rem;
  font-variant-numeric: tabular-nums;
  font-weight: 820;
}

.new-theme-codex-theme-carousel {
  display: grid;
  grid-template-columns: 2.25rem minmax(0, 1fr) 2.25rem;
  align-items: center;
  gap: 0.42rem;
  min-width: 0;
}

.new-theme-codex-theme-arrow {
  display: grid;
  place-items: center;
  width: 2.25rem;
  height: 2.25rem;
  border: 1px solid #dce3ec;
  border-radius: 50%;
  color: #475569;
  background: #ffffff;
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.08);
}

.new-theme-codex-theme-arrow:hover {
  border-color: rgba(6, 182, 212, 0.45);
  color: #0891b2;
  background: #ecfeff;
  transform: translateY(-1px);
}

.new-theme-codex-theme-arrow:disabled {
  cursor: default;
  opacity: 0.58;
  transform: none;
}

.new-theme-codex-theme-track {
  position: relative;
  height: clamp(18rem, 48vh, 22rem);
  min-width: 0;
  overflow: hidden;
  perspective: 78rem;
  transform-style: preserve-3d;
  isolation: isolate;
}

.new-theme-codex-theme-card {
  --theme-accent: #06b6d4;
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1;
  width: 34%;
  min-width: 0;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0;
  background-color: #111827;
  background-repeat: no-repeat;
  background-size: 200% 200%;
  box-shadow: 0 9px 22px rgba(15, 23, 42, 0.12);
  transform: translate(-50%, -50%);
  transform-origin: center;
  cursor: pointer;
  will-change: left, top, transform, opacity, filter;
  isolation: isolate;
  transition:
    left 380ms cubic-bezier(0.22, 1, 0.36, 1),
    top 380ms cubic-bezier(0.22, 1, 0.36, 1),
    width 380ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 180ms ease,
    box-shadow 180ms ease,
    filter 260ms ease,
    opacity 260ms ease,
    transform 380ms cubic-bezier(0.22, 1, 0.36, 1);
}

.new-theme-codex-theme-card:hover {
  filter: brightness(1.06) saturate(1.04);
}

.new-theme-codex-theme-card.selected {
  border-color: var(--theme-accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--theme-accent) 22%, transparent), 0 12px 26px rgba(15, 23, 42, 0.16);
}

.new-theme-codex-theme-card.is-far-left {
  top: 58%;
  left: 3%;
  z-index: 1;
  width: 28%;
  opacity: 0.38;
  filter: saturate(0.62) brightness(0.8);
  transform: translate(-50%, -50%) rotateY(42deg) scale(0.68);
  transform-origin: right center;
}

.new-theme-codex-theme-card.is-outer-left {
  top: 55%;
  left: 14%;
  z-index: 2;
  width: 32%;
  opacity: 0.62;
  filter: saturate(0.72) brightness(0.86);
  transform: translate(-50%, -50%) rotateY(34deg) scale(0.76);
  transform-origin: right center;
}

.new-theme-codex-theme-card.is-inner-left {
  top: 52%;
  left: 27%;
  z-index: 4;
  width: 39%;
  opacity: 0.84;
  filter: saturate(0.9) brightness(0.92);
  transform: translate(-50%, -50%) rotateY(24deg) scale(0.86);
  transform-origin: right center;
}

.new-theme-codex-theme-card.is-center {
  top: 50%;
  left: 50%;
  z-index: 7;
  width: min(62%, 44rem);
  opacity: 1;
  filter: none;
  cursor: default;
  transform: translate(-50%, -50%) rotateY(0) scale(1);
}

.new-theme-codex-theme-card.is-inner-right {
  top: 52%;
  left: 73%;
  z-index: 4;
  width: 39%;
  opacity: 0.84;
  filter: saturate(0.9) brightness(0.92);
  transform: translate(-50%, -50%) rotateY(-24deg) scale(0.86);
  transform-origin: left center;
}

.new-theme-codex-theme-card.is-outer-right {
  top: 55%;
  left: 86%;
  z-index: 2;
  width: 32%;
  opacity: 0.62;
  filter: saturate(0.72) brightness(0.86);
  transform: translate(-50%, -50%) rotateY(-34deg) scale(0.76);
  transform-origin: left center;
}

.new-theme-codex-theme-card.is-far-right {
  top: 58%;
  left: 97%;
  z-index: 1;
  width: 28%;
  opacity: 0.38;
  filter: saturate(0.62) brightness(0.8);
  transform: translate(-50%, -50%) rotateY(-42deg) scale(0.68);
  transform-origin: left center;
}

.new-theme-codex-theme-card:not(.is-center):hover {
  opacity: 0.94;
  filter: saturate(0.9) brightness(1);
}

.new-theme-codex-theme-track.is-moving .new-theme-codex-theme-card {
  pointer-events: none;
}

.new-theme-codex-theme-coverflow-enter-active,
.new-theme-codex-theme-coverflow-leave-active {
  transition:
    left 380ms cubic-bezier(0.22, 1, 0.36, 1),
    top 380ms cubic-bezier(0.22, 1, 0.36, 1),
    width 380ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 260ms ease,
    opacity 260ms ease,
    transform 380ms cubic-bezier(0.22, 1, 0.36, 1);
}

.new-theme-codex-theme-coverflow-enter-from,
.new-theme-codex-theme-coverflow-leave-to {
  opacity: 0;
  filter: saturate(0.45) blur(3px);
}

.new-theme-codex-theme-coverflow-leave-active {
  pointer-events: none;
}

.new-theme-codex-theme-card-shade {
  position: absolute;
  z-index: -1;
  inset: 34% 0 0;
  background: linear-gradient(180deg, transparent, rgba(3, 7, 18, 0.9));
}

.new-theme-codex-theme-card-badge {
  position: absolute;
  top: 0.55rem;
  left: 0.55rem;
  max-width: calc(100% - 1.1rem);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
  padding: 0.18rem 0.42rem;
  color: #ffffff;
  background: rgba(15, 23, 42, 0.58);
  font-size: 0.62rem;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
  backdrop-filter: blur(8px);
}

.new-theme-codex-theme-card-copy {
  position: absolute;
  right: 9rem;
  bottom: 0.95rem;
  left: 1rem;
  z-index: 2;
  display: grid;
  gap: 0.18rem;
  min-width: 0;
  text-align: left;
}

.new-theme-codex-theme-card-copy strong,
.new-theme-codex-theme-card-copy small {
  overflow: hidden;
  color: #ffffff;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-codex-theme-card-copy strong {
  font-size: 1.05rem;
  font-weight: 900;
}

.new-theme-codex-theme-card-copy small {
  color: rgba(255, 255, 255, 0.74);
  font-size: 0.68rem;
}

.new-theme-codex-theme-card-action {
  position: absolute;
  right: 1rem;
  bottom: 0.9rem;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.38rem;
  min-width: 7.3rem;
  min-height: 2.45rem;
  border: 1px solid color-mix(in srgb, var(--theme-accent) 68%, #ffffff);
  border-radius: 0.6rem;
  padding: 0 0.9rem;
  color: #ffffff;
  background: var(--theme-accent);
  box-shadow: 0 10px 24px rgba(3, 7, 18, 0.28);
  font-size: 0.78rem;
  font-weight: 850;
  white-space: nowrap;
  backdrop-filter: blur(10px);
}

.new-theme-codex-theme-card-action:hover:not(:disabled) {
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.new-theme-codex-theme-card-action:disabled {
  border-color: rgba(255, 255, 255, 0.34);
  background: rgba(15, 23, 42, 0.72);
  box-shadow: none;
}

.new-theme-codex-theme-card-progress {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 4;
  height: 0.34rem;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.2);
}

.new-theme-codex-theme-card-progress span {
  display: block;
  height: 100%;
  background: var(--theme-accent);
  transition: width 160ms ease;
}

.new-theme-codex-theme-card:not(.is-center) .new-theme-codex-theme-card-badge,
.new-theme-codex-theme-card:not(.is-center) .new-theme-codex-theme-card-copy,
.new-theme-codex-theme-card:not(.is-center) .new-theme-codex-theme-card-action,
.new-theme-codex-theme-card:not(.is-center) .new-theme-codex-theme-card-progress {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .new-theme-codex-theme-card,
  .new-theme-codex-theme-coverflow-enter-active,
  .new-theme-codex-theme-coverflow-leave-active {
    transition-duration: 1ms;
  }
}

.new-theme-codex-theme-tutorial {
  display: grid;
  gap: 1rem;
}

.new-theme-codex-theme-tutorial-intro {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.8rem;
  border-bottom: 1px solid #edf1f5;
  padding-bottom: 0.95rem;
}

.new-theme-codex-theme-tutorial-intro > span {
  display: grid;
  place-items: center;
  width: 2.65rem;
  height: 2.65rem;
  border-radius: 0.72rem;
  color: #7c3aed;
  background: rgba(124, 58, 237, 0.1);
}

.new-theme-codex-theme-tutorial-intro small {
  color: #7c3aed;
  font-size: 0.72rem;
  font-weight: 850;
}

.new-theme-codex-theme-tutorial-intro h3 {
  margin-top: 0.12rem;
  font-size: 1.02rem;
  font-weight: 900;
}

.new-theme-codex-theme-tutorial-intro p {
  margin: 0.3rem 0 0;
  color: #697386;
  font-size: 0.78rem;
}

.new-theme-codex-theme-tutorial-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: 1rem;
}

.new-theme-codex-theme-spec,
.new-theme-codex-theme-package,
.new-theme-codex-theme-prompt {
  min-width: 0;
  border: 1px solid #e5eaf1;
  border-radius: 0.78rem;
  padding: 0.9rem;
  background: #fafbfc;
}

.new-theme-codex-theme-section-title {
  justify-content: flex-start;
}

.new-theme-codex-theme-section-title > svg {
  flex: 0 0 auto;
  color: #0891b2;
}

.new-theme-codex-theme-section-title > div {
  min-width: 0;
  flex: 1;
}

.new-theme-codex-theme-section-title h4 {
  font-size: 0.88rem;
  font-weight: 880;
}

.new-theme-codex-theme-section-title p {
  margin: 0.14rem 0 0;
  color: #7b8492;
  font-size: 0.7rem;
}

.new-theme-codex-theme-spec dl {
  display: grid;
  gap: 0;
  margin: 0.78rem 0;
}

.new-theme-codex-theme-spec dl > div {
  display: grid;
  grid-template-columns: 5.3rem minmax(0, 1fr);
  gap: 0.75rem;
  border-top: 1px solid #e9edf3;
  padding: 0.52rem 0;
}

.new-theme-codex-theme-spec dt,
.new-theme-codex-theme-spec dd {
  margin: 0;
  font-size: 0.74rem;
}

.new-theme-codex-theme-spec dt {
  color: #7b8492;
}

.new-theme-codex-theme-spec dd {
  color: #334155;
  font-weight: 760;
}

.new-theme-codex-theme-safe-area {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 16 / 5.2;
  overflow: hidden;
  border: 1px solid #cbd5e1;
  border-radius: 0.58rem;
  color: #334155;
  background:
    linear-gradient(90deg, rgba(14, 116, 144, 0.12) 0 20%, transparent 20%),
    #eef6f8;
}

.new-theme-codex-theme-safe-area::before {
  position: absolute;
  inset: 0 0 auto;
  height: 26%;
  border-bottom: 1px dashed rgba(14, 116, 144, 0.32);
  background: rgba(255, 255, 255, 0.58);
  content: "";
}

.new-theme-codex-theme-safe-area > div {
  position: absolute;
  inset: 0;
}

.new-theme-codex-theme-safe-area span,
.new-theme-codex-theme-safe-area i {
  position: absolute;
  color: #64748b;
  font-size: 0.6rem;
  font-style: normal;
  font-weight: 760;
}

.new-theme-codex-theme-safe-area span {
  top: 0.22rem;
  left: 0.45rem;
}

.new-theme-codex-theme-safe-area i {
  top: 42%;
