}

.new-theme-codex-theme-package ul {
  display: grid;
  gap: 0;
  margin: 0.74rem 0 0;
  padding: 0;
  list-style: none;
}

.new-theme-codex-theme-package li {
  display: grid;
  grid-template-columns: minmax(6.7rem, auto) minmax(0, 1fr);
  align-items: center;
  gap: 0.72rem;
  border-top: 1px solid #e9edf3;
  padding: 0.64rem 0;
}

.new-theme-codex-theme-package code {
  width: fit-content;
  border-radius: 0.34rem;
  padding: 0.2rem 0.4rem;
  color: #0e7490;
  background: rgba(6, 182, 212, 0.09);
  font-size: 0.7rem;
  font-weight: 820;
}

.new-theme-codex-theme-package li span {
  color: #64748b;
  font-size: 0.72rem;
}

.new-theme-codex-theme-prompt .new-theme-codex-theme-section-title > button {
  display: inline-flex;
  align-items: center;
  align-self: center;
  justify-content: center;
  flex: 0 0 auto;
  height: 2.2rem;
  margin-left: auto;
  line-height: 1;
  white-space: nowrap;
}

.new-theme-codex-theme-prompt .new-theme-codex-theme-section-title > button > svg {
  display: block;
  flex: 0 0 auto;
}

.new-theme-codex-theme-prompt pre {
  max-height: 10.5rem;
  overflow: auto;
  margin: 0.75rem 0 0;
  border-radius: 0.58rem;
  padding: 0.75rem;
  color: #dbeafe;
  background: #111827;
  font: 0.7rem/1.65 "Cascadia Code", "SFMono-Regular", Consolas, monospace;
  white-space: pre-wrap;
}

.new-theme-login-contact-dialog {
  width: min(46rem, calc(100vw - 2rem));
}

.new-theme-contact-preview-dialog {
  width: min(28rem, calc(100vw - 2rem));
}

.new-theme-share-badge,
.new-theme-share-card-icon,
.new-theme-login-contact-badge,
.new-theme-contact-preview-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.new-theme-share-badge,
.new-theme-login-contact-badge,
.new-theme-contact-preview-badge {
  gap: 0.34rem;
  width: fit-content;
  margin-bottom: 0.75rem;
  border-radius: 999px;
  padding: 0.3rem 0.62rem;
  color: #0e7490;
  background: rgba(8, 145, 178, 0.1);
  font-size: 0.74rem;
  font-weight: 860;
}

.new-theme-login-contact-badge {
  color: #047857;
  background: rgba(16, 185, 129, 0.12);
}

.new-theme-contact-preview-badge {
  color: #1d4ed8;
  background: rgba(37, 99, 235, 0.1);
}

.new-theme-login-contact-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.9rem;
  padding: 1rem 1.15rem 1.2rem;
}

.new-theme-login-contact-card {
  display: grid;
  gap: 0.55rem;
  align-content: start;
  min-width: 0;
  border: 1px solid rgba(16, 185, 129, 0.24);
  border-radius: 0.85rem;
  padding: 0.85rem;
  color: #0f172a;
  background:
    linear-gradient(135deg, rgba(16, 185, 129, 0.1), transparent 68%),
    #f8fafc;
  text-align: left;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.new-theme-login-contact-card:hover,
.new-theme-login-contact-card:focus-visible {
  border-color: rgba(16, 185, 129, 0.48);
  box-shadow: 0 14px 32px rgba(16, 185, 129, 0.14);
  transform: translateY(-1px);
}

.new-theme-login-contact-card strong {
  color: #0f172a;
  font-size: 0.92rem;
  font-weight: 860;
}

.new-theme-login-contact-card img,
.new-theme-login-contact-card > span {
  display: grid;
  place-items: center;
  width: 100%;
  height: 11.4rem;
  min-height: 0;
  border: 1px solid #e2e8f0;
  border-radius: 0.7rem;
  padding: 0.45rem;
  background: #ffffff;
}

.new-theme-login-contact-card img {
  object-fit: contain;
}

.new-theme-login-contact-card small {
  min-height: 2.1rem;
  color: #64748b;
  font-size: 0.76rem;
  font-weight: 650;
  line-height: 1.45;
}

.new-theme-contact-preview-body {
  display: grid;
  place-items: center;
  padding: 1.2rem 1.4rem 0.9rem;
}

.new-theme-contact-preview-body img {
  display: block;
  width: min(100%, 22rem, 72vh);
  max-height: min(22rem, 72vh);
  aspect-ratio: 1;
  object-fit: contain;
  border: 1px solid #e2e8f0;
  border-radius: 0.9rem;
  padding: 0.75rem;
  background: #fff;
  box-shadow: 0 18px 44px rgba(15, 23, 42, 0.12);
}

.new-theme-share-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.86rem;
  padding: 1rem 1.15rem 1.2rem;
}

.new-theme-share-card {
  --share-tone: #2563eb;
  --share-soft: rgba(37, 99, 235, 0.1);
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(3.7rem, auto) auto auto;
  gap: 0.72rem;
  align-content: start;
  min-width: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--share-tone) 34%, #dbe4f0);
  border-radius: 0.75rem;
  padding: 0.9rem;
  background:
    linear-gradient(135deg, var(--share-soft), transparent 62%),
    #f8fafc;
  box-shadow: 0 12px 26px color-mix(in srgb, var(--share-tone) 10%, transparent);
}

.new-theme-share-invite-card {
  grid-column: 1 / -1;
}

.new-theme-share-card button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.new-theme-share-card.tone-rose {
  --share-tone: #7c3aed;
  --share-soft: rgba(124, 58, 237, 0.11);
}

.new-theme-share-card.tone-emerald {
  --share-tone: #0891b2;
  --share-soft: rgba(8, 145, 178, 0.11);
}

.new-theme-share-card-head {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

.new-theme-share-card-icon {
  flex: 0 0 auto;
  width: 2.65rem;
  height: 2.65rem;
  border: 1px solid color-mix(in srgb, var(--share-tone) 36%, transparent);
  border-radius: 0.7rem;
  color: var(--share-tone);
  background: color-mix(in srgb, var(--share-tone) 12%, #ffffff);
}

.new-theme-share-card-head div {
  display: grid;
  min-width: 0;
  line-height: 1.08;
}

.new-theme-share-card small {
  color: #64748b;
  font-size: 0.72rem;
  font-weight: 860;
}

.new-theme-share-card strong {
  margin-top: 0.18rem;
  color: #0f172a;
  font-size: 1.16rem;
  font-weight: 940;
}

.new-theme-share-card p {
  display: -webkit-box;
  min-height: 3.7rem;
  overflow: hidden;
  margin: 0;
  color: #475569;
  font-size: 0.78rem;
  font-weight: 720;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.new-theme-share-card code {
  display: block;
  min-width: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--share-tone) 20%, #e2e8f0);
  border-radius: 0.58rem;
  padding: 0.52rem 0.58rem;
  color: #334155;
  background: rgba(255, 255, 255, 0.72);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 0.68rem;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-share-card button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.36rem;
  min-height: 2.15rem;
  border: 1px solid color-mix(in srgb, var(--share-tone) 32%, transparent);
  border-radius: 0.62rem;
  color: #ffffff;
  background: linear-gradient(135deg, var(--share-tone), color-mix(in srgb, var(--share-tone) 74%, #0f172a));
  font-size: 0.78rem;
  font-weight: 860;
  box-shadow: 0 10px 22px color-mix(in srgb, var(--share-tone) 20%, transparent);
}

.new-theme-share-card button:hover {
  filter: brightness(1.04);
}

.new-theme-confirm-dialog {
  width: min(30rem, calc(100vw - 2rem));
}

.new-theme-announcement-popup {
  width: min(34rem, calc(100vw - 2rem));
}

.new-theme-update-dialog {
  width: min(35rem, calc(100vw - 2rem));
}

.invoice-download-dialog {
  width: min(37rem, calc(100vw - 2rem));
}

.invoice-download-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin-bottom: 0.75rem;
  border-radius: 999px;
  padding: 0.34rem 0.62rem;
  color: #047857;
  background: #ecfdf5;
  font-size: 0.76rem;
  font-weight: 900;
}

.invoice-download-body {
  display: grid;
  gap: 0.9rem;
  padding: 0 1.6rem 0.35rem;
}

.invoice-download-meta {
  display: grid;
  gap: 0.48rem;
  border: 1px solid #dbeafe;
  border-radius: 0.75rem;
  padding: 0.82rem 0.9rem;
  color: #334155;
  background: #f8fafc;
  font-size: 0.82rem;
  overflow-wrap: anywhere;
}

.invoice-download-meta strong {
  color: #0f172a;
}

.new-theme-announcement-popup .new-theme-dialog-head {
  border-bottom: 0;
  padding-bottom: 0.85rem;
}

.new-theme-announcement-popup-badge,
.new-theme-update-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  margin-bottom: 0.75rem;
  border-radius: 999px;
  padding: 0.34rem 0.62rem;
  color: #1d4ed8;
  background: #eff6ff;
  font-size: 0.76rem;
  font-weight: 900;
}

.new-theme-update-badge {
  color: #047857;
  background: #ecfdf5;
}

.new-theme-update-badge.force {
  color: #b91c1c;
  background: #fff1f2;
}

.new-theme-announcement-popup-body {
  padding: 0 1.6rem 1.35rem;
}

.new-theme-update-body {
  display: grid;
  gap: 0.9rem;
  padding: 0 1.6rem 0.35rem;
}

.new-theme-update-progress {
  overflow: hidden;
  height: 0.55rem;
  border-radius: 999px;
  background: #e2e8f0;
}

.new-theme-update-progress span {
  display: block;
  height: 100%;
  min-width: 0.35rem;
  border-radius: inherit;
  background: linear-gradient(90deg, #10b981, #2563eb);
  transition: width 0.2s ease;
}

.new-theme-update-meta {
  display: grid;
  gap: 0.42rem;
  border: 1px solid #dbeafe;
  border-radius: 0.75rem;
  padding: 0.78rem 0.9rem;
  color: #1e3a8a;
  background: #eff6ff;
  font-size: 0.84rem;
  font-weight: 800;
}

.new-theme-update-progress.indeterminate span {
  width: 38% !important;
  animation: invoice-download-indeterminate 1.05s ease-in-out infinite;
}

@keyframes invoice-download-indeterminate {
  0% { transform: translateX(-115%); }
  50% { transform: translateX(85%); }
  100% { transform: translateX(265%); }
}

.new-theme-update-dialog.force .new-theme-update-meta {
  border-color: #fecaca;
  color: #7f1d1d;
  background: #fff1f2;
}

.new-theme-update-error {
  margin: 0;
  border: 1px solid #fecaca;
  border-radius: 0.75rem;
  padding: 0.78rem 0.9rem;
  color: #991b1b;
  background: #fff1f2;
  font-size: 0.84rem;
  line-height: 1.5;
}

.codex-operation-backdrop {
  z-index: 120;
  cursor: wait;
  background: rgba(248, 250, 252, 0.72);
}

.codex-operation-dialog {
  width: min(31rem, calc(100vw - 2rem));
  gap: 1rem;
  overflow: hidden;
  padding: 1.35rem;
}

.codex-operation-hero {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.codex-operation-hero h2 {
  margin: 0.52rem 0 0;
  color: #111316;
  font-size: 1.22rem;
  font-weight: 940;
  letter-spacing: 0;
}

.codex-operation-hero p,
.codex-operation-detail {
  margin: 0.4rem 0 0;
  color: #5f6673;
  font-size: 0.9rem;
  font-weight: 680;
  line-height: 1.55;
}

.codex-operation-detail {
  border: 1px solid #dbeafe;
  border-radius: 0.78rem;
  padding: 0.78rem 0.9rem;
  color: #1e3a8a;
  background: #eff6ff;
}

.codex-operation-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.36rem;
  border-radius: 999px;
  padding: 0.34rem 0.62rem;
  color: #047857;
  background: #ecfdf5;
  font-size: 0.76rem;
  font-weight: 900;
}

.codex-operation-spinner {
  flex: 0 0 auto;
  width: 2.35rem;
  height: 2.35rem;
  border: 0.22rem solid #dbeafe;
  border-top-color: #2563eb;
  border-radius: 999px;
  animation: codex-operation-spin 0.8s linear infinite;
}

.codex-operation-progress {
  overflow: hidden;
  height: 0.42rem;
  border-radius: 999px;
  background: #e2e8f0;
}

.codex-operation-progress span {
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #10b981, #2563eb);
  animation: codex-operation-progress 1.15s ease-in-out infinite;
}

@keyframes codex-operation-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes codex-operation-progress {
  0% {
    transform: translateX(-115%);
  }

  100% {
    transform: translateX(245%);
  }
}

.new-theme-announcement-popup-body p {
  margin: 0;
  border: 1px solid #e2e8f0;
  border-radius: 0.9rem;
  padding: 0.9rem 1rem;
  color: #334155;
  background: #f8fafc;
  font-size: 0.94rem;
  line-height: 1.65;
  white-space: pre-wrap;
}

.new-theme-confirm-details {
  display: grid;
  gap: 0.45rem;
  margin: 0.85rem 0 0;
  border: 1px solid #fecaca;
  border-radius: 0.62rem;
  padding: 0.75rem 0.85rem;
  color: #7f1d1d;
  background: #fff1f2;
  font-size: 0.82rem;
  line-height: 1.5;
  list-style: none;
}

.new-theme-confirm-details li::before {
