}

.new-theme-confirm-dialog.warning .new-theme-dialog-head h2 {
  color: #b45309;
}

.new-theme-confirm-dialog.error .new-theme-dialog-head h2 {
  color: #b91c1c;
}

.new-theme-dialog-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid #e5e7eb;
  padding: 1.35rem 1.6rem 1.1rem;
}

.new-theme-dialog-head h2 {
  margin: 0;
  color: #111316;
  font-size: 1.28rem;
