.new-theme-dialog-head > button {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  color: #5f6673;
  background: transparent;
}

.new-theme-dialog-head > button:hover {
  background: #f3f4f6;
}

.new-theme-security-prompt {
  display: flex;
  align-items: flex-start;
  gap: 0.85rem;
  margin: 1rem 1.6rem 0;
  border: 1px solid rgba(59, 130, 246, 0.22);
