  padding: 1rem;
  color: #1d4ed8;
  background: rgba(59, 130, 246, 0.08);
}

.new-theme-security-prompt div {
  display: grid;
  gap: 0.28rem;
}

.new-theme-security-prompt strong {
  color: #111316;
  font-size: 0.96rem;
  font-weight: 900;
}

.new-theme-security-prompt span {
  color: #4b5563;
  font-size: 0.84rem;
  line-height: 1.55;
}

.new-theme-account-settings-body {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
  padding: 1rem 1.6rem 0;
}

.new-theme-account-settings-reminder {
  grid-column: 1 / -1;
  display: flex;
  align-items: flex-start;
  gap: 0.72rem;
  border: 1px solid rgba(245, 158, 11, 0.3);
  border-radius: 0.78rem;
