  gap: 0.42rem;
}

.new-theme-oauth-field > span {
  color: #111316;
  font-size: 0.84rem;
  font-weight: 820;
}

.new-theme-oauth-field > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.5rem;
}

.new-theme-oauth-field input {
  min-width: 0;
  min-height: 2.28rem;
  border: 1px solid #dde3ec;
  border-radius: 0.62rem;
  padding: 0 0.75rem;
  color: #111316;
  background: #ffffff;
  font: 0.8rem/1.4 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  outline: none;
}

.new-theme-oauth-field input:focus {
  border-color: rgba(59, 130, 246, 0.55);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.oauth-activate-checkbox {
  margin: 0;
  background: #ffffff;
}

.new-theme-oauth-submit {
  justify-self: end;
  border-color: #2563eb;
  color: #ffffff;
  background: #2563eb;
}

.new-theme-oauth-submit:disabled,
.new-theme-oauth-head button:disabled,
.new-theme-oauth-field button:disabled {
  cursor: default;
  opacity: 0.62;
}

.new-theme-session-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 1rem 1.6rem 0;
  color: #64748b;
  font-size: 0.78rem;
  font-weight: 820;
}

.new-theme-session-divider::before,
.new-theme-session-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: #e2e8f0;
}

.new-theme-session-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.8rem;
  padding: 1rem 1.6rem;
}

.new-theme-session-steps article {
  display: grid;
  align-content: start;
  gap: 0.58rem;
  min-height: 10.2rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.92rem;
  padding: 1rem;
  background: #ffffff;
}

.new-theme-session-steps article > span {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  color: #ffffff;
  background: #2563eb;
  font-weight: 900;
}

.new-theme-session-steps strong {
  color: #111316;
  font-size: 0.98rem;
  font-weight: 900;
}

.new-theme-session-steps p {
  margin: 0;
  color: #626b78;
  font-size: 0.82rem;
  line-height: 1.5;
}

.new-theme-session-steps button,
.new-theme-session-input-head button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.38rem;
  width: fit-content;
  min-height: 2rem;
  border: 1px solid #dde3ec;
  border-radius: 0.6rem;
  padding: 0 0.72rem;
  color: #111316;
  background: #ffffff;
  font-size: 0.78rem;
  font-weight: 780;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
}

.new-theme-session-warning {
  margin: 0 1.6rem 1rem;
  border: 1px solid rgba(251, 146, 60, 0.28);
  border-radius: 0.72rem;
  padding: 0.78rem 0.9rem;
  color: #9a3412;
  background: rgba(251, 191, 36, 0.12);
  font-size: 0.8rem;
  line-height: 1.55;
}

.new-theme-session-input-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0 1.6rem 0.55rem;
}

.new-theme-session-input-head span {
  color: #111316;
  font-size: 0.92rem;
  font-weight: 800;
}

.new-theme-session-textarea {
  width: calc(100% - 3.2rem);
  min-height: 8.2rem;
  margin: 0 1.6rem;
  border: 1px solid #dde3ec;
  border-radius: 0.82rem;
  padding: 0.85rem;
  resize: vertical;
  color: #111316;
  background: #ffffff;
  font: 0.82rem/1.5 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  outline: none;
}

.new-theme-session-textarea:focus {
  border-color: rgba(59, 130, 246, 0.55);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.new-theme-session-checkbox {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.5rem;
  margin: 0.72rem 1.6rem 0;
  border: 1px solid #e5e7eb;
  border-radius: 0.62rem;
  padding: 0 0.75rem;
  color: #5f6673;
  background: #fafafa;
  font-size: 0.8rem;
}

.new-theme-session-checkbox input {
  width: 0.95rem;
  height: 0.95rem;
}

.new-theme-dialog-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.55rem;
  border-top: 1px solid #e5e7eb;
  margin-top: 1rem;
  padding: 1rem 1.6rem;
  background: #fafafa;
}

.new-theme-dialog-actions button {
  min-height: 2.25rem;
  border: 1px solid #dde3ec;
  border-radius: 0.62rem;
  padding: 0 1rem;
  color: #111316;
  background: #ffffff;
  font-size: 0.86rem;
  font-weight: 820;
}

.new-theme-dialog-actions button.primary {
  border-color: #3b82f6;
  color: #ffffff;
  background: #3b82f6;
}

.new-theme-dialog-actions button:disabled {
  cursor: default;
  opacity: 0.62;
}

.new-theme-toast-stack {
  position: fixed;
  z-index: 120;
  right: 1.2rem;
  bottom: 1.2rem;
  display: grid;
  gap: 0.7rem;
  width: min(24rem, calc(100vw - 2rem));
  pointer-events: none;
}

.new-theme-toast {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.65rem;
  align-items: flex-start;
  border: 1px solid #e2e8f0;
  border-radius: 0.85rem;
  padding: 0.78rem 0.85rem;
  color: #1f2937;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 16px 45px rgba(15, 23, 42, 0.16);
  animation: new-theme-toast-enter 0.22s ease both;
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.new-theme-toast.leaving {
  opacity: 0;
  transform: translateY(0.4rem);
}

@keyframes new-theme-toast-enter {
  from {
    opacity: 0;
    transform: translateY(0.55rem) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.new-theme-toast svg {
  margin-top: 0.1rem;
  color: #3b82f6;
}

.new-theme-toast.success svg {
  color: #059669;
}

.new-theme-toast.warning svg {
  color: #d97706;
}

.new-theme-toast.error svg {
  color: #dc2626;
}

.new-theme-toast strong {
  display: block;
  color: #111827;
  font-size: 0.86rem;
  font-weight: 880;
}

.new-theme-toast span {
  display: block;
  margin-top: 0.18rem;
  color: #4b5563;
  font-size: 0.8rem;
  line-height: 1.45;
  word-break: break-word;
}

.new-theme-export-list {
  display: grid;
  margin: 1rem 1.6rem 0;
  overflow: hidden;
  max-height: min(20rem, calc(100vh - 17rem));
  overflow-y: auto;
  border: 1px solid #e2e8f0;
  border-radius: 0.72rem;
}

.new-theme-export-list button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.65rem;
  min-height: 3.25rem;
  border-bottom: 1px solid #e5e7eb;
  padding: 0 0.9rem;
  color: #111316;
  background: #ffffff;
  text-align: left;
}

.new-theme-export-list button:hover {
  background: #f8fafc;
}

.new-theme-export-list button:last-child {
  border-bottom: 0;
}

.new-theme-export-check {
  display: grid;
  place-items: center;
  width: 1.18rem;
  height: 1.18rem;
  border: 1px solid #cbd5e1;
  border-radius: 999px;
  color: #ffffff;
  background: #ffffff;
}

.new-theme-export-check.checked {
  border-color: #2563eb;
  background: #2563eb;
}

.new-theme-export-copy {
  display: grid;
  gap: 0.16rem;
  min-width: 0;
}

.new-theme-export-copy strong {
  overflow: hidden;
  color: #111316;
  font-size: 0.9rem;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-theme-export-copy small,
.new-theme-export-all small {
  color: #626b78;
  font-size: 0.76rem;
}

.new-theme-export-plan {
  border-radius: 999px;
  padding: 0.18rem 0.5rem;
  color: #111316;
  background: #f3f4f6;
  font-size: 0.7rem;
  font-weight: 900;
}

.new-theme-export-all {
  grid-template-columns: auto minmax(0, 1fr) auto;
  background: #fafafa !important;
}

.new-theme-shell.mode-dark {
  --background: #0f131a;
  --foreground: #f8fafc;
  --muted: #171c25;
  --muted-foreground: #9aa4b2;
  --border: #29313d;
  --sidebar: #111720;
  --accent: #1d2530;
  --accent-foreground: #f8fafc;
  --primary: #f8fafc;
  --primary-foreground: #111316;
  color-scheme: dark;
}

.mode-dark .new-theme-topbar-action.is-contact {
  --topbar-action-tone: #60a5fa;
}

.mode-dark .new-theme-topbar-action.is-announcement {
  --topbar-action-tone: #fbbf24;
}

.mode-dark .new-theme-topbar-action.is-feedback {
  --topbar-action-tone: #22d3ee;
}

.mode-dark .new-theme-topbar-action {
  border-color: color-mix(in srgb, var(--topbar-action-tone) 24%, transparent);
  color: color-mix(in srgb, var(--topbar-action-tone) 78%, #f8fafc);
  background: color-mix(in srgb, var(--topbar-action-tone) 13%, #111720);
}

.mode-dark .new-theme-topbar-action:hover,
.mode-dark .new-theme-topbar-action.active {
  border-color: color-mix(in srgb, var(--topbar-action-tone) 48%, #29313d);
  color: color-mix(in srgb, var(--topbar-action-tone) 86%, #ffffff);
  background: color-mix(in srgb, var(--topbar-action-tone) 20%, #111720);
  box-shadow: 0 8px 20px color-mix(in srgb, var(--topbar-action-tone) 22%, transparent);
}

.mode-dark .new-theme-sidebar-utility-button.is-contact {
  --sidebar-utility-tone: #60a5fa;
  --sidebar-utility-soft: rgba(96, 165, 250, 0.15);
}

.mode-dark .new-theme-sidebar-utility-button.is-share {
  --sidebar-utility-tone: #22d3ee;
  --sidebar-utility-soft: rgba(34, 211, 238, 0.14);
}

.mode-dark .new-theme-sidebar-utility-button {
  border-color: color-mix(in srgb, var(--sidebar-utility-tone) 28%, transparent);
  color: color-mix(in srgb, var(--sidebar-utility-tone) 78%, #f8fafc);
  background:
    linear-gradient(135deg, var(--sidebar-utility-soft), color-mix(in srgb, var(--sidebar-utility-tone) 8%, #111720));
}

.mode-dark .new-theme-sidebar-utility-button:hover,
.mode-dark .new-theme-sidebar-utility-button.active {
  border-color: color-mix(in srgb, var(--sidebar-utility-tone) 48%, #29313d);
  color: color-mix(in srgb, var(--sidebar-utility-tone) 88%, #ffffff);
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--sidebar-utility-tone) 22%, #111720), color-mix(in srgb, var(--sidebar-utility-tone) 12%, #111720));
  box-shadow: 0 8px 20px color-mix(in srgb, var(--sidebar-utility-tone) 22%, transparent);
}

.mode-dark .new-theme-content {
  background: linear-gradient(180deg, #0f131a 0%, #111722 100%);
}

.mode-dark .new-theme-mode-toggle {
  border-color: #29313d;
  background: #171d27;
}

.mode-dark .new-theme-mode-toggle button {
  color: #a8b3c2;
}

.mode-dark .new-theme-mode-toggle button.active {
  color: #f8fafc;
  background: #252d3a;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.24);
}

.mode-dark .new-theme-stat-card,
.mode-dark .new-theme-metric-card,
.mode-dark .new-theme-account-strip,
.mode-dark .new-theme-subscription-panel,
.mode-dark .new-theme-empty-panel,
