.tone-blue {
  --tone: #3b82f6;
  --tone-strong: #2563eb;
  --tone-soft: rgba(59, 130, 246, 0.13);
  --tone-pill: rgba(59, 130, 246, 0.1);
}

.tone-amber {
  --tone: #f59e0b;
  --tone-strong: #b45309;
  --tone-soft: rgba(245, 158, 11, 0.15);
  --tone-pill: rgba(245, 158, 11, 0.12);
}

.tone-emerald {
  --tone: #10b981;
  --tone-strong: #047857;
  --tone-soft: rgba(16, 185, 129, 0.13);
  --tone-pill: rgba(16, 185, 129, 0.11);
}

.tone-violet {
  --tone: #8b5cf6;
  --tone-strong: #6d28d9;
  --tone-soft: rgba(139, 92, 246, 0.13);
  --tone-pill: rgba(139, 92, 246, 0.1);
}

.tone-cyan {
  --tone: #06b6d4;
  --tone-strong: #0e7490;
  --tone-soft: rgba(6, 182, 212, 0.13);
  --tone-pill: rgba(6, 182, 212, 0.1);
}

.tone-rose {
  --tone: #f43f5e;
  --tone-strong: #be123c;
  --tone-soft: rgba(244, 63, 94, 0.12);
  --tone-pill: rgba(244, 63, 94, 0.1);
}

